P.transport["item:99-year-old-port"] = {
  hash = "d7d79a",
  fullHash = "d7d79a",
  text = "99-Year-Old Port. The 99-Year-Old Port is an exceptionally rare bottle of vintage liquor shipped from Booty Bay as a personal gift for Gazlowe. After a cargo accident on the Ratchet docks, it was snatched away by a lunatic named Mad Magglish, who fled into the twisting tunnels outside the Wailing Caverns. Transporting precious freight across the Great Sea always carries risks, but Crane Operator Bigglefuzz made things far worse during a routine morning unloading in Ratchet. Attempting to clear an overwhelming shipment from Booty Bay, the goblin overloaded his crane and brought a mountain of crates crashing down onto the docks. In the chaos, the town eccentric—a troublesome figure known as Mad Magglish—snatched an extraordinarily aged bottle of 99-Year-Old Port and bolted into the hills toward the Wailing Caverns.",
  ["1"] = {
    {file = "Audio/Transport/full_item_99-year-old-port-a557edbc01c387e95b6b/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["item:a-bloodstained-journal-page"] = {
  hash = "fc97f7",
  fullHash = "fc97f7",
  text = "A Bloodstained Journal Page. Commander Althea Ebonlocke has a torn, bloodstained journal page examined during the investigation into Stalvan Mistmantle. A few words remain legible, and she asks Clerk Daltry to compare the handwriting with the Town Registry. Commander Althea Ebonlocke watches over Darkshire and asks that the handwriting on a torn, bloodstained page be examined. Though thick blood covers it, a few words remain legible for Clerk Daltry to compare with the Town Registry.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-bloodstained-journal-page-4bcbd7e84e757a5a9904/1-0000.mp3", duration = 26.2008163, start = 0},
  },
}
P.transport["item:a-clue-to-sanders-treasure"] = {
  hash = "39d150",
  fullHash = "39d150",
  text = "A Clue to Sanders' Treasure. In Westfall, a weathered parchment carries the trail of notorious pirate Captain Sanders. It marks the second step in a treasure hunt across the bluffs and coastlines. After you follow Captain Sanders' first treasure map, you find a parchment that points farther inland into Westfall. The scrawled note sends you east from the coast, up the bluffs toward the main road. Near crumbling stone ruins and an abandoned chimney, an old barrel marks the next place Sanders hid a clue, drawing seekers deeper into the troubled farmlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-clue-to-sanders-treasure-5543438b6ecd05a1ab40/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["item:a-dusty-unsent-letter"] = {
  hash = "f46eec",
  fullHash = "f46eec",
  text = "A Dusty Unsent Letter. In Westfall, a dusty letter sheds light on Stalvan Mistmantle’s past in Moonbrook. The unsent parchment was found in an old footlocker and confirms that he lived there before his disappearance. Investigators searching for Stalvan Mistmantle’s past find an unsent letter in an old footlocker in Moonbrook. Darkshire’s town registry still gives his last address as the Moonbrook Schoolhouse, and Clerk Daltry wants to know whether he truly lived there. The letter confirms that Stalvan resided in the Westfall township for a time. Finding it disturbs a vengeful Forlorn Spirit, which guards the remnants of Stalvan’s past with bitter malice.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-dusty-unsent-letter-b02e097daf792e9b16dc/1-0000.mp3", duration = 37.4595918, start = 0},
  },
}
P.transport["item:a-faded-journal-page"] = {
  hash = "4f45e7",
  fullHash = "4f45e7",
  text = "A Faded Journal Page. In eastern Elwynn, an old page points toward Stalvan Mistmantle's grim history. The Faded Journal Page lay for years in an old trunk at Marshal Haggard's home near Elwynn Forest's eastern border. Haggard had retired there, but his failing eyesight kept him from reading the weathered parchment. The page stayed neglected until investigators seeking the truth about Stalvan Mistmantle retrieved it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-faded-journal-page-6555545c5b57e01c3a33/1-0000.mp3", duration = 20.9240816, start = 0},
  },
}
P.transport["item:a-letter-to-grelin-whitebeard"] = {
  hash = "da2900",
  fullHash = "da2900",
  text = "A Letter to Grelin Whitebeard. A letter from Ironforge reaches Grelin Whitebeard at his camp in Coldridge Valley. The dispatch carries news and instructions to the experienced dwarf on the snowy frontier. Grelin Whitebeard receives word from Ironforge at his wilderness campsite. Coldridge Valley can feel far from the safety of Anvilmar, and letters connect scouts and scholars in the field with the halls of the mountain capital. This missive has traveled south along the mountain paths to reach him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-letter-to-grelin-whitebeard-960ba2eacf74af55ab85/1-0000.mp3", duration = 27.0628571, start = 0},
  },
}
P.transport["item:a-mysterious-message"] = {
  hash = "178291",
  fullHash = "178291",
  text = "A Mysterious Message. A courier's intercepted message gives the People's Militia proof of who directs the Defias Brotherhood in Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-mysterious-message-a98cce278f07bb0debc8/1-0000.mp3", duration = 6.03428571, start = 0},
  },
}
P.transport["item:a-simple-compass"] = {
  hash = "57faac",
  fullHash = "57faac",
  text = "A Simple Compass. At the burned Alexston Farmstead in Westfall, A Simple Compass waits in a small chest. It belonged to Baros Alexston before he became Stormwind's City Architect. Baros Alexston grew up working his family's farm in Westfall. His simple compass was his first navigational instrument, and may have stirred his interest in geometry, drafting, and exploration. The Defias Brotherhood raided and burned the farmstead, leaving the compass in a sturdy chest among the ruins as bandits overran the farmland. Baros's father escaped the destruction but could not carry the family's possessions to safety. The compass offers little use to a master builder within Stormwind City's stone walls, yet it holds great meaning for Baros. Its return would restore a rare, intact link to his humble beginnings and the peaceful countryside of his childhood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-simple-compass-27614039d020645a6031/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["item:a-stack-of-letters"] = {
  hash = "43c185",
  fullHash = "43c185",
  text = "A Stack of Letters. A Stack of Letters has come through the mountain pass into Coldridge Valley. The bundle is meant for scouts stationed in the snowy wilderness. Mail for Coldridge Valley comes from Anvilmar by way of travelers crossing the pass. The journey to the remote camps in Dun Morogh's mountains is hard, and postal runners rely on travelers to carry letters onward. This bundle is bound for scouts deeper in Coldridge Valley. Talin Keeneye, at his lakeside camp, is thought to be its only recipient until the letters are sorted. Among them is a missive for Grelin Whitebeard, a mountaineer.",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-stack-of-letters-f83d4cda2b0ab119721b/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["item:a-torn-journal-page"] = {
  hash = "7332ce",
  fullHash = "7332ce",
  text = "A Torn Journal Page. In Stormwind, A Torn Journal Page links an old crate to Stalvan Mistmantle's past. Its worn script points toward records kept in Elwynn Forest. A Torn Journal Page lies in a sealed storage crate beside Stormwind City's canals. Old books, family heirlooms, and a ceramic vase surround the worn fragment among forgotten personal effects. Its distinct handwriting points to Stalvan Mistmantle's past, though the page is damaged and hard to read. Who in the kingdom might recognize the hand that wrote it?",
  ["1"] = {
    {file = "Audio/Transport/full_item_a-torn-journal-page-daa7aaacf53796d87950/1-0000.mp3", duration = 30.7461224, start = 0},
  },
}
P.transport["item:abercrombie-s-crate"] = {
  hash = "2b9188",
  fullHash = "2b9188",
  text = "Abercrombie's Crate. Near the Vul'Gol Ogre Mound, Abercrombie's Crate lies abandoned after ogres drove off its owner. The crate holds delicate tools and gathered herbs belonging to the eccentric hermit. Abercrombie left his shack in western Duskwood to gather vegetation. Far from home, he met a hostile band of ogres and fled for his life, leaving behind his crate of instruments and harvested plants. The ogres carried it to the Vul'Gol Ogre Mound, where the heavy chest rests near the cave mouth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_abercrombie-s-crate-f72236f556a3d0e50172/1-0000.mp3", duration = 27.3240816, start = 0},
  },
}
P.transport["item:admiral-proudmoore-s-orders"] = {
  hash = "cc88e5",
  fullHash = "cc88e5",
  text = "Admiral Proudmoore's Orders. Kul Tiras forces keep their coastal positions in Durotar, and Admiral Proudmoore's Orders lay out their plans. The documents were written before Daelin Proudmoore fell at Theramore and describe a campaign against the Horde. Admiral Proudmoore's Orders show that the Kul Tiras forces at Tiragarde Keep still mean to fight. Lieutenant Benedict's garrison holds the papers, which detail long-term maneuvers and fortifications against the Horde. The plans show that Daelin Proudmoore's offensive in Durotar was an organized campaign, built to continue after his death. For the Horde, the documents reveal Kul Tiras operations and possible reinforcements threatening its borders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_admiral-proudmoore-s-orders-451b4232bacf873f1920/1-0000.mp3", duration = 38.4261224, start = 0},
  },
}
P.transport["item:ados-fragment"] = {
  hash = "9a0907",
  fullHash = "9a0907",
  text = "Ados Fragment. At Whelgar's Excavation in the Wetlands, Ados Fragment lies among three lost pieces of the Goaz Stone. Together, the four shards make an ancient relic carved with Titan inscriptions. The Ados Fragment is one of four pieces Prospector Whelgar needs to restore the Goaz Stone at Whelgar's Excavation. Before raptors overran the dig site, Whelgar began translating the main tablet and found its inscriptions broke off at crucial moments. The four pieces, named Ados, Modr, Golm, and Neru, were lost across the ruins in ancient containers and dirt mounds, among prowling beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ados-fragment-4d3ea092a73638b14b62/1-0000.mp3", duration = 33.5412245, start = 0},
  },
}
P.transport["item:agamand-family-axe"] = {
  hash = "a8d9a6",
  fullHash = "a8d9a6",
  text = "Agamand Family Axe. In northern Tirisfal, the Agamand Family Axe remains among the family's ancestral arms. Once a symbol of the wealthy mill owners, it is now sought by Coleman Farthing to strip the undead Agamands of their remaining dignity. Before the Third War, the Agamand dynasty owned land across Tirisfal Glades' northern hills and kept vast mills and a family crypt. The Agamand Family Axe rested with the ancestral arms, beside the buried patriarchs and warriors. The Scourge overran the estate and slaughtered its inhabitants, but the weapons remained on racks underground. The Scourge raised the fallen Agamands as mindless thralls to the Lich King. Their former servant Coleman Farthing survived in undeath, bitter toward his old masters. Farthing blames the family for his own death and sends Forsaken wanderers into the crypt to take the axe, sword, mace, and dagger from the racks. He wants the last traces of the Agamand heritage erased.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-axe-3ad5e7f53f9043586638/1-0000.mp3", duration = 55.6146939, start = 0},
  },
}
P.transport["item:agamand-family-dagger"] = {
  hash = "8cb962",
  fullHash = "8cb962",
  text = "Agamand Family Dagger. In northern Tirisfal, the Agamand Family Dagger rests among the weapons in the family crypt. Coleman Farthing seeks it and the family’s other arms to strip his former masters of their legacy and honor. Before the Third War, the Agamand family held vast estates and grain mills in the rolling meadows of northern Tirisfal Glades. The Scourge destroyed their power, but their weapons endured in the family crypt north of Agamand Mills. Restless undead members of the household and mindless servants of the Lich King guard the dagger. It recalls the martial heritage and standing the family once held above its servants and tenants. Coleman Farthing resides at Brill, but he once died in the Agamands’ service. He blames the family for his death, and the dagger means resentment to him, not noble lineage. Farthing sends adventurers into the Agamand Family Crypt for the dagger, sword, axe, and mace. By taking these arms from the tomb, he seeks to rob the Scourge patriarchs of their last dignity and extinguish the Agamand name.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-dagger-9e00dbf11018c97544e2/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["item:agamand-family-mace"] = {
  hash = "056899",
  fullHash = "056899",
  text = "Agamand Family Mace. At Agamand Mills, the Agamand Family Mace remains locked in the family crypt. Once a proud heirloom of northern Lordaeron, it is now sought by their former servant, Coleman Farthing. Before the Third War, the Agamand family held vast farmlands and windmills in northern Tirisfal Glades. Like the region’s other aristocrats, they fell to the plague of undeath. The Scourge raised them as mindless thralls in service to the Lich King, and they wander their ruined estate. Their ancient treasures remain locked in the family crypt. Among them rests the Agamand Family Mace, a remnant of a lineage reduced to shambling undead.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-mace-774762661da69a865a77/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["item:agamand-family-sword"] = {
  hash = "c60377",
  fullHash = "c60377",
  text = "Agamand Family Sword. In northern Tirisfal, the Agamand Family Sword remains in the family crypt. The tarnished blade once marked the wealth and standing of the mill-owning dynasty, and Coleman Farthing now seeks it to erase their legacy. The Agamands once held great wealth and influence through their mills in northern Tirisfal Glades. When the Scourge swept through Lordaeron, the family met a gruesome end, and their bodies rose as mindless thralls of the Lich King. Their ancestral weapons, including the ceremonial sword, were sealed inside the Agamand Family Crypt at the northern edge of the mills. Taking these blades from their burial racks is an act meant to break the memory and noble standing of the fallen household.",
  ["1"] = {
    {file = "Audio/Transport/full_item_agamand-family-sword-4386e202178c2ff19550/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:ahanu-s-leather-goods"] = {
  hash = "7b0641",
  fullHash = "7b0641",
  text = "Ahanu's Leather Goods. Ahanu's Leather Goods carries Thunder Bluff's leatherwork to the Crossroads. Ahanu sends finished leather armor and supplies to the Barrens for travelers there. Ahanu prepares leather goods for trade beyond Mulgore. In Thunder Bluff, the leatherworker turns raw hides into finished apparel and gear for Jahan Hawkwing, a merchant at the Crossroads in the Barrens. The plains make overland travel slow, so the tauren send the parcel by air. Tal and Devrak's trained wind riders carry goods swiftly across long distances.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ahanu-s-leather-goods-94ccd071c7a664515698/1-0000.mp3", duration = 30.6677551, start = 0},
  },
}
P.transport["item:alaric-s-remains"] = {
  hash = "4f2ce6",
  fullHash = "4f2ce6",
  text = "Alaric's Remains. Alaric's bones lie in a shallow grave in Silverpine Forest, far from Fenris Isle. His spirit asks travelers to carry them past the Rot Hide gnolls and directly into Fenris Keep. Alaric's bones were unearthed from a shallow grave in Silverpine Forest. He was once a resident of Fenris Isle, and his spirit longs for the place he cherished in life. He asks whoever finds his bones to leave his ill-fitting boots behind and carry his remains directly into Fenris Keep, far from the scavengers prowling the mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alaric-s-remains-4a1686eca4a6700eb41a/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["item:alien-egg"] = {
  hash = "f503b9",
  fullHash = "f503b9",
  text = "Alien Egg. The Alien Egg is an unusual and mysterious clutch found guarded by local wind serpents across the canyons of Thousand Needles. Despite its unfamiliar appearance, the native serpents protect the egg fiercely as if it were their own. Its presence has aroused the curiosity and concern of the tauren scouts stationed atop Freewind Post. Discovered resting at the base of the towering spires south and northeast of Freewind Post, the Alien Egg stands out dramatically from the typical fauna of the canyon floor. Rather than abandoning or destroying the odd clutch, the native serpents of the needles fiercely guard it alongside their own nests. Hagar Lightninghoof, a tauren brave keeping watch from the heights of Freewind Post, sought to retrieve the specimen to determine whether it represented a threat to the mesa settlements or merely an unusual variation of local reptilian life.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alien-egg-77cea891d9e4e5323c83/1-0000.mp3", duration = 50.155102, start = 0},
  },
}
P.transport["item:alterac-granite"] = {
  hash = "b65451",
  fullHash = "b65451",
  text = "Alterac Granite. Across the mountains of northern Lordaeron, Alterac Granite is quarried near Darrow Hill in the Hillsbrad Foothills. Its resilience and grain draw master stonecutters, and King Magni Bronzebeard's royal mason insists on it for a tribute to fallen soldiers. King Magni Bronzebeard ordered a monument for Sully Balloo, a brave dwarven defender who perished in the tragedy at the Thandol Span. Grand Mason Marblesten, charged with sculpting it in Ironforge, insisted on Alterac Granite instead of ordinary quarry stone. Across the Eastern Kingdoms, few stones are finer. Its legendary durability ensures the likeness and memory of a fallen hero endure untarnished for generations. Alterac Granite lies around Darrow Hill in the northern Hillsbrad Foothills, near the ruined territories of Alterac. Hostile wildlife, syndicate brigands, and lingering strife make the journey perilous. Bold adventurers must venture deep into contested lands to retrieve unblemished slabs for Ironforge's artisans.",
  ["1"] = {
    {file = "Audio/Transport/full_item_alterac-granite-4bf3a8c1526ab2223304/1-0000.mp3", duration = 58.3053061, start = 0},
  },
}
P.transport["item:altered-snapjaw-shell"] = {
  hash = "19f900",
  fullHash = "19f900",
  text = "Altered Snapjaw Shell. At the Lushwater and Stagnant Oases, snapjaws bear altered shells that draw a druid’s attention. Their carapaces may reveal what the fissures beneath the Barrens are doing to local wildlife. Oasis snapjaws have changed in ways that trouble those who study the land. The freshwater turtles of Lushwater and Stagnant Oases are believed to drink from springs fed by mysterious underground fissures. Their altered carapaces have caught the attention of researchers at the Crossroads. Tonga Runetotem, a tauren druid, gathers the shells as he seeks to understand the land’s health. He wants to learn whether energies rising from deep below are an unnatural blight or something stranger.",
  ["1"] = {
    {file = "Audio/Transport/full_item_altered-snapjaw-shell-955aaa144b0c9d91214b/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["item:ambercorn"] = {
  hash = "69de1e",
  fullHash = "69de1e",
  text = "Ambercorn. Across Mulgore, Ambercorn falls beneath the ancient trees. Tauren gather it for the Water of the Seers, a brew used in the Rite of Vision. Ambercorn falls beneath Mulgore's great trees, where tauren gather it from the grass. To the tauren, these nuts carry the land's spiritual vitality and latent magic. Tauren mystics have understood and used that power for generations. Young hunters and wanderers learn to watch the ground beneath the canopy and honor the Earth Mother's gifts. In Bloodhoof Village, seer Zarlman Two-Moons prepares young tauren for the Rite of Vision with ambercorn. He combines it with stones gathered from the plains' water wells to make the Water of the Seers. Initiates drink the ceremonial brew before the ancestral flames. Their senses shift, revealing a guiding spirit animal meant to lead them to their next destination.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ambercorn-b7f24ade1573eab8c067/1-0000.mp3", duration = 49.7632653, start = 0},
  },
}
P.transport["item:amethyst-phial"] = {
  hash = "047ea2",
  fullHash = "047ea2",
  text = "Amethyst Phial. Corithras Moonrage entrusts the Amethyst Phial to travelers in Dolanaar. They carry it to the Oracle Glade to gather water from the moonwell beneath the Oracle Tree. Corithras Moonrage entrusts the Amethyst Phial to travelers on Teldrassil. It is the final vessel used in the Crown of the Earth pilgrimage. They carry it to the far northwest of the boughs, to the Oracle Glade. Beneath the ancient canopy of the Oracle Tree lies the island’s first and most potent moonwell. The phial is dipped into its radiant waters to gather the essence of Elune’s grace. Druids and priestesses study and tend to the World Tree’s unpredictable growth with that water.",
  ["1"] = {
    {file = "Audio/Transport/full_item_amethyst-phial-ebc2485231a037280bb2/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["item:an-undelivered-letter"] = {
  hash = "0f3d6a",
  fullHash = "0f3d6a",
  text = "An Undelivered Letter. Long-forgotten mail lies in Goldshire's Lion's Pride Inn, carrying a critical clue to Stalvan Mistmantle's past. Years ago, a storm sent a traveling courier to the Lion's Pride Inn for shelter. Near midnight, the frightened messenger fled downstairs in his sleeping clothes and vanished into the pouring rain, never to return. On the second floor, he left a chest of belongings, including a letter from Stalvan Mistmantle addressed to an estate in Stormwind City's Canal District.",
  ["1"] = {
    {file = "Audio/Transport/full_item_an-undelivered-letter-eed1b0f13bdcd374465c/1-0000.mp3", duration = 29.4661224, start = 0},
  },
}
P.transport["item:anaya-s-pendant"] = {
  hash = "231abb",
  fullHash = "231abb",
  text = "Anaya's Pendant. Across Ameth'Aran, Anaya's Pendant remains with the restless ghost of Anaya Dawnrunner. Cerellean Whiteclaw carries grief for the love he lost when the Sundering shattered their world. When the Well of Eternity was destroyed ten thousand years ago, the ancient kaldorei city of Ameth'Aran fell into ruin. Cerellean Whiteclaw believed his beloved Anaya had perished, and carried his grief into a long sleep beside Shan'do Malfurion Stormrage. After waking, he wandered Darkshore and found Anaya's tormented apparition still drifting through Ameth'Aran, bearing the pendant. Cerellean cannot raise a hand against her himself, so he asks travelers to free her spirit and recover the heirloom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_anaya-s-pendant-7a13188bf1ab7afc7703/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:ancient-moonstone-seal"] = {
  hash = "0bdfac",
  fullHash = "0bdfac",
  text = "Ancient Moonstone Seal. The Ancient Moonstone Seal holds Asterion captive in the ruins of Bashal'Aran. Forged by the Highborne long before the Sundering, it binds his spirit with arcane magic. The Ancient Moonstone Seal binds Asterion's soul to the pillars of Bashal'Aran. His former master, the Highborne sorcerer Athrikus Narassin, forged it as an unbreakable anchor while the Well of Eternity still stood and Queen Azshara reigned. More than ten millennia later, Asterion remains a spirit bound by its magic. No strength or spell he commands can break the ward.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ancient-moonstone-seal-96ea14ad5ff46465086c/1-0000.mp3", duration = 33.044898, start = 0},
  },
}
P.transport["item:ancient-statuette"] = {
  hash = "9f2eaf",
  fullHash = "9f2eaf",
  text = "Ancient Statuette. Along Ashenvale's northwestern shore, Talen seeks the Ancient Statuette he recovered from Zoram's sunken ruins. The night elf effigy came from a city lost beneath the waves. The sunken ruins of Zoram lie off northwestern Ashenvale. The pre-Sundering night elven city was lost beneath the waves ten thousand years ago. Recently, the explorer Talen surveyed the ruins from a small craft, searching for historical relics. Naga attacked and drove him ashore. In his flight, he left most of his belongings behind, including the ancient statuette he had dredged up. It lies on the tideline sand near his scuttled skiff. Talen calls the statuette his most prized possession and the reason he braved the monster-infested coast. He believes the effigy can help decipher Zoram's architecture, history, and arcane secrets, all hidden beneath the surf of Zoram Strand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ancient-statuette-8ee6ff49e6a358f57616/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["item:andron-s-ledger"] = {
  hash = "c4368e",
  fullHash = "c4368e",
  text = "Andron's Ledger. In the Undercity, Andron Gant's ledger draws the Deathstalkers' attention. They seek it as an operative gathers information for the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_andron-s-ledger-566b4b934435ef687b33/1-0000.mp3", duration = 8.59428571, start = 0},
  },
}
P.transport["item:another-clue-to-sanders-treasure"] = {
  hash = "91c47c",
  fullHash = "91c47c",
  text = "Another Clue to Sanders' Treasure. In Westfall, a scrap of Captain Sanders' parchment points the way to his next hidden marker. Captain Sanders hid his stolen riches across Westfall, using riddles and buried markers instead of one map that could be seized. This scrap continues the trail from the previous hiding place. It tells the finder to turn north and look for a discarded jug near a lonely windmill above the sea cliffs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_another-clue-to-sanders-treasure-dde7203872c2eb19a9a5/1-0000.mp3", duration = 24.0326531, start = 0},
  },
}
P.transport["item:arikara-serpent-skin"] = {
  hash = "90c658",
  fullHash = "90c658",
  text = "Arikara Serpent Skin. At Darkcloud Pinnacle, Arikara is summoned and slain, leaving a scaled hide behind. Carried to Whitereach Post, the skin proves the wind serpent was defeated. Arikara is a formidable wind serpent tied to ancient tauren legend. Rumor says she seeks retribution against Cairne Bloodhoof as tauren ways change. Under Elder Magatha Grimtotem's direction, champions prepare enchanted Incendia Powder. They light the sacred fire atop Darkcloud Pinnacle's burial bluffs, drawing the spirit-beast into the physical realm. Stripping Arikara's hide leaves the Arikara Serpent Skin, proof of her death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_arikara-serpent-skin-57a92341c3a2749483ea/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["item:arnak-s-hoof"] = {
  hash = "2dd193",
  fullHash = "2dd193",
  text = "Arnak's Hoof. Arnak's Hoof is the macabre proof of death taken from the criminal Arnak Grimtotem. Hunted down on the bluffs of Darkcloud Pinnacle, Arnak was marked for execution by the defenders of Freewind Post after murdering a fellow tauren and kidnapping his sister. Arnak Grimtotem earned notoriety throughout Thousand Needles as an outlaw whose brutality crossed even the contentious lines of tauren clan politics. After murdering another tauren and abducting the victim's sister, Lakota Windsong, a formal bounty was posted for his death. Arnak holed up on the heights of Darkcloud Pinnacle, surrounded by Grimtotem guards. Slaying him and claiming his severed hoof serves as undeniable confirmation for Cliffwatcher Longhorn at Freewind Post that the murderer has finally answered for his crimes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_arnak-s-hoof-f40b6e7b2b5ee8b1d566/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["item:astor-s-letter-of-introduction"] = {
  hash = "f4610a",
  fullHash = "f4610a",
  text = "Astor's Letter of Introduction. Astor Hadren carries a letter between Silverpine Forest and the Undercity. Deathstalkers use it to pose as the courier and investigate Andron Gant, a shopkeeper suspected of leaking Forsaken intelligence. Astor Hadren carries messages between Silverpine Forest and the Undercity. His letter of introduction gives its bearer credentials with illicit contacts in the city. Mennet Carkad, a Deathstalker handler, needs to investigate suspicious leaks in the Undercity, and Astor's travels make him a target. An operative can eliminate Astor and take his papers, then assume his identity and intercept the covert messages meant for him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_astor-s-letter-of-introduction-9cf1ab4a204eb283b05a/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["item:ataeric-s-staff"] = {
  hash = "bb4b22",
  fullHash = "bb4b22",
  text = "Ataeric's Staff. At the Sepulcher, Ataeric's Staff marks the archmage's defeat. Archmage Ataeric, a senior Dalaran wizard in Silverpine Forest, wielded it to command local ley lines. Shadow Priest Allister feared Dalaran's growing reach in magic and ordered Ataeric killed. He also demanded the staff. Once Ataeric was slain and the staff recovered, the concentrated ley energies sank back into dormancy. Carrying the staff to the Sepulcher marked a clear victory over Dalaran's ambitions. Yet power still lies latent in the earth, and the Forsaken remain watchful.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ataeric-s-staff-4437fa5f0e2417f6c53d/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["item:athrikus-narassin-s-head"] = {
  hash = "299102",
  fullHash = "299102",
  text = "Athrikus Narassin's Head. At the Tower of Althalaxx, Athrikus Narassin's Head proves the ancient warlock's death. The coven's demonic activity in northern Darkshore has been disrupted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_athrikus-narassin-s-head-887cf4b0e473a26eee33/1-0000.mp3", duration = 9.71755102, start = 0},
  },
}
P.transport["item:bag-of-empty-ooze-containers"] = {
  hash = "d88309",
  fullHash = "d88309",
  text = "Bag of Empty Ooze Containers. In Ironforge, Laris Geardawdle supplies empty containers for his ooze research. The jars are meant to hold pristine slime specimens gathered in the field. Laris Geardawdle studies the strange biology of Azeroth's oozes. He found that slime creatures quickly take on the corruption around them, including tainted residues from Felwood. To study oozes in their natural state, he commissioned sturdy jars that can hold acidic specimens without harming them. The bag contains enough jars to collect clean slime in wild regions, especially Un'Goro Crater, where ancient glutinous oozes live free from demonic taint.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bag-of-empty-ooze-containers-f3c78cbc58588d33b825/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["item:balnir-snapdragons"] = {
  hash = "1653ea",
  fullHash = "1653ea",
  text = "Balnir Snapdragons. At Balnir Farmstead, vibrant snapdragons grow where the Scourge's corruption presses toward Tirisfal Glades. The Forsaken study their sensitivity to magic to watch for that corruption's spread. Balnir Snapdragons still bloom in the garden of Balnir Farmstead in eastern Tirisfal Glades. The homestead lies in ruin after the fall of Lordaeron and the rise of the Scourge. The Plaguelands border Tirisfal to the east, and the garden sits where the Lich King's blight presses against the region. Its flowers give the Forsaken a place to watch for the spread of that corruption. Balnir Snapdragons are unusually sensitive to atmospheric magic, making them living barometers for magical blights. Anastasia Hartwell and the Forsaken mages in the Undercity seek fresh flowers from the farmstead's window boxes. They send the plants to the Royal Apothecary Society for study, hoping to measure how far the Lich King's plague has seeped across the border into Tirisfal's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_balnir-snapdragons-c9d7a30b8e8065d8385a/1-0000.mp3", duration = 56.8163265, start = 0},
  },
}
P.transport["item:baron-longshore-s-head"] = {
  hash = "1062a2",
  fullHash = "1062a2",
  text = "Baron Longshore's Head. Along the Merchant Coast, Baron Longshore's Head proves the pirate captain's death. Gazlowe posted a public bounty for Longshore's identifiable remains to protect Ratchet's commercial shipping. Baron Longshore led Southsea Freebooter raids from camps along the Merchant Coast south of Ratchet. His flagship, the Heedless, threatened goblin trade lanes between Kalimdor and the Eastern Kingdoms. Gazlowe, Ratchet's Chief Engineer, offered a bounty for identifiable proof of Longshore's death. The port authority pays a monetary reward when the pirate's head is delivered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_baron-longshore-s-head-8a4113abc9bdc45fa527/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["item:barrel-of-barleybrew-scalder"] = {
  hash = "027048",
  fullHash = "027048",
  text = "Barrel of Barleybrew Scalder. Marleth Barleybrew sends a cask of Scalder toward the Thunderbrew Distillery in Kharanos. The ale is meant to prove his brewing against the Thunderbrews, his chief competitors. The Thunderbrews and Barleybrews compete fiercely over brewing in Dun Morogh. The Thunderbrews are renowned, with their busy distillery in Kharanos. Marleth Barleybrew refuses to live in their shadow. He brews the fiery Scalder to show his recipes can rival theirs, hoping those who taste it will see the Thunderbrews do not own the art of fine dwarven drink.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-barleybrew-scalder-e4114bf605b624b55d44/1-0000.mp3", duration = 30.4065306, start = 0},
  },
}
P.transport["item:barrel-of-shimmer-stout"] = {
  hash = "4ce81c",
  fullHash = "4ce81c",
  text = "Barrel of Shimmer Stout. In Dun Morogh, Rejold Barleybrew sends a barrel of Shimmer Stout to the mountain watch. The experimental ale is meant for guards on the high passes, and drinkers say it brightens their vision. Rejold Barleybrew brewed Shimmer Stout after gathering ingredients across Dun Morogh. The recipe is the latest work of the Barleybrew family, whose dwarven brewers compete to make hearty ales against the mountain cold. Rejold made this stout to warm the gut and sharpen the senses of those posted in the wind. This barrel is bound for Mountaineer Wellart Barleybrew at the southern tower on the pass into Loch Modan. Mountaineers there endure cold and long watches between skirmishes with troggs and wildlife. A cask of family ale brings a taste of home, and its kick can leave a tired sentry feeling able to see clearly in the dark.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-shimmer-stout-0ddb18809db13b98500a/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["item:barrel-of-thunder-ale"] = {
  hash = "7563cd",
  fullHash = "7563cd",
  text = "Barrel of Thunder Ale. In Kharanos, a barrel of Thunder Ale has been taken from the Thunderbrew Distillery. Its place was meant to be taken by Marleth's Barleybrew Scalder, proof of a brewing feud turned to foul play. The Thunderbrews of Kharanos and the Barleybrews of Brewnall Village are bitter rivals. Marleth Barleybrew tried to slip a barrel of his Barleybrew Scalder into the Thunderbrews' cellar, hoping their patrons would choose his brew. The Thunder Ale barrel was seized in the exchange, evidence that the switch succeeded despite the local guards.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrel-of-thunder-ale-fc4c3537f32e11a44f92/1-0000.mp3", duration = 30.72, start = 0},
  },
}
P.transport["item:barrow-key"] = {
  hash = "7183a1",
  fullHash = "7183a1",
  text = "Barrow Key. Deep beneath Stonetalon Peak, the Barrow Key lies locked in the Talon Den. It is one of three druidic keys guarding the ancient treasures sealed within the den's hoard. Night elf druids placed wards throughout the Talon Den's underground barrows to protect their relics from intruders. The Barrow Key is hidden in a cache among the passages, one part of that layered defense. The cache opens only with the Gatekeeper's Key, so a seeker must know the druids' defenses to reach it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_barrow-key-5d828526d858712a061c/1-0000.mp3", duration = 28.1861224, start = 0},
  },
}
P.transport["item:bartleby-s-mug"] = {
  hash = "e1dfce",
  fullHash = "e1dfce",
  text = "Bartleby's Mug. In Stormwind, a stubborn brawler keeps Bartleby's Mug close. A warrior must win it in a tavern brawl, then watch Bartleby drain his drink before he surrenders it. Bartleby keeps his mug close, and a young warrior in Stormwind must wrest it from him. The stubborn brawler gives it up only after a fight leaves him beaten. Even then, Bartleby drains every last drop before handing over the mug as proof of victory.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bartleby-s-mug-63591f29861e4535a23c/1-0000.mp3", duration = 24.0326531, start = 0},
  },
}
P.transport["item:bathran-s-hair"] = {
  hash = "412987",
  fullHash = "412987",
  text = "Bathran's Hair. Among the ruins of Bathran's Haunt in northwestern Ashenvale, Bathran's Hair remains a rare herb. Night elf healers value its power against afflictions of the flesh and spirit. Bathran's Hair grows among the ancient ruins north of Maestra's Post, where night elf healers have long valued it. Common herbs soothe wounds of the body, but Bathran's Hair is said to restore the spirit as well. When a young night elf in Astranaar falls gravely ill, herbalist Orendil Broadleaf seeks the rare plant to prepare a remedy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bathran-s-hair-4a15b3f4bf80ac8164e3/1-0000.mp3", duration = 29.9363265, start = 0},
  },
}
P.transport["item:battleboar-flank"] = {
  hash = "c41d7e",
  fullHash = "c41d7e",
  text = "Battleboar Flank. In Mulgore, young hunters gather Battleboar Flanks from beasts threatening tauren hunting grounds. The meat feeds the tribe's youth. Bristleback quilboar train battleboars in Brambleblade Ravine to enter tauren hunting grounds. Their attacks threaten the young tauren at Camp Narache. Grull Hawkwind sends novice hunters to take the flanks and snouts from the beasts they kill. The flank meat is cooked into stew for the tribe's youth, feeding them with what the quilboar sent against their people.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleboar-flank-695056422ca661007040/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["item:battleboar-snout"] = {
  hash = "dfb5ea",
  fullHash = "dfb5ea",
  text = "Battleboar Snout. Young tauren hunters gather Battleboar Snouts near Red Cloud Mesa as the Bristleback press into their hunting grounds. The snouts also go into stews for the young in Camp Narache. Bristleback quilboar train battleboars in Brambleblade Ravine, in the shadow of Red Cloud Mesa, to probe tauren hunting grounds. Grull Hawkwind sends young braves to push back against the encroachment. A snout proves that a battleboar has been brought down. The tauren use the snouts with cuts of flank in rich stews for their young.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleboar-snout-9a49332afaf31354e0ed/1-0000.mp3", duration = 28.7346939, start = 0},
  },
}
P.transport["item:battleworn-axe"] = {
  hash = "6c6762",
  fullHash = "6c6762",
  text = "Battleworn Axe. In Redridge, Battleworn Axe blades mark the Blackrock orcs invading the mountains. Marshal Marris accepts the recovered weapons in Lakeshire as proof of the threat to its people. Blackrock reavers carry these heavy, nicked axes as they push south from the Burning Steppes into Redridge. Marshal Marris and Lakeshire's hard-pressed town watch collect the blades to confirm another marauding orc has fallen and to show how well armed the advancing warband is. Blackrock invaders have fortified Stonewatch Keep and taken footholds in southeastern Redridge, trapping townspeople in Lakeshire. Taking their battleworn weapons reduces the arms available to the warband and clears roads for Alliance travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_battleworn-axe-3f196035fd3febbe7edf/1-0000.mp3", duration = 39.444898, start = 0},
  },
}
P.transport["item:berard-s-journal"] = {
  hash = "b2a504",
  fullHash = "b2a504",
  text = "Berard's Journal. In Pyrewood Village, Berard's Journal holds research the Royal Apothecary Society needs. Berard studied an ancient plague that wiped out the aquatic life of Lake Lordamere. Before Arugal's shadow magic spread across Silverpine Forest, Apothecary Berard was one of the Royal Apothecary Society's most promising minds. From Pyrewood Village, he studied an ancient blight that had wiped out all aquatic life in Lake Lordamere centuries earlier. When Arugal's curse gripped the settlement, Berard lost his mind and became a thrall. His detailed field notes remained on a bookshelf in his quarters at the Pyrewood Village Inn.",
  ["1"] = {
    {file = "Audio/Transport/full_item_berard-s-journal-a399222f64f3dee35746/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["item:bernice-s-necklace"] = {
  hash = "e32396",
  fullHash = "e32396",
  text = "Bernice's Necklace. At Stonefield Farm in Elwynn Forest, Bernice keeps her late husband's necklace close. Auntie Bernice Stonefield's necklace once belonged to her late husband, a veteran of Stormwind's military campaigns. He carried it into battle as a charm for good fortune. Bernice says tragedy came only during his final campaign, the one expedition when he forgot to bring it. Since his death, the keepsake has remained among her most cherished possessions at Stonefield Farm.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bernice-s-necklace-8591052a9c88b65880fc/1-0000.mp3", duration = 27.0628571, start = 0},
  },
}
P.transport["item:besseleth-s-fang"] = {
  hash = "8b6750",
  fullHash = "8b6750",
  text = "Besseleth's Fang. In Sishir Canyon, Besseleth's Fang marks the end of a deadly spider's threat. Besseleth and her brood make Sishir Canyon dangerous for travelers. At night, the giant spider turns the Webwinder Path into a death trap for those crossing the gorge. Her fang measures nearly two feet and drips with potent venom. Local defenders have suffered her venomous strikes, and presenting the fang brings them relief.",
  ["1"] = {
    {file = "Audio/Transport/full_item_besseleth-s-fang-f8dd8d44c5c4d60d591e/1-0000.mp3", duration = 24.1110204, start = 0},
  },
}
P.transport["item:bethor-s-scroll"] = {
  hash = "008223",
  fullHash = "008223",
  text = "Bethor's Scroll. Bethor Iceshard writes counter-incantations to help Apothecary Renferrel brew a protective draught against Thule Ravenclaw's dark sorcery. The scroll holds the key to facing the Scourge necromancy guarding Fenris Isle.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bethor-s-scroll-0f78a247d4def257fe08/1-0000.mp3", duration = 13.6359184, start = 0},
  },
}
P.transport["item:bingles-blastencapper"] = {
  hash = "129f01",
  fullHash = "129f01",
  text = "Bingles' Blastencapper. Bingles Blastenheimer’s explosive lies in trogg hands after his gyrocopter fell into the Loch. Its loss threatens his plans to aid Gnomeregan’s liberation. Bingles Blastenheimer’s Blastencapper lies among the wreckage of his gyrocopter in Loch Modan. The pilot built the explosive for aerial strikes against the troggs and leper gnomes who overran Gnomeregan. Mechanical failure sent his craft into the Loch, though Bingles survived. Troggs from the lake’s northern islands raided the wreckage and carried the volatile weapon back to their camps. Bingles needs the Blastencapper for the coming effort to retake Gnomeregan. The exiled gnomes are preparing to reclaim their radioactive home, and he counts on his gyrocopter and signature munitions for the air assault. The troggs of Loch Modan could accidentally trigger a catastrophe with the explosive, and its recovery would preserve a valuable weapon for the gnomish resistance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-blastencapper-5364e0bb5636c25541c9/1-0000.mp3", duration = 52.3232653, start = 0},
  },
}
P.transport["item:bingles-hammer"] = {
  hash = "e8be4b",
  fullHash = "e8be4b",
  text = "Bingles' Hammer. Troggs have taken Bingles' Hammer from the crash site in Loch Modan. Bingles Blastenheimer, a stranded gnome aviator, needs his specialized gear to repair his flying machine and help free Gnomeregan. Bingles Blastenheimer survived his flying machine's plunge into the Loch, then lost his tools to troggs on the freshwater islands. They took his hammer and high-potency explosives from the crash site. He needs the hammer to repair the dented airframe and adjust the gyrocopter's mechanical parts. Without his equipment, Bingles cannot fly support runs for the gnome forces fighting to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-hammer-5711a1018674d61cd3e1/1-0000.mp3", duration = 35.1346939, start = 0},
  },
}
P.transport["item:bingles-screwdriver"] = {
  hash = "68f8e5",
  fullHash = "68f8e5",
  text = "Bingles' Screwdriver. Bingles' Screwdriver lies among the gear scattered across Loch Modan's northern islands. Gnome pilot Bingles Blastenheimer lost it when troggs plundered his crashed gyrocopter. Bingles Blastenheimer lost the tools he needs to repair his gyrocopter when he crashed into Loch Modan. Troggs on the nearby islands carried off his tool buckets, and the screwdriver was packed in one of them. Bingles needs the screwdriver to make fine adjustments as he repairs the craft and handles its armaments. Bingles works to free Gnomeregan from troggs and leper gnomes. He plans to combine his flying skill with volatile Blastencapper munitions for an aerial assault. Recovering the screwdriver, wrench, and hammer will help him rebuild his gyrocopter and keep the airborne counteroffensive alive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-screwdriver-b076d7e61e9fa5d4c16f/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["item:bingles-wrench"] = {
  hash = "44ec84",
  fullHash = "44ec84",
  text = "Bingles' Wrench. Bingles' Wrench is missing, along with the pilot's other tools. Troggs took it after Bingles Blastenheimer crash-landed his flying machine into the Loch. Bingles Blastenheimer survived his gyrocopter's crash into the Loch, but survival quickly became an ordeal. Troggs on the small northern islands raided the crash site, taking his specialized supplies and scattering his tools among buckets in their camps. Bingles' Wrench is one of three critical hand tools, alongside his high-yield Blastencapper explosives. Without the wrench, Bingles cannot repair his downed gyrocopter, delaying his planned aerial offensive to aid the exiled gnomes fighting to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bingles-wrench-dd97f94c8e8a99c29ece/1-0000.mp3", duration = 39.1314286, start = 0},
  },
}
P.transport["item:black-claw-stout"] = {
  hash = "0bbf6f",
  fullHash = "0bbf6f",
  text = "Black Claw Stout. Beneath Stormwind, Zardeth of the Black Claw prepares a drink for Lord Wishock. The stout is delivered as an ordinary tavern beverage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_black-claw-stout-a1157c7e1d9b7812c095/1-0000.mp3", duration = 8.04571429, start = 0},
  },
}
P.transport["item:black-feather-quill"] = {
  hash = "57155f",
  fullHash = "57155f",
  text = "Black Feather Quill. The Black Feather Quill lies in Ban'ethil Barrow Den, needed to wake the Druids of the Talon. The Black Feather Quill is one of four sacred focuses used to wake the Druids of the Talon from hibernation. The others are the Raven Claw Talisman, the Sapphire of Sky, and the Rune of Nesting. The rite calls slumbering druids back from the Emerald Dream. Without these items, a druid may remain trapped in the Dream and unable to return to their waking body. Corrupted Gnarlpine furbolgs overran Ban'ethil Barrow Den, putting the chests that held the relics in danger. Athridas Bearmantle in Dolanaar ordered their swift recovery, before the captive druids were lost to the Dream.",
  ["1"] = {
    {file = "Audio/Transport/full_item_black-feather-quill-b397c86ad10a95b7c14d/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:blackened-skull"] = {
  hash = "5d1eeb",
  fullHash = "5d1eeb",
  text = "Blackened Skull. At Agamand Mills, Blackened Skull trophies mark the fight against the Scourge. Deathguard Dillinger in Brill wants them as proof that the Darkeye Bonecasters are being destroyed. Darkeye Bonecasters haunt the Agamand Mills. These skeletal spellcasters turn their necromantic malice against the living and the Forsaken, seeking to secure a forward base for the Lich King's armies in northern Tirisfal. Deathguard Dillinger in Brill asks for their ruined skulls as proof that the Scourge's mystical vanguard is being beaten back.",
  ["1"] = {
    {file = "Audio/Transport/full_item_blackened-skull-305bef1ee5411ef7fac5/1-0000.mp3", duration = 32, start = 0},
  },
}
P.transport["item:bloodfeather-belt"] = {
  hash = "f7b4fa",
  fullHash = "f7b4fa",
  text = "Bloodfeather Belt. In northern Teldrassil, Bloodfeather harpies wear crude leather belts as they crowd the Oracle Glade. Sentinel Arynia Cloudsbreak collects them as proof that the nearby nests have been cleared. Bloodfeather harpies have built aggressive nests in the boughs around the Oracle Glade. Their presence threatens the ancient Oracle Tree and blocks travel through northern Teldrassil. After the flock ambushed and killed a runner carrying reports to Darnassus, Sentinel Arynia Cloudsbreak called on travelers to strike at the nests. The belts taken from fallen harpies show that their numbers are being culled and the paths are being secured, so messages can reach the capital again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodfeather-belt-ddfe92218bd16745c20b/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["item:bloodfury-ripper-s-remains"] = {
  hash = "8845b1",
  fullHash = "8845b1",
  text = "Bloodfury Ripper's Remains. At Sun Rock Retreat, Maggran Earthbinder seeks Bloodfury Ripper's Remains as proof that the Bloodfury harpy leader is dead. Her death strikes at the threat to the tauren settlement. Bloodfury Ripper leads the harpies of the Charred Vale with fierce, territorial aggression. They nest among the scorched ruins and threaten travelers and shamans across the Stonetalon Mountains. Culling the flock eases the danger for a time, but Maggran Earthbinder at Sun Rock Retreat knows that lasting relief means removing its leader. Bloodfury Ripper rules almost like a queen, directing the harpies' attacks on their territory. Her remains prove she is dead, leaving the flock in disarray and giving the tauren who seek to heal and secure their rugged lands greater peace of mind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodfury-ripper-s-remains-d81063b37e838433e167/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["item:bloodstone-choker"] = {
  hash = "e5939e",
  fullHash = "e5939e",
  text = "Bloodstone Choker. In Stormwind, the Bloodstone Choker binds a warlock’s ritual to the void. Gakin the Darkbinder once held the bloodstone talisman, until an apprentice stole it and fled to the Defias Brotherhood. Carved from bloodstone, the choker can bridge the mortal world and the twisting shadows of the Twisting Nether. Gakin puts it to use in the crypts beneath the tavern, channeling its magic at the summoning circle to draw a hostile Voidwalker from the void. A warlock must subdue the furious creature in direct combat while wielding the talisman to prove the will to command such a guardian.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bloodstone-choker-604c95fa1e74f74fdb72/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["item:blueleaf-tuber"] = {
  hash = "d78b23",
  fullHash = "d78b23",
  text = "Blueleaf Tuber. Beneath Razorfen Kraul, Blueleaf Tubers grow hidden from the surface. Their rarity draws wealthy gourmands and traders from across the world. Blueleaf Tubers grow beneath Razorfen Kraul in the Barrens. Dense roots and quilboar briars hide them from casual foragers. Though the ground is harsh, wealthy gourmands and traders across the world pay an exorbitant price for their distinct flavor. In Ratchet, the goblin Mebok Mizzyrix devised a way to find the hidden roots. He trains native snufflenose gophers to scent tubers from fifty paces away. Guided by specialized command sticks, adventurers can unearth them before quilboar patrols catch wind of the intrusion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_blueleaf-tuber-68f1176900f2bbefbaff/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["item:book-from-sven-s-farm"] = {
  hash = "5f105b",
  fullHash = "5f105b",
  text = "Book from Sven's Farm. In Duskwood, Sven's ruined farm holds a dirt-stained journal with no title. Its fragments record an unknown onlooker's glimpse of the attack on Sven Yorgen's family. A loose mound of dirt among the charred remains of Sven's farm in southern Duskwood hides a weather-damaged journal. Its anonymous writer left frantic, incomplete notes about the tragedy at the homestead. The pages support Sven Yorgen's suspicion that someone watched from the shadows while his family was slain. The account breaks off without explaining who the writer was or what happened next. Sven's clue leads investigators to carry the book to Darkshire, hoping someone there will recognize the handwriting.",
  ["1"] = {
    {file = "Audio/Transport/full_item_book-from-sven-s-farm-c5242a9ed155b8b9b2c9/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["item:book-stresses-of-iron"] = {
  hash = "625418",
  fullHash = "625418",
  text = "Book: Stresses of Iron. In Stormwind Keep, Margulf Blaggon’s book on metallurgy has been lent to Northshire Abbey for copying. Margulf Blaggon wrote about the practical and theoretical sides of metallurgy. Milton Sheaf cared for the volume in the Royal Library of Stormwind Keep. The library lent it to Northshire Abbey, where Brother Paxton copied it by hand for his own collection. Paxton’s work took far longer than expected, and Brother Kristoff waited anxiously in Cathedral Square for the book to return to the city.",
  ["1"] = {
    {file = "Audio/Transport/full_item_book-stresses-of-iron-a10fab0f20287cf97b67/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["item:bottle-of-disease"] = {
  hash = "b6408d",
  fullHash = "b6408d",
  text = "Bottle of Disease. Forsaken alchemists brew disease near the Dor'Danil Barrow Den in Ashenvale. The bottles hold virulent concoctions found at their encampment. Near the Dor'Danil Barrow Den, Forsaken alchemists brew contagions in an outpost beyond the Warsong Outriders' front lines. The bottles give night elves at Forest Song evidence of an offensive aimed at sickening the woodland soil and wildlife instead of meeting their sentinels in open combat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-disease-099b081b4d9dd4628d4d/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["item:bottle-of-moonshine"] = {
  hash = "2d5967",
  fullHash = "2d5967",
  text = "Bottle of Moonshine. In Darkshire, a bottle of moonshine is sought for Lakeshire’s tavern. Barkeep Daniels needs one while Blackrock orc incursions keep regular supplies from reaching town. Blackrock orcs have cut off Lakeshire’s regular supply caravans. Barkeep Daniels seeks regional drinks to restock the tavern for the guards and townsfolk. One is brewed and sold at the Scarlet Raven Tavern in Darkshire, where locals favor strong drinks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-moonshine-72e210e516f96c238c96/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["item:bottle-of-zombie-juice"] = {
  hash = "39418f",
  fullHash = "39418f",
  text = "Bottle of Zombie Juice. In Darkshire, a Bottle of Zombie Juice is bound for Abercrombie, a reclusive hermit in Duskwood. The potent liquor is brewed from rot blossom, and Abercrombie says he needs it to keep warm. Rot blossoms gathered in Duskwood go into this harsh brew. The bartender in Darkshire warns that it is potent enough to raise the dead. Most folk want nothing to do with such a vile drink, but Abercrombie, an eccentric hermit, says it is the only thing that keeps him warm on the damp, cold nights by his lonely shack.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottle-of-zombie-juice-a553209e69215c1f858e/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["item:bottom-of-gelkak-s-key"] = {
  hash = "0324ba",
  fullHash = "0324ba",
  text = "Bottom of Gelkak's Key. Along Darkshore, the Bottom of Gelkak's Key is one of three fragments of a shattered winding key. It belonged to the shipwrecked gnome pirate Gelkak Gyromast, and reef crawlers scavenged it from the shore. Threshadons sank Gelkak Gyromast's ship off Darkshore, casting the gnome and his belongings ashore. Among them was the winding key that activated his mechanical first mate. The key broke against the coastal rocks into three pieces, and local scavengers descended on the debris. Reef and tide crawlers seized the bottom fragment as they searched the tideline.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bottom-of-gelkak-s-key-1d7804ab2794e808dc9d/1-0000.mp3", duration = 32.2612245, start = 0},
  },
}
P.transport["item:branch-of-cenarius"] = {
  hash = "6da35f",
  fullHash = "6da35f",
  text = "Branch of Cenarius. In eastern Ashenvale, Geltharis holds the Branch of Cenarius, sacred to the dryads. Anilia died defending the relic, and her dying wish was to see it recovered. The Branch of Cenarius is sacred to the dryads who follow the Forest Lord. Anilia and her sister Illiyana treasured it until corrupt satyrs ambushed them. Their leader, Geltharis, seized the branch and mortally wounded Anilia near the tainted ruins of eastern Ashenvale. As she lay dying, Anilia pointed north toward the arch where Geltharis lurks. She pleaded for a champion to take back the bough and return it to the dryads at Forest Song.",
  ["1"] = {
    {file = "Audio/Transport/full_item_branch-of-cenarius-dd224014e3dca5615e8c/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["item:brass-collar"] = {
  hash = "1a9687",
  fullHash = "1a9687",
  text = "Brass Collar. At the Brackwell pumpkin patch, Princess wears a brass collar that Ma Stonefield wants as proof the sow is gone. Princess is a huge, prize-winning sow owned by the Brackwell family. She roams their pumpkin patch east of the Maclure homestead, and her appetite leads her into the Stonefield Farm’s crops. After losing valuable vegetables to the sow, Ma Stonefield seeks someone willing to slay her. Princess wears a brass band around her neck, and the collar proves she will not raid the Stonefield fields again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_brass-collar-15352c71db02dfb963e9/1-0000.mp3", duration = 30.484898, start = 0},
  },
}
P.transport["item:bristleback-attack-plans"] = {
  hash = "f8982c",
  fullHash = "f8982c",
  text = "Bristleback Attack Plans. Bristleback Attack Plans warn of a planned siege on Camp Narache. Quilboar of Brambleblade Ravine drew crude maps and tactical notes for an assault meant to overrun the tauren settlement. The Bristleback quilboar plan a sustained assault on Camp Narache. Their leadership means to push beyond skirmishes along the borders of the Red Cloud Mesa and wipe out the young tauren training there. The plans lie deep within a dirt cave in Brambleblade Ravine. Chief Hawkwind can send word to Bloodhoof Village for reinforcements, giving Camp Narache a chance to blunt the invasion before it begins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-attack-plans-3d100c01ec510b8c4d9c/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["item:bristleback-belt"] = {
  hash = "867971",
  fullHash = "867971",
  text = "Bristleback Belt. In Camp Narache, young tauren gather Bristleback Belts to prove their valor. The belts come from quilboar in Brambleblade Ravine and mark a step in the Rite of Strength. The Red Cloud tribe tests youths who seek respect in Thunder Bluff through the ancient Rites of the Earthmother. The first trial, the Rite of Strength, asks each initiate to protect the tribe from threats. Bristleback quilboar raid food supplies and ambush hunting parties outside Camp Narache. Chief Hawkwind demands their belts in return. Bringing him twelve proves an initiate can face danger and help defend the tribe. Bristleback warriors and shamans in Brambleblade Ravine wear belts made from rough hide, twine, and scrap. A tauren warrior has little use for one as apparel, but its quilboar make marks it as evidence of a slain enemy. Bringing the belts back to the camp circle fulfills the rite's proof.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-belt-1ef6e5f6400efc761ebd/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["item:bristleback-quilboar-tusk"] = {
  hash = "8904ad",
  fullHash = "8904ad",
  text = "Bristleback Quilboar Tusk. Across the northern and central Barrens, Bristleback Quilboar Tusks are taken from slain quilboar. Mankrik gathers them as proof of slaughter and tokens of vengeance. Bristleback quilboar defend their territory across the Barrens against Horde expansion. Their jagged ivory tusks serve as weapons in close combat. Mankrik, a veteran orc warrior stationed at the Crossroads, lost his wife in a vicious quilboar ambush. He gathers dozens of tusks as retribution, a bloody count of the suffering he means to return to the Bristlebacks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bristleback-quilboar-tusk-6d0017b4c23f8ad867c6/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["item:brock-s-list"] = {
  hash = "cd50f7",
  fullHash = "cd50f7",
  text = "Brock's List. Brock's List carries the names of mining pupils honored by the guild halls in Ironforge. Brock Stoneseeker, the mining instructor in Thelsamar, compiles the dispatch for students who earn honorary picks. In Thelsamar, Brock Stoneseeker records the mining pupils who prove their skill. Apprentices must show what they can do before taking on serious work in Khaz Modan's veins. The honored students earn picks from the guild halls in Ironforge, marks of their skill as miners. Brock's List travels from Thelsamar to the Deep Mountain Mining Guild in Ironforge's Great Forge. A gryphon carries the dispatch from Thelsamar's roost to Golnir Bouldertoe. There, the students' names are engraved on their honorary picks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_brock-s-list-8f37fb29b14a7dbf0f71/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["item:broken-and-battered-samophlange"] = {
  hash = "cc7b2f",
  fullHash = "cc7b2f",
  text = "Broken and Battered Samophlange. In the northern Barrens, Venture Company machinery lies battered after a failed inspection. The damaged samophlange must reach goblin experts in Orgrimmar, where someone may understand how it works. The Venture Company made samophlanges for its resource work in the northern Barrens. Wenikee Boltbucket tried to inspect and modify one, adding gauges, levers, and dials to measure its stability. Her tinkering weakened the mechanism instead, leaving it battered and close to ruin. Knowing more additions might make it fail completely, she sent the fragile device to someone with factory experience. Repairing the device calls for someone who has worked on Venture Company production lines. Rilli Greasygob, a former Venture employee, works at Nogg's Machine Shop in Orgrimmar's Valley of Honor. The battered apparatus catches the engineer's eye. Anyone who scavenges from goblin operations may seem daring, or simply foolhardy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-and-battered-samophlange-7286f8352aab6745806d/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["item:broken-samophlange"] = {
  hash = "9663e4",
  fullHash = "9663e4",
  text = "Broken Samophlange. In the northern Barrens, a broken samophlange draws the notice of curious engineers. Its gears and shifting parts hint at a purpose no one has uncovered. The broken samophlange is a baffling contraption from the northern Barrens. Its moving assemblies and fine gears show careful workmanship, even in ruin. Sputtervalve, a goblin in Ratchet, damaged the delicate device by accident before anyone could document how it worked. The finder hoped to send working results to curious colleagues in Undermine, so they sought someone able to repair it. Wenikee Boltbucket, a clever tinkerer near the border outpost of Mor'shan Rampart, was the one they turned to. Wenikee Boltbucket cannot tell what a samophlange is meant to do, even after examining its ruined parts. Its clockwork sounds and shifting motion catch her interest, though. Rather than discard it as junk, she sets out to repair the device and see its mechanisms working at full capacity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-samophlange-2e55de347093ca7ad792/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["item:broken-tools"] = {
  hash = "76fb06",
  fullHash = "76fb06",
  text = "Broken Tools. At the dig northwest of Bloodhoof Village, dwarven picks lie broken on the forge. Baine Bloodhoof wants proof that the excavation threatening Mulgore's land and wildlife has been stopped. Northwest of Bloodhoof Village, dwarven excavators dig into Mulgore's hills in search of ancient history. The tauren see their work as a defilement of the Earth Mother. The digging's noise and destruction agitate the local wildlife, especially the roaming kodo herds. Young Baine Bloodhoof orders defenders to take the prospectors' iron picks and break them at a forge. With their picks ruined, the expedition cannot gouge further into the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_broken-tools-b21d852fec406aa45c18/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:bundle-of-crocolisk-skins"] = {
  hash = "ae8874",
  fullHash = "ae8874",
  text = "Bundle of Crocolisk Skins. In the Wetlands, hunters prepare crocolisk skins for Menethil Harbor. The hides are valuable trade goods for local leatherworkers. Crocolisk hides are an essential trade good for coastal Menethil Harbor. Hunters gather and cure the tough, water-resistant skins in the Wetlands before sending them west to artisans such as James Halloran. Einar has gathered this bundle, but asks a traveler to carry it into town. He wants to avoid returning home to face the temper of his frustrated wife, Sida.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-crocolisk-skins-21c55e6f7cfe38079583/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["item:bundle-of-hides"] = {
  hash = "5b2d32",
  fullHash = "5b2d32",
  text = "Bundle of Hides. Across the Barrens, a Bundle of Hides travels toward Thunder Bluff with the Horde’s wind riders. The cured skins are a straightforward courier shipment for the leatherworkers, and their delivery introduces travelers to the wind rider network. Hunters skin the beasts of the Barrens for cured hides. The plains hold vast herds of kodo, prowling lions, and roving raptors. These skins supply the leatherworkers of Thunder Bluff, who turn them into gear, pouches, armor, and bindings for the Horde. Couriers carry the bundle from the Crossroads to Thunder Bluff on Devrak’s trained wyverns. Overland travel through the Barrens and into Mulgore is slow and dangerous, with roaming quilboar and centaur raiders. Handing the hides to a wind rider courier shows how swiftly air travel can cross Kalimdor’s fractured terrain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-hides-32a4ee255efbb797507a/1-0000.mp3", duration = 46.4979592, start = 0},
  },
}
P.transport["item:bundle-of-wood"] = {
  hash = "b52500",
  fullHash = "b52500",
  text = "Bundle of Wood. Near Eastvale Logging Camp, Bundle of Wood waits in the trees for an urgent shipment west. Freshly chopped timber from Eastvale Logging Camp helps supply the Kingdom of Stormwind. The camp sends wood west for town buildings and other construction. Bears and wolves have pushed into the groves northwest of camp, and terrified loggers fled, leaving their freshly gathered Bundles of Wood among the trees. With delivery deadlines close, overseer Raelen needs travelers to pass the predators and recover the timber before the lumber contracts are breached.",
  ["1"] = {
    {file = "Audio/Transport/full_item_bundle-of-wood-ef9c9110593fc0ed38b5/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:burning-blade-medallion"] = {
  hash = "809e80",
  fullHash = "809e80",
  text = "Burning Blade Medallion. Cultists in the Valley of Trials carry the Burning Blade Medallion. Yarrog Baneshadow holds it deep in the Burning Blade Coven, where its dark magic threatens Durotar's young warriors. Zureetha Fargaze's divinations point to the medallion in the Burning Blade Coven. Yarrog Baneshadow, an agent of the Burning Blade cult, carries it deep inside the winding caverns. The trinket channels dark power among the cult's impish familiars and felstalkers. Defeating Yarrog and taking the medallion ends the cult's attempt to undermine the Horde's training grounds from within Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-blade-medallion-d37e351444cfcd71e87d/1-0000.mp3", duration = 33.3583673, start = 0},
  },
}
P.transport["item:burning-blood-quest-item"] = {
  hash = "9eabef",
  fullHash = "9eabef",
  text = "Burning Blood (quest item). In Duskwood, Burning Blood is gathered from the Nightbane worgen. Grimand Elmore needs twenty vials for experiments in smithing. Nightbane worgen prowl Duskwood with a strange fury, and their blood burns with real heat. The fluid can be drawn from worgen haunting the timberlands and Roland's Doom. Though foul to gather, its heat draws the interest of armorers seeking to temper resilient plate. Grimand Elmore works as an armorer in Stormwind's Dwarven District. He wants to test smithing methods developed by his former student Furen Longbeard. For the experiment, Elmore needs Burning Blood and a dense burning rock held by the worgen chieftain Gutspill. Those who bring back the bubbling fluid are promised sturdy warrior armor from his forge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-blood-quest-item-cbab577e8ee2b3b86ff0/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["item:burning-rock"] = {
  hash = "4217b2",
  fullHash = "4217b2",
  text = "Burning Rock. In Duskwood, Burning Rock smolders in the depths of Roland's Doom. Gutspill, leader of the Nightbane worgen, carries it, and Grimand Elmore in Stormwind needs it with fiery worgen blood to forge enchanted armor for promising warriors. Gutspill carries Burning Rock through the shafts of Roland's Doom. Grimand Elmore in Stormwind wants its heat for armor made with fiery worgen blood. He is testing smithing techniques developed by his peer Furen Longbeard, to make tough plates for veteran fighters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_burning-rock-43b063378b0d928001e7/1-0000.mp3", duration = 29.1526531, start = 0},
  },
}
P.transport["item:cache-of-zanzil-s-altered-mixture"] = {
  hash = "15382a",
  fullHash = "15382a",
  text = "Cache of Zanzil's Altered Mixture. At the Venture Company tower near the Sludge Fen, a stockpile of potent poison lies locked away. The mixture bears the name of Zanzil, a jungle troll witch doctor, and draws the Shattered Hand's attention. North of the Sludge Fen in the Barrens, the Venture Company holds a tower outpost. At its summit, Grand Foreman Puzik Gallywix keeps a cache of altered mixture bearing the name of the troll witch doctor Zanzil in his private strongbox. A poison has weakened everyone in the tower, leaving its goblin inhabitants vulnerable to a bold intruder.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cache-of-zanzil-s-altered-mixture-af8c14963f91de74606b/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:cactus-apple"] = {
  hash = "e419d5",
  fullHash = "e419d5",
  text = "Cactus Apple. In the Valley of Trials, Cactus Apples offer orcs a rare source of moisture in Durotar's dry heat. Cactus apples grow in clusters around the thick cactuses scattered across the Valley of Trials. Gathering them means working among the thorns, but the fruit gives welcome hydration in Durotar's heat. Galgar, an orc in the valley, gathers the apples to make Cactus Apple Surprise, a cooling treat for recruits enduring their early training.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cactus-apple-092bbcfa9868997a8d06/1-0000.mp3", duration = 25.5477551, start = 0},
  },
}
P.transport["item:calor-s-note"] = {
  hash = "764249",
  fullHash = "764249",
  text = "Calor's Note. In Duskwood, Calor's Note carries a woodsman's recommendation to Master Jonathan Carevin. Calor writes it on a scrap of faded parchment for a tested adventurer, opening a path to a hidden band that fights beside Darkshire's militia but remains apart from it. Calor is notoriously hard to impress, and Duskwood offers strangers little warmth. When an adventurer survives the bloodthirsty worgen stalking the woods, Calor's respect is earned, and he writes a brief message. The faded note travels to Darkshire, where it introduces the outsider directly to Jonathan Carevin. Darkshire relies on the Night Watch for public defense, while Calor and Carevin pursue a grimmer, hidden fight. Calor laments that the town guard outnumbers them and hopes to find enough capable fighters to advance their private war. When the note is handed over, it grants entry to Carevin's campaign against demons, undead, and the hidden sympathizers aiding Duskwood's decline.",
  ["1"] = {
    {file = "Audio/Transport/full_item_calor-s-note-fbe3dbdcd1e2a501bba6/1-0000.mp3", duration = 53.7861224, start = 0},
  },
}
P.transport["item:candle-of-beckoning"] = {
  hash = "447ca0",
  fullHash = "447ca0",
  text = "Candle of Beckoning. On Brightwater Lake, Gunther Arcanus keeps an enchanted candle for a summons. Light it on a nearby islet, and the restless spirit Lillith Nefara answers. Gunther Arcanus keeps the Candle of Beckoning in a crate beside him on his island in Brightwater Lake. The candle is an instrument for a ritual of summoning. Gunther is a fiercely independent undead sorcerer who broke free of the Lich King's command on his own, and he remains wary of both the Scourge and the Forsaken. To show Gunther that you are not loyal to the Lich King, carry one of the candles southwest to a smaller islet. Set it on an old, bloodstained table and light it. The flame pierces the veil between worlds and beckons the dormant, restless shade of Lillith Nefara, a powerful Scourge agent, so she can be destroyed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_candle-of-beckoning-244c245c6f2c723680f5/1-0000.mp3", duration = 47.4644898, start = 0},
  },
}
P.transport["item:cantation-of-manifestation"] = {
  hash = "ee9e49",
  fullHash = "ee9e49",
  text = "Cantation of Manifestation. In the Undercity, Anastasia Hartwell gives apprentices a scroll to reveal unseen magical beings in Algernon's shop. The Cantation of Manifestation reveals beings hidden by magic. Anastasia Hartwell keeps the scroll in the Magic Quarter and entrusts it to capable mages sent to contain rogue magical anomalies. Read aloud where arcane instability troubles the air, such as Algernon's alchemical workshop in the Apothecarium, its words force stray rift spawns into sight. The caster can then subdue them and trap them in containment coffers for further study.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cantation-of-manifestation-e2f76477abada9511442/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["item:canvas-scraps"] = {
  hash = "2bb783",
  fullHash = "2bb783",
  text = "Canvas Scraps. At Razor Hill, Furl Scornbrow gathers Canvas Scraps to make travel sacks for new Horde recruits. The cloth comes from human invaders and centaur tribes in Durotar. Kul Tiras marines and sailors carry canvas along Durotar’s eastern shore. Their gear and sails leave scraps behind. Inland, Kolkar centaur reuse coarse cloth taken from supply caravans and past conflicts. Their camps and gear hold scraps that can be salvaged. Furl Scornbrow watches for invaders from the Razor Hill watchtower. The aging veteran has left his fighting days behind, but puts salvaged enemy cloth to use. He stitches it into sturdy carrying bags for younger soldiers, helping the new generation defend the Horde’s borders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_canvas-scraps-91b58a1b5693d5891c3f/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["item:cask-of-merlot"] = {
  hash = "e2791d",
  fullHash = "e2791d",
  text = "Cask of Merlot. In Stormwind, Cask of Merlot supplies Lakeshire while Blackrock orcs cut its trade routes. Harvested and fermented in the heart of the kingdom, the merlot comes from the Galina Winery's cellars. The winery lies along the canals bordering Stormwind's Trade District, where winemaker Roberto Pupellyverbos tends its vintages for the capital's refined tastes. Unlike Duskwood moonshine or Elwynn spirits, this wine reflects the craft of human vintners working within the city's walls. When the Blackrock clan invaded the Redridge Mountains, supply routes failed and Lakeshire lost its usual merchant shipments. With locals parched and terrified, Barkeep Daniels sends willing couriers across the kingdom to refill his tavern's cellars. The cask gives defenders and refugees by Lake Everstill a gentle drink to wash down their rations.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-merlot-3b4841694624b6827147/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:cask-of-scalder"] = {
  hash = "d134a9",
  fullHash = "d134a9",
  text = "Cask of Scalder. In Stormwind, a cask of Barleybrew Scalder is on its way to an old acquaintance. The fiery ale carries a favor between dwarves. Travelers who have proved themselves across the Rethban Gauntlet carry Barleybrew Scalder to Furen Longbeard in Stormwind's Dwarven District. The dwarf is an artisan shieldsmith, and he considers dry times intolerable. A cask of the warming ale gives Yorus Barleybrew a way to call in an old favor and secure fine dwarven craftsmanship.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-scalder-e29d45e35c0f0479c435/1-0000.mp3", duration = 26.2791837, start = 0},
  },
}
P.transport["item:cask-of-shimmer-stout"] = {
  hash = "82dc17",
  fullHash = "82dc17",
  text = "Cask of Shimmer Stout. In Dun Morogh's cold heights, Cask of Shimmer Stout is bound for the eastern mountains. Rejold Barleybrew brewed the potent new ale, and his brother sends a cask east as a gift for fellow dwarven mountaineers. Rejold Barleybrew brews Shimmer Stout in Brewnall Village, where local patrons and mountaineers who brave Dun Morogh's biting frosts take to it quickly. Impressed by his brother's brew, Mountaineer Barleybrew commissions a cask to be hauled through the eastern pass into Loch Modan. Dwarves prize strong drink for company and for warmth in the mountain chill. Sharing a fresh brew with comrades on distant patrols is a military tradition. During his watch in Thelsamar, Mountaineer Kadrell opens the cask and samples the brew. Shimmer Stout lives up to its reputation: one draught is said to lighten the limbs and make a soldier feel as though he could fly. It is the sort of invigorating drink a dwarven scout might welcome on a long, lonely patrol along the high roads.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cask-of-shimmer-stout-790f5dd354a8112c08a9/1-0000.mp3", duration = 55.6930612, start = 0},
  },
}
P.transport["item:cats-eye-emerald"] = {
  hash = "423bf5",
  fullHash = "423bf5",
  text = "Cats Eye Emerald. In the northern Barrens, the Cats Eye Emerald has drawn the eye of Ratchet's Wharfmaster Dizzywig. Venture Company bosses keep the fist-sized gem under guard at Boulder Lode Mine. Venture Company laborers struck a massive emerald at Boulder Lode Mine, northeast of the Sludge Fen. Word of the find spread quickly across the savanna. In goblin country, rare gemstones seldom stay secret. Trade gossip carried news from Ratchet's docks to Booty Bay, and Wharfmaster Dizzywig heard of the prize. He began plotting to send it to the open market in Undermine. Venture Company management keeps the emerald inside the mine under heavy guard. Overseers, Enforcers, and chief operators such as Boss Copperplug defend it from rival cartels and fortune-hunters. Dizzywig has promised a fifty-percent cut to those who help him secure the gem.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cats-eye-emerald-83346dbf2aaabfca073e/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["item:cenarion-lunardust"] = {
  hash = "6ad363",
  fullHash = "6ad363",
  text = "Cenarion Lunardust. Turak Runetotem gives Cenarion Lunardust to young tauren druids on Thunder Bluff. They use it to awaken Lunaclaw at an ancient Moonkin Stone between Mulgore and the Barrens. Cenarion Lunardust carries the Cenarion Circle’s blessing for druids ready to join the Druids of the Claw. At the Moonkin Stone west of Camp Taurajo, the dust calls Lunaclaw, a sacred beast bound to test each initiate. Defeating the guardian tests strength and resolve. The trial teaches the young druid the strength of body and heart needed to take the form of a bear.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cenarion-lunardust-6eea4ae59c64e4e4e351/1-0000.mp3", duration = 30.4065306, start = 0},
  },
}
P.transport["item:cenarion-moondust"] = {
  hash = "d2a100",
  fullHash = "d2a100",
  text = "Cenarion Moondust. At the Moonkin Stone east of Auberdine, Cenarion Moondust calls forth Lunaclaw. Night elf druids use the sacred powder in their trial to become Druids of the Claw. Mathrengyl Bearwalker gives Cenarion Moondust to young druids in Darnassus for their final trial of heart and body. To face Lunaclaw, the guardian, an initiate travels to the moonkin dens east of Auberdine in Darkshore. Scattered on the ancient Moonkin Stone, the powder summons Lunaclaw to test the druid in combat. Through the trial, the initiate takes in the enduring strength needed to channel the bear form.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cenarion-moondust-554ae7e318cb008b5aea/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["item:centaur-bracers"] = {
  hash = "2288ad",
  fullHash = "2288ad",
  text = "Centaur Bracers. Across the Barrens, Centaur Bracers are stripped from slain Kolkar warriors. Regthar Deathgate gathers them west of the Crossroads as proof that centaur raiders have been culled. Kolkar raiders threaten the Horde’s foothold across the Barrens. Their fallen warriors leave behind leather and iron bracers, proof that a raider has been removed from the trade roads. Regthar Deathgate, an orc scout stationed on the bluffs west of the Crossroads, offers a standing bounty for these trophies to curb the tribe’s aggression.",
  ["1"] = {
    {file = "Audio/Transport/full_item_centaur-bracers-f90057d8cd729d05a429/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["item:charred-horn"] = {
  hash = "ec4738",
  fullHash = "ec4738",
  text = "Charred Horn. Charred Horns are the rugged, heat-baked horns harvested from youthful chimaeras dwelling in the crags of the Stonetalon Mountains. Tough enough to withstand harsh elemental forces, they serve as an essential tempering component in specialized armorsmithing. Harvested from fledgling and young chimaeras nesting across the craggy heights of the Stonetalon Mountains, Charred Horns are coveted for their unnatural resistance to flame and blunt force. The dwarven armorsmith Furen Longbeard, working from his forge in Stormwind, requires a collection of these horns to craft fire-hardened mail. Combined with venomous spider fangs from the Wetlands, phlogiston from Razorfen Kraul, and the galvanized horn of a chimaera matriarch, these calcified horns provide the core structural reinforcement necessary to produce an exceptionally resilient suit of protective armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_charred-horn-f6832e4c94ab8e8592eb/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["item:chest-of-containment-coffers"] = {
  hash = "61ef45",
  fullHash = "61ef45",
  text = "Chest of Containment Coffers. Mages in the Undercity keep the Chest of Containment Coffers close at hand. Its enchanted vessels can secure unstable magical phenomena. Invisible arcane creatures can emerge from experiments or sudden rifts between planes. Ordinary cages cannot hold beings made of magic. The Chest of Containment Coffers holds enchanted vessels that bind subdued creatures alive. Senior instructors keep the chest nearby, including Anastasia Hartwell in the Undercity and Jennea Cannon in Stormwind. They give initiates the coffers for surveying anomalies before those forces can unsettle their surroundings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chest-of-containment-coffers-839368055f84e106393b/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["item:chief-sharptusk-thornmantle-s-head"] = {
  hash = "fe847d",
  fullHash = "fe847d",
  text = "Chief Sharptusk Thornmantle's Head. Chief Sharptusk Thornmantle's Head marks the end of a threat to Red Cloud Mesa. The Bristleback leader threatened the young tauren braves, and his head was recovered from deep in Brambleblade Ravine as proof of victory. The Bristleback quilboar of Brambleblade Ravine have attacked the tribes of Camp Narache. Their chieftain, Sharptusk Thornmantle, urges them on. The tauren seek to protect their homeland in Mulgore with vigilance and strength. Sharptusk's head proves he is dead and warns the surviving quilboar clans against encroaching on the mesa borders. Brave Windfeather demands Sharptusk's head as a rite of passage for young hunters and tribal defenders. Facing an enemy clever enough to strike back and lead a war band tests a young combatant's martial skill. Presenting the head fulfills that trial and earns the young fighter a reputation among the braves of Red Cloud Mesa.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chief-sharptusk-thornmantle-s-head-806e9f7eb5fe34c3e3c5/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["item:chok-sul-s-head"] = {
  hash = "76ab19",
  fullHash = "76ab19",
  text = "Chok'sul's Head. In Thelsamar, Chok'sul's Head proves the Mo'grosh chieftain is dead. Magistrate Bluntnose requires it before paying the bounty set by local dwarven authorities. Ogres from Mo'grosh Stronghold threaten Loch Modan's settlements. They attack Thelsamar, excavation sites, and the Stonewrought Dam. Magistrate Bluntnose placed a bounty on Chok'sul, the brute believed to direct these assaults. The northeastern hills are in turmoil, so the magistrate demands clear proof before releasing township funds. Chok'sul's severed head gives the dwarven council the certainty it needs to mark the bounty fulfilled.",
  ["1"] = {
    {file = "Audio/Transport/full_item_chok-sul-s-head-f657593d79e2819615ef/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["item:clarice-s-pendant"] = {
  hash = "712c7f",
  fullHash = "712c7f",
  text = "Clarice's Pendant. In the Pools of Vision in Thunder Bluff, Clarice Foster keeps a bitter reminder of the family she lost. Her pendant came from her former husband, Yuriv, whose devotion to the Light left Clarice and their children behind. Clarice's Pendant recalls the life Clarice Foster lost before she became Forsaken. Before the Third War consumed Lordaeron, her husband Yuriv left her and their children to fight the undead. He believed devotion to the Holy Light came before all else. Yuriv died, and his family was left to fall to the very Scourge he had set out to fight. Clarice does not treasure the pendant he gave her. To her, it is an insult, a reminder that she and the children came second to his zeal and duty.",
  ["1"] = {
    {file = "Audio/Transport/full_item_clarice-s-pendant-eb08ae8f83f1911e9522/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["item:claw-key"] = {
  hash = "79442d",
  fullHash = "79442d",
  text = "Claw Key. Within the Talon Den atop Stonetalon Peak, three druidic keys open the enchanted hoard. High on Stonetalon Peak, night elf druids built the Talon Den as a sanctuary and a storehouse for powerful relics. They hid the treasures behind several layers of protection. Three enchanted locks seal the hoard: the Barrow Key, the Sleepers' Key, and the Claw Key. Each key lies in its own druidic cache, shaped like a torch and hidden in the winding tunnels of the barrow den. The druids kept the keys guarded and out of easy reach. Near the barrow entrance lies the Gatekeeper's Key, needed to open the cache that holds the Claw Key. The Claw Key is vital to breaking the druids' seal and claiming the riches hidden deep within the mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_claw-key-a0e9bf13a0d2e324ddaa/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:cliffspring-river-sample"] = {
  hash = "ac356b",
  fullHash = "ac356b",
  text = "Cliffspring River Sample. In Darkshore, foul water gathers at the base of the Cliffspring River waterfall. Drawn for Thundris Windweaver in Auberdine, the vial shows that corruption is moving toward the coast. The Cliffspring River runs from Darkshore's eastern heights, past ancient stone bridges, and into the sea at Mist's Edge. Its clear waters have turned foul and visibly corrupted. Thundris Windweaver, a night elf in Auberdine, fears the tainted flow will reach the settlement's shore and water supply. He sent travelers to draw water from the pool beneath the river's lower waterfall. The sample confirms that unnatural rot is moving downstream toward the coast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cliffspring-river-sample-d4a3df7909cfb0a4888d/1-0000.mp3", duration = 37.0677551, start = 0},
  },
}
P.transport["item:cloth-request"] = {
  hash = "7cb53d",
  fullHash = "7cb53d",
  text = "Cloth Request. At the Canal Tailor and Fit Shop, Rema Schneider receives Harlan Bagley's request for fresh cloth and knitted goods. His shelves are emptying quickly. Harlan Bagley asks Rema Schneider for a fresh supply of knitted garments and cloth. Bagley notes a sudden and unsettling surge in trade: citizens and travelers are buying armor and sturdy clothing as if bracing for a brutal season. The rush leaves Rema puzzled and wary. The House of Nobles has announced no open war, so Rema wonders why city folk are quietly armoring themselves and whether the crown's leaders are hiding unrest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cloth-request-dd9fa37cfc6e7df38b82/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
P.transport["item:cloven-hoof"] = {
  hash = "19d326",
  fullHash = "19d326",
  text = "Cloven Hoof. Deep in Thousand Needles, the Galak centaur guard the Cloven Hoof within a sacred flame at Splithoof Hold. Tauren scholars seek to understand the strange energy rising from the relic. At the heart of Splithoof Hold, the Galak centaur keep the Cloven Hoof in an ancient brazier. Magical fire surrounds the relic, and blessed water must quench the flame for a moment before anyone can handle it. The centaur clans are divided and violent, yet their care for the brazier points to a ritual bound to their origins. At Freewind Post, Rau Cliffrunner and other tauren observers hope the strange aura of the hoof will teach them about the centaur who have long troubled Kalimdor's plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cloven-hoof-7f6f0be49b36c21212ff/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["item:comar-s-heart"] = {
  hash = "4d2e53",
  fullHash = "4d2e53",
  text = "Comar's Heart. In the Undercity, warlocks seek Comar's Heart to draw a succubus into their service. The heart belonged to Comar Villard, a human searching the Wetlands for his lost wife. Comar Villard keeps searching the Wetlands for his lost wife. Though turmoil has swept the Eastern Kingdoms, he refuses to abandon the search. Carendin Halgar's disciples in the Undercity judge his fidelity among the rarest and purest. To bind a succubus, a creature both capricious and predatory, warlocks need devotion like his as bait. Comar's steadfast love marks him for slaughter, and his heart becomes the lure for a demonic servant.",
  ["1"] = {
    {file = "Audio/Transport/full_item_comar-s-heart-43fc44c835a64cc8f6a3/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["item:consecrated-rune"] = {
  hash = "8ae1a5",
  fullHash = "8ae1a5",
  text = "Consecrated Rune. In Coldridge Valley, the Consecrated Rune calls fledgling dwarven paladins to Anvilmar. Bromos Grummner sends them to begin their formal duties as Knights of the Silver Hand. A Consecrated Rune marks a novice dwarf’s place among the Knights of the Silver Hand. Dwarven paladins receive one in Coldridge Valley after proving basic skill in arms. Sacred words are inscribed on the rune, and the Holy Light blesses it. Bromos Grummner, the paladin trainer inside Anvilmar, sends the rune as an official summons. Dwarves hold great respect for the Holy Light traditions their human allies introduced to them. Reading the rune confirms the novice’s place in the order and marks a passage into its service.",
  ["1"] = {
    {file = "Audio/Transport/full_item_consecrated-rune-7a84a1c1cda1eb2fe672/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["item:console-key"] = {
  hash = "0521af",
  fullHash = "0521af",
  text = "Console Key. At the Venture Company digsite in the Barrens, Tinkerer Sniggles holds the Console Key. It unlocks the main control terminal and lets the samophlange be removed once the apparatus is shut down. The Venture Company runs an industrial outpost in the northern Barrens. Its steam-driven machinery depends on a device called a samophlange. The console is locked against unauthorized hands, and only Tinkerer Sniggles, the chief technician on site, carries the Console Key. The key opens the terminal casing so the rig can be powered down.",
  ["1"] = {
    {file = "Audio/Transport/full_item_console-key-1375307f256e4ecee377/1-0000.mp3", duration = 31.6081633, start = 0},
  },
}
P.transport["item:control-console-operating-manual"] = {
  hash = "91ebed",
  fullHash = "91ebed",
  text = "Control Console Operating Manual. At the Venture Company site southwest of Sludge Fen, the Control Console Operating Manual guides workers through the machinery. It explains how to close the valves and disengage the samophlange. Southwest of Sludge Fen, the Venture Company runs a drilling and research site in the northern Barrens. Its machinery links gauges, pressurized valves, and mechanisms to a device called a samophlange. Without the right instructions, working the volatile controls can cause a dangerous failure or lock the system. The manual gives the valve sequence for disengaging the core apparatus without triggering an explosive failure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_control-console-operating-manual-020bd6e54149e2a8f1ee/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:corroded-shrapnel"] = {
  hash = "4bc15a",
  fullHash = "4bc15a",
  text = "Corroded Shrapnel. In Stonetalon, jagged metal remains lodged deep inside corrupted treants. The Venture Company’s retreating munitions left fragments in the forest’s protectors, now sought for study. When the Venture Company was driven from Stonetalon’s groves, its goblins used reckless munitions to cover their escape. Explosive shrapnel tore into the valley’s defending treants, lodging deep within their bark and core. The ancient guardians slowly succumbed to corruption. Their wood blackened, and their fury turned against anyone entering the vale. Kaela Shadowspear seeks the rusted fragments so Gaxim Rustfizzle, a gnome, can study how the weapons brought on the treants’ corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corroded-shrapnel-efda1a504d363fc4cfd1/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["item:corrupt-manifestation-s-bracers"] = {
  hash = "c7173a",
  fullHash = "c7173a",
  text = "Corrupt Manifestation's Bracers. Tainted bracers lie on the coast of Silverpine Forest, remnants of a corrupted water elemental. Shaman initiates recover them during the Call of Water and cast them into the Brazier of Everfount with pure water to cleanse the shrine and summon a pure water spirit. The Scourge's plague reached the spirits of Lordaeron. Along Silverpine Forest's misty coast, west of the Sepulcher, a sacred water shrine fell to corruption. Its water manifestation became an aggressive shade. Shaman initiates must defeat it and recover its bracers. At the Brazier of Everfount, they cast the bindings into the flame with pure water, lifting the corruption and calling forth an unblemished water spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupt-manifestation-s-bracers-9c5aa8a861f62cc3f406/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:corrupted-brain-stem"] = {
  hash = "b98498",
  fullHash = "b98498",
  text = "Corrupted Brain Stem. In Blackfathom Deeps and along Ashenvale's coast, Corrupted Brain Stem specimens come from twisted naga and satyrs. Gershala Nightwhisper of Auberdine studies the deformities caused by reckless magic. Night elf scholars hope the findings can help keep the blood elves from suffering the same fate. Naga and satyrs bear the marks of forbidden magic and demonic pacts. Long ago, reckless kaldorei highborne became serpent-like aquatic beasts and demonic horned fiends. Their brain stems show heavy physical mutation, proof of how deeply corruptive energies altered the nervous systems of beings who were once elves. Gershala Nightwhisper watches troubling rumors about the blood elves of the Eastern Kingdoms from Auberdine. She fears their use of demonic sorcery will create another generation of monsters on Azeroth, so she sends adventurers into Blackfathom Deeps. By examining naga and satyr tissues, she hopes to trace magical degeneration before another elven culture is lost.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupted-brain-stem-5071a9044e62b4601c28/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["item:corrupted-kor-gem"] = {
  hash = "42e464",
  fullHash = "42e464",
  text = "Corrupted Kor Gem. Around Blackfathom Deeps, naga rites leave Kor gems corrupted. Spellcasters prize the stones for holding arcane force, but this taint must be cleansed before a gem can be used in righteous smithing. Kor gems can capture and hold great stores of magic, making them prized by sorcerers and enchanted smiths. Near the ruins of Blackfathom Deeps, naga oracles and tide priestesses claim the stones for their shadowy rites. Their foul enchantments warp each gem with corruption from the sea. The taint does not drain the stone's latent power, so those who need a potent focus still seek gems among the naga.",
  ["1"] = {
    {file = "Audio/Transport/full_item_corrupted-kor-gem-89032dcd36ce4016db0f/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["item:cougar-claws"] = {
  hash = "536028",
  fullHash = "536028",
  text = "Cougar Claws. Across Mulgore’s central plains, tauren hunters gather Cougar Claws for a cleansing ritual. The claws come from flatland cougars, among the grasslands’ apex hunters. Flatland cougars rank among the apex hunters of Mulgore’s grasslands, stalking prey by instinct. For the tauren, taking their claws is neither casual slaughter nor trophy hunting; it gathers the beast’s natural spirit. When goblin operations defile the plains’ ancestral waters, Mull Thunderhorn asks young hunters to collect Cougar Claws alongside prairie stalker claws. The tauren believe native beasts’ pure predatory instincts can be woven into a ritual totem. They mean to use it to scour unnatural toxins and foul sorcery from the poisoned Thunderhorn Water Well.",
  ["1"] = {
    {file = "Audio/Transport/full_item_cougar-claws-8ce17605a49a2a0a5e63/1-0000.mp3", duration = 44.2253061, start = 0},
  },
}
P.transport["item:courser-eye"] = {
  hash = "355b31",
  fullHash = "355b31",
  text = "Courser Eye. Coursers roam the highlands of Stonetalon, where Courser Eye is gathered for a troll witch doctor's brew. Witch Doctor Jin'Zil in Malaka'jin wants many eyes for a concoction he calls forest magic.",
  ["1"] = {
    {file = "Audio/Transport/full_item_courser-eye-a2a82a632d6a03e3b274/1-0000.mp3", duration = 12.277551, start = 0},
  },
}
P.transport["item:covert-ops-pack"] = {
  hash = "c8b60b",
  fullHash = "c8b60b",
  text = "Covert Ops Pack. In Stonetalon, the Covert Ops Pack equips Alliance agents to sabotage Venture Company sites and steal their plans. Its charges and schematics target the company’s work in Windshear Crag. The Covert Ops Pack carries charges and plans for strikes inside Venture Company territory. Red and blue NG-5 explosives pair with remote detonators, while Plan Alpha and Plan Beta give agents instructions. The explosives target the Cragpool Lake lumber mill and the eastern mine. As goblins rush to fight fires and inspect broken machinery, an infiltrator can slip through the confusion and take documents and schematics. The pack serves both the night elf Sentinels and Alliance engineers in Stonetalon. Its blasts and theft hinder the clear-cutting and excavation of the sacred mountainside. The stolen Venture Company engineering plans also offer insight into goblin heavy machinery. They show where the machines can fail and give Alliance engineers ideas to adapt for their own designs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_covert-ops-pack-7bf098a116fa2813a9fa/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["item:crate-of-crash-helmets"] = {
  hash = "b2b108",
  fullHash = "b2b108",
  text = "Crate of Crash Helmets. A heavy supply shipment of dwarven Siege Engine headgear destined for the Shimmering Flats in Thousand Needles. The sturdy helmets are urgently required by the Brassbolts brothers to protect test drivers from concussions caused by their experimental rocket cars. Out across the blinding white expanse of the Shimmering Flats, gnome engineers test the absolute limits of mechanical propulsion. Unfortunately for the test pilots, the experimental rocket cars designed by the Brassbolts brothers move far faster than their steering can reliably handle. With drivers routinely suffering violent crashes and head trauma, ordinary leather caps no longer suffice. To prevent their roster of willing daredevils from vanishing entirely, heavy-duty dwarven Siege Engine helmets are packed and dispatched across the sea to keep drivers conscious—and alive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-crash-helmets-6c8d367f2b359bcfbe03/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:crate-of-horseshoes"] = {
  hash = "59fe8d",
  fullHash = "59fe8d",
  text = "Crate of Horseshoes. In Elwynn, fifty iron horseshoes are bound for Lakeshire. Smith Argus forged fifty fresh horseshoes in Goldshire, then packed the crate and hammered it shut. Verner Osgood commissioned them for Lakeshire, where constant pressure from gnolls and orcs leaves local craftsmen reliant on Elwynn for essential metal goods. The delivery answers Verner's desperate need for equipment, and Argus includes a stern bill of sale so the Redridge craftsman knows frontier survival comes at a steep price.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-horseshoes-bfeca3e73b21c4894454/1-0000.mp3", duration = 29.0742857, start = 0},
  },
}
P.transport["item:crate-of-inn-supplies"] = {
  hash = "93fe4b",
  fullHash = "93fe4b",
  text = "Crate of Inn Supplies. In Coldridge Valley, the Crate of Inn Supplies waits for a journey to Kharanos. Troggs have cut off the mountain pass, so the Thunderbrew Distillery depends on travelers to carry its goods. The Crate of Inn Supplies is waiting near Anvilmar for a safe way through Coldridge Pass. Troggs have cut off the route, stopping civilian couriers until Mountaineers can clear the road. Hands Springsprocket packed the crate with tavern provisions for Tannok Frosthammer in Kharanos, where the supplies are needed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-inn-supplies-7a1ef87478c3da636c0c/1-0000.mp3", duration = 29.0481633, start = 0},
  },
}
P.transport["item:crate-of-lightforge-ingots"] = {
  hash = "fa0ab8",
  fullHash = "fa0ab8",
  text = "Crate of Lightforge Ingots. In Duskwood, the Crate of Lightforge Ingots carries hope against Morbent Fel. The rare consecrated metal is bound for the Dwarven District in Stormwind. Duskwood's hope rests in this crate of lightforge iron. The rare metal can channel holy power against dark entities, while Morbent Fel's protections turn aside ordinary steel. Only an artisan who knows its temper and honors its sacred nature can work it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-of-lightforge-ingots-110cdfede72441436dad/1-0000.mp3", duration = 23.797551, start = 0},
  },
}
P.transport["item:crate-with-holes"] = {
  hash = "c1c490",
  fullHash = "c1c490",
  text = "Crate With Holes. In Ratchet, Mebok Mizzyrix prepares a crate for a Snufflenose Gopher. Mebok Mizzyrix sends trained Snufflenose Gophers to find Blueleaf Tubers in Razorfen Kraul. The gophers cannot follow an adventurer across the Barrens on foot, so Mebok places each one in a wooden crate with air holes. Inside the quilboar stronghold, the crate is opened and the gopher follows its keen nose toward the buried tubers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crate-with-holes-d02cafa81315870080d6/1-0000.mp3", duration = 23.7191837, start = 0},
  },
}
P.transport["item:crawler-leg"] = {
  hash = "51aad7",
  fullHash = "51aad7",
  text = "Crawler Leg. Along Darkshore’s misty coast, crabs lose legs that most travelers have no use for. Their tough limbs can help keep a gnome’s communication device working. Darkshore’s crabs leave sturdy limbs along the shore, from pygmy tide crawlers to reef crawlers. Night elf sentinels pay them little mind, but the gnome engineer Wizbang Cranktoggle has found a use for them. Working from Auberdine, Wizbang designed his prototype long-distance communication devices, called buzzboxes, to run on improvised local components. Crawler legs’ segmented joints and durable chitin provide the friction and leverage needed to repair Buzzbox 827, along the shoreline just south of town.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crawler-leg-a6fe6b8a560539a721d0/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:creeper-ichor"] = {
  hash = "e3b9b2",
  fullHash = "e3b9b2",
  text = "Creeper Ichor. Across the Hillsbrad forests, rare, virulent Creeper Ichor is harvested from moss creepers. The Royal Apothecary Society in Tarren Mill seeks it as a biological agent for formulating novel plagues against the living. In Tarren Mill, Apothecary Lydon seeks natural toxins and biological catalysts to craft deadly new toxins and eradicate the surrounding human population. The clean air and vibrant life of the foothills offend him. Among the forest’s giant arachnids, mature moss creepers hold an elusive ichor that makes an ideal base for his Elixir of Suffering. Mixed with other reagents, including gray bear tongues, the fluid helps the Forsaken perfect their lethal alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_creeper-ichor-9684d14bf2d17aa0b312/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["item:crocolisk-skin-classic"] = {
  hash = "e2b135",
  fullHash = "e2b135",
  text = "Crocolisk Skin (Classic). In Loch Modan, crocolisk skins come from the fierce beasts that haunt the Loch’s islands and waters. Merchants and leatherworkers seek their durable hides, though hunters face danger to gather them. Crocolisks crowd the Loch’s cold waters and make dens along its islands and shores. Their sharp teeth and thick scales make them dangerous quarry. Hunters based at Farstrider Lodge still pursue them for their hides. Tailors, leatherworkers, and merchants from distant places seek the skins for sturdy garments and armor, so undamaged hides bring a good price in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crocolisk-skin-classic-72334585250fde8ff8fc/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["item:crocolisk-tear-classic"] = {
  hash = "a51a8f",
  fullHash = "a51a8f",
  text = "Crocolisk Tear (Classic). At the Stonewrought Dam, Chief Engineer Hinderweir needs a Crocolisk Tear to counter Dark Iron explosives. Crocolisk Tears come from reptiles living in Loch Modan's waters. Chief Engineer Hinderweir found that their secretions have an unexpected use. Mixed with potent spider venom and resonant ogre minerals, a tear has the chemical properties needed to counter volatile Dark Iron demolition charges threatening the Stonewrought Dam.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crocolisk-tear-classic-51c406a3b4d33e62523e/1-0000.mp3", duration = 26.4359184, start = 0},
  },
}
P.transport["item:crossroads-supply-crate"] = {
  hash = "e2e864",
  fullHash = "e2e864",
  text = "Crossroads Supply Crate. Stolen provisions for the Crossroads lie scattered among Razormane camps in the Barrens. A raided caravan left the settlement short of food, tools, and necessities. Razormane quilboar raided a caravan carrying supplies to the Crossroads. The crates were dragged into nearby camps among the underbrush and dirt dens. Thork, the settlement's commander, seeks their return before the outpost runs dangerously low on food, tools, and necessities.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crossroads-supply-crate-0d2eb0c7830e81a919f2/1-0000.mp3", duration = 25.1559184, start = 0},
  },
}
P.transport["item:crude-flint"] = {
  hash = "36ba36",
  fullHash = "36ba36",
  text = "Crude Flint. Across the Wetlands, Mosshide gnolls carry Crude Flint to kindle fires with freshly hewn marsh timber. Their fires anger Rethiel the Greenwarden, protector of the marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crude-flint-0da0968377a5272c8b31/1-0000.mp3", duration = 11.3893878, start = 0},
  },
}
P.transport["item:crystal-kelp-frond"] = {
  hash = "6744f6",
  fullHash = "6744f6",
  text = "Crystal Kelp Frond. Murlocs carry Crystal Kelp Fronds from the ocean to Crystal Lake in Elwynn Forest. William Pestle in Goldshire seeks them for an invisibility liquor. Crystal Kelp Fronds come from saltwater oceans, so their presence in Elwynn Forest’s fresh water is unusual. Murloc tribes along Crystal Lake’s shores gather and keep the fronds for reasons of their own. Alchemists value their strange power to distort sight. William Pestle in Goldshire uses them as the chief ingredient in an invisibility liquor, meant to help sweethearts slip past watchful family eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystal-kelp-frond-81ac292b23cbe63cc07a/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["item:crystal-phial"] = {
  hash = "586ebe",
  fullHash = "586ebe",
  text = "Crystal Phial. In Shadowglen, Tenaron Stormgrip entrusts young night elves with a Crystal Phial. They carry it to a nearby moonwell to draw sacred water for rites honoring and nourishing Teldrassil. Young night elves receive a Crystal Phial atop Aldrassil. Tenaron Stormgrip sends them to the moonwell just north of the bough to gather its glowing waters. The delicate vessel holds water touched by the sacred legacy of the Well of Eternity. Returning with a Filled Crystal Phial begins the Crown of the Earth pilgrimage, teaching the young kaldorei about the balance of magic, history, and nature in their new island home.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystal-phial-435de9ef9953b9d721ec/1-0000.mp3", duration = 35.1346939, start = 0},
  },
}
P.transport["item:crystalized-scales"] = {
  hash = "182232",
  fullHash = "182232",
  text = "Crystalized Scales. Basilisks in harsh Kalimdor lands yield Crystalized Scales for arcane work. The mineralized hides come from the Charred Vale and Thousand Needles, and Collin Mauren seeks them in Stormwind. Basilisks endure heat and ash in Stonetalon's Charred Vale and the salt flats of Thousand Needles. Their hides harden beneath a crystal crust, and the scales hold latent arcane resonance. Wizards across the Great Sea prize them for experiments in rare spellcraft. In Stormwind, the mage Collin Mauren seeks travelers bound for Kalimdor to bring him these scales. Mauren pulverizes their crystalline mineral layers into dust, then uses the powder as a reagent for newly conceived spells and his own arcane research.",
  ["1"] = {
    {file = "Audio/Transport/full_item_crystalized-scales-39eb3f6908f09f5e0e54/1-0000.mp3", duration = 43.8334694, start = 0},
  },
}
P.transport["item:curative-animal-salve"] = {
  hash = "303ab6",
  fullHash = "303ab6",
  text = "Curative Animal Salve. Across Darkshore and the Barrens, druids use Curative Animal Salve to treat sick wildlife. Herbalists prepare it in both lands, while the Cenarion Circle sees the animals’ afflictions as signs of a wider blight. Druids use Curative Animal Salve to ease sick wildlife in Darkshore and the Barrens. Alanndarian Nightsong directs young druids to treat sick deer between the Cliffspring River and the borders of Ashenvale. In the Barrens, Tonga Runetotem brews the same remedy for sick gazelles grazing north of the Crossroads. Each herbalist prepares the salve from locally gathered herbs in batches of ten doses. Field practitioners apply it directly to the animals, while both herbalists work with local authorities to produce larger supplies. The salve eases an animal’s suffering, but the Cenarion Circle sees the afflictions as signs of a wider disturbance. In Moonglade, Dendrite Starblaze observes that the afflicted deer on the coast and the suffering gazelles on the savannah are no random casualties. They are unwitting victims of a blight spreading across Kalimdor from multiple directions. For initiates, treating the animals tests their dedication to protecting nature and their skill in cleansing poison.",
  ["1"] = {
    {file = "Audio/Transport/full_item_curative-animal-salve-296e4a57baf97504867e/1-0000.mp3", duration = 69.0416327, start = 0},
  },
}
P.transport["item:daffodil-bouquet"] = {
  hash = "b00dd4",
  fullHash = "b00dd4",
  text = "Daffodil Bouquet. In Lakeshire, Guard Parker sends a bouquet to thank Darcy for packing his lunch. Martie Jainrose gathers the flowers, and their choice stirs gossip between the two women. Guard Parker wants to thank Darcy at the Lakeshire inn for packing his daily lunch. He asks the town herbalist, Martie Jainrose, to prepare a bouquet of daffodils. Martie says they are her favorite flowers. Darcy recognizes them as Martie’s signature bloom and suspects jealousy. Half-joking, she wonders whether Martie poisoned the stems out of spite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_daffodil-bouquet-7648a71d6adede680b13/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["item:daggerspine-scale"] = {
  hash = "12ad6e",
  fullHash = "12ad6e",
  text = "Daggerspine Scale. Along Hillsbrad Foothills' southern shores, Daggerspine Scale comes from tough reptilian scales harvested from prowling Daggerspine naga. The Royal Apothecary Society seeks them to activate virulent brews in the Forsaken's ongoing plague experiments. The Royal Apothecary Society seeks reagents for its toxins, plagues, and concoctions. While refining the experimental Elixir of Agony, its apothecaries found that scales from the local Daggerspine naga react in a useful way. Combined with troll regenerative elixirs and murloc organs, the scales chemically activate dormant contaminating agents suspended in raw mixtures. Gathering them means hunting along the rocky coastline east of Southshore, near both the vicious naga tribe and Alliance forces. The apothecaries need these scales for their research.",
  ["1"] = {
    {file = "Audio/Transport/full_item_daggerspine-scale-4e0e795bf1f4b261f77c/1-0000.mp3", duration = 47.36, start = 0},
  },
}
P.transport["item:dal-bloodclaw-s-skull"] = {
  hash = "abebe8",
  fullHash = "abebe8",
  text = "Dal Bloodclaw's Skull. In northern Ashenvale, Dal Bloodclaw's Skull marks the end of a threat to Astranaar. Raene Wolfrunner receives it as proof that an attack on the night elf settlement has been averted. The Thistlefur furbolgs north of Astranaar have grown in number and aggression. Like much of Ashenvale's ancient forest, they have been corrupted. Raene Wolfrunner, a night elf sentinel, fears they will soon march on Astranaar. She orders their ranks culled and their leader, Dal Bloodclaw, slain. His skull gives grim proof that the tribe's leadership has been shattered, buying Astranaar's defenders precious time.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dal-bloodclaw-s-skull-943342811f947ef699d9/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["item:dalaran-mana-gem"] = {
  hash = "c77ff3",
  fullHash = "c77ff3",
  text = "Dalaran Mana Gem. Near Ambermill, Kirin Tor mages carry Dalaran Mana Gems to replenish their power. Forsaken tailors use the gems to weave enchanted robes. Kirin Tor mages, conjurors, and guards around Ambermill carry mana gems to focus and replenish their arcane power. In the Undercity’s Magic Quarter, Forsaken practitioners prize the gems as a ready supply of concentrated magic. Some undead mages share an academic heritage with Dalaran, but survival comes first. To the Forsaken, the Kirin Tor are rivals whose magical stores can be taken. Forsaken bring mana gems taken from fallen Kirin Tor operatives to tailors such as Josef Gregorian in the Undercity, along with simple linen. A tailor cannot channel arcane power directly, but can bind a gem into the cloth. The magic then strengthens the wearer’s connection to the arcane.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-mana-gem-b446446a25742fc94d7c/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["item:dalaran-pendant"] = {
  hash = "6efa3b",
  fullHash = "6efa3b",
  text = "Dalaran Pendant. In Ambermill, Dalaran Pendants focus the Kirin Tor's magic. The Forsaken seek them to hinder the wizards' work and trace the source of their power. Kirin Tor sorcerers, conjurers, and protectors weave powerful spells in Ambermill, threatening Forsaken control of southern Silverpine Forest. Each carries an attuned Dalaran Pendant. At the Sepulcher, Shadow Priest Allister sends Forsaken operatives to recover the pendants, slowing the mages' efforts and uncovering who guides their magical weave.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-pendant-9ba47cb0681d88d56177/1-0000.mp3", duration = 29.7012245, start = 0},
  },
}
P.transport["item:dalaran-status-report"] = {
  hash = "482263",
  fullHash = "482263",
  text = "Dalaran Status Report. At Ambermill, the Kirin Tor watch Dalaran as the city is rebuilt in the open. Their report carries intelligence the Deathstalkers seek. The Scourge sacked Dalaran, and Archimonde brought down its towering spires during the Third War. Early in the rebuilding, the surviving magi removed the city's protective shield and began their work in the open. The Kirin Tor also keeps enclaves such as Ambermill in southeastern Silverpine Forest. Its wizards compile the Dalaran Status Report, which holds intelligence about the city's condition and draws the Deathstalkers' attention.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalaran-status-report-4ba2405a5f80a3091b37/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["item:dalin-s-heart"] = {
  hash = "655377",
  fullHash = "655377",
  text = "Dalin's Heart. Near the Greymane Wall in Silverpine Forest, Dalin Forgewright patrols with an honorable heart. Undercity warlocks seek hearts from truly virtuous mortals to call and bind a succubus to their service. Dalin Forgewright spends his days defending desperate Lordaeron refugees kept from safety by the sealed Greymane Wall. His selfless devotion marks him as a rare offering of unblemished purity, and his heart is carved for the rites held in the Temple of the Damned.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dalin-s-heart-8f7dec8da6dd4bbd98da/1-0000.mp3", duration = 26.5142857, start = 0},
  },
}
P.transport["item:darkhound-blood"] = {
  hash = "8d7b67",
  fullHash = "8d7b67",
  text = "Darkhound Blood. Darkhound Blood is a foul bodily fluid harvested from the tainted canine beasts roaming the fields and forests of Tirisfal Glades. Gathered at the behest of the Royal Apothecary Society, it serves as an early reagent in their dark experiments to engineer a lethal new plague. Under the command of Lady Sylvanas Windrunner, the Royal Apothecary Society strives to develop a virulent contagion capable of wiping out Arthas and his Scourge. Stationed in Brill, Apothecary Johaan theorizes that local beasts, corrupted by dark energies and resilient to the surrounding decay, possess unusual biological properties. By distilling the blood of wild darkhounds, Johaan aims to uncover biological compounds that can resist or propagate virulent necrotic strains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darkhound-blood-f98f4bfc78ead654276e/1-0000.mp3", duration = 45.7665306, start = 0},
  },
}
P.transport["item:darkshore-grouper"] = {
  hash = "fd890c",
  fullHash = "fd890c",
  text = "Darkshore Grouper. Along Darkshore, grouper are a familiar catch, though murloc attacks have driven fishermen from their boats. The fish is prized for food and sport, and a good haul is harder to find. Darkshore Grouper are a welcome catch in the cold waters off Darkshore. Anglers around Auberdine value them for the simple dishes they make, and travelers and residents alike enjoy those meals. A fishing line and basic gear are enough to bring one in. For many fishermen, the pleasure of catching a grouper matches the pleasure of eating it. Fishermen such as Gubber Blump once took small boats into deeper waters and brought back grouper by the dozen. Coastal murlocs have grown more aggressive, grounding most boats around Auberdine. Anglers now fish from shore and dock, where locals suspect the murlocs are eating the grouper. A good haul takes patience.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darkshore-grouper-fd6a6bb9c3bae4220821/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["item:darksoul-shackle"] = {
  hash = "94069c",
  fullHash = "94069c",
  text = "Darksoul Shackle. In Silverpine Forest, Moonrage Darksouls wear enchanted fetters forged under Archmage Arugal’s direction. Forsaken mages at the Sepulcher seek them to learn how the magic gripping the region can be undone. Archmage Arugal’s magic could not fully command or sustain the worgen he unleashed upon Silverpine Forest. He bound enchanted implements such as Darksoul Shackles to the beasts to make up for that failing. The fetters channel outside sorcery into the Moonrage Darksouls, strengthening them and anchoring the curse that keeps them thrall to Shadowfang Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darksoul-shackle-e1d2951e25267c289e66/1-0000.mp3", duration = 32.235102, start = 0},
  },
}
P.transport["item:darnassus-marzipan"] = {
  hash = "8905bf",
  fullHash = "8905bf",
  text = "Darnassus Marzipan. At Hallow's End, Darnassus innkeepers hand out festive marzipan to visitors who dance for it. Crafted in the night elven capital for the autumn celebration, this sweet is one of four treats Jesper needs. During Hallow's End, Alliance capitals share a tradition of lighthearted trick-or-treating. Dwarves offer sharp mints, Stormwind makes chewy nougat, and Darnassus innkeepers prepare delicate marzipan for visitors. To receive a piece, you must show some festive spirit and dance when the innkeeper asks. The sweet is one of four regional treats sought by Jesper, a sick orphan in Stormwind's Cathedral Square who cannot go out to collect sweets himself.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darnassus-marzipan-3b8f221c52afa9f1a939/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:darthalia-s-sealed-commendation"] = {
  hash = "6ed114",
  fullHash = "6ed114",
  text = "Darthalia's Sealed Commendation. At Tarren Mill, Darthalia sends word of victories against Hillsbrad's humans to Undercity's high command. After the fighting across the Hillsbrad Foothills, High Executor Darthalia seals a dispatch recording victories against Hillsbrad's human defenders and the ruin of their positions. She addresses it to Varimathras, the dreadlord who advises Lady Sylvanas Windrunner. In the Royal Quarter, the report gives Forsaken leaders proof that Alliance enclaves south of Lordaeron can be broken, leaving northern garrisons free to face the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_darthalia-s-sealed-commendation-ccc7ccc385ea34c096a6/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["item:deadmire-s-tooth"] = {
  hash = "4ede86",
  fullHash = "4ede86",
  text = "Deadmire's Tooth. In Dustwallow Marsh, Deadmire stalks the murky waters, and his tooth marks an honorable hunt. Melor Stonehoof on Hunter Rise in Thunder Bluff receives it as proof that the ancient crocolisk's suffering has ended. Tauren hunters on Hunter Rise see the hunt as a bond of balance, reverence, and mercy. Deadmire was once among the most magnificent crocolisks in Dustwallow Marsh. Great age turned his final years to torment, though he kept the fierce spirit of his prime. His massive bones and failing body had become a prison of pain. Deadmire's Tooth gives Melor Stonehoof proof that an honorable hunt has ended the beast's suffering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deadmire-s-tooth-0b49d0f78d6d31eeba97/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:death-cap"] = {
  hash = "86fd39",
  fullHash = "86fd39",
  text = "Death Cap. In Darkshore, Death Cap grows in the cave behind Cliffspring Falls. Night elf herbalists seek the scarce fungus, but the Grove of the Ancients warns against approaching the falls. Death Cap grows in the damp cave behind Cliffspring Falls, along Darkshore's northeastern mountain ridges. Scaber stalks carpet the cavern floor, but Death Cap is scarce. Night elf herbalists such as Barithras Moonshade value it for experimental brewing. Finding even one means entering a cavern the Grove of the Ancients warns against, where corruption is taking root.",
  ["1"] = {
    {file = "Audio/Transport/full_item_death-cap-6594db8c7232bfba1962/1-0000.mp3", duration = 31.6865306, start = 0},
  },
}
P.transport["item:deathstalker-report"] = {
  hash = "cf53a2",
  fullHash = "cf53a2",
  text = "Deathstalker Report. Deathstalker Rane Yorick sends word of Scourge resistance in Silverpine Forest to High Executor Hadrec. Deathstalkers Rane Yorick and Quinn Yorick faced a deadly ambush in northern Silverpine Forest. Pinned down by Scourge in the pine woods, they gathered their findings into a hurried dispatch. It describes stronger resistance than the Forsaken expected as they seek to claim the region. Quinn was grievously injured, so Rane entrusted the report to passing allies, who must carry it to High Executor Hadrec at the Sepulcher without delay.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deathstalker-report-6df5d1bed621a085e126/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["item:deepfury-s-orders"] = {
  hash = "05a6f9",
  fullHash = "05a6f9",
  text = "Deepfury's Orders. Beneath the Thandol Span, Deepfury's Orders lie with the fallen Ol' Rustlocke. The crumpled parchment carries grim instructions from the Dark Iron dwarves who ambushed the scouting defender. Ol' Rustlocke, a dwarven bridge defender, was scouting the foundations of the Thandol Span when Dark Iron dwarves cornered and slew him. Beside his clenched fist lay crumpled orders drafted by their leader, Deepfury. The parchment is direct proof of a coordinated plot against the bridge linking the Wetlands and the Arathi Highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deepfury-s-orders-91cd127338c20e7df697/1-0000.mp3", duration = 32.2612245, start = 0},
  },
}
P.transport["item:deepmoss-egg"] = {
  hash = "1c1fdf",
  fullHash = "1c1fdf",
  text = "Deepmoss Egg. In the Stonetalon Mountains, Deepmoss Eggs draw goblin merchants from Ratchet. Deepmoss spiders lay clustered clutches in the crags and canyons, and Booty Bay pirates prize them for omelettes. Deepmoss spiders nest across the Stonetalon Mountains, especially in Sishir Canyon and beneath the surviving trees of Windshear Crag. They leave clustered clutches of viable eggs in thick webbed sacks, sheltered by damp mountain moss. Most travelers have little use for them, but goblin traders see a chance to profit. Booty Bay has taken to spider egg omelettes, an eccentric culinary fad among wealthy pirates and adventurous diners. Local supplies cannot satisfy their appetite, so Mebok Mizzyrix of Ratchet arranges shipments through Wharfmaster Dizzywig. Collectors brave Stonetalon's venomous broods for fresh clutches, which become valuable cargo.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deepmoss-egg-14730100016cee5bb1be/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["item:defias-docket"] = {
  hash = "47610b",
  fullHash = "47610b",
  text = "Defias Docket. Defias operatives have hidden their orders at Addle's Stead in western Duskwood. The docket gives Stormwind's search for its missing emissary a lead into the Brotherhood's plans. Master Elling Trias points investigators toward Duskwood as they follow leads on the kingdom's missing diplomat. Watcher Backus has noted unusual Defias movements converging on Addle's Stead, the derelict farm south of the road from Westfall. A strongbox on the property holds the Defias Docket. Its records track the Brotherhood's movements, revealing work that reaches beyond highway robbery and local banditry.",
  ["1"] = {
    {file = "Audio/Transport/full_item_defias-docket-4b53515d2d14a87a18e1/1-0000.mp3", duration = 33.5412245, start = 0},
  },
}
P.transport["item:defias-tower-key"] = {
  hash = "089a10",
  fullHash = "089a10",
  text = "Defias Tower Key. At Klaven's Tower in Westfall, the Defias Tower Key proves an infiltrator reached the guarded perimeter. Stormwind operatives seek it from the malformed drones outside. Klaven's Tower stands on the Westfall coast as a Defias Brotherhood stronghold. Recent shipments from Duskwood brought new guards to its perimeter: malformed Defias drones, undead and covered in spikes. SI:7 operatives watch the grounds and direct field agents to pick the pockets of these sentries. Fighting them head-on is not the way to prove the perimeter has been breached. The key shows an infiltrator got through without raising an alarm.",
  ["1"] = {
    {file = "Audio/Transport/full_item_defias-tower-key-4c50e1fc83491a4e1882/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["item:deliah-s-ring"] = {
  hash = "cee1de",
  fullHash = "cee1de",
  text = "Deliah's Ring. A grim trail begins with Deliah's Ring, found among the Rot Hide gnolls’ corpse piles in Silverpine Forest. Its inscription, “For Deliah,” points back to a plague victim taken from Tirisfal’s mass graves. Among the gnoll mounds in Silverpine Forest, a ring rests on the pockmarked hand of a relatively fresh corpse. The band bears a simple inscription: “For Deliah.” The Rot Hide gnolls are doing more than scavenging battlefields. They raid the mass graves of Tirisfal Glades and carry human and Forsaken corpses south to Fenris Isle for their own purposes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deliah-s-ring-be25db2d44175eab5201/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["item:delivery-to-mathias"] = {
  hash = "aacf07",
  fullHash = "aacf07",
  text = "Delivery to Mathias. Keryn Sylvius sends a sealed parcel from Goldshire to Master Mathias Shaw in Stormwind. The delivery gives a promising rogue entry into SI:7's inner workings. A parcel from the Lion's Pride Inn to the Stormwind Barracks may look like ordinary courier work. For a budding rogue, it is an audition for Stormwind Intelligence. Local trainer Keryn Sylvius entrusts the package to novice cutpurses, giving them a direct introduction to Master Mathias Shaw. The delivery tests whether they can cross the capital quietly, keep a low profile, and follow discreet orders without asking questions. The handoff brings an operative into SI:7 headquarters in Old Town. Mathias Shaw uses such deliveries to separate pretenders from true talents. Those who present the parcel without faltering receive high-stakes field assignments, beginning with covert reconnaissance and infiltration against Defias smuggling networks in Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_delivery-to-mathias-0a43fd85c35e15d8eb3f/1-0000.mp3", duration = 54.6481633, start = 0},
  },
}
P.transport["item:deviate-hide"] = {
  hash = "825fc9",
  fullHash = "825fc9",
  text = "Deviate Hide. Deviate Hides are the mutated skins stripped from the beasts dwelling within the Wailing Caverns. Warped by the corrupting dream of the druid Naralex, these otherworldly pelts are sought by druids looking to repurpose the nightmare's taint into durable leather goods. When the night elf druid Naralex entered his deep slumber beneath the Barrens, his dream turned into an Emerald Nightmare that warped the local cavern ecology. The beasts lurking in the depths transformed into unnatural deviate predators with tough, mutated hides. While inherently touched by evil, these pelts possess unusual, supple resilience that makes them uniquely suited for leathercrafting. Nalpak, perched high above the cavern mouth in the skull-shaped rock formation, collects these hides to study their properties and fashion them into sturdy utility packs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_deviate-hide-caa5ac84ea06a7315931/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:devlin-s-remains"] = {
  hash = "ba26b3",
  fullHash = "ba26b3",
  text = "Devlin's Remains. Near Agamand Mills, Devlin Agamand’s bones carry a bitter legacy. The younger son of the wealthy family that owned the mills, he roamed the road by his ruined home as a mindless Scourge thrall. A traveler struck him down and brought his remains to a survivor in Brill, who sought vengeance. Devlin Agamand lived in the shadow of his elder brother Thurman. Thurman was gentle and tall, while Devlin was frail and sharp-tongued. When the Plague of Undeath swept through northern Tirisfal Glades, the Agamand family failed to protect its lands and laborers. Devlin was among the first to fall. The Scourge raised him as a ravenous ghoul, and his mad chattering haunted the roadside leading to Agamand Mills. Coleman Farthing lives in Brill and holds a deep grudge against the Agamand bloodline. He blames the family for failing his own when the plague came. Farthing sent travelers to lay Devlin to rest and gather his remains. He wanted Devlin’s bones on his mantle, to savor how his former masters had been reduced to dust and shattered fragments beneath his heel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_devlin-s-remains-c86f853470372aa99be0/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["item:dirt-caked-pendant"] = {
  hash = "6a7547",
  fullHash = "6a7547",
  text = "Dirt-Caked Pendant. In the Barrens, a captive orc gives up the Dirt-Caked Pendant he carried. The keepsake reaches Gan'rul Bloodeye in Orgrimmar, where it is used to draw a succubus.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dirt-caked-pendant-f2cfb11c850978e7735c/1-0000.mp3", duration = 10.3444898, start = 0},
  },
}
P.transport["item:disarming-colloid"] = {
  hash = "b98950",
  fullHash = "b98950",
  text = "Disarming Colloid. At the Stonewrought Dam, Disarming Colloid could keep Seaforium from exploding when wet. Ashlan Stonesmirk provides it in the Wetlands for a mixture that can neutralize the powder. Ashlan Stonesmirk recognized the powder left by Dark Iron sappers at the Stonewrought Dam in Loch Modan as Seaforium. Its scent and fine silver crystals gave it away. The powder is harmless while dry, but moisture makes it immensely destructive, a grave danger at the waterlogged dam. Stonesmirk provided Disarming Colloid to stop the reaction before detonation. Mixed with lurker venom, crushed Mo'grosh crystal, and a crocolisk tear, the colloid neutralizes Seaforium's explosive properties.",
  ["1"] = {
    {file = "Audio/Transport/full_item_disarming-colloid-22ce1b7e609f910c8b79/1-0000.mp3", duration = 40.96, start = 0},
  },
}
P.transport["item:disarming-mixture"] = {
  hash = "b6647b",
  fullHash = "b6647b",
  text = "Disarming Mixture. At Stonewrought Dam, Disarming Mixture is prepared to stop a Seaforium charge from breaking the dam. Chief Engineer Hinderweir makes it to neutralize explosives planted by Dark Iron saboteurs. Dark Iron saboteurs planted a heavy Seaforium charge beneath Stonewrought Dam’s foundation. With no Mountaineer support close at hand, Chief Engineer Hinderweir used ingredients named by explosives expert Ashlan Stonesmirk to make the Disarming Mixture. Stirred into the planted powder keg underwater, the solution neutralizes its reactive compounds and leaves the charge fizzled and harmless.",
  ["1"] = {
    {file = "Audio/Transport/full_item_disarming-mixture-76604179c26b9cca72f9/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:divined-scroll"] = {
  hash = "97fc38",
  fullHash = "97fc38",
  text = "Divined Scroll. At Silverwind Refuge, the Divined Scroll can expose the mage behind Ashenvale's troubled waters. Night elves use magic from intact water elemental bracers to reveal the summoner's identity. Mystral Lake's tainted waters trouble the Sentinels guarding Ashenvale. Sentinel Velene Starstrike gives travelers an uncharged divining scroll to trace whoever manipulates the water elementals infesting the lake. Gather intact bracers from slain elementals and use them as an arcane reagent; their latent bindings pass into the parchment. The Divined Scroll then reveals the magical signature of the rogue wizard behind the infestation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_divined-scroll-d33df7d4ed8a11e66518/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["item:divining-scroll"] = {
  hash = "9b3c16",
  fullHash = "9b3c16",
  text = "Divining Scroll. At Silverwind Refuge, Sentinel Velene Starstrike gives investigators the Divining Scroll to trace the corrupted elementals to their creator. Corrupt water elementals rise from Ashenvale’s pools, and the Sentinels know the disturbance is unnatural. Sentinel Velene Starstrike obtains a scroll to find who is responsible. With intact elemental bracers as a focus, its magic draws out the summoner’s signature. The blank parchment becomes a Divined Scroll and names the guilty party.",
  ["1"] = {
    {file = "Audio/Transport/full_item_divining-scroll-dbee1b279b5d7c7452c4/1-0000.mp3", duration = 28.4212245, start = 0},
  },
}
P.transport["item:dogran-s-pendant"] = {
  hash = "2c1b20",
  fullHash = "2c1b20",
  text = "Dogran's Pendant. Dogran's Pendant draws a succubus toward the warlocks of Orgrimmar. Dogran, a wounded orc, carries it while separated from his mate, Zankaja. In the Cleft of Shadow, warlocks turn the sorrow bound to it into a lure. Dogran's Pendant carries the sorrow of an orc separated from Zankaja. Captivity and crippling wounds have overshadowed their love. The warlocks of the Cleft of Shadow know that demons such as succubi prey on love, yearning, and vulnerability. They use the pendant's grief to draw a succubus across the Twisting Nether and into Neeru Fireblade's summoning circle.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dogran-s-pendant-1e69fd77b29fbe62c099/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["item:dolanaar-delivery"] = {
  hash = "24a9f4",
  fullHash = "24a9f4",
  text = "Dolanaar Delivery. In Shadowglen, young travelers carry harvested herbs south to Dolanaar. Porthannius entrusts them with the bundle for Innkeeper Keldamyr. Fresh herbs from Aldrassil are bound for Dolanaar. Porthannius is occupied with matters among the druids of Shadowglen, so he entrusts the bundle to young travelers heading south along the road. They carry it to Innkeeper Keldamyr. The parcel brings you to Dolanaar's inn, where Keldamyr receives it with gratitude. The inn offers weary travelers rest, peace of mind, and sanctuary before they venture deeper into Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dolanaar-delivery-2b1ac0aac00c3fb69174/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["item:dragonmaw-war-banner"] = {
  hash = "c063ba",
  fullHash = "c063ba",
  text = "Dragonmaw War Banner. Dragonmaw War Banners rise over orc encampments in the Wetlands. Their clan markings give the dwarven defenders of Menethil Harbor proof of the growing threat. After the Second War, the Dragonmaw clan was shattered when they lost control of their enslaved red dragons. The enraged drakes turned on their captors and drove the survivors from Grim Batol into the eastern hills. Now the remaining orcs gather strength under Chieftain Nek'rosh and raise their banners over camps northeast of Menethil Harbor. Those rough standards mark their defiance and threaten the settlements in the marsh. Captain Stoutfist at Menethil Harbor sends Alliance adventurers into the marsh camps to bring back Dragonmaw banners. Raiders, centurions, and bone-warders carry these trophies, which confirm to the dwarven garrison that the camps are being broken before the clan can launch coordinated raids.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dragonmaw-war-banner-e7e5aa085e614e3270d9/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["item:dried-seeds"] = {
  hash = "736e32",
  fullHash = "736e32",
  text = "Dried Seeds. At the Crossroads, Tonga Runetotem gives travelers Dried Seeds to test the life-giving power beneath the Barrens' waters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dried-seeds-5c17b1a57b06464b6200/1-0000.mp3", duration = 6.66122449, start = 0},
  },
}
P.transport["item:durnan-s-scalding-mornbrew"] = {
  hash = "84b1c8",
  fullHash = "84b1c8",
  text = "Durnan's Scalding Mornbrew. In Coldridge Valley, Durnan Furcutter waits for his scalding mornbrew inside Anvilmar. The cup must reach him before the mountain air cools it. A fresh cup of mornbrew is bound for Durnan Furcutter inside Anvilmar. A courier delayed on the way to Grelin Whitebeard leaves the brew at risk of cooling in Coldridge Valley's frost. Durnan wants it scalding, so there are only a few minutes to carry the mug up the snowy path into the mountain hall before it goes cold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_durnan-s-scalding-mornbrew-89c0799dfaa5618a6860/1-0000.mp3", duration = 25.6261224, start = 0},
  },
}
P.transport["item:durotar-tiger-fur"] = {
  hash = "0fc8e6",
  fullHash = "0fc8e6",
  text = "Durotar Tiger Fur. Across the Echo Isles off Durotar's southeastern coast, tigers supply fur for the Darkspear, whose refugee population keeps growing. The trolls use the pelts for blankets, tents, and armor. In Sen'jin Village, the Darkspear must make scarce supplies last. They let the local tigers thrive until their growing needs call for a cull. Trolls cure the thick hides into goods their settlement needs, including protective armor and warm blankets for changing seasonal weather. The Echo Isles lie south of Durotar, across open water. The Darkspear once called the archipelago home, until the witch doctor Zalazane drove them out. Hunters face dangers from Zalazane's thralls and from tigers waiting among the thick foliage. Experienced hunters such as Vel'rin Fang speak of spending entire days motionless in the jungle brush to secure a single clean kill.",
  ["1"] = {
    {file = "Audio/Transport/full_item_durotar-tiger-fur-2e99ac52f95743106dbd/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["item:duskbat-wing"] = {
  hash = "1328e0",
  fullHash = "1328e0",
  text = "Duskbat Wing. Duskbats circle Deathknell, and local tailors turn their wings into makeshift armor for newly risen soldiers. New Forsaken claw from Deathknell’s soil with little more than rags and brittle bones. With mindless Scourge and hostile wildlife nearby, they must gather what protection they can. Novice Elreth, assistant to Shadow Priest Sarvis, collects Duskbat Wings and wolf paws to piece together and strengthen clothing and armor for freshly raised warriors before they enter the wilderness to fight.",
  ["1"] = {
    {file = "Audio/Transport/full_item_duskbat-wing-ede81c82aa0253f69b5f/1-0000.mp3", duration = 28.8391837, start = 0},
  },
}
P.transport["item:dusky-crab-cakes"] = {
  hash = "ac2517",
  fullHash = "ac2517",
  text = "Dusky Crab Cakes. In Darkshire, Chef Grual prepares Dusky Crab Cakes for the hungry Jitters. The dish is a local delicacy, and Jitters finds it exquisite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dusky-crab-cakes-110ae7b072d9b3a0ce58/1-0000.mp3", duration = 9.14285714, start = 0},
  },
}
P.transport["item:dust-devil-debris"] = {
  hash = "c7a13a",
  fullHash = "c7a13a",
  text = "Dust Devil Debris. Across Westfall, Dust Devils leave charged grit in their wake. Mages value this debris as a reagent for enchanting parchment and binding messaging spells into scrolls. Dust Devils sweep across Westfall’s plains as violent whirlwinds. When one is struck down, the living storm collapses into charged dust and grit called Dust Devil Debris. A faint trace of the elemental vortex remains in the residue. In Stormwind, arcane practitioners such as Collin Mauren prize it for specialized sorcery. Infused into enchanted ink and parchment, the grit helps a wizard bind an airy messaging spell to a scroll, carrying words across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dust-devil-debris-05b5bc92ed8fd1550fc0/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:dwarven-tinder"] = {
  hash = "066739",
  fullHash = "066739",
  text = "Dwarven Tinder. In the Wetlands, Dwarven Tinder gives Alliance saboteurs a way to burn Dragonmaw siege engines before they reach Menethil Harbor. When Alliance scouts found Chieftain Nek'rosh's heavy catapults inside the Dragonmaw encampment, Menethil Harbor faced a crisis. Fighting in Dun Algaz had cut off the harbor from southern reinforcements, and its defenders could not withstand a long siege. They chose to sabotage the catapults before they could be used. Volunteers carrying Dwarven Tinder into orcish territory could light it with a struck spark. Its flames burned through the reinforced wooden engines in minutes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_dwarven-tinder-c368579f688ac477f80a/1-0000.mp3", duration = 36.1795918, start = 0},
  },
}
P.transport["item:ear-of-balgaras"] = {
  hash = "bcb1d7",
  fullHash = "bcb1d7",
  text = "Ear of Balgaras. At Dun Modr, Balgaras the Foul's ear marks the warlock's end. Recovered from the Dark Iron commander's corpse, it gives Ironforge's mountaineers proof of his death. Balgaras the Foul commanded the Dark Iron assault on Dun Modr. The invaders sabotaged the Thandol Span and destroyed the local dwarven garrison, leaving the outpost in ruins. A scheming warlock, Balgaras directed his troops from the shadows and shunned personal combat. Longbraid the Grim, the mountain king's officer stationed outside the ruins, wants proof that the ringleader has fallen. Balgaras's severed ear confirms the warlock's reign at the northern border is over. Dun Modr's fall cost Longbraid his brother and dozens of stout soldiers in the collapse of the West Bridge. The ear cannot mend the span or revive the fallen. With Balgaras unable to direct them, the surviving Dark Iron forces scattered through the northern Wetlands become easier for Ironforge's scouts to contain before another commander arrives from the south.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ear-of-balgaras-c0df1a516f4764205ca3/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["item:ebonlocke-s-response-to-solomon"] = {
  hash = "17a9ca",
  fullHash = "17a9ca",
  text = "Ebonlocke's Response to Solomon. Lord Ello Ebonlocke sends Solomon a refusal from Darkshire. His letter rejects the plea for Night Watch aid in Redridge. Magistrate Solomon asked Duskwood for reinforcements against the blackrock orcs after Stormwind ignored his petitions. Lord Ello Ebonlocke answers with anger and no promise of aid. He reminds Solomon that the Night Watch exists because Stormwind abandoned Darkshire when corrupting magic first gripped the woods. If its defenders leave to help Redridge, Duskwood will be left defenceless and fall to evil before the militia reaches the forest's edge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ebonlocke-s-response-to-solomon-402f2f6f49dc482d9a20/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["item:echeyakee-s-hide"] = {
  hash = "f1742a",
  fullHash = "f1742a",
  text = "Echeyakee's Hide. At the Crossroads, Sergra Darkthorn awaits the pale hide of Whitemist, the legendary white lion of the Barrens. Tauren honor the beast as an embodiment of mercy and death, while hunters bring the pelt as proof of their prowess. Echeyakee means Whitemist in the Taur-ahe tongue. The lion earned that name among the savannah's predators for his stealthy white coat and swift kills, ending prey's lives before fear or pain could take hold. A hunter summons the elusive cat near the giant kodo bones northeast of the Crossroads with a ceremonial horn, then claims his pelt. Bringing it to Sergra Darkthorn proves martial skill and honors Whitemist's silent, merciful end.",
  ["1"] = {
    {file = "Audio/Transport/full_item_echeyakee-s-hide-33b54feca923a3ba2320/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:egalin-s-grimoire"] = {
  hash = "169f4e",
  fullHash = "169f4e",
  text = "Egalin's Grimoire. In the Undercity, Egalin's Grimoire holds the rites for summoning and commanding a voidwalker. A master warlock wrote it as a teaching text for the Temple of the Damned. Egalin's Grimoire records how to call a being of chaos from the Nether. Egalin was a master summoner, renowned for his effortless command of voidwalkers. He passed that skill to his students, including Carendin Halgar. Without the formulas and channeling methods in the book, an unprepared summoner risks being torn apart by the being they call forth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_egalin-s-grimoire-184c8d2556737a38bc67/1-0000.mp3", duration = 28.9697959, start = 0},
  },
}
P.transport["item:electropeller"] = {
  hash = "b708ff",
  fullHash = "b708ff",
  text = "Electropeller. In Darkshore, Wizbang Cranktoggle's electropellers lie scattered in freshwater rivers after a failed night outing. Wizbang Cranktoggle built the electropeller to propel an experimental exploding duck decoy. The gnome inventor works out of Auberdine. While scouting Darkshore's waterways after too many drinks, he blacked out. Hours later, he woke with singed hair and an empty pack. His electropellers had tumbled into Darkshore's freshwater currents, where they remain scattered through rivers and lakes until patient anglers recover them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_electropeller-8881d23c25bfbfd039e6/1-0000.mp3", duration = 29.8579592, start = 0},
  },
}
P.transport["item:elixir-of-pain"] = {
  hash = "a9f827",
  fullHash = "a9f827",
  text = "Elixir of Pain. Forsaken apothecaries at Tarren Mill brew the Elixir of Pain for dangerous experiments. The mixture tests biological agents meant to advance Lady Sylvanas's darker ambitions. The Royal Apothecary Society seeks formulas to strengthen the Forsaken against their mortal neighbors and the Scourge. The Elixir of Pain is one such trial, made with freshly harvested ingredients from around the Hillsbrad Foothills. Its living subjects matter little to its makers; the potion tests volatile substances meant to aid the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elixir-of-pain-e70cd454ddc2ed37c59e/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["item:elixir-of-suffering"] = {
  hash = "3df0b5",
  fullHash = "3df0b5",
  text = "Elixir of Suffering. In Tarren Mill, Apothecary Lydon brews an experimental draught for the Royal Apothecary Society. Its work aims to create a virulent plague against living humans and the Scourge. Apothecary Lydon gathers raw reagents from the wilderness around ruined Tarren Mill and combines them into toxic draughts. The work follows the Royal Apothecary Society's overarching mandate to formulate a new plague that will exterminate the living and the dead alike. To test the brew's potency, Lydon gives it to his assistant, a frog named Umpi.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elixir-of-suffering-ca07beb27fa32fe6e186/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["item:elune-s-tear"] = {
  hash = "dc89d4",
  fullHash = "dc89d4",
  text = "Elune's Tear. On Ashenvale's central island, Elune's Tear offers night elf healers a sacred means to cleanse corruption and sickness. Elune's Tear rests on a small islet in Iris Lake, east of Astranaar. Night elves believe the stone carries the Moon Goddess's purity. Corruption has turned the lake green, and twisted bog beasts roam its shores. Local herbalists and healers, including Orendil Broadleaf, seek the stone as an emergency remedy when ordinary woodland poultices cannot wash away deep corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_item_elune-s-tear-96f79421b1e1ca6023f2/1-0000.mp3", duration = 30.4326531, start = 0},
  },
}
P.transport["item:embalming-ichor"] = {
  hash = "601ba1",
  fullHash = "601ba1",
  text = "Embalming Ichor. In northern Tirisfal, Rot Hide gnolls carry a fluid that preserves their decaying bodies. The Forsaken Apothecaries seek to study it against the Scourge. Rot Hide gnolls at Garren's Haunt and the nearby mass graves are rotting thralls sent by the Scourge to dig up plague victims. Embalming Ichor flows through their decayed veins, preserving their flesh and sustaining their unlife. Magistrate Sevren in Brill wants vials recovered from these grave robbers. The Royal Apothecary Society will use fresh specimens to study the fluid and seek ways to turn it against the Lich King's minions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_embalming-ichor-97b18d2829e122d9150d/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["item:emerald-dreamcatcher"] = {
  hash = "06a941",
  fullHash = "06a941",
  text = "Emerald Dreamcatcher. In Starbreeze Village, the Emerald Dreamcatcher lies forgotten after the Gnarlpine furbolgs drove out its people. Druids of Ban’ethil Barrow Den gave it to Tallonkai Swiftroot, hoping it would draw vigor from the Emerald Dream. Gaerolas Talvethren, the druidic warden of Ban’ethil Barrow Den, oversaw the making of the Emerald Dreamcatcher. The druids gave the enchanted amulet to only a chosen few. It draws ambient energy from the Emerald Dream, bringing fortune and protection to whoever carries it. When the maddened Gnarlpine furbolgs overran Starbreeze Village, the amulet remained inside a dresser, stranded in hostile, corrupted territory.",
  ["1"] = {
    {file = "Audio/Transport/full_item_emerald-dreamcatcher-549a44bd02c4fa26edf4/1-0000.mp3", duration = 39.1314286, start = 0},
  },
}
P.transport["item:empty-blue-waterskin"] = {
  hash = "5c8ca0",
  fullHash = "5c8ca0",
  text = "Empty Blue Waterskin. Brine sends the Empty Blue Waterskin north from the Barrens to gather sacred water. The liquid will help her prepare the draught needed to summon and appease the water spirit. Brine gives the Empty Blue Waterskin to a shaman initiate at her hilltop hut in the southern Barrens. The vessel marks the final and most perilous gathering task of early training. To commune with the spirit of water, the initiate must seek pure, undisturbed sources across Kalimdor. The waterskin is meant for a secluded fountain deep within the Ruins of Stardust, along Ashenvale's contested borderlands. The initiate must leave the safety of Horde territory and travel into ancient groves guarded by nature beasts and night elves. At a fountain in the ruined sanctuary deep within the Ruins of Stardust, the waterskin is filled and becomes a Filled Blue Waterskin. With water samples from the Barrens and Tarren Mill, its contents let Brine brew the draught needed to summon and appease the elemental spirit of water.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-blue-waterskin-7ad4762648c59a5dc7cc/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["item:empty-brown-waterskin"] = {
  hash = "5b1af4",
  fullHash = "5b1af4",
  text = "Empty Brown Waterskin. In the Barrens, Brine gives an empty waterskin to a shaman initiate. Brine gives a shaman initiate an empty leather skin for the opening trial of the Call of Water. The initiate must carry it to the watering hole beneath her dwelling and return with it full. The pool is guarded by local quilboar, who prize its water. In the Barrens, where water is scarce, even a small oasis can sustain life and spark violence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-brown-waterskin-2141795637a3e978cc9c/1-0000.mp3", duration = 25.4693878, start = 0},
  },
}
P.transport["item:empty-cleansing-bowl"] = {
  hash = "a2ca26",
  fullHash = "a2ca26",
  text = "Empty Cleansing Bowl. At Auberdine, the Empty Cleansing Bowl carries moonwell water against the Blackwood corruption. Mixed with food samples, the water makes a meal that briefly breaks the satyrs’ demonic sway over the furbolgs. Thundris Windweaver gives the Empty Cleansing Bowl to adventurers in Auberdine to carry sacred water from the local moonwell. The night elves have learned that satyrs use enchanted talismans to drive the northern Blackwood furbolgs into demonic madness. Dip the bowl into the moonwell, then mix the water with nuts, grains, and fruits gathered from the furbolgs. The blessed meal briefly restores the afflicted creatures’ sanity and reveals the satyr overseer responsible.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-cleansing-bowl-55a3fcd078ee08593b78/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:empty-cliffspring-falls-sampler"] = {
  hash = "65dd38",
  fullHash = "65dd38",
  text = "Empty Cliffspring Falls Sampler. At Cliffspring Falls in Darkshore, young druids gather water to investigate a poison killing local wildlife. The Cenarion Circle gives them empty samplers for water from the cave mouth. Cliffspring Falls feeds northern Darkshore, so trouble in its headwaters threatens the local wildlife. When a wasting poison began killing the region’s deer, Dendrite Starblaze of the Cenarion Circle gave empty samplers to young druids sent from Moonglade. They must reach the cliffs by the falls and gather water at a cave entrance overrun by hostile naga.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-cliffspring-falls-sampler-944d1402b1174c8b79df/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:empty-dreadmist-peak-sampler"] = {
  hash = "dcddc6",
  fullHash = "dcddc6",
  text = "Empty Dreadmist Peak Sampler. At Dreadmist Peak, druids seek tainted water in an empty Cenarion vessel. The sample may help diagnose and cure the blight spreading among wildlife in the northern Barrens. Dendrite Starblaze suspects the pools atop Dreadmist Peak are at the heart of a sickness afflicting gazelles and unsettling the northern Barrens. The pools influence the weather, and the druid fears they are tied to the spreading blight. He sends druid initiates with empty samplers to brave the mountain heights and draw water from the peak. The Burning Blade, a demon-worshipping cult, now infests the mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-dreadmist-peak-sampler-bbcc704857b00a747c37/1-0000.mp3", duration = 33.1493878, start = 0},
  },
}
P.transport["item:empty-leaden-collection-phial"] = {
  hash = "05fd95",
  fullHash = "05fd95",
  text = "Empty Leaden Collection Phial. In the ruins of Gnomeregan, Ozzie Togglevolt’s leaden phial gathers radioactive fallout for study. He hopes it may help cure his afflicted kin, or make an extraordinarily potent drink. Ozzie Togglevolt made a leaden phial to gather the radiation left in Gnomeregan. When the city’s vents flooded its tunnels with toxic radiation to purge the trogg menace, the surviving defenders became leper gnomes and the invading beasts were irradiated. The green glow still clings to Irradiated Invaders and Pillagers prowling the ruins. The phial’s lead shields its handler as it draws in the dangerous residue. Once sealed, it becomes a Full Leaden Collection Phial, holding matter for Ozzie’s experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-leaden-collection-phial-653d59e24fd7bb4069ce/1-0000.mp3", duration = 39.5232653, start = 0},
  },
}
P.transport["item:empty-red-waterskin"] = {
  hash = "b41d74",
  fullHash = "b41d74",
  text = "Empty Red Waterskin. In Tarren Mill, an empty red waterskin is bound for a well untouched by blight. Brine gives it to shaman initiates for their elemental trials. Brine gives shaman initiates this plain red skin for the Call of Water trials. They carry it across the sea to Tarren Mill in the Hillsbrad Foothills. The Forsaken occupy the town, but its central well still draws fresh spring water. The filled skin brings a sample to Brine, who blends the water into a vial of purest water for the initiate’s trial.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-red-waterskin-2211526cc98cf3d94fe4/1-0000.mp3", duration = 30.3542857, start = 0},
  },
}
P.transport["item:empty-sampling-tube"] = {
  hash = "2d5c6f",
  fullHash = "2d5c6f",
  text = "Empty Sampling Tube. Thundris Windweaver gives an Empty Sampling Tube in Auberdine to gather water from the Cliffspring River. Night elf scholars study the taint threatening Darkshore. Darkshore's waterways are turning foul as blight spreads through the wilderness. Thundris Windweaver, an investigator in Auberdine, gives you an empty glass tube to collect water from the Cliffspring River. Take the sample from the pool beneath the first waterfall north of town. Night elf naturalists examine it to learn about the corruption flowing toward Mist's Edge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-sampling-tube-802c119bc04dce62768a/1-0000.mp3", duration = 30.4065306, start = 0},
  },
}
P.transport["item:empty-water-tube"] = {
  hash = "50136e",
  fullHash = "50136e",
  text = "Empty Water Tube. In Auberdine, the Empty Water Tube is ready to gather sacred moonwell water for the red crystal on Darkshore’s eastern cliffs. Sentinels and scholars seek pure lunar essence to study the mysterious red crystal along Darkshore’s eastern ridge. Ordinary glass or flasks can contaminate consecrated water, so investigators visiting Auberdine’s moonwell receive this sealed vial for the work. They carry its filled contents up the mountain slopes to learn how the alien mineral responds to Elune’s magic.",
  ["1"] = {
    {file = "Audio/Transport/full_item_empty-water-tube-7409bdb736c629f78459/1-0000.mp3", duration = 29.3877551, start = 0},
  },
}
P.transport["item:enchanted-gaea-seeds"] = {
  hash = "dc4f00",
  fullHash = "dc4f00",
  text = "Enchanted Gaea Seeds. At Sun Rock Retreat, Enchanted Gaea Seeds are prepared for the Charred Vale. Druidic magic gives them strength to take root in ash-choked soil and begin restoring Kalimdor's ravaged land. The Horde's druids are trying to heal the deep scars across Stonetalon Mountains. At Sun Rock Retreat, Tammra Windfield enchants raw Gaea Seeds so they can withstand corruption and elemental blight. Planted in the fertile dirt mounds beneath the Charred Vale's soot, they take root despite the harsh land. Hostile fire elementals and invasive harpies still dominate the vale. Planting the seeds is part of the struggle for Stonetalon's future. Their enchanted husks resist lingering corruption and give native plants a foothold. The returning vegetation is meant to soothe agitated fire elementals, crowd out feral harpies, and counter the deforestation caused by the Venture Company's relentless logging.",
  ["1"] = {
    {file = "Audio/Transport/full_item_enchanted-gaea-seeds-cc092ec10a709694d714/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:enchanted-resonite-crystal"] = {
  hash = "3ab338",
  fullHash = "3ab338",
  text = "Enchanted Resonite Crystal. In Stonetalon, Mor'rogal has altered resonite crystals with shamanic magic. The Enchanted Resonite Crystal is made to break the cask holding Goggeroc. Deep in the caverns of the Stonetalon Mountains, raw resonite crystals carry unusual harmonic and earthen properties. Shaman Mor'rogal sensed danger sleeping inside a sealed underground cask and altered the minerals with his elemental powers. The Enchanted Resonite Crystal can break the reinforced Resonite cask and rouse Goggeroc, a giant Earthen, while he is still dazed from his long sleep.",
  ["1"] = {
    {file = "Audio/Transport/full_item_enchanted-resonite-crystal-ce38fe0a32709f7fee1f/1-0000.mp3", duration = 33.2016327, start = 0},
  },
}
P.transport["item:encrypted-memorandum"] = {
  hash = "251b5f",
  fullHash = "251b5f",
  text = "Encrypted Memorandum. In Coldridge Valley, the Encrypted Memorandum guides new rogues to their trainer. Solm Hargrin disguises his invitation as official communication and calls scoundrels in exile to stand together. In Anvilmar, rogues keep their presence quiet. Their trainer, Solm Hargrin, uses the Encrypted Memorandum to reach recruits without approaching them in plain view. Disguised as a directive from distant superiors, the coded parchment tells fledgling rogues where to find a mentor while avoiding the attention of local guards and suspicious townsfolk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-memorandum-7b0c98b30d79475613e2/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["item:encrypted-parchment"] = {
  hash = "24f252",
  fullHash = "24f252",
  text = "Encrypted Parchment. In the Valley of Trials, Encrypted Parchment guides young orc rogues toward the Den. Gornek hands it to recruits who show promise, and its cipher points them to Rwag, the hidden trainer. Young orcs prove their strength in the Valley of Trials under the open sun. Those who show a gift for stealth, deception, and bladecraft draw different notice. After facing the local wildlife, promising orc rogues receive Encrypted Parchment from Gornek. Its coded words call to those who can read a message meant to stay hidden. The cipher leads a novice into the Den, past the other clan trainers, to find Rwag. The recruit learns there that the Shattered Hand arranged the summons. The order works within the Horde's covert network, and answering the call begins a rogue's training in espionage and shadowcraft.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-parchment-c517788e0f06d86b7e9d/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["item:encrypted-rune"] = {
  hash = "481efa",
  fullHash = "481efa",
  text = "Encrypted Rune. In Coldridge Valley, an Encrypted Rune quietly calls promising new rogues to Anvilmar. Its message asks them to decipher its contents and seek out rogue trainer Solm Hargrin. The Encrypted Rune is a discreet summons for those who show promise in stealth and cunning. Solm Hargrin, the rogue mentor in Anvilmar, sends the inscribed stone with ciphers for its bearer to decipher. The message tests whether a new rogue can read thieves' cant and introduces the shadowy craft needed to survive Dun Morogh's harsh wilderness. Deciphering the rune leads new rogues to Solm Hargrin inside Anvilmar. He hopes to strengthen the valley's covert ranks amid rising local tensions. Along with bladecraft and stealth, Solm teaches vigilance and camaraderie. In a time of strained peace, rogues need to stick together.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-rune-1ed81ff38300550679d1/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["item:encrypted-scroll"] = {
  hash = "5c67c3",
  fullHash = "5c67c3",
  text = "Encrypted Scroll. In Deathknell, an Encrypted Scroll calls a newly risen rogue to training. Sealed by David Trias, it directs its bearer to meet him at the inn and begin training among the Forsaken’s covert operatives. In Deathknell, a newly awakened Forsaken with a gift for stealth draws notice. The Encrypted Scroll is handed over after a scout proves capable against the mindless Scourge in the nearby graveyard. Sealed by rogue trainer David Trias, it tells the bearer to find him at the local inn. The summons points a fledgling operative toward the discipline needed to serve the Dark Lady, rather than spend a second chance at life as a pickpocket. The scroll’s brief message tells the rogue to make contact in Deathknell before traveling deeper into Tirisfal Glades. Trias watches for promising talent on behalf of the Shadowstalkers, the Forsaken’s covert arm. In Lordaeron, the Forsaken rely on silent blades and cunning scouts against the Scarlet Crusade, surviving Alliance enclaves, and the Scourge left behind. Answering the ciphered summons begins the path toward joining that covert network.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-scroll-9e9bfbe5949b5faf03f3/1-0000.mp3", duration = 64.5485714, start = 0},
  },
}
P.transport["item:encrypted-sigil"] = {
  hash = "b34c3b",
  fullHash = "b34c3b",
  text = "Encrypted Sigil. In Shadowglen, the Encrypted Sigil carries a summons to newly awakened night elf rogues. Frahun Shadewhisper calls them to begin training as dangers gather around Teldrassil. New night elf scouts and infiltrators in Shadowglen receive the Encrypted Sigil through discreet means. A quiet messenger delivers it on behalf of Frahun Shadewhisper. Its contents are hidden instructions that tell the initiate to report to Frahun near Aldrassil. Reading and delivering the token shows Frahun that an initiate can follow subtle directions and handle covert messages. Frahun uses the summons to explain why rogues matter in an unsettled world. Tensions simmer between the night elves and the distant Horde, but open warfare is not the only danger facing their people. Rogues must gather intelligence across Teldrassil as the Kaldorei’s unseen eyes and blades, and learn to strike before threats take root in the World Tree’s boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-sigil-e2795ecb779ac64cdf36/1-0000.mp3", duration = 54.4130612, start = 0},
  },
}
P.transport["item:encrypted-tablet"] = {
  hash = "66491c",
  fullHash = "66491c",
  text = "Encrypted Tablet. In the Valley of Trials, the Encrypted Tablet sends novice troll rogues to Rwag. The rogue trainer inscribes its coded message and keeps his post inside the Den. Novice troll rogues receive the Encrypted Tablet when they arrive in the Valley of Trials. Its ciphered words direct them to Rwag, an orc trainer who lives in the Den’s shaded caves. The slate keeps the local shadow operatives’ business discreet while testing whether new recruits can understand its message. Deciphering the tablet brings recruits into contact with the Horde’s wider shadow network. When they report to Rwag, scouts learn that syndicates such as the Shattered Hand watch their progress. The syndicates rely on valley trainers to judge whether prospective cutpurses, spies, and assassins are sharp enough to serve the new nation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_encrypted-tablet-1ea54ee327f7c5a4d611/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["item:essence-of-nightlash"] = {
  hash = "1054f2",
  fullHash = "1054f2",
  text = "Essence of Nightlash. At the Dead Fields, Nightlash's defeat leaves a trace the Forsaken can carry away. High Executor Hadrec needs it as proof that the Scourge force behind the rot hide gnolls has been broken. At the abandoned farmstead called the Dead Fields in northern Silverpine, packs of undead rot hide gnolls have dug in under Scourge command. Forsaken assaults have failed again and again, not because of the feral gnolls, but because their spectral commander, Nightlash, turns them back. Her wailing magic strengthens the gnoll lines and routs forces sent from the Sepulcher. When Nightlash is slain, her incorporeal form dissolves into dust, leaving a crystalline magical essence behind. Banshees leave no bodily corpse, so Nightlash's essence is the only physical proof that the spirit has been destroyed. High Executor Hadrec at the Sepulcher needs it to confirm that the Scourge foothold has fallen. With that proof, the Forsaken can secure their northern perimeter and suppress the rot hide threat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_essence-of-nightlash-4e227cddba1b6bcc88fa/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["item:essential-artificial"] = {
  hash = "4ef5f6",
  fullHash = "4ef5f6",
  text = "Essential Artificial. In Ironforge, Essential Artificial parts remain vital to gnomish tinkers and engineers rebuilding from exile. Stockpiles were left behind when the gnomes fled Gnomeregan. Before Gnomeregan fell, tinkers called the Essential Artificial a nigh-universal component. Gnomish engineers fitted it into countless contraptions, clockwork wonders, and heavy machinery throughout the subterranean halls. Its standardized design gave smiths and machinists reliable parts they could interchange. The trogg invasion and radiation disaster drove the gnomes from Gnomeregan in a desperate rush. Large reserves of Essential Artificial parts stayed behind in heavy, steam-powered dispensers called artificial extrapolators, scattered through the deeper passages. In Tinker Town, master craftsman Klockmort Spannerspan actively recruits daring adventurers to return to the contaminated ruins and salvage the parts, so research and invention can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_item_essential-artificial-14433d6e5d05d9b9f679/1-0000.mp3", duration = 54.6481633, start = 0},
  },
}
P.transport["item:etched-note"] = {
  hash = "7c8d00",
  fullHash = "7c8d00",
  text = "Etched Note. At Camp Narache, the Etched Note calls a young tauren hunter to begin training. Lanka Farshot, the camp's hunter trainer, welcomes the novice to the traditions of the hunt. At Camp Narache, a runner brings young shu'halo a message from Lanka Farshot, the camp's hunter trainer. The note names the hunter the heart of the tribe. It also warns that natural instinct needs rigorous instruction and deep respect for Mulgore's wilderness. For the tauren, hunting is a sacred discipline and a way of survival, woven into tribal life. Hunters join the work of warriors, shamans and druids, and the tribe looks to them for guidance and protection. The student presents the note to Lanka to begin learning weaponcraft and how to understand beasts, preparing to defend and sustain the tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-note-3e6ce367a29e386b78b8/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["item:etched-parchment"] = {
  hash = "4d7286",
  fullHash = "4d7286",
  text = "Etched Parchment. Gornek gives hunters in the Valley of Trials a summons from Jen'shan. The Etched Parchment points them toward their first lessons in Durotar. Young orcs and Darkspear trolls begin their rites in the Valley of Trials. As recruits prove themselves against the local vermin, Gornek guides them toward their calling. He gives the Etched Parchment to those who will wield bow, gun, and fang. Its message comes from Jen'shan, a skilled hunter trainer seeking fresh eyes and steady hands. Taking the parchment to Jen'shan begins a hunter's training in Durotar. She teaches that the wild path takes dedication: mastering the beasts of the desert demands as much effort as an arcanist's magic or a shaman's work with the spirits. Her summons brings new hunters to lessons in marksmanship and wilderness survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-parchment-b694d659219e21b3688a/1-0000.mp3", duration = 46.2628571, start = 0},
  },
}
P.transport["item:etched-rune"] = {
  hash = "5c27c4",
  fullHash = "5c27c4",
  text = "Etched Rune. In Coldridge Valley, the Etched Rune invites aspiring dwarven hunters to Anvilmar. Hunter trainer Thorgas Grimson sends it to begin their formal wilderness instruction. The Etched Rune bears dwarven runes and reaches novices who show promise in Coldridge Valley’s snowdrifts. Mountaineer and hunter trainer Thorgas Grimson sends it to call fledgling trackers to Anvilmar. The rune marks their first step beyond basic survival and into the craft of the wild: respecting Dun Morogh’s beasts, tracking mountain predators, caring for ranged weapons, and enduring the harsh elements.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-rune-e6f20642645c8f6b1ddc/1-0000.mp3", duration = 33.9330612, start = 0},
  },
}
P.transport["item:etched-sigil"] = {
  hash = "6b4e7a",
  fullHash = "6b4e7a",
  text = "Etched Sigil. In Shadowglen, the Etched Sigil calls new night elf hunters to their trainer. Newly awakened night elf hunters receive the Etched Sigil as they enter Shadowglen. Its carved marks of the hunt carry a welcome and summons from Ayanna Everstride, the hunter trainer who lives high in Aldrassil’s hollowed boughs. The token sends each novice to seek her out and begin instruction in archery, wilderness tracking, and the night elf bond between stalker and beast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_etched-sigil-1361c13b4a2a1a13adb0/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["item:explosive-stick-of-gann"] = {
  hash = "f22af4",
  fullHash = "f22af4",
  text = "Explosive Stick of Gann. In the southern Barrens, Gann Stonespire turns stolen dwarven plans against Bael Modan. He built the charge to sabotage the dwarves’ flying machine. When Prospector Khazgorm led the Ironforge excavation into southern Kalimdor, the dwarves drove the Stonespire tauren from their ancestral village and razed their sacred grounds to build Bael Modan. Gann Stonespire reclaimed Khazgorm’s blueprints to avenge his displaced and fallen kin. He studied the plans and assembled a charge with enough force to wreck heavy machinery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_explosive-stick-of-gann-16ba6b4548d9fb621d04/1-0000.mp3", duration = 30.3281633, start = 0},
  },
}
P.transport["item:faded-shadowhide-pendant"] = {
  hash = "c3210b",
  fullHash = "c3210b",
  text = "Faded Shadowhide Pendant. A voice now comes from the Faded Shadowhide Pendant, found in the Redridge Mountains. The Shadowhide gnolls wore it to receive orders from Morganth, and the delayed message is a spell cast by Theocritus. The Shadowhide gnolls of the Redridge Mountains follow Morganth and coordinate their movements through enchanted pendants. From his sanctuary at Tower Azora, High Mage Theocritus studied the talismans and devised a spell to breach their magical link. His broadcast took weeks to appear. This faded pendant proves the gnolls’ communication can be intercepted, giving Theocritus a way to disrupt Morganth’s reach.",
  ["1"] = {
    {file = "Audio/Transport/full_item_faded-shadowhide-pendant-bb19d7878e74412b1002/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:fallen-moonstone"] = {
  hash = "1243c2",
  fullHash = "1243c2",
  text = "Fallen Moonstone. At Fallen Sky Lake in Ashenvale, night elves gather luminous, magically charged Fallen Moonstones from its tranquil waters. Sacred lunar energy gives the stones restorative power that can renew vitality and cure severe frailty. Southeast of Astranaar, Fallen Sky Lake once yielded many stones along its shores and shallows. Night elves prized their restorative magic and lunar blessing when ordinary remedies failed. Gathering them grew dangerous after corrupt Shadethicket bog beasts overran the lake. Their leader, a Shadethicket Oracle, hoarded every stone it found on a small island at the lake’s center, cutting the local Kaldorei off from a vital source of healing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fallen-moonstone-7bf1de709f383a2ca886/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["item:fandral-s-message"] = {
  hash = "63b8b8",
  fullHash = "63b8b8",
  text = "Fandral's Message. In Darnassus, Fandral Staghelm sends a message across the sea to Onu in Darkshore. The sealed dispatch carries news about Oracle Glade in Teldrassil. Arch Druid Fandral Staghelm writes from the Cenarion Enclave in Darnassus. His sealed dispatch is addressed to Onu, the Ancient of Lore who dwells in the Grove of the Ancients. Reports have reached Fandral about the state of Oracle Glade in Teldrassil, and he sends a courier south of Auberdine with word for Onu. The journey crosses the waters to Darkshore, carrying a message from the heart of the new World Tree to Kalimdor’s older, shadowed mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fandral-s-message-28b64719520e6daf69f2/1-0000.mp3", duration = 35.604898, start = 0},
  },
}
P.transport["item:fang-of-vagash"] = {
  hash = "c321de",
  fullHash = "c321de",
  text = "Fang of Vagash. In Dun Morogh, Vagash threatens the breeders’ prized rams from the snowy crags. The Fang of Vagash proves the notorious marauding predator has been slain. Vagash is a savage beast that stalks downhill from the ridges above Amberstill Ranch, often under cover of darkness, to slaughter prized rams. Dun Morogh’s high crags shelter bitter cold and fierce predators, but none have plagued the local ranches as Vagash has. Ironforge’s troops are stretched thin, leaving herdsmen without the city guard’s protection. A severed fang gives the breeders proof that Vagash is dead and the pasturelands are safe again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fang-of-vagash-261347556ddcbcffab20/1-0000.mp3", duration = 36.4146939, start = 0},
  },
}
P.transport["item:fangore-s-paw"] = {
  hash = "a3ca15",
  fullHash = "a3ca15",
  text = "Fangore's Paw. In the Redridge Mountains, Lieutenant Fangore leads the Shadowhide gnolls against Lakeshire. His severed paw proves his death to Magistrate Solomon, whose bounty seeks to end the threat Fangore poses to the besieged town. Lieutenant Fangore is a primary field commander among the Shadowhide gnolls encroaching across the Redridge Mountains. He serves the renegade mage Morganth and directs attacks on trade roads, outlying farms, and the defenses around Lake Everstill. Gnoll raiders leave no uniforms, official seals, or banners to confirm their dead, so the township authorities rely on physical proof. Magistrate Solomon demanded Fangore's paw to prove he had been executed, giving Lakeshire some relief amid the dangers closing around the town.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fangore-s-paw-85a3419b405f97add737/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["item:farren-s-report"] = {
  hash = "9ce67e",
  fullHash = "9ce67e",
  text = "Farren's Report. In Southshore, Farren's Report carries Lieutenant Farren Orinelle's findings on the local naga. He hopes the dispatch will win him a return to Stormwind. Lieutenant Farren Orinelle grew tired of Southshore's embattled coast, its local leadership, and its remote frontier. He had adventurers hunt the Daggerspine naga to gather proof of their threat, then gathered the findings into a formal report. Farren plans to send it to Major Samuelson, captain of the guard in Stormwind Keep, rather than to his commanding officer, Marshal Redpath. Samuelson trained Farren, and Farren hopes the report will show his competence and earn him an immediate transfer back to Stormwind City's comforts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_farren-s-report-07a6b43d4f3a986a560d/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:fathom-core"] = {
  hash = "c27ff4",
  fullHash = "c27ff4",
  text = "Fathom Core. Beneath the Moonshrine Ruins, the Fathom Core records the elements at work in Blackfathom Deeps. The Earthen Ring seeks it to learn how the Twilight's Hammer is manipulating those forces. The Fathom Core rests inside an ancient fathom stone beneath the Moonshrine Ruins. It records shifts, disruptions, and surges in the elements over time. Je'neu Sancrea, an Earthen Ring shaman at Zoram'gar Outpost, seeks the core to understand how the Twilight's Hammer cultists are turning the region's elements to their own ends.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fathom-core-ac7c28d850dc9cc10cfc/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["item:feather-charm"] = {
  hash = "42169f",
  fullHash = "42169f",
  text = "Feather Charm. In Anvilmar, the Frostmane novices' Feather Charms draw a warlock instructor's interest. Their crude trinkets carry a faint magical power. Southwest of Anvilmar, Frostmane novices carry feather charms through the snowy caverns. Their tribe is known for territorial savagery, yet the young trolls dabble in primitive spellcraft. The charms hold a faint but unmistakable magical power. In Anvilmar, warlock instructor Alamar Grimm studies this crude trollcraft with interest. He uses the charms as a proving ground for fledgling warlocks seeking to master the binding of their first imp.",
  ["1"] = {
    {file = "Audio/Transport/full_item_feather-charm-f3233b794c4eea576a30/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["item:fel-cone"] = {
  hash = "4c96ce",
  fullHash = "4c96ce",
  text = "Fel Cone. Beneath Teldrassil's boughs, Fel Cones carry corruption into the forest. Night elf defenders put the pods to use against nearby tricksters. Beneath Teldrassil's boughs, Fel Cones show that corruption has reached the young tree. Gnarled and fallen, the pine cones billow foul green smoke. They lie scattered just east of Dolanaar. Tainted magic has warped the surrounding flora, and the pods are dangerous to touch or eat without caution.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fel-cone-1932b5af0927c7b93d82/1-0000.mp3", duration = 26.357551, start = 0},
  },
}
P.transport["item:fel-moss"] = {
  hash = "8d4891",
  fullHash = "8d4891",
  text = "Fel Moss. Fel Moss spreads through Teldrassil’s forests, its insidious corruptive energies carried by hostile grell and grellkin. The taint threatens the World Tree’s wildlife and native furbolg tribes. Corruption has reached Teldrassil’s boughs, though the World Tree was planted to restore the night elves’ immortality and heal the natural world. Fel Moss is one clear sign of that decay. Impish grell and grellkin infest Shadowglen, with the unnatural, wicked magic of the moss clinging to them and radiating from their growth. The dryad Tarindrella gathers samples to measure how deeply the rot has entered the sacred woodland canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fel-moss-40de428c4f5577e01485/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["item:felix-s-box"] = {
  hash = "e40728",
  fullHash = "e40728",
  text = "Felix's Box. Felix Whindlebolt's box lies in Frostmane camps southwest of Anvilmar, far from the gnome refugee who lost it. Radiation swept through Gnomeregan during the failed attempt to purge the trogg menace, and Felix Whindlebolt fled with the gnomes into Coldridge Valley. In his rush to escape the fumes, he left his personal possessions and crafting gear along the snowy road. Frostmane trolls plundered the roadside goods before Felix could return. They carried his box, his chest, and his bucket of bolts to their settlements southwest of Anvilmar. Felix is unused to violence and poorly suited to Dun Morogh's wilderness, so he needs passing adventurers in Anvilmar to help recover his belongings. Getting them back would restore a measure of normalcy and the means to earn a living for the displaced artisan, who lost everything when Gnomeregan fell.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-box-95f9c058f05f2296c587/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["item:felix-s-bucket-of-bolts"] = {
  hash = "9f4565",
  fullHash = "9f4565",
  text = "Felix's Bucket of Bolts. In Dun Morogh, Felix Whindlebolt is missing the tools he carried from Gnomeregan. Frostmane trolls seized his bucket during his flight and took it to their camps. Felix Whindlebolt lost his tools while fleeing Gnomeregan. After the disaster against the troggs, radiation drove thousands of gnomes into Dun Morogh's freezing wilds with whatever they could carry. Felix escaped with his equipment and headed for Anvilmar, but Frostmane trolls from the crags southwest of town ambushed him. They plundered his belongings, including his bucket of bolts and parts, leaving the artisan without the materials he needed for his craft in exile.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-bucket-of-bolts-459f4eb36587f3870df8/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["item:felix-s-chest"] = {
  hash = "3f5f81",
  fullHash = "3f5f81",
  text = "Felix's Chest. Felix's Chest lies in a Frostmane camp southwest of Anvilmar. It holds belongings lost by the exiled gnome during the flight from Gnomeregan. Felix Whindlebolt fled Gnomeregan with the other gnomes when troggs and toxic radioactive fallout drove them from the city. The refugees crossed into snowy Dun Morogh with whatever they could carry. In the confusion, Frostmane trolls scavenged the roads and overtook scattered survivors. Felix lost his toolkits and belongings, and the trolls hauled his sturdy chest to their camps in the crags southwest of Anvilmar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felix-s-chest-bac7ad20c7f6d7a0bfee/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["item:felstalker-hoof"] = {
  hash = "cc32a4",
  fullHash = "cc32a4",
  text = "Felstalker Hoof. In Durotar's Valley of Trials, young shaman face demonic felstalkers as a test of readiness. Their hooves are brought to Canaga Earthcaller before they learn to commune with the earth spirits. Canaga Earthcaller sends young shaman against the demonic taint threatening Durotar. The Burning Blade Coven lies north in the Valley of Trials, where felstalkers roam among the coven's vile familiars. Taking a felstalker's hoof tests a shaman's endurance, resolve, and spirit. Those who subdue the beasts prove ready to receive the secrets of the earth and prepare the ceremonial sapta for communing with elemental spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_felstalker-hoof-006695ad2fe5e1f7a84b/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:fenwick-s-head"] = {
  hash = "15b86c",
  fullHash = "15b86c",
  text = "Fenwick's Head. Forsaken rogues seek Fenwick Thatros along the shores of Lordamere Lake. His head is proof of his execution, claimed on orders passed down from Lord Varimathras. Mennet Carkad acts from the Rogues' Quarter of the Undercity on urgent intelligence from dreadlord Varimathras. Fenwick Thatros, a hostile undead leader, has established a foothold near the decaying docks along Lordamere Lake in Silverpine Forest. To keep him from rallying hostile undead against the Forsaken, Carkad sends promising Deathstalkers to find and kill him, then bring back his head as proof. For Deathstalker operatives, bringing Fenwick's Head to Carkad is a trial beyond collecting a bounty. The severed head proves a rogue's skill in infiltration and assassination. Success opens the way to deeper, more specialized instruction in the shadow arts from Forsaken masters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fenwick-s-head-15a72f1b20db7a629d8d/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["item:fey-dragon-scale"] = {
  hash = "23c34b",
  fullHash = "23c34b",
  text = "Fey Dragon Scale. Around Stonetalon Peak, faerie dragons yield scales coveted by Jin'Zil. The Darkspear witch doctor uses one as a reagent in a brew that mocks night elven nature magic. Around Stonetalon Peak, faerie dragons haunt the wild groves of Kalimdor. Their scales gleam with natural magic. Night elves revere them as harmless woodland spirits and allies, while outsiders prize the scales as rare magical ingredients.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fey-dragon-scale-09f3083eeb8594daa4f7/1-0000.mp3", duration = 26.122449, start = 0},
  },
}
P.transport["item:filled-amethyst-phial"] = {
  hash = "94eae4",
  fullHash = "94eae4",
  text = "Filled Amethyst Phial. In Teldrassil, water from the Oracle Tree's moonwell fills an amethyst phial. Corithras Moonrage receives it for the Cenarion druids to study the World Tree's troubled growth. The Oracle Glade lies in northwest Teldrassil, where the oldest and most potent moonwell rests beneath the Oracle Tree. Other moonwells across the boughs meet the night elves' daily needs, but the water here carries the raw essence of Elune's grace. Druids who watch over the World Tree's health collect it in amethyst phials, preserving it for testing and ritual cleansing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-amethyst-phial-ba3d09a44b7b796fbdd8/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["item:filled-blue-waterskin"] = {
  hash = "941563",
  fullHash = "941563",
  text = "Filled Blue Waterskin. Shamans gather water for their trials at the Ruins of Stardust in Ashenvale. The Filled Blue Waterskin carries a pristine sample from the ancient fountain. Call of Water initiates cross north from the Barrens into Ashenvale's dense forests. Beyond Lake Mystral, the Ruins of Stardust lie against the mountains dividing Ashenvale from Stonetalon. Fierce forest beasts guard the secluded elven sanctuary. At the center of its lake, an untouched fountain holds water untainted by corruption or drought. A blue waterskin filled from its basin carries the sample sought by shaman masters for ritual attunement. Brine, a hermit and water expert, lives on a hill in the southern Barrens and needs this final sample. He combines it with water from contrasting wells and springs, then distills the pure essence into an offering. The offering can manifest and soothe the elemental spirits of water, completing an initiate's trial.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-blue-waterskin-692600ee26fe1e63d2f1/1-0000.mp3", duration = 53.7077551, start = 0},
  },
}
P.transport["item:filled-brown-waterskin"] = {
  hash = "c68ff6",
  fullHash = "c68ff6",
  text = "Filled Brown Waterskin. In the Barrens, the Filled Brown Waterskin carries fresh water from the pond below Brine's hut. Aspiring shaman bring it to her to begin brewing sapta, used to commune with water spirits. The pond beneath Brine's hut is a rare source of fresh water in the Barrens. Nearby quilboar fight fiercely over it, and a novice shaman sees how scarce water can drive creatures to defend what sustains them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-brown-waterskin-a40fcdc7be8cd8e2c7d4/1-0000.mp3", duration = 22.0212245, start = 0},
  },
}
P.transport["item:filled-cliffspring-falls-sampler"] = {
  hash = "b0032e",
  fullHash = "b0032e",
  text = "Filled Cliffspring Falls Sampler. Near Cliffspring Falls in Darkshore, the Filled Cliffspring Falls Sampler holds foul water drawn from the headwaters. The Cenarion Circle needs it to study the sickness striking local deer. Cliffspring Falls feeds much of Darkshore with water from the eastern highlands. Local deer have recently fallen ill with an unnatural sickness. At Dendrite Starblaze’s request in Moonglade, druidic initiates draw water from a cave mouth where hostile naga dwell. The liquid in the vial is visibly foul, showing that the fresh water supply is tainted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-cliffspring-falls-sampler-a724ba3c1853552bbf1d/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["item:filled-containment-coffer"] = {
  hash = "290d32",
  fullHash = "290d32",
  text = "Filled Containment Coffer. In the Undercity, Forsaken spellcasters use Filled Containment Coffers to capture erratic magical entities. A Cantation of Manifestation reveals and weakens rift spawn in the Apothecarium, so mages can seal them inside for examination. Magical disturbances have appeared in Algernon's shop in the Apothecarium. The Forsaken mage Anastasia Hartwell has called on arcane practitioners to capture the entities behind them. Rift creatures are living magical energy and cannot be seen, so ordinary cages cannot hold them. Spellcasters reveal them with a Cantation of Manifestation, defeat them in combat, and snap prepared coffers shut around them. The sealed boxes protect their carriers from volatile magical backlashes and keep the creatures intact for magical dissection. Living mana creatures in the Undercity pose a serious threat. Once sealed inside containment coffers, the beasts are carried to Anastasia Hartwell and the city's scholars. Forsaken mages seek to learn whether the intrusions come from natural rifts in Azeroth's magical fabric or are preliminary probes in a calculated magical assault on the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-containment-coffer-c129a5d0557b01a17dc8/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["item:filled-crystal-phial"] = {
  hash = "afb216",
  fullHash = "afb216",
  text = "Filled Crystal Phial. In Shadowglen, the Filled Crystal Phial holds water drawn from the moonwell north of Aldrassil. Tenaron Stormgrip asks young night elves to gather it as a first lesson in Teldrassil’s sacred power. Tenaron Stormgrip sends young night elves to gather moonwell water before they venture into the wider world. The moonwell lies in Shadowglen, and its waters hold more than spring water: they carry energies traced to the ancient Well of Eternity. Sentinels honor moonwells as shrines of Elune, while druids use their restorative power to tend nature. The arcane sorcery of old remains forbidden. Gathering the water begins a lesson in the sacrifice at Mount Hyjal and the care needed to nurture Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-crystal-phial-c360c3d29210382e1df7/1-0000.mp3", duration = 39.8628571, start = 0},
  },
}
P.transport["item:filled-cursed-ooze-jar"] = {
  hash = "ecc737",
  fullHash = "ecc737",
  text = "Filled Cursed Ooze Jar. In Felwood, a Filled Cursed Ooze Jar holds a sample for Laris Geardawdle in Ironforge. The gnome scholar seeks the ancient origins of slimes across Azeroth. Laris Geardawdle, a gnome researcher, sees mystery where most adventurers see vile puddles and caustic slimes. Slimes thrive in many places, and Forsaken apothecaries gather them with care. Those sights led Geardawdle to a bold theory: oozes may be primordial secretions bound to Azeroth's creation. To gather a sample, brave Felwood's blighted woods, defeat a cursed ooze, and scoop its acidic remains into an empty jar before they dissolve. Laris Geardawdle hopes his ooze samples will bring both knowledge and a lasting name. A major discovery could secure his reputation in the dwarven-led Explorers' League. Since Gnomeregan fell, many gnome refugees in Ironforge feel pressed to prove their worth to their dwarven hosts. Geardawdle believes that uncovering the ancient secrets of ooze will show them that welcoming gnomes was no mistake.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-cursed-ooze-jar-0cf0d4e007a8b69ca215/1-0000.mp3", duration = 60.8653061, start = 0},
  },
}
P.transport["item:filled-dreadmist-peak-sampler"] = {
  hash = "6e33dc",
  fullHash = "6e33dc",
  text = "Filled Dreadmist Peak Sampler. At Dreadmist Peak, a filled sampler holds water gathered by Horde druids from the summit pools. The Cenarion Circle studies the sample to learn what is poisoning wildlife in the northern Barrens. Dreadmist Peak’s high crags hold pools whose mists shape weather and rainfall across the northern Barrens. The Burning Blade, who worship demons, made their coven atop the summit, and the water soon soured. Cenarion druids suspect demonic rites poisoned the vapors that feed the surrounding savanna. They send initiates to collect a sample in a special sampler. The foul liquid confirms their fears: its corruption can sicken the herds below.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-dreadmist-peak-sampler-1d0628b1e8536af04a35/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:filled-etched-phial"] = {
  hash = "1dc407",
  fullHash = "1dc407",
  text = "Filled Etched Phial. In Thunder Bluff, the tauren seek a dryad phial filled with moonwell water. Its rare spiritual power can quench the eternal flame shielding a sacred centaur relic. To fill the phial, you must enter night elf territory deep in Ashenvale. Dryads around Raynewood Retreat carry the empty vessels, crafted to hold pure restorative draughts. A sacred moonwell near the western bank of the Falfarren River fills the phial with water rich in celestial and nature-bound power. Night elves regard taking it without leave as desecration. The tauren see the water as vital to meeting a threat farther south.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-etched-phial-1b2495d61233f26d62dd/1-0000.mp3", duration = 35.9444898, start = 0},
  },
}
P.transport["item:filled-jade-phial"] = {
  hash = "32a60c",
  fullHash = "32a60c",
  text = "Filled Jade Phial. In Dolanaar, the Filled Jade Phial is carried back with sacred water from Starbreeze Village. The water helps replenish the central wells while young night elves learn their people's history. Druids in Darnassus draw sacred moonwell water from across Teldrassil to replenish their central wells. Corithras Moonrage entrusts young travelers in Dolanaar with a jade phial made to hold the pure water safely. The moonwell outside Starbreeze Village lies east of Dolanaar. Initiates collect its water as they tend the World Tree. When you bring the Filled Jade Phial back to Dolanaar, Corithras Moonrage shares another chapter of kaldorei history. He tells of the years after the Third War, when Nordrassil burned, night elves lost their immortality, the Betrayer was released, and Shan'do Malfurion Stormrage disappeared.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-jade-phial-a6040079109346174333/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["item:filled-pure-sample-jar"] = {
  hash = "42b6b6",
  fullHash = "42b6b6",
  text = "Filled Pure Sample Jar. In Ironforge, Laris Geardawdle studies how corruption changes living matter. A Filled Pure Sample Jar holds primordial ooze gathered from the remote wilds, giving him an uncorrupted specimen for comparison. Laris Geardawdle studies oozes across Azeroth and how corruption changes living matter. He found that these shapeless creatures absorb and reflect the magic and conditions of their homes. After cataloging tainted slimes in Felwood, he sought a clean sample to compare with them. A Filled Pure Sample Jar holds primordial ooze gathered from the wilds of Un'Goro Crater, where it can be studied apart from corrupted strains. Oozes change readily, so Laris cannot find pure samples near civilization, demonic blights, or necromantic fallout. The glutinous oozes of Un'Goro Crater's untamed basin remain relatively isolated from outside corruption, making them a useful standard for scholars in Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-pure-sample-jar-23eb2c0a18e96a1903dc/1-0000.mp3", duration = 56.2416327, start = 0},
  },
}
P.transport["item:filled-red-waterskin"] = {
  hash = "c208ba",
  fullHash = "c208ba",
  text = "Filled Red Waterskin. In Tarren Mill, a well gives clear spring water for a shaman’s trial. The Filled Red Waterskin carries water drawn from the village well, amid ruins held by the Forsaken. Brine, a hermit in the Barrens, sends shaman initiates to Tarren Mill for water training. The journey leads to the Hillsbrad Foothills, where decay and the dead surround the town. Yet the central well still draws clear spring water. Brine sees this pure water as a sign of endurance in an unhallowed land. She compares the uncorrupted spring with Warchief Thrall’s resolve through hardship. Gathering the water tests an initiate’s respect for its purity, even in hostile surroundings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-red-waterskin-c4aec1b4b61adff829cd/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["item:filled-tainted-ooze-jar"] = {
  hash = "e0be5b",
  fullHash = "e0be5b",
  text = "Filled Tainted Ooze Jar. In Felwood, tainted ooze is gathered from the remains of corrupted oozes. The samples travel in containment jars to Ironforge, where they support bold theories about life’s origins on Azeroth. Across northern Kalimdor, tainted oozes carry Felwood’s lingering corruption. Gnomish researchers provide jars to contain them safely. Most travelers keep clear of the noxious creatures, but their remains yield samples for natural philosophy and biological study far from the blighted woods. Laris Geardawdle, a gnome scholar with the Explorers' League in Ironforge, gathers the samples. He is fascinated by how common slimes are, and has noticed the Forsaken's Royal Apothecary Society taking an interest in them as well. Many scholars dismiss his theory, but Geardawdle believes slimes and oozes may be primal secretions tied to Azeroth's creation. He seeks proof and a place among dwarven scholars after Gnomeregan's tragic fall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-tainted-ooze-jar-bab349ec8c7e26647db8/1-0000.mp3", duration = 54.3346939, start = 0},
  },
}
P.transport["item:filled-tourmaline-phial"] = {
  hash = "620290",
  fullHash = "620290",
  text = "Filled Tourmaline Phial. At the Pools of Arlithrien, the Filled Tourmaline Phial carries moonwell water for Corithras Moonrage. Its waters help him watch the health and balance of the growing World Tree. The Filled Tourmaline Phial draws water from a moonwell southeast of the road to Darnassus, on the shores of the Pools of Arlithrien. Reaching the shrine has grown dangerous as the Gnarlpine furbolgs, once peaceful neighbors, turn violently mad. Corithras Moonrage asks travelers to brave the hostile groves and bring back the water. He hopes it will help him find the deepening corruption unsettling the land.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-tourmaline-phial-4f0fcf8027c7a3f9150f/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["item:filled-vessel"] = {
  hash = "0c44ca",
  fullHash = "0c44ca",
  text = "Filled Vessel. At Dolanaar, Corithras Moonrage gathers sacred waters for Fandral Staghelm in Darnassus. The Filled Vessel carries samples from Teldrassil’s moonwells to aid his study of the World Tree’s ailments. Night elf acolytes gather water from moonwells across Teldrassil. The tree was planted without the blessings of the Great Aspects, Alexstrasza and Nozdormu, leaving its boughs open to corruption, strange beasts, and crazed furbolg tribes. Corithras Moonrage gathers the phials in Dolanaar and pours them into the Filled Vessel for the journey to the capital. Together, the waters offer a vital sample of Teldrassil’s vitality. Arch Druid Fandral Staghelm studies them in the Cenarion Enclave, seeking a remedy for the Great Tree’s flaws.",
  ["1"] = {
    {file = "Audio/Transport/full_item_filled-vessel-5267c9a74ff2ef920ee6/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["item:final-clue-to-sanders-treasure"] = {
  hash = "67355b",
  fullHash = "67355b",
  text = "Final Clue to Sanders' Treasure. Along Westfall's coast, Captain Sanders' last directions point out to sea. A note in an old jug sends scavengers west toward his buried treasure. Captain Sanders left his final directions in an old whiskey jug on the Westfall coast. The pirate had scattered cryptic notes along the shoreline, and this one completes the trail. From the jug, the directions lead due west into the ocean. Follow them through the surf to a lonely offshore rock, where his ironbound sea chest lies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_final-clue-to-sanders-treasure-d5a28c24ef521aa9e1ab/1-0000.mp3", duration = 31.0073469, start = 0},
  },
}
P.transport["item:fine-crab-chunks"] = {
  hash = "530314",
  fullHash = "530314",
  text = "Fine Crab Chunks. Fine Crab Chunks come from the Reef Crawlers and Encrusted Tide Crawlers along Darkshore's coast. Gubber Blump seeks them for his cooking. Reef Crawlers and Encrusted Tide Crawlers roam Darkshore's shores. Travelers may see them as pests or dangers by the water, while cooks prize their meat. The chunks can be boiled, broiled, fried, or added to stews.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fine-crab-chunks-9205bcece870c1c837d7/1-0000.mp3", duration = 21.8644898, start = 0},
  },
}
P.transport["item:fine-moonstalker-pelt"] = {
  hash = "c5b356",
  fullHash = "c5b356",
  text = "Fine Moonstalker Pelt. In southern Darkshore, mature moonstalkers carry the hides Terenthis needs. Their Fine Moonstalker Pelt is thick and healthy enough for an enchanted cloak that helps searchers pass the region’s hostile beasts unnoticed. Moonstalker sires and matriarchs have coats dense and healthy enough to yield a fine pelt. They hold territories along the Wildbend River and farther south toward Ashenvale’s borders, where they hunt with patience. Common moonstalkers prowl across Darkshore’s forests, but their hides are not fine enough.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fine-moonstalker-pelt-e563b9ab15df3818f514/1-0000.mp3", duration = 29.9885714, start = 0},
  },
}
P.transport["item:fire-tar"] = {
  hash = "bdf070",
  fullHash = "bdf070",
  text = "Fire Tar. Across the eastern Barrens, Razormane spellcasters carry Fire Tar. Horde shamans use it to brew the Fire Sapta, which lets them commune with fire spirits. Razormane geomancers, mystics, and thornweavers carry Fire Tar. The quilboar use the flame-tuned substance in their harsh magic and rituals. Shamanic instructors prize it as a worldly reagent that helps mortal senses reach the raw fury of the elements. Young orc and troll shamans travel to Telf Joolam, high among Durotar's crags, to forge their fire totems. Telf asks them for a reagent pouch taken from Burning Blade cultists and Fire Tar gathered from the Razormane. He brews the two ingredients into a fire sapta. Drinking it lets a shaman perceive the fire spirits waiting atop the nearby peaks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fire-tar-cb9a6f47cff14eff3582/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["item:fizzle-s-claw"] = {
  hash = "df51b7",
  fullHash = "df51b7",
  text = "Fizzle's Claw. In Thunder Ridge, Fizzle Darkstorm’s claw is carried to Razor Hill as proof of his death. The goblin warlock was a dangerous Burning Blade conspirator. Orgnil Soulscar sent forces to root out shadow cults threatening the orcish homeland. He identified Fizzle Darkstorm as an instigator spreading corruption in Thunder Ridge. The claw gives Horde commanders proof that the warlock, who operated under the Burning Blade’s banner, has been slain. Thunder Ridge lies just northwest of Razor Hill, close enough to threaten the surrounding lands. Horde scouts took Fizzle’s claw back to Razor Hill, confirming that his rituals and attempt to establish a Burning Blade foothold had been stopped.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fizzle-s-claw-ec35d632fd36e0756565/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:flagongut-s-fossil"] = {
  hash = "53b282",
  fullHash = "53b282",
  text = "Flagongut's Fossil. At the Wetlands dig, Flagongut seeks answers in an ancient fossil. The Explorers' League keeps the specimen, and Flagongut believes the Stone of Relu can help him decipher its secrets. Prospector Whelgar keeps the fossil at his excavation site in the southern hills of the Wetlands. Dwarven expeditions across Khaz Modan unearthed it, and Archaeologist Flagongut believes its ancient stone holds forgotten powers. He sees a kinship with artifacts found across the sea in Darkshore.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flagongut-s-fossil-e1430089c88f19bf9552/1-0000.mp3", duration = 28.682449, start = 0},
  },
}
P.transport["item:flatland-cougar-femur"] = {
  hash = "d98672",
  fullHash = "d98672",
  text = "Flatland Cougar Femur. Across Mulgore, cougars prowl the plains, and Maur Raincaller needs one of their bones. A Flatland Cougar Femur is part of the remedy he seeks for a venomous bite. Flatland cougars rank among Mulgore's most dangerous native stalkers. They blend into the dry brush, then spring upon unsuspecting prey. Hunters take their pelts and claws for leatherworking and trophies, while their heavy, marrow-rich bones have use in local medicine. Maur Raincaller of Bloodhoof Village suffered a venomous wound from Mazzranache, a monstrous pink strider. He urgently asked for a cougar femur and parts from other local beasts. Crushed or boiled, the bone yields properties for an antitoxin poultice meant to draw fever and necrotic venom from a festering bite.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flatland-cougar-femur-869aa2477ced99533f8d/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["item:flatland-prowler-claw"] = {
  hash = "fbff2a",
  fullHash = "fbff2a",
  text = "Flatland Prowler Claw. Across Mulgore's plains, Flatland Prowler Claws mark a young hunter's trial. Hunters gather them to prove their resolve and fieldcraft to the elders of Thunder Bluff. Flatland prowlers stalk Mulgore's plains, quick to ambush prey in tall grass. Their cunning and territorial nature makes them dangerous to travelers and a hard test for young hunters. Gathering their claws is a recognized tradition. Skorn Whitecloud sends promising wanderers to bring the claws to Melor Stonehoof at Hunter Rise in Thunder Bluff, proof that they have the resolve and fieldcraft to follow the hunter's way.",
  ["1"] = {
    {file = "Audio/Transport/full_item_flatland-prowler-claw-3f25dad33cdf0adf6398/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["item:foreman-s-blackjack"] = {
  hash = "69d01b",
  fullHash = "69d01b",
  text = "Foreman's Blackjack. Foreman's Blackjack keeps peons at work in Durotar's Valley of Trials. Foremen use the leather-wrapped cosh to wake laborers who fall asleep during the Horde's early construction. Durotar's rugged desert needs stockpiles of lumber for the Horde's new home. In the Valley of Trials, the work falls to the peons, and Foreman Thazz'ril keeps the crews moving with Foreman's Blackjack. The weighted bludgeon delivers a jarring wake-up call to laborers caught napping beneath the valley's shade trees, rather than a lethal blow. Peon life in the new Horde means grueling, unglamorous work under an iron fist.",
  ["1"] = {
    {file = "Audio/Transport/full_item_foreman-s-blackjack-5b04eeb2b0ebaa100bc5/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["item:forged-steel-bars"] = {
  hash = "ebbdab",
  fullHash = "ebbdab",
  text = "Forged Steel Bars. In the northern Barrens, Thun'grim Firegaze's steel bars are missing. Recovering them will prove a warrior's resolve to reclaim stolen property. Thun'grim Firegaze, a visually impaired orc smith, keeps a camp in the northern Barrens. Razormane quilboar took his iron chest during a night raid, distracting him with grunts and snorts while thieves slipped away. Unable to work fine steel, the quilboar left the unopened chest near a ruined wagon in their encampment to the northwest. The bars remain intact for warriors willing to recover them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_forged-steel-bars-517af054bd137e1585ee/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:fragments-of-rok-alim"] = {
  hash = "da3321",
  fullHash = "da3321",
  text = "Fragments of Rok'Alim. Fragments of Rok'Alim are the shattered stone remains of a primeval earth elemental roaming the canyons of Thousand Needles. Brought to Dorn Plainstalker at the Weathered Nook, they serve as undeniable physical proof that a warrior has bested an ancient terror in single combat. While most elementals faded from Azeroth following the banishment of the Old Gods, a handful possessed enough raw power to endure on the surface without being summoned by mortal magic. Rok'Alim the Pounder is one such survivor, wandering the canyon flats south of the main thoroughfare. Local centaur know him by the thunderous crashes of his stony fists pulverizing anything foolish enough to wander into his path. Striking down this living remnant of the primordial world yields jagged pieces of dense, animated rock—a trophy fit to prove unmatched physical prowess. For the tauren hermit Dorn Plainstalker, recovering the fragments is the decisive component of the Test of Strength. As part of a series of spiritual and martial rites conducted high within the Weathered Nook, the trial demands that an initiate face an entity of unyielding brute force. Delivering the battered rubble of Rok'Alim proves that an adventurer possesses the bravery and physical might required to survive the harshest perils of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fragments-of-rok-alim-be71d5984a0c577b16cb/1-0000.mp3", duration = 71.5755102, start = 0},
  },
}
P.transport["item:frostwolf-banner"] = {
  hash = "a2e362",
  fullHash = "a2e362",
  text = "Frostwolf Banner. In Alterac Valley, Horde initiates seek the Frostwolf Banner in Wildpaw Cavern. Recovering it is an ancestral rite of passage that awakens their battle spirit and earns their first clan insignia. Horde warriors seeking a place among the Frostwolf clan face a trial of grit in Alterac Valley. Warmaster Laggrond sends new recruits south into Wildpaw Cavern, where territorial gnolls fill the damp, hostile corridors. Reaching the hidden banner and bringing it back unbroken proves their courage and shows their battle rage has awakened. The trial earns each warrior the Frostwolf initiate's insignia.",
  ["1"] = {
    {file = "Audio/Transport/full_item_frostwolf-banner-d360bcb47e5e6e6c78b3/1-0000.mp3", duration = 36.5714286, start = 0},
  },
}
P.transport["item:full-leaden-collection-phial"] = {
  hash = "c0efc0",
  fullHash = "c0efc0",
  text = "Full Leaden Collection Phial. Ozzie Togglevolt seeks a sample from Gnomeregan’s troggs in a heavy, lead-lined phial. He hopes to make a cure for irradiated leper gnomes, or perhaps a dangerously potent rum. The phial’s lead lining shields its carrier from the volatile green fallout that saturates Gnomeregan. High Tinker Mekkatorque’s advisors flooded the lower corridors with toxic radiation to stop the invading troggs. Instead, the disaster corrupted troggs and surviving gnomes into maddened, irradiated horrors. Fluid residue gathered from Irradiated Invaders and Pillagers gives refugee tinkerers in Kharanos, including Ozzie Togglevolt and Razzle Sprysprocket, raw material for their experiments on remedies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_full-leaden-collection-phial-808859c32fed2d9d060b/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:fungal-spores"] = {
  hash = "66da85",
  fullHash = "66da85",
  text = "Fungal Spores. Around the Barrens' oases, Fungal Spores gather in swollen mushrooms. The waters quicken the life around them, and the Royal Apothecary Society seeks the spores for its alchemy. The Barrens' oases bring unusual life to the dry plains. At the Forgotten Pools, the Lushwater Oasis, and the Stagnant Oasis, the water does more than ease thirst. It quickens and changes the plants and wildlife nearby. Mushrooms along the damp shores swell with spores, carrying the waters' concentrated power to spur growth. Naturalists study this change, while the Royal Apothecary Society gathers the mushrooms for its alchemy. Apothecaries abroad gather unusual local ingredients for their laboratories and colleagues. At the Crossroads, Apothecary Helbrim sends such reagents onward, including to Apothecary Zamah in Thunder Bluff. The spores are valuable for brewing potent chemical mixtures. Their natural properties have already been altered by the mysterious forces beneath Kalimdor's soil, making them useful to the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_fungal-spores-1d7ec6472b8bebedc283/1-0000.mp3", duration = 61.0220408, start = 0},
  },
}
P.transport["item:furen-s-instructions"] = {
  hash = "2bf04e",
  fullHash = "2bf04e",
  text = "Furen's Instructions. In Stormwind, Furen's Instructions name the materials needed for fire-hardened mail. Furen Longbeard gives the parchment to Alliance warriors he has tested. Furen Longbeard offers to forge a resilient suit of mail for a warrior who has proved himself through simpler smithing work. The dwarven armorer asks the warrior to fetch the rare components himself. His parchment records what is needed and sends the warrior across continents to gather it. The parchment calls for a dangerous journey through the Eastern Kingdoms and Kalimdor. The hardened links need dozens of scorched spider fangs from damp caves in the Wetlands, along with horns from fire-breathing chimaeras in the crags of Stonetalon Mountains. The list also calls for a galvanized horn from the chimaera matriarch and a vial of volatile phlogiston held deep within Razorfen Kraul, a quilboar bastion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furen-s-instructions-dd085de985b8bef92a78/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["item:furen-s-notes"] = {
  hash = "724f42",
  fullHash = "724f42",
  text = "Furen's Notes. Furen's Notes carry his discoveries in metallurgy and armorsmithing from Stormwind to Alliance craftsmen. After forging protective gear for veteran warriors, Furen Longbeard sends copies to help fellow smiths refine their work. In Stormwind's Dwarven District, Furen Longbeard forges specialized armaments for warriors and records the methods and discoveries he makes along the way. Dwarven metalworking keeps changing, so he makes several copies for other smiths to use and build upon. His notes describe practical ways to temper, reinforce, and shape armor against deadly blows. Furen sends copies to trusted contacts in the Alliance's crafting networks. Grimand Elmore may scoff at a fellow smith he claims to have taught, but the notes still hold useful insights. Copies cross the Great Sea to night elven craftsmen, including Mathiel on Darnassus's Warrior's Terrace. Shared needs in battle bring their different traditions into contact.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furen-s-notes-ba35def946c6e05b483c/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["item:furlbrow-s-deed"] = {
  hash = "43daf1",
  fullHash = "43daf1",
  text = "Furlbrow's Deed. The Furlbrows are stranded near Westfall's border, and their land deed is in Defias hands. The paper bears Theodore and Verna Furlbrow's claim to their family farm, while the couple waits by their broken wagon. The deed bears Theodore Furlbrow's signature and Verna's as well, securing their family farm in Westfall. When the Defias Brotherhood overran the region, bandits drove the couple from their home and carried the paper into Elwynn Forest. Notes on its back show they meant to copy it when forging claims to other properties. The Furlbrows lost their home and livelihood, then took to the road. Their wagon broke near the border, leaving them stranded.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furlbrow-s-deed-c7287951314608d1990e/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:furlbrow-s-pocket-watch"] = {
  hash = "79ad1b",
  fullHash = "79ad1b",
  text = "Furlbrow's Pocket Watch. In Westfall, Farmer Furlbrow has lost a keepsake from his wedding day. His pocket watch came from Verna’s father, and it was left behind when Defias bandits seized the family’s pumpkin farm. Farmer Furlbrow and Verna fled their home in the night when Defias bandits swarmed the Furlbrow Pumpkin Patch. In the rush, he left a pocket watch from Verna’s father behind. The watch remains in a wardrobe in the overrun farmhouse, where Benny Blaanco and his cutthroats keep watch. The displaced couple now camps along the road, and the watch is one of the few pieces of their former life the outlaws have not ruined.",
  ["1"] = {
    {file = "Audio/Transport/full_item_furlbrow-s-pocket-watch-5fbbf62b3badb77cf66c/1-0000.mp3", duration = 36.4146939, start = 0},
  },
}
P.transport["item:gaea-seed"] = {
  hash = "dc24f1",
  fullHash = "dc24f1",
  text = "Gaea Seed. Along Mirkfallon Lake, Gaea Seeds offer a way to heal Stonetalon's wounded land. Tauren shamans value the hardy kernels for restoring places scarred by war and industry. Gaea Seeds wash ashore or grow along Mirkfallon Lake in the Stonetalon Mountains. Small and fibrous, they look like coconuts, yet endure harsh conditions. As conflict and industry scar the land, shamans see the seeds as a means to heal it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gaea-seed-ed30420000c1f0c7459b/1-0000.mp3", duration = 25.6261224, start = 0},
  },
}
P.transport["item:gaffer-jack"] = {
  hash = "233a7b",
  fullHash = "233a7b",
  text = "Gaffer Jack. Off Auberdine, Gaffer Jack parts lie beneath Darkshore's waves. Wizbang Cranktoggle lost a crate of them during his voyage across the sea. Gnome tinkerer Wizbang Cranktoggle booked passage to Auberdine, seeking quiet away from Ironforge's forge-works and taverns. During the voyage, he drank too much and fumbled an entire container of gaffer jacks over the railing. The small fasteners sank into Darkshore's coastal waters, leaving Wizbang without the parts he needed to tune his stintle pegs. The gaffer jacks sank in the surf along Darkshore's shore, where patient fishermen sometimes snag them on their hooks. Recovering the parts lets Wizbang assemble his strange contraptions. Finding tiny metal hardware in the open sea takes patience and luck.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gaffer-jack-b76401daaccbd3449f03/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["item:gallywix-s-head"] = {
  hash = "a1a4a1",
  fullHash = "a1a4a1",
  text = "Gallywix's Head. In Orgrimmar, Gallywix's Head proves that a Venture Company overseer was executed. The Shattered Hand demands the trophy as proof of the killing. Grand Foreman Puzik Gallywix directed the Venture Company's work from its tower north of the Sludge Fen. When word arrived that the Venture Co. planned something on a grand scale, the Shattered Hand sent operatives to dismantle the facility. Bringing Gallywix's head to Shenthul in Orgrimmar proves the overseer was executed and secures the rogue's standing within the guild.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gallywix-s-head-d95c146934b38e394f4e/1-0000.mp3", duration = 29.9363265, start = 0},
  },
}
P.transport["item:galvanized-horn"] = {
  hash = "d3b76d",
  fullHash = "d3b76d",
  text = "Galvanized Horn. In the Charred Vale, chimaera matriarchs bear horns that Stormwind and Thunder Bluff armorers seek. These hardened growths go into specialized armor for warriors. Chimaera matriarchs prowl the Charred Vale in the Stonetalon Mountains. Their horns grow unusually hard through ash, flame, and survival. Lesser fledgling chimaeras yield brittle, blackened horns, but a matriarch's horn has strength like treated metal. Furen Longbeard in Stormwind and Orm Stonehoof in Thunder Bluff both seek one as a test of martial valor and a key ingredient for exceptional mail armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_galvanized-horn-200a6e6d76d75028fe9f/1-0000.mp3", duration = 33.9330612, start = 0},
  },
}
P.transport["item:gargantuan-tumor"] = {
  hash = "697532",
  fullHash = "697532",
  text = "Gargantuan Tumor. In Teldrassil, a great growth was torn from Oakenscowl, the corrupted timberling by Lake Al'Ameth. The tumor bears witness to sickness spreading among the creatures there. Oakenscowl lurks in a cavern near Lake Al'Ameth's southern bank. Once a noble timberling elder, the creature has fallen to a vile affliction. A huge growth poisoned Oakenscowl, warped its behavior, and spread taint through the surrounding wildlife. The tumor was severed to end the beast's rampage and give local researchers a chance to examine the blight. They hope to learn how the malady took root in the boughs of the newly grown World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gargantuan-tumor-69a2292ddc098d19c438/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["item:garrick-s-head"] = {
  hash = "6cef4d",
  fullHash = "6cef4d",
  text = "Garrick's Head. At Northshire's vineyards, Garrick Padfoot's severed head proves the cutthroat is dead. The authorities at Northshire Abbey require it to pay the bounty. Garrick Padfoot and his gang harassed Northshire Valley's farmers and merchants for weeks. With Stormwind's defenses stretched thin, Garrick made his hideout in a shack near the vineyards and raided passing trade. Local guards were occupied by kobolds and Defias bandits, so Deputy Willem offered a bounty for the outlaw's death. He sought someone willing to kill Garrick and bring back proof.",
  ["1"] = {
    {file = "Audio/Transport/full_item_garrick-s-head-d9de1caad9344524df49/1-0000.mp3", duration = 31.4514286, start = 0},
  },
}
P.transport["item:gazlowe-s-ledger"] = {
  hash = "b59dca",
  fullHash = "b59dca",
  text = "Gazlowe's Ledger. In Ratchet, Gazlowe checks his trade records against the harbor manifest when a shipment from Booty Bay goes missing. Gazlowe tracks trade goods in Ratchet with a personal ledger. It records imported crates, outbound cargo, and warehouse stores. When a shipment from Booty Bay is missing, Gazlowe compares his expected inventory with the dock records kept by Wharfmaster Dizzywig.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gazlowe-s-ledger-0f846e52b79db96bf21f/1-0000.mp3", duration = 22.6742857, start = 0},
  },
}
P.transport["item:gem-of-anacondra"] = {
  hash = "30a6dd",
  fullHash = "30a6dd",
  text = "Gem of Anacondra. The Gem of Anacondra is one of four dream gems held by the corrupted serpent leaders within the Wailing Caverns. Carried by Lady Anacondra, it serves as tangible proof of her defeat and the curbing of the Nightmare's spread over the Barrens. When Naralex entered his deep slumber to bring water and life back to the arid Barrens, the Emerald Nightmare invaded his thoughts and warped his closest disciples. Lady Anacondra and her fellow conspirators abandoned their traditional ways to become the Druids of the Fang, twisting their noble restorative purpose into a toxic delusion. The Gem of Anacondra is one of the four dream gems carried by these serpentine leaders, focusing their corrupted bond with the Emerald Dream and anchoring the nightmare within the cave system.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-anacondra-f112e722378f62fc1e28/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["item:gem-of-cobrahn"] = {
  hash = "ebf758",
  fullHash = "ebf758",
  text = "Gem of Cobrahn. The Gem of Cobrahn is a dream gem carried by Lord Cobrahn, one of the corrupt leaders of the Druids of the Fang within the Wailing Caverns. It serves as both a focus of his corrupted reverie and physical proof needed by Nara Wildmane to confirm his defeat. When the night elf druid Naralex entered the Emerald Dream to restore the barren plains of Kalimdor, his nightmare twisted both the Wailing Caverns and his disciples. Among them was Cobrahn, who abandoned the peaceful ways of the Cenarion Circle to take the shape of the serpent. Lord Cobrahn carries one of the four dream gems that anchor the leaders' hold over the subterranean waterways, using it to channel the twisted dreams that threaten to transform the Barrens into a venomous marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-cobrahn-9d8e81008953ea69f323/1-0000.mp3", duration = 42.2661224, start = 0},
  },
}
P.transport["item:gem-of-pythas"] = {
  hash = "21b460",
  fullHash = "21b460",
  text = "Gem of Pythas. The Gem of Pythas is one of four corrupted dream gems carried by the leaders of the Druids of the Fang within the Wailing Caverns. Held by Lord Pythas, it fuels the nightmare twisting the subterranean oasis and threatening the Barrens. When Naralex entered the Emerald Dream to restore the arid Barrens, his noble vision was twisted into a living nightmare. His foremost followers fell with him, styling themselves the Druids of the Fang and seeking to remake the surface world into a venomous jungle. Lord Pythas carries this resonant stone, one of four dream gems anchoring the corruption within the caverns. The gem serves as a conduit of their dark design and proof to the druids of Thunder Bluff that Pythas's twisted trance has finally been broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-pythas-f3d2a4d33252462dc419/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["item:gem-of-serpentis"] = {
  hash = "132e2c",
  fullHash = "132e2c",
  text = "Gem of Serpentis. The Gem of Serpentis is a dream gem carried by Lord Serpentis, one of the four leaders of the Druids of the Fang in the Wailing Caverns. It acts as a focal conduit for the twisted nightmare reshaping the cave network and threatening the Barrens. When Naralex's slumber inside the Wailing Caverns succumbed to the Emerald Nightmare, his most devoted followers were warped into the fanatical Druids of the Fang. Lord Serpentis is one of the cabal's four leaders. Like the other three, Serpentis carries an enchanted dream gem that anchors their collective will to the corrupted vision. Recovering this gem breaks Serpentis's hold over the cavern's ecosystem, striking directly at the leadership directing the corruption spreading across the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gem-of-serpentis-eba2bee6cf5fd067d60d/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["item:gerenzo-s-mechanical-arm"] = {
  hash = "9dab03",
  fullHash = "9dab03",
  text = "Gerenzo's Mechanical Arm. In the Stonetalon Mountains, goblin operatives seek Gerenzo's Mechanical Arm as proof while clearing out competition. Taken from rogue engineer Gerenzo Wrenchwhistle, the grafted limb marks his death. Above Cragpool Lake, rogue engineer Gerenzo Wrenchwhistle grafted whirring gears and metal onto his failing body. The renegade gnome replaced his natural limbs with intricate machinery. Goblin tinker Ziz Fizziks seeks Gerenzo's elimination to impress his superiors, and this distinctive arm is the trophy he needs as indisputable proof of the engineer's death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gerenzo-s-mechanical-arm-5143075c48c99edd7e36/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["item:ghost-hair-comb"] = {
  hash = "d83a59",
  fullHash = "d83a59",
  text = "Ghost Hair Comb. Madame Eva sends Ghost Hair Comb to Blind Mary at her lonely home on Duskwood’s outskirts. The comb stirs grief, then yields ghostly hair for Eva to spin into thread. Madame Eva of Darkshire sends Ghost Hair Comb to Blind Mary, who lives in a lonely, dilapidated dwelling on Duskwood’s outskirts. At the sight of it, the ghost recoils in horror. She must face that she is no longer the lovely living woman she remembers. Grief-stricken, Mary thrusts the comb away, leaving strands of her ghostly hair tangled in its teeth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghost-hair-comb-ae11d4a7dd7449be53f0/1-0000.mp3", duration = 33.044898, start = 0},
  },
}
P.transport["item:ghost-hair-thread"] = {
  hash = "a556ea",
  fullHash = "a556ea",
  text = "Ghost Hair Thread. In Darkshire, Madame Eva spins Ghost Hair Thread from the spirit world. Its occult powers can bind spirits or stitch life into inanimate things. Abercrombie asks for it to ward his shack against restless ghosts. Madame Eva spins Ghost Hair Thread in Darkshire, where its strange powers are known. Eva says the spectral strand can bind malevolent spirits or stitch vitality into inanimate objects. In Duskwood, it can be used in rituals and wards.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghost-hair-thread-aae0f16d68801b026559/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["item:ghoul-fang"] = {
  hash = "2c0885",
  fullHash = "2c0885",
  text = "Ghoul Fang. In Duskwood, Ghoul Fang is gathered from the undead for Madame Eva’s protective talismans. The fangs are essential to her work in Darkshire, where travelers face the forest’s encroaching darkness. Ravenous undead haunt Duskwood’s shadowed woods and graves. Flesh Eaters lurk near the burial grounds, while Rotted Ones roam among the trees. Taking a fang from these creatures is grim work, and proof of survival against the dead threatening Darkshire’s borders. Madame Eva, Darkshire’s fortune teller and mystic, sees terrible omens around travelers who cross Duskwood. She combines ghoul fangs with skeletal fingers and arachnid venom to enchant the Totem of Infliction. The charm turns the forest’s dark forces against violent assault, protecting the one who bears it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghoul-fang-d901c7e95cb3a4fb3263/1-0000.mp3", duration = 47.3861224, start = 0},
  },
}
P.transport["item:ghoul-rib"] = {
  hash = "6cb1d4",
  fullHash = "6cb1d4",
  text = "Ghoul Rib. In Duskwood, ghouls roam the groves and cemeteries, and Abercrombie asks for their ribs. The hermit says he needs them to build an effigy that will ward off the flesh-eating horrors near his shack. Ghouls haunt Duskwood, among them Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones, and Plague Spreaders. Abercrombie lives alone in a shack north of Raven Hill Cemetery and asks travelers for their sturdy, rotted ribs. He says he lives beyond the Night Watch’s protection in Darkshire and needs a fearsome effigy to frighten the dead away from his home.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ghoul-rib-969e96a36633f3703a53/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["item:giant-crocolisk-skin"] = {
  hash = "09cde9",
  fullHash = "09cde9",
  text = "Giant Crocolisk Skin. In the Wetlands, giant crocolisks yield thick hides that Menethil Harbor tradesmen need for leatherworking. Taking one is perilous work, and more than one hunter has been maimed. The Wetlands' bogs and waterways shelter enormous crocolisks with hides dense enough to resist the marsh's damp rot. In Menethil Harbor, artisans such as James Halloran rely on steady shipments of skins to make rugged leather goods. Reaching a full-grown giant crocolisk means braving deep water and facing a fierce swamp predator, so every hide comes hard-won.",
  ["1"] = {
    {file = "Audio/Transport/full_item_giant-crocolisk-skin-2a83f5bb35e410bd796e/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["item:gloom-weed"] = {
  hash = "6d6aa3",
  fullHash = "6d6aa3",
  text = "Gloom Weed. In Tirisfal Glades, Gloom Weed grows in the fields between Deathknell and Brill. Gordo, a lumbering Forsaken abomination, gathers it by mistake while searching for doom weed. Gloom Weed grows in the fields west of Brill and east of Solliden Farmstead. The plant is harmless, with none of the alchemical strength sought by the Royal Apothecary Society. Gordo, an abomination, wanders the road pulling weeds with his clumsy hands. He misunderstood his master's orders and keeps gathering Gloom Weed instead. Then he asks travelers to carry it to Master Holland in the Brill graveyard, much to the apothecary's annoyance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gloom-weed-aaccd6457c9828afa9e8/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["item:glowing-ember"] = {
  hash = "0a8a69",
  fullHash = "0a8a69",
  text = "Glowing Ember. At the Shrine of Eternal Flame, a Glowing Ember kindles the brazier for a shaman's trial. It comes from a Minor Manifestation of Fire on Durotar's crags. A rising shaman drinks fire sapta to see the fiery spirits on the ridge near Telf Joolam. There, the initiate faces a Minor Manifestation of Fire. When the elemental falls, only a smoldering ember remains of its physical form. Raw elemental heat still pulses within it, carrying the living spark needed to awaken the sacred brazier at the Shrine of Eternal Flame.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-ember-e31cfdce6f4bbd581e88/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["item:glowing-fruit"] = {
  hash = "fc132f",
  fullHash = "fc132f",
  text = "Glowing Fruit. On Teldrassil, a strange fruit glows beneath unusual fronds. Denalan at Lake Al'Ameth studies its strange reaction to the World Tree's soil. The Glowing Fruit hangs beneath unusual fronds on Teldrassil, bright and round. Botanist Denalan at Lake Al'Ameth recognizes it as foreign to the World Tree. He thinks its seeds came from distant lands across the sea. Its reaction to Teldrassil's rich, enchanted soil shows how foreign plants can affect the young World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-fruit-31c883e554c836504398/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["item:glowing-gem"] = {
  hash = "a2a001",
  fullHash = "a2a001",
  text = "Glowing Gem. At Lake Falathim, the Glowing Gem lies among the murlocs after Teronis fell seeking it. The stone holds magic needed to restore Dartol's rod. Murlocs near Lake Falathim hold the Glowing Gem, a stone with latent magic. Teronis, a young night elf from Astranaar, went after it to find a way to push back the corruption spreading through Ashenvale's forests. Teronis died at the lake, but the stone remained intact among the scavengers along the shore.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-gem-bde60651ccae7e5ccbea/1-0000.mp3", duration = 27.5591837, start = 0},
  },
}
P.transport["item:glowing-soul-gem"] = {
  hash = "2a418d",
  fullHash = "2a418d",
  text = "Glowing Soul Gem. In Ordil'Aran, the Glowing Soul Gem serves the Cult of the Dark Strand's work in northern Ashenvale. Shadow sorcery fills the stone, which holds the spirit of an unwitting victim. Northeast of Maestra's Post, the ruins of Ordil'Aran shelter members of the Cult of the Dark Strand and their shadowy masters. The cult's operatives carry Glowing Soul Gems, enchanted vessels that trap and torment the souls of the dead. These stones channel magical energy and bind spirits to the cult's ends.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glowing-soul-gem-8c3f78beadeeab3994d7/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["item:glutton-shackle"] = {
  hash = "010b72",
  fullHash = "010b72",
  text = "Glutton Shackle. In Silverpine Forest, Glutton Shackles lend strength to Arugal’s flawed sorcery. The mad archmage crafted these enchanted restraints for Moonrage Glutton worgen. Feral worgen infest Silverpine Forest, and the Forsaken’s trained mages see them as proof of poor arcane work. Dalar Dawnweaver, an accomplished arcanist stationed at the Sepulcher, holds Archmage Arugal in contempt and calls him an incompetent hack unworthy of the Kirin Tor. Dawnweaver found that Arugal relied on enchanted relics to shore up his fragile spells. The heavy Moonrage Gluttons that roam northern Silverpine wear Glutton Shackles, magical anchors that reinforce the curse binding the beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glutton-shackle-7779e292ae276d4c292f/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:glyph-of-azora"] = {
  hash = "f5d32d",
  fullHash = "f5d32d",
  text = "Glyph of Azora. From the Tower of Azora, Theocritus uses Glyphs of Azora to watch distant threats. The inscribed stones extend the Eye of Azora's reach, letting him read enemies' thoughts and plans. Theocritus watches hostile powers from his tower in Elwynn Forest. His crystal relic, the Eye of Azora, lets him see across great distances, but cannot reach into the minds or plans of his adversaries. He places small focuses called Glyphs of Azora on surfaces far away to carry his magic farther. Each glyph anchors his power, letting him read enemy intentions and project his voice across miles to speak with field agents.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyph-of-azora-b80db4959796b1bcb6ef/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["item:glyphic-letter"] = {
  hash = "97b2ae",
  fullHash = "97b2ae",
  text = "Glyphic Letter. At Northshire Abbey, Glyphic Letter calls promising novitiates to arcane study. After early service to the garrison, they are summoned upstairs to Khelden Bremen, the resident mage trainer. Khelden Bremen seals the Glyphic Letter with his personal insignia. Apprentice spellcasters receive it after proving their discipline in Northshire Valley. The summons calls them away from basic field duties and into dedicated magical instruction within the abbey. Bremen tests each student's resolve before they take up the arcane, with its dangerous forces, unyielding scrutiny, and burdens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-letter-d826ac6e3ec760336242/1-0000.mp3", duration = 34.8734694, start = 0},
  },
}
P.transport["item:glyphic-memorandum"] = {
  hash = "d96b65",
  fullHash = "d96b65",
  text = "Glyphic Memorandum. In Coldridge Valley, the Glyphic Memorandum sends novice mages to Anvilmar. Marryk Nurribit wrote it to guide arriving spellcasters into formal arcane instruction. Novice spellcasters receive the Glyphic Memorandum after finishing their first tasks in Coldridge Valley. Marryk Nurribit, the local mage trainer, calls them inside Anvilmar. His advice is plain: learn your incantations, save coin for training and tavern ale, and keep clear of Gnomeregan, ruined by radiation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-memorandum-0b28c7de8eddd4e0f3c4/1-0000.mp3", duration = 27.8726531, start = 0},
  },
}
P.transport["item:glyphic-scroll"] = {
  hash = "87be62",
  fullHash = "87be62",
  text = "Glyphic Scroll. In Deathknell, the Glyphic Scroll calls newly raised Forsaken magi to the church. Isabella’s seal marks the summons, which invites fledgling spellcasters to begin their arcane training in undeath. Newly awakened Forsaken mages find a sealed scroll after culling mindless Scourge in Deathknell’s graveyard. Isabella, the settlement’s mage trainer, marks it with her seal and calls them to the ruined parish sanctuary. There, new magi begin learning the arcane under the Forsaken banner. Death has freed them from mortal weakness, but magic’s corrupting temptations remain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-scroll-2505a41374c8c00724b0/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["item:glyphic-tablet"] = {
  hash = "0453f8",
  fullHash = "0453f8",
  text = "Glyphic Tablet. In the Valley of Trials, Gornek gives the Glyphic Tablet to novice Darkspear troll mages. Its summons sends them to Mai'ah for instruction in arcane magic. New Darkspear initiates with an affinity for arcane power receive the Glyphic Tablet in the Valley of Trials. Gornek passes it to young recruits as they handle early tasks around the red canyons. On the slate, Mai'ah, a seasoned troll mage outside the Den, invites them to meet her. The Darkspear follow arcane traditions unlike the scholarly academies of humans or high elves. Mai'ah offers instruction and a solemn warning: raw magic corrupts and deceives, and its dangers to a mage's mind exceed those of any enemy soldier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphic-tablet-8ba816559be61fc1064c/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["item:glyphs-of-summoning"] = {
  hash = "b0c4ff",
  fullHash = "b0c4ff",
  text = "Glyphs of Summoning. In Orgrimmar, apprentice warlocks use the Glyphs of Summoning to call a voidwalker. Transcribed from the ancient Tablet of Verga, the inscriptions draw one from the Nether into a summoning circle and bind it to the warlock’s service. In the Cleft of Shadow, warlocks study the dark arts far from the prying eyes of the Warchief’s guards. For an aspiring warlock learning from Gan'rul Bloodeye, commanding a voidwalker marks an important step. The Glyphs of Summoning come from knowledge inscribed on the Tablet of Verga, and bridge Azeroth and the Nether. In Neeru Fireblade's tent, the warlock lays them within a summoning circle. They open a threshold and draw a creature of the Void into the mortal realm. Before Gan'rul teaches the final methods of binding, the warlock must defeat the summoned creature in combat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_glyphs-of-summoning-8cdec86872c4bd784826/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["item:gnoam-sprecklesprocket"] = {
  hash = "caa455",
  fullHash = "caa455",
  text = "Gnoam Sprecklesprocket. Deep in the Deadmines, Gnoam Sprecklesprocket powers a plan to reach Gnomeregan. Shoni the Shilent seeks it for drilling machines that could breach the rock around the lost gnomish home. Sneed's shredder runs deep in the Defias stronghold. The goblin taskmaster Sneed pilots the machine, whose compact power core supplies energy for heavy logging and cutting blades. Its steady output makes the Gnoam Sprecklesprocket valuable salvage in the tunnels of Westfall. In Stormwind City, the gnomish inventor Shoni the Shilent has chosen the Deadmines shredder for a larger effort. Gnomish forces seek to reclaim Gnomeregan from the troggs who overran it, but sealed underground approaches block the way. Shoni plans to power heavy gyrodrillmatic excavationators with the Sprecklesprocket. They could bore through the bedrock around the lost techno-city and open an unexpected route for an underground assault.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnoam-sprecklesprocket-f7159deaa1bab1f2d316/1-0000.mp3", duration = 49.9461224, start = 0},
  },
}
P.transport["item:gnoll-paw"] = {
  hash = "7e45fe",
  fullHash = "7e45fe",
  text = "Gnoll Paw. Gnoll Paws reach Sentinel Hill as proof of a patrol against Westfall’s Riverpaw packs. The People's Militia offers bounties to help protect local farmsteads. The People's Militia defends Westfall from Sentinel Hill. With the royal army absent and the crown seemingly blind to rural troubles, ordinary citizens and volunteers face outlaws, rogue mechanoids, and Riverpaw gnolls. Captain Danuvin offers bounties for proof that gnolls have been slain. Bringing back their paws shows that patrols have searched the scrublands instead of resting beneath the watchtower.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnoll-paw-65abfb101e08b0234275/1-0000.mp3", duration = 32.0261224, start = 0},
  },
}
P.transport["item:gnomeregan-gumdrop"] = {
  hash = "337a1f",
  fullHash = "337a1f",
  text = "Gnomeregan Gumdrop. During Hallow's End, Gnomeregan Gumdrops reach travelers from the exiled gnomes. One sweet helps sick Jesper celebrate at the Stormwind orphanage. At Ironforge's Mystic Ward, Talvash del Kissel hands out Gnomeregan Gumdrops to travelers who play along with his Hallow's End tricks. Innkeepers across the Alliance offer regional treats, but the exiled gnomes have no capital inn of their own. The radioactive disaster drove them from their underground kingdom, yet they still share their distinct sweets with the Alliance. Sick Jesper is confined to the Stormwind orphanage in Cathedral Square and cannot travel the continents to trick-or-treat. Travelers gather four regional sweets from Alliance capitals to bring the holiday to him: Gnomeregan Gumdrop, Stormwind Nougat, Ironforge Mint, and Darnassus Marzipan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnomeregan-gumdrop-a3b16861b4db36bedf06/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["item:gnomish-tools"] = {
  hash = "c2c334",
  fullHash = "c2c334",
  text = "Gnomish Tools. Along Durotar's coast, Gnomish Tools lie among the wrecks of Proudmoore's fleet. The Horde seeks the salvaged devices to study Alliance engineering and adapt its innovations for survival. Grand Admiral Daelin Proudmoore's fleet brought vast supplies of modern equipment to Durotar. Proudmoore led Kul Tiras and Alliance forces to its shores, with sophisticated gear made by their gnomish allies aboard. After the fleet was destroyed along the Scuttle Coast, east of Tiragarde Keep, the delicate mechanical kits sank beneath the waves. Waterproof toolboxes still lie among the rotting timbers and barnacle-encrusted hulls in the shallows. Gar'Thok, who oversees Razor Hill, sent Horde scouts to recover tools from the watery grave of Proudmoore's navy. The orcs know humans and gnomes are skilled in engineering, especially siege engines, shipwrighting, and clockwork mechanics. They send the kits by caravan to craftsmen and scholars in Orgrimmar. There, the Horde means to study Alliance contraptions, learn to counter enemy war machines, and adapt foreign innovations for its own survival.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gnomish-tools-033b70215e81e513aedb/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["item:gold-dust"] = {
  hash = "7174da",
  fullHash = "7174da",
  text = "Gold Dust. In Elwynn Forest, kobolds gather and hoard flecks of gold in the mines. Local buyers pay for the dust, while miners seek whole veins of ore. Kobolds dig through the Fargodeep and Jasperlode mines beneath Elwynn Forest. They keep the gold dust they find in pockets and pouches instead of refining it. Local peddlers and fences want these scraps, hoping to profit without paying official smelting tariffs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gold-dust-15d69950b103685494f6/1-0000.mp3", duration = 23.4840816, start = 0},
  },
}
P.transport["item:golm-fragment"] = {
  hash = "9b94ea",
  fullHash = "9b94ea",
  text = "Golm Fragment. The Golm Fragment is one of four missing pieces chipped from the Goaz Stone, an ancient relic uncovered at the Wetlands excavation site. Recovered by adventurers dodging ferocious raptors, it helps dwarven archaeologists piece together mysterious Titan inscriptions. Discovered at the excavation site in the southern Wetlands, the Golm Fragment is part of a monumental slab known as the Goaz Stone. Prospector Whelgar discovered the stone shortly before raptors drove the Explorers' League back, but found its inscription severed in four critical places. The Golm Fragment was abandoned amid the dirt and overturned crates when the dig was overrun, hidden away inside an ancient relic box until brave explorers could retrieve it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_golm-fragment-5db8c295b09c9037caba/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:gordon-s-crate"] = {
  hash = "3191af",
  fullHash = "3191af",
  text = "Gordon's Crate. Weapons are bound for the Forsaken forces in Silverpine Forest, packed in Gordon's Crate in the Undercity. The shipment is meant for the remote garrison at the Sepulcher. The Forsaken keep a steady flow of supplies from the Undercity to hold Silverpine Forest. Gordon's Crate carries weapons for Deathguard Podrig's defenders at the Sepulcher. The outpost sentries face worgen, wild beasts, and human remnants in the woods. Overland roads from the capital are dangerous and slow, so valuable shipments travel with the Undercity's bat handlers. Gordon's Crate is handed to Michael Garrett, the bat master above the city's trade quarter. He arranges passage on a trained flying bat to Karos Razok's roost back at the Sepulcher.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gordon-s-crate-95f6171c9786c48b247d/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["item:grape-manifest"] = {
  hash = "760c17",
  fullHash = "760c17",
  text = "Grape Manifest. At Northshire Abbey, the Grape Manifest records grapes recovered from Milly Osworth's vineyard after brigands seized the harvest. The fruit is bound for the abbey's cellars. Milly Osworth tends a vineyard in Northshire Valley, where local farms help feed Northshire Abbey. Defias bandits seized the harvest, putting the abbey's supply of fresh fruit and fermentable grapes at risk. The Grape Manifest records the grapes reclaimed from the fields and their quantity, so the abbey's quartermasters can account for their stores and prepare barrels for fermentation. Brother Neals oversees Northshire Abbey's food and drink, and he enjoys sampling its wine in the quiet of the bell tower. The manifest tells him the grapes are coming, helping ensure monks and visiting recruits have drink. For the abbey's brothers, each saved bushel is a victory for their stores and a blessing from the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grape-manifest-a9a4c6e203440b0e5372/1-0000.mp3", duration = 52.5583673, start = 0},
  },
}
P.transport["item:gray-bear-tongue"] = {
  hash = "fcd0fb",
  fullHash = "fcd0fb",
  text = "Gray Bear Tongue. In Hillsbrad Foothills, gray bear tongues are raw reagents sought by the Royal Apothecary Society in Tarren Mill for experimental toxins. Gray bears roam the wilds around Tarren Mill in several sturdy varieties. Their tongues hold heavy muscular tissue and fluids that Apothecary Lydon uses as a base ingredient for lethal solutions, including the Elixir of Suffering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gray-bear-tongue-5f6f3fb3b77763a126dd/1-0000.mp3", duration = 22.282449, start = 0},
  },
}
P.transport["item:gregor-s-remains"] = {
  hash = "e7733a",
  fullHash = "e7733a",
  text = "Gregor's Remains. Coleman Farthing seeks Gregor's Remains to settle an old score. The bones belonged to Gregor Agamand, once a member of Tirisfal Glades' wealthiest family. Before the Third War, the Agamands held great wealth and broad lands across northern Tirisfal Glades. When the Scourge invaded Lordaeron, the family patriarchs chose pride over flight. They fortified their mills and urged their loyal laborers to stand against the undead. The defense failed. The estate fell, and those who stood their ground were butchered and raised into undeath. Gregor Agamand became a mindless servant of the Lich King, haunting the mills his family had ruled. Some who escaped the Lich King's control joined the Forsaken, but the memory of that defense still wounds them. Coleman Farthing, a former mill worker now stationed in Brill, blames the Agamands' pride for trapping his soul in eternal rot. Farthing seeks Gregor's remains as personal retribution against the master who led his household into damnation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gregor-s-remains-b399d71f9aff6f79bd80/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["item:grelin-s-report"] = {
  hash = "263d23",
  fullHash = "263d23",
  text = "Grelin's Report. Grelin's Report is a dispatch written by Grelin Whitebeard detailing the Frostmane troll situation in Coldridge Valley. Entrusted to an adventurer rather than a novice apprentice, it serves as the official link between the scouts guarding Anvilmar and Senir Whitebeard stationed in Kharanos. Written after observing the Frostmane trolls in Coldridge Valley, Grelin's Report concludes that they pose no large threat and can be dealt with by the Mountaineers already stationed there and mercenaries paid from Senate funds. Rather than trusting his fumbling apprentice with such vital intelligence, Grelin enlists a capable traveler to carry the document through the trogg-infested Coldridge Pass. The paper acts as an official pass through Mountaineer Thalos's blockade, proving the bearer travels on urgent business to the wider snowy expanse of Dun Morogh. When delivered to Senir Whitebeard at the Thunderbrew Distillery in Kharanos, the report provides critical field updates intended for Ironforge. Senir notes with amused resignation that his brother invoked King Magni Bronzebeard's name liberally throughout the text. Grelin claims the King's sanction for the action, and Senir expects that appeal to royal authority to ruffle some feathers in the Ironforge Senate.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grelin-s-report-cf5810ea5d78c298afeb/1-0000.mp3", duration = 69.9820408, start = 0},
  },
}
P.transport["item:grelin-whitebeard-s-journal"] = {
  hash = "1dd100",
  fullHash = "1dd100",
  text = "Grelin Whitebeard's Journal. Grelin Whitebeard keeps a field journal in Coldridge Valley. The dwarf scout records Frostmane troll activity in its pages, until Grik'nir the Cold steals it and drags it into the troll cave. Grelin Whitebeard watches the Frostmane trolls near Coldridge Valley and records their movements in a leatherbound notebook. His field notes describe their strength, organization, and threat. Grik'nir the Cold, a heavily marked troll brute, takes the journal during a confrontation or ambush and carries it into the troll cave. Grelin needs the notes to finish his report, so he asks passing adventurers to retrieve the book.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grelin-whitebeard-s-journal-e121260ec09df4a6c408/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["item:grell-earring"] = {
  hash = "6ecfcf",
  fullHash = "6ecfcf",
  text = "Grell Earring. In Bashal'Aran, Grell Earring carries traces of the seal binding Asterion. Wild Grells and Vile Sprites in Bashal'Aran gather scraps among the ruins and make earrings from them. Most mortals see only worthless trinkets. Asterion, an ancient night elf bound there as a tormented phantom, studies the magic lingering on the earrings. He hopes those traces will lead him to the ancient seal that imprisons him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grell-earring-bc24c5ec9874f3222c29/1-0000.mp3", duration = 25.5477551, start = 0},
  },
}
P.transport["item:grenka-s-claw"] = {
  hash = "e7c79f",
  fullHash = "e7c79f",
  text = "Grenka's Claw. Grenka's Claw is a physical trophy taken from the formidable harpy Grenka Bloodscreech in the depths of Roguefeather Den. Presented to Dorn Plainstalker at the Weathered Nook, it serves as undeniable proof that an aspiring adventurer has endured a grueling physical trial in the canyon heights. Within the winding caverns of Roguefeather Den, west of Freewind Post, harpies cache food and violently defend their territory against outsiders. To test the physical resilience of young champions, Dorn Plainstalker tasks them with invading the deep roosts and destroying the flock's food reserves. Such brazen provocation inevitably draws the fury of Grenka Bloodscreech. Severing and returning her wicked talon proves that a warrior can withstand wave after wave of enraged harpies and survive the vicious onslaught of their matriarch.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grenka-s-claw-af10c656136954e70560/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:grimtotem-satchel"] = {
  hash = "0bdb5b",
  fullHash = "0bdb5b",
  text = "Grimtotem Satchel. Deep beneath Orgrimmar, Grimtotem Satchel remains in Maur Grimtotem’s grasp. Troggs killed the tauren in Ragefire Chasm, but he shielded the pouch as he died. Its return to Thunder Bluff brings Magatha Grimtotem’s interest to light. Maur Grimtotem fell to troggs deep inside Ragefire Chasm, beneath Orgrimmar. The tauren still clutched the simple leather pack when his body was found. He had fought to protect it while the troggs surrounded him. What could it hold that made him guard it with his life?",
  ["1"] = {
    {file = "Audio/Transport/full_item_grimtotem-satchel-37d9635cdb2e13215c37/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["item:grizzled-bear-heart"] = {
  hash = "1356ae",
  fullHash = "1356ae",
  text = "Grizzled Bear Heart. In Silverpine Forest, sturdy bears yield hearts for the Royal Apothecary Society's research into the New Plague. The Royal Apothecary Society works without pause to create an engineered blight that can exterminate both the Scourge and living humanity. In Silverpine Forest's woodlands, Apothecary Renferrel found that toxins from a grizzled bear's heart make a remarkably lethal concoction when joined with arachnid ichor. Couriers and Forsaken loyalists hunt ferocious grizzled bears, giant grizzled bears, and the roaming beast Old Vicejaw. They carve out the hearts and carry them to Master Apothecary Faranell, deep within the Undercity's Apothecarium.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grizzled-bear-heart-0a6cbc7c16d9ae676b68/1-0000.mp3", duration = 38.5044898, start = 0},
  },
}
P.transport["item:grizzled-scalp"] = {
  hash = "fa0eb4",
  fullHash = "fa0eb4",
  text = "Grizzled Scalp. In southern Darkshore, grizzled thistle bears roam the forests south of Auberdine. Their thick, furred hides reach Wizbang Cranktoggle, a gnome tinkerer with a use for them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_grizzled-scalp-dc0e40905320145e7e8e/1-0000.mp3", duration = 9.87428571, start = 0},
  },
}
P.transport["item:gryshka-s-letter"] = {
  hash = "3b5571",
  fullHash = "3b5571",
  text = "Gryshka's Letter. Innkeeper Gryshka sends a note of thanks to Zargh at the Crossroads after receiving fresh meat. The letter also introduces young Horde couriers to the wind rider flight network. Innkeeper Gryshka thanks Zargh for the steaks he sends from the Barrens to Orgrimmar's central tavern. She recalls the time he lost a finger while preparing meat, then teases that he looks handsome even when bloodied by his trade. To return Gryshka's Letter to the Crossroads, you report to Doras, the wind rider master atop Orgrimmar's plateau. Show him that you have already checked in with Devrak at the Crossroads, and Doras introduces young couriers to the wyvern flight paths linking settlements in Durotar and the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gryshka-s-letter-d6babb255ab4aabf5a13/1-0000.mp3", duration = 38.9746939, start = 0},
  },
}
P.transport["item:gunther-s-spellbook"] = {
  hash = "63a6d4",
  fullHash = "63a6d4",
  text = "Gunther's Spellbook. Bethor's enchantment now marks Gunther's Spellbook in Tirisfal Glades. The tome may show its owner that other mages have escaped the Lich King's control.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gunther-s-spellbook-c0dd5de1a57e915e9db2/1-0000.mp3", duration = 8.35918367, start = 0},
  },
}
P.transport["item:gyromechanic-gear"] = {
  hash = "73c5d9",
  fullHash = "73c5d9",
  text = "Gyromechanic Gear. Outside Gnomeregan, salvaged Gyromechanic Gears are sought for a bold gnomish experiment. Inventors in Kharanos hope to use them to reverse leper gnome mutations. Radiation swept through Gnomeregan as gnomes fought to purge the trogg invasion. Many survivors became mad, irradiated leper gnomes. Ozzie Togglevolt and Razzle Sprysprocket refuse to abandon their twisted kin, and have drawn up plans for the ambitious Recombobulator, a contraption meant to undo radiation's effects. Its prototype needs precise mechanisms that can withstand volatile pressure inside the machine, including Gyromechanic Gears and Restabilization Cogs. With local manufacturing gone after the fall of their capital, the inventors must salvage these delicate parts from hostile leper gnomes roaming Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_gyromechanic-gear-fe47fc20648dd9d83ce3/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:hallowed-letter"] = {
  hash = "7ea215",
  fullHash = "7ea215",
  text = "Hallowed Letter. Priestess Anetta calls young priests from Northshire Valley to Northshire Abbey. Her letter begins their study of the Holy Light. The Hallowed Letter bears Priestess Anetta’s personal mark and reaches fledgling priests after their first trials against the kobold camps of Northshire Valley. She sees the Holy Light’s spark within each novice and urges them to enter the abbey and dedicate themselves to its service. Dark forces still linger across Azeroth in the wake of the Third War. The priesthood gathers those able to heal, protect, and guide an empire struggling to keep order.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-letter-5d2a486ee5f1067b5f1b/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["item:hallowed-rune"] = {
  hash = "31c90e",
  fullHash = "31c90e",
  text = "Hallowed Rune. In Coldridge Valley, the Hallowed Rune calls novice priests to Anvilmar for training. Branstock Khalder sends the inscribed stone to aspiring wielders of the Holy Light. Branstock Khalder sends the Hallowed Rune when a young priest proves their resolve by aiding Coldridge Valley’s mountaineers and defenders. The stone bears teachings of the Holy Light and invites them to Anvilmar. There, Branstock prepares them to mend wounds and wield holy power against the troggs threatening Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-rune-94ba326b2382be7d1a24/1-0000.mp3", duration = 27.637551, start = 0},
  },
}
P.transport["item:hallowed-scroll"] = {
  hash = "3d69fd",
  fullHash = "3d69fd",
  text = "Hallowed Scroll. In Deathknell, the Hallowed Scroll calls newly awakened Forsaken priests to the ruined chapel. Sealed by Dark Cleric Duesten, it begins their training in faith, willpower, and shadow. Newly risen Forsaken priests feel their bond with the world change violently. As Deathknell is reclaimed amid ongoing chaos, the Hallowed Scroll sends them to seek guidance in the settlement’s ruined chapel. Dark Cleric Duesten’s seal marks the parchment. It introduces the new priests to formal instruction and directs them to report for it, beginning their study of the practical beliefs that shape Forsaken priesthood. Dark Cleric Duesten tells priests who answer the summons to leave old teachings behind. The Holy Light, ancestral spirits, and demonic pacts cannot be their crutches. Instead, the scroll begins a discipline grounded in each priest’s own will. Its teachings call on them to survive and rule through conviction, making faith a means of self-command and mastery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-scroll-0da5dd89ede44d3579f1/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["item:hallowed-sigil"] = {
  hash = "53acab",
  fullHash = "53acab",
  text = "Hallowed Sigil. In Shadowglen, the Hallowed Sigil summons young night elf initiates to Aldrassil. Shanda sends it to call them into service to Elune. Young night elf priests in Shadowglen receive the Hallowed Sigil from a woodland messenger. Holy markings are engraved on the token, which carries a personal summons from Shanda, the priest trainer at Aldrassil. Read it, then go up to the great hollow of Aldrassil. There, the summons brings the acolyte to the Sisterhood of Elune and begins their service to the Kaldorei as new travelers arrive across Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-sigil-f7e3ad604b66ddc4a714/1-0000.mp3", duration = 31.3730612, start = 0},
  },
}
P.transport["item:hallowed-tablet"] = {
  hash = "6849df",
  fullHash = "6849df",
  text = "Hallowed Tablet. In the Valley of Trials, the Hallowed Tablet calls young Darkspear priests to Ken'jai. Its words begin their lessons in communing with the spirits. Gornek gives the Hallowed Tablet to a promising troll priest taking their first steps through the Valley of Trials. The words carry a personal invitation from Ken'jai, the priest trainer outside the Den. Ken'jai reads signs and hears the spirits' whispers, sensing when young Darkspear with spiritual potential arrive in Durotar. The tablet tells the initiate to read its message and seek Ken'jai's guidance in channeling spiritual authority.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hallowed-tablet-bb631730b3c9aa890f25/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["item:hand-of-dextren-ward"] = {
  hash = "b0ad71",
  fullHash = "b0ad71",
  text = "Hand of Dextren Ward. Darkshire demands proof that Dextren Ward has been executed in the Stormwind Stockade. The severed hand is bound for town, where grieving families await justice for their dead. Dextren Ward was sentenced to death by Lord Ebonlocke after he was caught digging up bodies in Duskwood cemeteries and selling them to the necromancer Morbent Fel. Stormwind intervened before the town could execute him and took him to the Stockade. For Darkshire's grieving families, Ward's hand proves the defiler has been executed, despite the House of Nobles' unwanted leniency.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hand-of-dextren-ward-64b075f76ff39c38a004/1-0000.mp3", duration = 32.6530612, start = 0},
  },
}
P.transport["item:handful-of-oats-classic"] = {
  hash = "fda7c6",
  fullHash = "fda7c6",
  text = "Handful of Oats (Classic). In Westfall, Old Blanchy needs oats after the Furlbrows' wagon breaks down. Westfall once fed the Kingdom of Stormwind, but its farms now lie overgrown or under the control of Defias bandits and rogue harvest golems. Sacks of grain and oats remain near barns, outbuildings, and overgrown fields. Travelers and refugees stranded by broken wagons along the dusty roads can gather the leftover oats to feed their weary draft horses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_handful-of-oats-classic-53c6b54fc62a07397c89/1-0000.mp3", duration = 26.2791837, start = 0},
  },
}
P.transport["item:handful-of-stardust"] = {
  hash = "5c8ed9",
  fullHash = "5c8ed9",
  text = "Handful of Stardust. In the Ruins of Stardust, a pale frost gathers on the bushes south of Astranaar. Night elven healers use the powder to cool intense fevers. Stardust clings to shrubs in the Ruins of Stardust, south of Astranaar. The fine powder shines like frost. Lingering elemental spirits haunt the ruins, yet plants thrive among the broken stones and take in a rare glow. Night elven healers make the residue into poultices for dangerous, persistent fevers. They turn to it when ordinary salves and moonwell waters bring no full relief.",
  ["1"] = {
    {file = "Audio/Transport/full_item_handful-of-stardust-9c2370128489cf89be63/1-0000.mp3", duration = 31.4514286, start = 0},
  },
}
P.transport["item:hardened-tortoise-shell"] = {
  hash = "b3a140",
  fullHash = "b3a140",
  text = "Hardened Tortoise Shell. Hardened Tortoise Shells are remarkably durable carapaces harvested from the sparkleshell tortoises wandering the Shimmering Flats. Coveted by gnomish racers at the Mirage Raceway, these rugged organic plates offer unmatched resistance against volatile and corrosive experimental fuels. The sun-scorched expanse of the Shimmering Flats is home to various breeds of sparkleshell tortoises, including snappers and borers, whose carapaces have evolved into exceptionally tough defenses against the harsh desert salt and wandering predators. Out on the salt flats, standard metal alloy fuel tanks frequently corrode or rupture under the strain of gnomish experimental chemistry. Mechanics like Wizzle Brassbolts prize these shells not for armor or shields, but as organic raw material tough enough to be retrofitted into makeshift, acid-resistant fuel tanks capable of containing volatile rocket propellants.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hardened-tortoise-shell-893535749202d3a86423/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:hardened-tumor"] = {
  hash = "13b38b",
  fullHash = "13b38b",
  text = "Hardened Tumor. Forsaken researchers seek a Hardened Tumor for their work on the New Plague. Apothecary Berard first studied the growth before Arugal's curse made him a mindless servant. Along Lake Lordamere, Vile Fin murlocs sometimes develop a rare, calcified growth. Apothecary Berard recorded the abnormality while studying wildlife along Silverpine Forest's eastern borders. The growth appears only in mature specimens along the shoreline and the Dawning Isles. Its cause remains uncertain, but the Royal Apothecary Society took notice of the dense tissue.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hardened-tumor-a5e2c1517fb13249a957/1-0000.mp3", duration = 31.2946939, start = 0},
  },
}
P.transport["item:harpy-lieutenant-ring"] = {
  hash = "58bf8a",
  fullHash = "58bf8a",
  text = "Harpy Lieutenant Ring. In the Dry Hills, Harpy Lieutenant Rings mark the Witchwing Slayers who command the flock. Darsok Swiftdagger at the Crossroads asks for them as proof of death. Witchwing Slayers direct attacks on Horde travelers in the Barrens. Their rings mark their place among the flock’s leaders, above the ordinary raiders who fight with little coordination. At the Crossroads, Darsok Swiftdagger and the defenders need the rings taken from fallen slayers to confirm that this part of the harpies’ leadership has been broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_harpy-lieutenant-ring-c3783de5d442a8f6ef52/1-0000.mp3", duration = 29.7012245, start = 0},
  },
}
P.transport["item:head-of-arugal"] = {
  hash = "b72381",
  fullHash = "b72381",
  text = "Head of Arugal. At Shadowfang Keep, Head of Arugal is taken from the mad archmage who commands the worgen. The Forsaken at the Sepulcher seek it as proof that he has fallen. Archmage Arugal commands the worgen from Shadowfang Keep in Silverpine Forest. Dalar Dawnweaver at the Sepulcher gives the order to claim his severed head. The Forsaken see Arugal's fall as a blow against the beasts that hinder Lady Sylvanas's hold over Silverpine. Bringing the head to Dawnweaver proves the archmage's sorcery has been cut from the land.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-arugal-e1c5c2e6cb3c9b9cec61/1-0000.mp3", duration = 29.1265306, start = 0},
  },
}
P.transport["item:head-of-bazil-thredd"] = {
  hash = "5353b2",
  fullHash = "5353b2",
  text = "Head of Bazil Thredd. Warden Thelwater demands proof that the Stockade uprising has been crushed. The severed head of Bazil Thredd is meant to show that the rebellion's leader is dead and Defias control of Stormwind's prison has ended. Bazil Thredd led the uprising in the Stockade beneath Stormwind City. From his cell block, he directed the riots with the help of loyal Defias inmates. Warden Thelwater distrusts outsiders and struggles to keep order. He demands Thredd's head as proof that the ringleader is dead and to test the adventurer's allegiance to Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-bazil-thredd-f4b6b44698828ae164a5/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["item:head-of-deepfury"] = {
  hash = "b3af5d",
  fullHash = "b3af5d",
  text = "Head of Deepfury. At the Stormwind Stockade, Kam Deepfury’s severed head marks the end of a Dark Iron conspirator. His death in the prison riots answers the grievance of the dwarven defenders at Dun Modr. Kam Deepfury was held in the Stormwind Stockade for political reasons, spared immediate execution by human diplomacy. Roggo uncovered that Deepfury had orchestrated the attack on the Thandol Span, which cost the lives of King Magni’s soldiers and Longbraid the Grim’s kin. The Ironforge mountaineers at Dun Modr could not accept his continued imprisonment. Bound to his post, Motley Garmason sent Alliance champions into the rioting prison to take Deepfury’s head and deliver dwarven vengeance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-deepfury-0214a7c46672c0eea735/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["item:head-of-gath-ilzogg"] = {
  hash = "a5dab9",
  fullHash = "a5dab9",
  text = "Head of Gath'Ilzogg. Claiming Gath'Ilzogg's severed head proves the Blackrock warlord has been slain. His fall breaks the leadership behind the siege of Stonewatch Keep and brings desperate relief to Lakeshire. Gath'Ilzogg led the Blackrock assault that took Stonewatch Keep, drove out its defenders, and left the valley under constant raids. Lakeshire stood near ruin, while Stormwind sent almost no military help. Magistrate Solomon offered a bounty on the warlord. Gath'Ilzogg fell in the keep's fortified upper levels, and claiming his head breaks the local Blackrock leadership. For Lakeshire, it is the first step toward reclaiming the keep for the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-gath-ilzogg-d0a319bd1c52065071d5/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["item:head-of-grimson"] = {
  hash = "5a9188",
  fullHash = "5a9188",
  text = "Head of Grimson. At the Deep Elem Mine, Grimson the Pale's severed head proves the Forsaken have secured its riches. Dalar Dawnweaver receives the trophy at the Sepulcher, and the mine's minerals can supply Varimathras's military campaigns. Forsaken scouts called Darkstalkers found a strategic threat brewing in the southeastern hills. Archmage Arugal's shadowy enchantments had corrupted workers in the Deep Elem Mine and driven its overseer, Grimson the Pale, mad. From the Sepulcher, Dalar Dawnweaver sent champions to kill Grimson and bring back his severed head. The trophy confirms the mine is free of rogue magic, leaving its underground wealth for Varimathras's forces.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-grimson-aefea662638633eb6fd4/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["item:head-of-kelris"] = {
  hash = "ee2d0b",
  fullHash = "ee2d0b",
  text = "Head of Kelris. Agents of the Argent Dawn seek Kelris's severed head to confirm his fall and the end of his sacrifices. In Blackfathom Deeps, Twilight Lord Kelris led sacrifices to Aku'mai, a monstrous servant of an Old God. Taking his head marks the end of his rule over the Twilight's Hammer cultists and their naga allies in the cavern. The head must reach the surface so leaders can know his bloody ceremonies have ended. The Argent Dawn had presumed Kelris dead or lost for months before his influence returned with Kalimdor's encroaching shadows. His head, brought to agents in Darnassus or Thunder Bluff, settles lingering bounties and confirms that his attempt to plunge the world into primeval chaos has been stopped.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-kelris-ed1a8c5c9a4c2d8b3600/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["item:head-of-targorr"] = {
  hash = "54c9b1",
  fullHash = "54c9b1",
  text = "Head of Targorr. In the Stormwind Stockade, Targorr the Dread awaits an execution stopped by nobles in Stormwind. Once Gath'Ilzogg's supreme executioner in the Redridge Mountains, the captured orc is now the subject of Guard Berton's demand for proof of his death in Lakeshire. Targorr the Dread earned infamy across Redridge as the Blackrock clan warlord Gath'Ilzogg's brutal executioner. He tortured and slaughtered defenders of the Kingdom of Stormwind before his capture and death sentence in the Stormwind Stockade. Stormwind nobles intervened and mysteriously suspended the sentence. Guardsmen like Berton suspect foul play and corruption in the capital. Guard Berton fears Targorr could become a political pawn or arrange an escape, so he hires an outside champion to enter the volatile prison and finish what the courts delayed. Taking Targorr's head bypasses the stalled legal system and gives closure to grieving families and Lakeshire's besieged defenders, who suffered under the executioner's blades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-targorr-266afd0e652decdf6544/1-0000.mp3", duration = 57.835102, start = 0},
  },
}
P.transport["item:head-of-vancleef"] = {
  hash = "8d18c1",
  fullHash = "8d18c1",
  text = "Head of VanCleef. At Sentinel Hill, VanCleef's severed head proves the Defias leader has fallen. Carried from the depths of the Deadmines, it brings the People's Militia hard-won vengeance. Westfall's settlers need proof that their danger has passed. For months, Edwin VanCleef directed the Defias Brotherhood's terror from the deepest sanctum of the Deadmines, guarded by armed outlaws, goblin engineers, and a massive war juggernaut. Gryan Stoutmantle, leader of the People's Militia, demands physical proof before declaring the countryside safe. VanCleef's severed head, brought out into daylight, assures the exhausted defenders that the architect of their ruin can no longer threaten Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_head-of-vancleef-231013631be75cc0fabc/1-0000.mp3", duration = 39.2881633, start = 0},
  },
}
P.transport["item:heart-of-isha-awak"] = {
  hash = "5e0760",
  fullHash = "5e0760",
  text = "Heart of Isha Awak. Hunters seek Isha Awak’s heart along the Merchant Coast south of Ratchet. Mahren Skyseer wants it as proof that the Deep Doom has been overcome. Isha Awak prowls the sea off the Merchant Coast, south of Ratchet. Sailors and coastal folk revere and fear the massive thresher, known as the Deep Doom. It has killed many human trespassers along the shore. Mahren Skyseer, a tauren mystic, sees an honorable predator, not a mindless menace. She believes its fierce spirit dwells in its heart. Mahren charges brave hunters to plunge into the waves, defeat Isha Awak in its own domain, and claim the heart as both trophy and spiritual offering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heart-of-isha-awak-f9e07279786754e0007b/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["item:heartswood"] = {
  hash = "cb5c02",
  fullHash = "cb5c02",
  text = "Heartswood. Heartswood is timber harvested from a sacred tree rooted within the Ruins of Ordil'Aran in northwestern Ashenvale. Born from the final resting place of two ancient lovers, its resonance with undying devotion makes it an essential lure for summoning a succubus. The Heartswood grows among the elven stones of the Ruins of Ordil'Aran in northwestern Ashenvale. According to legend, two lovers named Anathera and Latherion fell side by side during the catastrophic War of the Ancients thousands of years ago. On the very earth where they breathed their last, a peculiar tree took root, blossoming as an eternal testament to their devotion. Even millennia later, the wood cut from this tree hums with the memory of undying passion, making it an object of great curiosity for those who study emotional and spiritual bonds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heartswood-fb2e3ff259fcdab190ca/1-0000.mp3", duration = 44.9567347, start = 0},
  },
}
P.transport["item:heartswood-core"] = {
  hash = "57fcf8",
  fullHash = "57fcf8",
  text = "Heartswood Core. Warlocks in Stormwind City use the Heartswood Core to summon a succubus. Gakin the Darkbinder provides the enchanted ritual focus, crafted from an ancient tree’s wood, to pierce the Twisting Nether and draw the demon into an arcane summoning circle. Beneath the Slaughtered Lamb in Stormwind’s Mage Quarter, warlocks perform rites beyond the city watch’s gaze. The Heartswood Core channels the magic needed to begin a binding ritual. Crafted from the wood of an ancient tree, it holds enough lingering magic to pierce the veil between worlds. At a consecrated summoning circle, an initiate focuses dark arts through the core and opens a passage to the Twisting Nether, drawing a succubus across the divide.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heartswood-core-d89983145930449a7df6/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["item:heavy-leaden-collection-phial"] = {
  hash = "d34e7c",
  fullHash = "d34e7c",
  text = "Heavy Leaden Collection Phial. In Kharanos, Ozzie Togglevolt provides the Heavy Leaden Collection Phial for research into decontamination. It is meant to siphon and contain unstable irradiated discharge from mutants deep inside Gnomeregan. The Heavy Leaden Collection Phial draws volatile residue from living, irradiated creatures in Gnomeregan. Keeping the fallout contained is difficult, and a suitable sample may take several attempts to collect. Ozzie Togglevolt provides the phial to support his research into reversing the horrific mutations afflicting leper gnomes. Earlier samples from surface troggs lacked the potency needed for effective chemical analysis. With the leaden phial, researchers hope to gather samples from virulent beasts such as irradiated slimes and lurkers in the Hall of Gears. They seek the active elements in the city's toxic fallout, then hope to formulate an effective antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_item_heavy-leaden-collection-phial-3220f7e365fed1a95cc4/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["item:hezrul-s-head"] = {
  hash = "1314e7",
  fullHash = "1314e7",
  text = "Hezrul's Head. At Lushwater Oasis, Hezrul Bloodmark leads the Kolkar centaur in the Barrens. His head is carried to Regthar Deathgate west of the Crossroads as proof their chieftain has fallen. Hezrul Bloodmark leads his Kolkar centaur clan from Lushwater Oasis, south of the Crossroads. The Kolkar hold the Barrens' oases and threaten Horde supply routes and young settlements. Regthar Deathgate, an orc veteran charged with securing the land west of the Crossroads, sees their fierce rage but little discipline. He demands Hezrul's severed head to break the clan's command and throw its surviving fighters into disarray, weakening their attacks on the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hezrul-s-head-5f220cbf589626f6b8b2/1-0000.mp3", duration = 38.5828571, start = 0},
  },
}
P.transport["item:high-potency-radioactive-fallout"] = {
  hash = "343e4d",
  fullHash = "343e4d",
  text = "High Potency Radioactive Fallout. In Gnomeregan's lower depths, researchers seek a potent sample of radioactive fallout. They hope to learn how the sludge afflicted the leper gnomes and find a cure. Deep in the Hall of Gears, irradiated horrors, lurkers, and slimes move through the lowest tiers of Gnomeregan. Researchers outside the fallen capital need fallout drawn from these living creatures. Samples scraped from contaminated scavengers outside are too weak for their work. The sludge decays quickly, so it must go into a leaden phial and reach the researchers before it loses its potency. Ozzie Togglevolt and his colleagues seek a cure for the leper gnomes. They believe the secrets of the irradiated sludge may point the way. During the trogg invasion, toxic venting deformed and drove these survivors mad. They remain trapped in a living nightmare, and the researchers consider dangerous expeditions into the ruins worth the risk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_high-potency-radioactive-fallout-7607e1701bd74158a400/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["item:highborne-relic-classic"] = {
  hash = "8657da",
  fullHash = "8657da",
  text = "Highborne Relic (Classic). In Darkshore, Highborne Relics remain in the hands of spirits haunting Ameth'Aran. Night elf scholars seek them for destruction before their dormant magic can cause more harm. Ten thousand years ago, the Highborne caste brought ruin upon ancient Kalimdor through reckless arcane magic. Their estates lie in shattered ruins across Darkshore. At Ameth'Aran, wailing apparitions wander among the crumbling columns, still clutching the implements of their old sorcery. The relics bind arcane taint to the spirits, who will not release the objects tied to their undoing. Night elf society largely renounced arcane magic after the Great Sundering, and scholars see these relics as a grave hazard. Acting on reports from the Sentinels, Thundris Windweaver in Auberdine sends travelers to wrest them from the cursed spirits. Once gathered, the relics are destroyed so the Highborne's ancient evils and catastrophic mistakes cannot be repeated.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highborne-relic-classic-8b02ef84a26712356967/1-0000.mp3", duration = 52.9763265, start = 0},
  },
}
P.transport["item:highperch-venom-sac"] = {
  hash = "4c89d7",
  fullHash = "4c89d7",
  text = "Highperch Venom Sac. Highperch Venom Sacs are harvested from the wild wyverns nesting upon the towering spires of Highperch in Thousand Needles. While orcs prize wyverns as aerial mounts, select apothecaries and traders value their potent stingers even more than the living beasts. The high spires of Thousand Needles house thriving prides of wild wyverns, particularly around the elevated crags of Highperch. These winged predators rely on powerful venom delivered through their barbed tails to paralyze and kill prey. While the Horde often domesticates these creatures as loyal wind riders, their venom sacs command a remarkably high price among alchemists, hunters, and opportunistic merchants across Kalimdor. Though native to the deep canyons of central Kalimdor, this venom draws interest far beyond them. In the port town of Theramore, the high elf Fiora Longears pays handsomely for fresh sacs collected from Highperch's broods. She seeks samples swollen with venom—typically found only on young wyverns or fertile females—fueling trade in dangerous reagents far from the beasts' natural desert habitat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highperch-venom-sac-11709f6529d498fe93b7/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["item:highperch-wyvern-egg"] = {
  hash = "e9d223",
  fullHash = "e9d223",
  text = "Highperch Wyvern Egg. Highperch Wyvern Eggs are clutch eggs gathered from the nesting grounds atop the high mesas of Thousand Needles. They are sought after by aspiring Horde wind riders to raise and train new aerial mounts. The high plateau of Highperch in Thousand Needles provides a natural sanctuary for native wyverns to roost and raise their young. Accessible only via steep winding paths up the canyon walls, these nesting grounds are fiercely guarded by adult beasts. The eggs laid among these roosts are sturdy and warm, holding developing hatchlings capable of adapting to the harsh skies of Kalimdor. Across Kalimdor, the demand for trained wyverns continually outstrips supply as the Horde expands its courier and scouting networks. At Freewind Post, trainees like the tauren Elu seek out intact eggs directly from wild aeries. By raising the hatchlings from their shells, handlers hope to forge the deep bonds required to train trustworthy winged mounts for the Horde's wind riders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_highperch-wyvern-egg-2e9557c118ee67b8a360/1-0000.mp3", duration = 56.3983673, start = 0},
  },
}
P.transport["item:hildelve-s-journal"] = {
  hash = "fc5527",
  fullHash = "fc5527",
  text = "Hildelve's Journal. Hildelve's Journal was recovered from the dwarf's remains in Dun Morogh. Its bloodstained pages recount a fatal meeting with a fierce bear and his last wish for vengeance. Dwarven pilot Hildelve set out alone into Dun Morogh after his steam tank broke down. He left his partner, Hammerfoot, with the tanks and went searching the snow-swept crags for rumored chiron ore. His journal says Mangeclaw, a monstrous ice claw bear, stalked him for days before ambushing him. Hildelve fought bravely and drove the bear off, but the beast mauled him, leaving him gravely wounded and stranded in the cold. His final hours were agonizing. Before the predator returned to finish him, Hildelve left one clear plea: whoever found his body should hunt Mangeclaw and avenge his death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hildelve-s-journal-5572161875c9c4645d21/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["item:hillsbrad-human-skull"] = {
  hash = "2140a9",
  fullHash = "2140a9",
  text = "Hillsbrad Human Skull. Across the Hillsbrad Foothills, Forsaken gather the skulls of slain humans. At Tarren Mill, they keep them as grim mementos of the assault on local settlements. Forsaken forces from Tarren Mill fight the humans of Southshore and nearby settlements. During the Battle of Hillsbrad, Deathstalkers and soldiers carry out the purge Darthalia ordered. Guards left on watch want a share of the slaughter. Deathguard Samsa collects skulls from the fighters on the front lines, taking pleasure in keeping the remains of people the Forsaken once lived among. These trophies are proof of the killing as the conflict rages.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hillsbrad-human-skull-77c9201c2b18c9ae9879/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:hillsbrad-town-registry"] = {
  hash = "ed1957",
  fullHash = "ed1957",
  text = "Hillsbrad Town Registry. In Hillsbrad Fields, the town hall keeps a ledger of the settlement's surviving citizens and landowners. The Hillsbrad Town Registry records civic matters, and the Forsaken seek it during their offensive against the human stronghold. The Hillsbrad Town Registry records the town's people and rights. It rests in the town hall near the podium of Magistrate Burnside. From Tarren Mill, the Forsaken press to break human resistance in the foothills. Darthalia sends Horde champions into the town hall to kill the council and seize the ledger. Its records cover Hillsbrad's population, households, and administrative rights. The registry would strip the town of its civic order and give the Undercity intelligence on the surviving population and their assets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hillsbrad-town-registry-57dc4b4e853afeb51ac7/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["item:hollow-vulture-bone"] = {
  hash = "58f904",
  fullHash = "58f904",
  text = "Hollow Vulture Bone. Hollow Vulture Bones are lightweight, durable skeletal remains harvested from the scavengers of the Shimmering Flats. At the Mirage Raceway, goblin mechanics prize them as specialized building materials to lighten their rocket cars without sacrificing structural integrity. Speed is everything out on the salt, and weight is the enemy of speed. While standard engineering leans heavily on iron and copper, the goblin pit crews at the Mirage Raceway turn to whatever the desert provides to gain an edge. Vulture bones are naturally hollow yet remarkably sturdy, providing the perfect strength-to-weight ratio for internal brackets, steering rigs, and minor structural supports. For chief tinkerers like Pozzik, harvesting bones from local scavengers is a practical and cheap shortcut to shaved seconds on the track.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hollow-vulture-bone-6179c93d1936200c4703/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:honorary-picks"] = {
  hash = "dc9fcf",
  fullHash = "dc9fcf",
  text = "Honorary Picks. In Ironforge, Honorary Picks are prepared for Brock Stoneseeker’s mining apprentices in Thelsamar. Gryphons carry them to Loch Modan, where the ceremonial tools mark students ready to work its ore veins. Mining keeps the great forges burning and supplies dwarves with iron and stone. In Thelsamar, Brock Stoneseeker teaches young apprentices to mine. Honorary Picks from Ironforge recognize students ready to work the open ore deposits across Loch Modan. The picks travel through the Alliance gryphon network, linking Ironforge with its outlying settlements. Gryth Thurden receives the shipment at Ironforge’s Great Forge and sends it over the mountains to Thorgrum Borrelson in Thelsamar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_honorary-picks-847ded9ed641dad59003/1-0000.mp3", duration = 40.8293878, start = 0},
  },
}
P.transport["item:horn-of-arra-chea"] = {
  hash = "9d121c",
  fullHash = "9d121c",
  text = "Horn of Arra'chea. Across Mulgore, Arra'chea roams while Cairne Bloodhoof calls young hunters to prove their worth. The kodo's horn confirms a hunter can track prey and provide for the Shu'halo. Passing the Rites of the Earthmother earns a youth a place atop Thunder Bluff, but High Chieftain Cairne Bloodhoof still expects his people to prove their worth. For the tauren, the hunt binds identity to lasting harmony with the land. Cairne sends young hunters to track Arra'chea, a massive, solitary kodo bull roaming the grasslands below. Taking the bull's horn shows mastery of tracking prey across vast distances. Bringing Arra'chea's horn to Thunder Bluff does more than display strength; it helps sustain the community. Tauren use every part of a slain beast. The trophy tells the High Chieftain where Arra'chea fell, so gathering parties can go down into the plains and harvest the kodo's thick hide and rich meat for the fledgling capital.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-arra-chea-788f1cada2ac4b44bd8e/1-0000.mp3", duration = 53.5771429, start = 0},
  },
}
P.transport["item:horn-of-awakening"] = {
  hash = "67ac6f",
  fullHash = "67ac6f",
  text = "Horn of Awakening. In southern Darkshore, Kerlonian Evershade keeps a horn close at hand. It rouses him whenever sleep overtakes him on the road to Ashenvale. Kerlonian Evershade has only recently awakened from centuries in the Emerald Dream, and wakefulness still weighs on him. The Druid of the Claw travels south toward Maestra's Post and entrusts the horn to travelers willing to escort him. When exhaustion takes him along the wilderness trail, a clear blast jolts him awake and gets him back on his feet before wild beasts or cultists can reach him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-awakening-678f49f10fc6dcb5ad73/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:horn-of-echeyakee"] = {
  hash = "362c44",
  fullHash = "362c44",
  text = "Horn of Echeyakee. At the Crossroads, Sergra Darkthorn gives hunters the Horn of Echeyakee. Sounded among the ancient kodo remains northeast of the settlement, it calls the legendary white predator of the Barrens. Hunters who are being tested in the hunt receive the horn. Its call summons Echeyakee, whose name means “Whitemist” in Taur-ahe. Taure n hunters revere the king of the savannah cats as both mercy and death. He strikes so swiftly that his quarry feels neither terror nor suffering. The horn belongs at the predator’s lair, among giant kodo bones behind the hills northeast of the Crossroads.",
  ["1"] = {
    {file = "Audio/Transport/full_item_horn-of-echeyakee-736a5a32363a043734c0/1-0000.mp3", duration = 33.7763265, start = 0},
  },
}
P.transport["item:huge-gnoll-claw"] = {
  hash = "a5f8ac",
  fullHash = "a5f8ac",
  text = "Huge Gnoll Claw. In southwestern Elwynn, Hogger’s huge claw is sought as proof of his death. Stormwind’s authorities in Goldshire require it for the bounty. Hogger has terrorized the southern woodlands of Forest's Edge for months. Patrols have failed to stop the brute, and the local garrison cannot corral or subdue him. The Stormwind Army, stretched thin across Elwynn, posted an open bounty on his head. Marshal Dughan in Goldshire requires clear proof before paying it. Hogger's oversized claw leaves no doubt that the notorious marauder has fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_item_huge-gnoll-claw-df6046da7823c92a72e7/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:humbert-s-sword"] = {
  hash = "4ad2a9",
  fullHash = "4ad2a9",
  text = "Humbert's Sword. At Dun Garok, Humbert's Sword lies among the dwarves who took it from his camp. Deathguard Humbert left his post to gather firewood while scouting the stronghold. Deathguard Humbert left his hidden post near Dun Garok one morning to gather firewood for boiling water. High Executor Darthalia had sent him to watch the dwarven presence there. While he was away, a dwarven patrol found his campsite and plundered his gear, including his personal blade. With so many dwarves to search, Humbert needs Horde agents to enter the fortress and recover it. Dun Garok's defenders carried Humbert's belongings behind the stronghold's barricades. Riflemen, mountaineers, and priests pass supplies around the garrison. Finding the thief means searching among the defenders in the trenches and redoubts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_humbert-s-sword-c1a82580b24d2e410850/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["item:hyacinth-mushroom"] = {
  hash = "19ec6a",
  fullHash = "19ec6a",
  text = "Hyacinth Mushroom. In Shadowglen, Hyacinth Mushrooms grow at the roots of trees across Teldrassil. Night elf herbalists use them for medicine, and grell and grellkin forage for them. Hyacinth Mushrooms grow in Shadowglen among the trees and roots of Aldrassil. Forest healers use them in remedies for young night elf sentinels and trainees harmed by venomous creatures. The spiders of Shadowthread Cave are among the dangers they face, and the mushrooms go into soothing draughts and antivenoms. Corrupted grell also hoard them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hyacinth-mushroom-435c49b77c6883a5bb44/1-0000.mp3", duration = 29.6228571, start = 0},
  },
}
P.transport["item:hypercapacitor-gizmo"] = {
  hash = "9e5c90",
  fullHash = "9e5c90",
  text = "Hypercapacitor Gizmo. The Hypercapacitor Gizmo is an eccentric piece of engineering recovered from the canyon floor of Thousand Needles. Once dangling from the neck of a caged beast in a ruined caravan, its true purpose remains a mystery even to the tinkerer who claims to own it. When centaur marauders ambushed a goblin caravan traveling through Thousand Needles, they plundered nearly everything in sight. The sole survivor, Wizlo Bearingshiner, managed to crawl his way to safety at Whitereach Post, leaving behind his best gizmo: the Hypercapacitor Gizmo. Strangely, the gadget wound up secured around the neck of a ferocious, enraged panther locked inside a transport cage. The raiding centaur feared the beast enough to leave the cage entirely alone amidst the burning wreckage, unwittingly preserving Wizlo's odd machine. While Wizlo proudly calls the device his best gizmo, he admits upon its recovery that he has no real idea what it actually does. Like many goblin contraptions, the Hypercapacitor Gizmo is a tangled mass of ambition and volatile parts, destined to keep its owner occupied with endless tinkering rather than serving any practical, understood function.",
  ["1"] = {
    {file = "Audio/Transport/full_item_hypercapacitor-gizmo-a86b2a2e9b0cab8c598f/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["item:ignition-key"] = {
  hash = "12f35f",
  fullHash = "12f35f",
  text = "Ignition Key. At Sludge Fen, the Ignition Key is held by Supervisor Lugwizzle at the Venture Company drilling operation. Wizzlecrank needs it to unlock an advanced shredder's movement column and activate its controls. Sputtervalve of Ratchet sent an operative to steal a Venture Company shredder from Sludge Fen, but the plan stalled. The undercover pilot, Wizzlecrank, climbed into the cockpit and found the movement column locked. He pretended the machine had mechanical trouble so the foremen would not grow suspicious while he waited for someone to fetch the Ignition Key. Supervisor Lugwizzle keeps the key high atop the central oil derrick, where access to the shredder's arm, speed, and rotation controls is held.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ignition-key-3119ff32c97dd90885e9/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["item:ilkrud-magthrull-s-tome"] = {
  hash = "3fc5d7",
  fullHash = "3fc5d7",
  text = "Ilkrud Magthrull's Tome. At Fire Scar Shrine, Ilkrud Magthrull's Tome draws Delgren the Purifier's attention. Its pages connect the warlock to the cultists at the Tower of Althalaxx. Ilkrud Magthrull holds the Fire Scar Shrine in southwestern Ashenvale, where demonic influence has poisoned the site. The formidable orc warlock is surrounded by summoned minions. His personal tome records foul rituals and shadowy communications. The Argent Dawn paladin Delgren the Purifier has long known of Magthrull's presence, but the ties between the warlock and the dark cultists gathering at the Tower of Althalaxx make the book urgent to recover.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ilkrud-magthrull-s-tome-cf4efdd085af8c4be787/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["item:incantations-from-the-nether"] = {
  hash = "240e9e",
  fullHash = "240e9e",
  text = "Incantations from the Nether. Beneath Orgrimmar, Searing Blade cultists hold Incantations from the Nether, a grimoire of demonic magic. Sylvanas Windrunner and Varimathras seek its fel knowledge for the Forsaken. The Searing Blade is a subterranean sect tied to the Shadow Council, working in the fiery tunnels of Ragefire Chasm beneath Orgrimmar's red stone streets. Its cultists prize Incantations from the Nether, a spellbook of demonic rites given by agents of the Burning Legion. They use its secrets to plot treason in the Orcish capital. Word of the tome has reached the royal quarters of Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incantations-from-the-nether-08d5999e6fd89202692d/1-0000.mp3", duration = 34.6644898, start = 0},
  },
}
P.transport["item:incendia-agave"] = {
  hash = "5e7dac",
  fullHash = "5e7dac",
  text = "Incendia Agave. Beneath Darkcloud Pinnacle, Incendia Agave grows in the Boiling Pool. A skilled shaman can enchant it to kindle the sacred fire of life. In Thousand Needles, Incendia Agave grows in and around the waters of the Boiling Pool, beneath Darkcloud Pinnacle. Wandering steam elementals guard the scarce plant, making it difficult to harvest. Though it grows underwater, the plant holds natural elements suited to rituals of flame.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incendia-agave-9e9a8f4f2679f8b923dd/1-0000.mp3", duration = 26.9844898, start = 0},
  },
}
P.transport["item:incendia-powder"] = {
  hash = "59f379",
  fullHash = "59f379",
  text = "Incendia Powder. On Thunder Bluff, Incendia Powder is prepared to call a sacred spirit into the open. Magatha Grimtotem enchants it for use at Darkcloud Pinnacle in Thousand Needles. Incendia Powder carries shamanic magic to the sacred fire atop Darkcloud Pinnacle. Magatha Grimtotem entrusts it to travelers on Thunder Bluff's Elder Rise. Scattered across the consecrated brazier where the dead are laid to rest, the powder calls forth Arikara, a vengeful winged serpent.",
  ["1"] = {
    {file = "Audio/Transport/full_item_incendia-powder-d98b95bc50591483683e/1-0000.mp3", duration = 27.7942857, start = 0},
  },
}
P.transport["item:insane-scribbles"] = {
  hash = "860e9c",
  fullHash = "860e9c",
  text = "Insane Scribbles. In Darkshore, cultists carry Insane Scribbles torn from the Twilight Tome, a fragment of dark literature. The dancing text and distorted scrollwork cause dizziness and mental strain. Ancient forest protectors study the fragments to learn the Twilight's Hammer's motives. Reading the Twilight Tome can endanger a mortal's sanity. Its script writhes across the parchment, and graceful scrollwork warps into grotesque images before the reader's eyes. Tearing out even one sheet, called Insane Scribbles, leaves the bearer lightheaded and disoriented. Though the writing makes little sense, the parchment hums with primal, deeply ancient magic tied to dark powers long buried beneath Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_insane-scribbles-8e6c1c2084f3426d5569/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["item:inscribed-bark"] = {
  hash = "e27510",
  fullHash = "e27510",
  text = "Inscribed Bark. In Teldrassil, Inscribed Bark carries word of the World Tree's state to Arch Druid Fandral Staghelm. The Oracle Tree entrusts it with news of the boughs and the threats troubling the woods. The Oracle Tree sends Inscribed Bark to the Cenarion Circle in Darnassus. After you drive the harpies from their nests, the ancient tree gives you its message, wary of sending ordinary couriers along Teldrassil's tainted paths. The report tells Arch Druid Fandral Staghelm of recent victories and the deeper blight still gripping the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_inscribed-bark-0412b9c9dc7c3f02bcdb/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["item:intact-raptor-horn"] = {
  hash = "3cc5d2",
  fullHash = "3cc5d2",
  text = "Intact Raptor Horn. Across the Barrens savannas, raptors are hunted for their intact horns. Mebok Mizzyrix of Ratchet wants them for a scheme built on rumors of raptor intelligence. Hunters prize raptor hides, talons, and trophies, but whole horns are harder to take in the field. Mebok Mizzyrix, an eccentric goblin alchemist in Ratchet, believes the Barrens raptors are more cunning than their kin elsewhere. He suspects their intellect lies in their horns. By grinding whole horns and brewing them into tonics, Mebok hopes to bottle that supposed genius in commercial drinks. A horn fit for brewing must come from a particularly vicious predator, not just any young raptor. Sunscale Scytheclaws prowl the southern plains and the northern borders near Ashenvale. Takk the Leaper and the elusive Ishamuhale are notable terrors of the veldt, and their stout horns can survive the clash of the hunt intact.",
  ["1"] = {
    {file = "Audio/Transport/full_item_intact-raptor-horn-74c4f477a83a9bb90a63/1-0000.mp3", duration = 51.2783673, start = 0},
  },
}
P.transport["item:intrepid-strongbox-key"] = {
  hash = "beca99",
  fullHash = "beca99",
  text = "Intrepid Strongbox Key. On the wreck of the Intrepid, Captain Halyndor still guards the key to his strongbox. The rusted iron key once kept a mysterious item locked away aboard the doomed Alliance vessel off the Wetlands. The Intrepid was wrecked with the Third Fleet off the Wetlands, and its crew became restless, cursed spirits. Captain Halyndor watched over a mysterious item inside the ship’s heavy strongbox. Now his ghost prowls the waterlogged deck, still clutching the rusted key that opens it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_intrepid-strongbox-key-1f91d3736ffcdba28066/1-0000.mp3", duration = 27.7942857, start = 0},
  },
}
P.transport["item:invisibility-liquor"] = {
  hash = "4f50e2",
  fullHash = "4f50e2",
  text = "Invisibility Liquor. Invisibility Liquor gives Maybell Maclure a way to slip from her family's sight and meet Tommy Joe Stonefield. Their households are locked in a feud. Tommy Joe Stonefield seeks a quiet meeting with Maybell Maclure, though their families' feud keeps the households apart. Their kin watch closely, and ordinary secrecy is not enough. Invisibility Liquor lets the drinker pass unseen across the disputed farmland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_invisibility-liquor-1ecf14fbdb6467c90c2b/1-0000.mp3", duration = 24.2677551, start = 0},
  },
}
P.transport["item:iron-pike"] = {
  hash = "dc2c49",
  fullHash = "dc2c49",
  text = "Iron Pike. In Lakeshire, Iron Pike supplies are needed to repair the Everstill Bridge. The shipment from Stormwind was seized by Redridge gnolls, leaving the town short of iron. Lakeshire spent its metal reserves forging armor, blades, and ammunition after recent attacks by the Blackrock orcs. Builders requested more iron from Stormwind City, but Redridge gnolls hijacked the caravan on the road. They carried crates of iron pikes and rivets north into the hills, stopping repairs on the Everstill Bridge. Foreman Oslow oversees the bridge's reconstruction and needs the stolen hardware back. Without the heavy pikes to reinforce its stone and timber frame, the bridge leaves Lakeshire partly cut off from the northern road and open to further incursions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-pike-317413e2a9bda8b2d3cf/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["item:iron-pommel"] = {
  hash = "0a51b6",
  fullHash = "0a51b6",
  text = "Iron Pommel. In Ashenvale, the Iron Pommel is the last missing piece of Dartol's Rod. The long-dead wizard Dartol made the rod, and the night elves of Astranaar seek it to slow the furbolg attacks on their people. Druids at Dor'Danil Barrow Den kept the pommel safe until their sanctuary was overrun and they were slaughtered. Dartol's Rod was split apart and scattered across Ashenvale to guard its mystic power. Night elf druids near the road south toward the Barrens took charge of the Iron Pommel. Their circle was massacred at Dor'Danil Barrow Den, and their shelter fell silent in ruins. The pommel vanished amid the destruction, swallowed by the bubbling oozes now moving through the defiled glade.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-pommel-14cc21d26627eed0f3bb/1-0000.mp3", duration = 41.0383673, start = 0},
  },
}
P.transport["item:iron-rivet"] = {
  hash = "9ba6d1",
  fullHash = "9ba6d1",
  text = "Iron Rivet. Iron Rivet shipments from Stormwind now lie in gnoll camps north of Lake Everstill. Foreman Oslow needs them to mend Lakeshire's damaged bridge. Lakeshire's iron stores went into weapons and armor when Blackrock orcs attacked. After the assaults eased, Foreman Oslow asked Stormwind for supplies to mend the damaged Everstill Bridge. Redridge gnolls ambushed the caravan before it reached town. They dragged its wagons and pack beasts into the hills north of Lake Everstill, scattering iron rivets and pikes among their camps. The Everstill Bridge needs heavy iron rivets to hold its stone and timber framework together under the weight of carts and travelers. Foreman Oslow cannot safely carry out repairs without them. The bridge links Lakeshire to the western valleys, and its repair will help secure the town's perimeter against further incursions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-rivet-2b69ba0ab6eebd622ed2/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:iron-shaft"] = {
  hash = "5611d5",
  fullHash = "5611d5",
  text = "Iron Shaft. Near Felwood, the Iron Shaft waits in a locked chest. It is one piece of Dartol's Rod, sought by Teronis to slow the furbolg assaults on Ashenvale. Dartol made the rod, then its pieces were scattered across Ashenvale. One was placed in the care of the druids of Dor'Danil. The Iron Shaft is the rod's sturdy metal core, kept in a locked chest in a glade near Ashenvale's northern border, close to Felwood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iron-shaft-4b2073947be166034d86/1-0000.mp3", duration = 25.1559184, start = 0},
  },
}
P.transport["item:ironband-s-progress-report"] = {
  hash = "b07834",
  fullHash = "b07834",
  text = "Ironband's Progress Report. In eastern Loch Modan, troggs keep Prospector Ironband's excavation from advancing. His report asks for more blastpowder after earlier supplies were sent weeks ago. Prospector Ironband's digging in Loch Modan is repeatedly disrupted by nearby troggs. His progress report, carried to Jern Hornhelm in Thelsamar and then sent on to the Explorers' League in Ironforge, describes the stalled work and asks for heavy munitions. League leaders already sent Ironband plenty of blastpowder weeks ago, and now wonder where those shipments went.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ironband-s-progress-report-c4c53153edcc0a364f46/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["item:ishamuhale-s-fang"] = {
  hash = "14c514",
  fullHash = "14c514",
  text = "Ishamuhale's Fang. At Camp Taurajo, Jorn Skyseer awaits Ishamuhale's Fang from the feared sunscale raptor Speartooth of the Barrens. The tooth proves the hunter bested one of Kalimdor's deadliest natural predators. Across the central savanna, hunters fear Ishamuhale, the fiercest sunscale raptor alive. Some say the apex hunter kills from predatory passion, not hunger. Fresh zhevra meat draws the beast into the open beside a withered tree northwest of Ratchet, where it gives no quarter. Taking its massive fang proves to the Horde's hunting instructors that a traveler has overcome the savagery of the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ishamuhale-s-fang-2735a3d652169ae8bb8d/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:ivar-s-head"] = {
  hash = "23438d",
  fullHash = "23438d",
  text = "Ivar's Head. In northern Silverpine, Ivar's Head proves Ivar the Foul is dead. Rane Yorick seeks it so her wounded brother Quinn can recover safely. Rane and Quinn Yorick were scouting northern Silverpine Forest on High Executor Hadrec's orders when Ivar the Foul ambushed them at an abandoned farmstead. The Forsaken Deathstalkers drove the feral ghoul off, but Quinn was badly mauled. Rane stayed at the ruined farm to watch over him and could not safely leave to finish their mission. Ivar's severed head proves the ghoul will no longer threaten the estate, giving Quinn time to recover under Rane's care.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ivar-s-head-ed8199cb06914362f426/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["item:iverron-s-antidote-item"] = {
  hash = "a48356",
  fullHash = "a48356",
  text = "Iverron's Antidote (item). In Shadowglen, Iverron's Antidote must reach a young night elf before it spoils. Dirania Silvershine brews it to counter the lethal venom of local Webwood spiders, but it lasts only five minutes. Dirania Silvershine brews the antidote in Aldrassil for Iverron, a young night elf bitten by Webwood spiders. Its volatile ingredients and herbal catalysts give the draught a shelf life of only five minutes. Couriers must hurry north to the Webwood cave and deliver it before it spoils.",
  ["1"] = {
    {file = "Audio/Transport/full_item_iverron-s-antidote-item-4989055dca289adafb71/1-0000.mp3", duration = 28.6040816, start = 0},
  },
}
P.transport["item:jade-phial"] = {
  hash = "487eb2",
  fullHash = "487eb2",
  text = "Jade Phial. In Dolanaar, Corithras Moonrage entrusts the Jade Phial to young initiates. It carries sacred water from Teldrassil’s moonwells to replenish the druids’ central well in Darnassus. The Jade Phial gathers water from a moonwell near Starbreeze Village. Teldrassil’s many moonwells channel lunar and natural energies that matter to night elf society and druidic worship. From time to time, the druids replenish their central moonwell in Darnassus with water from wells across the great bough. Corithras Moonrage entrusts the phial to young initiates, who use it to collect pure water without disturbing the moonwell’s spiritual potency.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jade-phial-f668bada978da8394563/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["item:jennea-s-flask"] = {
  hash = "f183fc",
  fullHash = "f183fc",
  text = "Jennea's Flask. At the Wizard's Sanctum in Stormwind, Jennea Cannon sends apprentices to Mirror Lake for water. They bring the sample back for arcane analysis. After magical struggles across Azeroth, arcane currents have torn loose from their ancient channels. Jennea Cannon seeks to learn how these shifts have affected Elwynn Forest. She gives promising apprentices a glass flask and sends them southwest of Stormwind's gates to the base of Mirror Lake's waterfall. The flask protects the water sample on the journey back to the Wizard's Sanctum, where it can be examined for arcane disturbances. Jennea's flask lets Stormwind's mages check whether shifting ley lines have tainted Mirror Lake. If the water carries harmful magic, the surrounding life and anyone who drinks from it could suffer strange afflictions. A sample can reveal magical residue before tainted currents spread through the countryside.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jennea-s-flask-06304bf8e03f2d29c296/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["item:jitters-completed-journal"] = {
  hash = "16873b",
  fullHash = "16873b",
  text = "Jitters' Completed Journal. Jitters gives up his completed journal, hoping to clear his name and expose the sinister forces haunting Duskwood. The reclusive man fears Sven Yorgen's vengeance after fleeing the massacre at Sven's farm.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jitters-completed-journal-0f51ca395299c56324d7/1-0000.mp3", duration = 12.042449, start = 0},
  },
}
P.transport["item:johaan-s-findings"] = {
  hash = "b503d1",
  fullHash = "b503d1",
  text = "Johaan's Findings. Apothecary Johaan sends his findings south from Brill to the Sepulcher. His research carries recent alchemical work from Tirisfal Glades to Apothecary Renferrel in Silverpine Forest. Apothecary Johaan sends his research from Brill to Apothecary Renferrel at the Sepulcher. The Royal Apothecary Society works under Lady Sylvanas Windrunner's demand for a New Plague that can destroy both the living and the Scourge. Its researchers are scattered across Lordaeron's contested ruins, so they must share their findings between outposts. Renferrel directs the Society's efforts from Silverpine Forest, while Johaan records his local tests in Brill. His documents join the Society's wider work to refine its deadly brews.",
  ["1"] = {
    {file = "Audio/Transport/full_item_johaan-s-findings-7eb1c012fef32f16d712/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["item:johaan-s-special-drink"] = {
  hash = "760969",
  fullHash = "760969",
  text = "Johaan's Special Drink. At Brill, Apothecary Johaan offers a drink with a deadly purpose. Disguised as a common refreshment, it tests the Royal Apothecary Society’s developing plague. In Brill, Apothecary Johaan prepares a brew from venomous components and local reagents. Though it looks like a tavern drink, the mixture is made to test how virulent the plague is against living beings. Johaan hands it over as if to quench a captive’s thirst. The work serves the Forsaken apothecaries’ effort to create a weapon potent enough to fulfill Sylvanas Windrunner’s designs for Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_johaan-s-special-drink-6320c06dce7b4be41b25/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["item:jordan-s-ore-shipment"] = {
  hash = "832427",
  fullHash = "832427",
  text = "Jordan's Ore Shipment. Mo'grosh ogres hold Jordan's Ore Shipment in the northeastern hills of Loch Modan. The ore came by caravan from the Wetlands for Bailor Stonehand to refine into an alloy for the smith Jordan Stilwell. Jordan Stilwell's ore shipment was bound for Bailor Stonehand, a dwarf who would refine it into his special alloy. The caravan carried the ore south through the mountains from the Wetlands into Loch Modan when Mo'grosh ogres ambushed it. The ogres dragged the shipment to their stronghold in the wilderness. The surviving guards perished from their wounds, and Jordan's smithing project waits until the ore is recovered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-ore-shipment-e3bb7f89c4a056a7a05d/1-0000.mp3", duration = 37.1461224, start = 0},
  },
}
P.transport["item:jordan-s-refined-ore-shipment"] = {
  hash = "0f403d",
  fullHash = "0f403d",
  text = "Jordan's Refined Ore Shipment. Jordan's Refined Ore Shipment reaches Ironforge for a paladin's sacred trials. The high-grade metal is prepared for blacksmith Jordan Stilwell to forge a holy weapon of virtue. Jordan Stilwell needs rare, exacting materials to forge a weapon worthy of a dedicated paladin. The set includes a Purified Kor Gem, sturdy Whitestone Oak lumber, his lost smithing hammer, and a shipment of refined ore. This consignment supplies the metal for the sacred labor, brought to Ironforge for the Test of Righteousness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-refined-ore-shipment-79823d04ef16ddb145f1/1-0000.mp3", duration = 32.1828571, start = 0},
  },
}
P.transport["item:jordan-s-smithing-hammer"] = {
  hash = "edf710",
  fullHash = "edf710",
  text = "Jordan's Smithing Hammer. At Jordan Stilwell’s forge, Jordan's Smithing Hammer carries a family legacy into his work. His father passed it down to him, and its recovery from Shadowfang Keep is needed for a weapon consecrated to the Light. Jordan Stilwell keeps his father’s hammer close, for it carries his family’s craft and his hopes for a masterwork. The human blacksmith works outside Ironforge, but the heirloom has somehow ended up in Shadowfang Keep, within the stone walls of Silverpine Forest. Jordan needs it back before he can forge a sacred weapon fit for a holy champion.",
  ["1"] = {
    {file = "Audio/Transport/full_item_jordan-s-smithing-hammer-edb127355d2789a1d3f1/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["item:kadrak-s-flag"] = {
  hash = "e9dc05",
  fullHash = "e9dc05",
  text = "Kadrak's Flag. At the edge of the Barrens and Ashenvale, Kadrak gives the Horde a mark to carry into enemy ground. The flag is planted in the Talon Den after Keymaster Rynthariel is killed. Kadrak sends the Horde flag into the Talon Den on Stonetalon Peak. The dryad Rynthariel, Keymaster of the Den, has sent communications across the border, and Kadrak decides her death alone will not answer them. He gives you the crimson banner to plant deep inside the Den. The Horde colors there carry a warning to the night elves and dryads: incursions across the Barrens will meet retaliation on Alliance soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kadrak-s-flag-ea5f88db89946cebc3ba/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["item:keg-of-shindigger-stout"] = {
  hash = "8ec0b7",
  fullHash = "8ec0b7",
  text = "Keg of Shindigger Stout. In Dun Garok, Shindigger Stout fills the dwarves’ kegs and draws interest from Tarren Mill. The Royal Apothecary Society wants the ale for a purpose far darker than drink. Dwarves of Ironforge hold Dun Garok in the southeastern Hillsbrad Foothills. Within its barracks and mess halls, defenders share Shindigger Stout through the cold and the siege against their regional enemies. The brew is a staple of the garrison’s daily life.",
  ["1"] = {
    {file = "Audio/Transport/full_item_keg-of-shindigger-stout-7662aaf6d41481297a07/1-0000.mp3", duration = 25.4693878, start = 0},
  },
}
P.transport["item:ken-zigla-s-draught"] = {
  hash = "e5b04f",
  fullHash = "e5b04f",
  text = "Ken'zigla's Draught. In the Stonetalon Mountains, Ken'zigla prepares a bitter draught for the gravely wounded. A careful half dose restores enough strength to move, while more can make a patient bleed out. Ken'zigla prepares the draught in the Stonetalon Mountains for those near death. Its strength must be measured with care: more than half a dose at once can make the patient bleed out as their circulation surges. Half a dose gives a wounded person enough vigor to move and flee danger. The rest must wait until the body steadies after a full night's rest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ken-zigla-s-draught-313a3f44deb551faf6ba/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["item:khazgorm-s-journal"] = {
  hash = "2943f8",
  fullHash = "2943f8",
  text = "Khazgorm's Journal. At Bael Modan, Prospector Khazgorm leads the Ironforge dwarven excavation in the southern Barrens. His field ledger records the Explorers' League's work on lands claimed by the Stonespire tauren. Prospector Khazgorm directs the heavy machinery and blasting that cut into the southern Barrens hillsides. His notes show an excavation far from the Explorers' League's promised search for knowledge: its work has displaced the Stonespire tribe. The tauren tried to settle matters peacefully, but the dwarves refused. Gann Stonespire wants the journal to understand the Ironforge presence in his homeland and find a way to break it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_khazgorm-s-journal-0a45d0869d43f8b8719d/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["item:klaven-mortwake-s-journal"] = {
  hash = "01372e",
  fullHash = "01372e",
  text = "Klaven Mortwake's Journal. Inside a chest from Duskwood, Klaven Mortwake's Journal records the Defias Brotherhood's search for a way to raise the dead. SI:7 operatives recovered it from the Defias tower in northeastern Westfall. Master Mathias Shaw leads Stormwind's intelligence service, SI:7, and sought Mortwake's journal to trace the Brotherhood's wider alliances. The notes confirm experiments in reanimation and illicit support linking Duskwood, the Venture Company, and the Defias. For rogues serving the crown, recovering the research marks a step toward mastering poisons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_klaven-mortwake-s-journal-f94054fc257d47ae9607/1-0000.mp3", duration = 33.7763265, start = 0},
  },
}
P.transport["item:kodo-horn"] = {
  hash = "8f04e8",
  fullHash = "8f04e8",
  text = "Kodo Horn. In the Barrens, Kodo Horns are gathered from the roaming kodos. Tonga Runetotem uses them in herbal remedies for poisoned wildlife. Across the Barrens, Tonga Runetotem uses intact kodo horns in his herbal remedies. He works from the Crossroads, where the horns help strengthen his salves. Chips and fragments lack the strength he needs, so he gathers whole horns from mature kodos wandering the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodo-horn-e41950b4e5ca9dd9572b/1-0000.mp3", duration = 24.3461224, start = 0},
  },
}
P.transport["item:kodo-liver"] = {
  hash = "7d8d8b",
  fullHash = "7d8d8b",
  text = "Kodo Liver. In Ratchet, Brewmaster Drohn needs Kodo Liver for a strange ale. He learned to brew trogg ale from the wandering brewmaster Chen Stormstout. Kodos roam the Barrens, where tauren and predators hunt them for their hides and meat. In Ratchet, Brewmaster Drohn uses a fresh Kodo Liver with thunderhawk saliva glands and lightning glands to make trogg ale. Chen Stormstout taught Drohn the recipe, and Drohn says the blend packs a potent kick for adventurous travelers. The ingredients come from the wilds of central Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodo-liver-a22496748f0782a67b57/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["item:kodobane-s-head"] = {
  hash = "e4802a",
  fullHash = "e4802a",
  text = "Kodobane's Head. Near the Forgotten Pools, Barak Kodobane's severed head proves the cunning chieftain's death. The orc warlord Regthar Deathgate receives it as proof that the centaur threat there has been broken. Kolkar bands in the Barrens have long been divided, but ambitious warlords now threaten to gather them into an army. Barak Kodobane made his camp by the lush waters of the Forgotten Pools, where the oasis offers vital resources and nearby paths lie open to raids. Regthar Deathgate, stationed in a bunker west of the Crossroads, demands Kodobane's severed head as proof that this commander can no longer rally his kin against the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kodobane-s-head-06f0dac0c7655d3a8451/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["item:kravel-s-crate"] = {
  hash = "770592",
  fullHash = "770592",
  text = "Kravel's Crate. Kravel's Crate is a heavy package dispatched by Kravel Koalbeard from the Mirage Raceway in the Shimmering Flats. Destined for the Nesingwary expedition in Stranglethorn Vale, it contains specialized hunting ammunition designed to bring down the jungle's deadliest game. Handed out by the shrewd entrepreneur Kravel Koalbeard at the Mirage Raceway, Kravel's Crate represents an unfinished business transaction across continents. Ordered weeks prior by a wealthy dwarven patron, the shipment was delayed long enough for its buyer to depart Kalimdor entirely. Rather than lose out on the favor of a wealthy customer who already paid for forwarding, Kravel entrusts passing adventurers to haul the crate all the way to northern Stranglethorn Vale. Despite its nondescript appearance and the crust of salt dust it gathers in the Shimmering Flats, the crate carries lethal cargo: heavy, special-gauge ammunition tailored specifically for hunting rifles. When received at the expedition camp north of Grom'gol, the recipient notes that the potent rounds are prized by big-game hunters and vital for survival against the predators roaming the jungle canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kravel-s-crate-3b11c3796519f66f4025/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["item:kreenig-snarlsnout-s-tusk"] = {
  hash = "76f4cb",
  fullHash = "76f4cb",
  text = "Kreenig Snarlsnout's Tusk. At the Crossroads, Thork seeks proof that Kreenig Snarlsnout has fallen. His tusk marks the end of the Razormane leader's attacks on Horde caravans in the northern Barrens. Horde caravans traveling west from Durotar face constant attacks in the Barrens. Those raids grew bolder under Kreenig Snarlsnout, a fierce Razormane leader. Thork, commander of the Crossroads watch, ordered Kreenig killed to disrupt the quilboars' coordination. His tusk offers proof that the leader is dead and insults the Razormane, weakening their resolve and leaving their fighters without central direction.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kreenig-snarlsnout-s-tusk-711ef6009598afc3b3ed/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["item:kuz-s-skull"] = {
  hash = "25f029",
  fullHash = "25f029",
  text = "Kuz's Skull. In the southern Barrens, Kuz's Skull marks the end of a feared Razormane raider. Kuz came from Razorfen Kraul and helped lead attacks on Horde outposts before a captive former kin sought vengeance. Kuz, Nak, and their chieftain Lok Orcbane led Razormane attacks across the southern Barrens. Sent from Razorfen Kraul, the three raiders struck travelers and settlements such as the Crossroads. Their betrayal of Mangletooth, a fellow quilboar, turned one of their own against them. They left Mangletooth to rot in a cage at Camp Taurajo. From that cage, he revealed Kuz's location to Horde champions willing to kill the raider and take her head.",
  ["1"] = {
    {file = "Audio/Transport/full_item_kuz-s-skull-49447555686b9241aaff/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:laced-pumpkin"] = {
  hash = "4045ef",
  fullHash = "4045ef",
  text = "Laced Pumpkin. At Apothecary Johaan's hand, Laced Pumpkin turns an ordinary gourd into a deadly test of Forsaken alchemy. In Brill, the Royal Apothecary Society seeks weapons against the Scourge and living human forces. In Tirisfal Glades, the pumpkin looks like ordinary produce salvaged from blighted soil. Apothecary Johaan in Brill treats it with experimental toxins meant to realize the full potential of undeath. The Royal Apothecary Society seeks weapons against the Scourge in the north and living human forces advancing from the south. Even a simple harvest can carry infection and chemical death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laced-pumpkin-eef716995b312ca5b65b/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["item:laird-s-response"] = {
  hash = "0f3e3f",
  fullHash = "0f3e3f",
  text = "Laird's Response. Along Teldrassil's shores, Laird's Response carries a puzzle for Nessa Shadowsong. The fish there are larger and more plentiful than those along mainland Darkshore. Laird compares catches from across the Veiled Sea. Fish from Teldrassil's coast are larger and more plentiful than those from Darkshore's mainland beaches. In his reply to Nessa Shadowsong, Laird of Auberdine offers a theory: the newly planted World Tree's unusual presence and vitality may be changing the surrounding sea life. Travelers carry his letter across the water to Rut'theran Village, where the fisherfolk greet the news with wonder and quiet curiosity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laird-s-response-f5ed123af1b03bc667cc/1-0000.mp3", duration = 37.0677551, start = 0},
  },
}
P.transport["item:lake-creeper-moss"] = {
  hash = "43f7e4",
  fullHash = "43f7e4",
  text = "Lake Creeper Moss. Around Lake Lordamere’s southern Dawning Isles, Lake Creeper Moss grows on aquatic beasts. The Royal Apothecary Society seeks the organic compound as a vital reagent for engineering a lethal new plague. Lake Creeper Moss grows on the hides of freshwater beasts in the waters by the southern Dawning Isles. Lordaeron’s blighted waters shape its unusual properties. Before Arugal’s curse claimed his mind, Apothecary Berard recorded the moss in his journal. He noted its resemblance to traces found on fossils of creatures killed by an ancient plague in the lake. Forsaken agents send recovered samples to the Apothecarium in the Undercity, where Master Apothecary Faranell uses them in his research.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lake-creeper-moss-6fc0888c8130746880a4/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["item:lake-skulker-moss"] = {
  hash = "d73f20",
  fullHash = "d73f20",
  text = "Lake Skulker Moss. In northern Lake Lordamere, Lake Skulker Moss draws the Royal Apothecary Society's attention. Apothecary Berard identified it as an organic part of research into brewing a New Plague before Arugal's curse claimed his mind. Lake Skulker Moss is gathered from Lake Skulkers and Elder Lake Skulkers on the Dawning Isles. Before Arugal's curse claimed his mind, Apothecary Berard cataloged the plants and creatures of eastern Silverpine Forest. In his journal, he wrote that Lake Skulker and Lake Creeper mosses could stabilize or react with other ingredients. After Berard became Arugal's mindless servant, his journal was recovered from Pyrewood Village for Apothecary Renferrel. Renferrel sent Forsaken champions to gather moss and a rare tumor from local Vile Fin murlocs, then deliver both to Master Apothecary Faranell in the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lake-skulker-moss-f8cf0cc92214be842009/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["item:large-candle"] = {
  hash = "f5d471",
  fullHash = "f5d471",
  text = "Large Candle. In Elwynn's mines, kobolds carry Large Candles on their heads for light and wax. Their flames guide them through dark tunnels, and apothecaries value the wax. Kobolds use candle flame to find their way through the dark shafts beneath Elwynn Forest. They fasten the tapers to their heads, and Kobold Miners, Tunnelers, and Geomancers defend them fiercely from intruders. Though crudely made, the Large Candles carried in Fargodeep Mine and Jasperlode Mine hold valuable wax. Surface tradesmen cannot easily produce it in bulk, so the candles are both tools for the kobolds and a commodity for alchemists. William Pestle, an apothecary operative from Stormwind City, gathers Large Candles at the Lion's Pride Inn in Goldshire. His family runs an apothecary, and he needs rendered wax for its concoctions, balms, and ointments. Pestle hires passing adventurers to clear the infested mines and take candles from the kobolds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_large-candle-19cfc3177d1e934ebeee/1-0000.mp3", duration = 53.76, start = 0},
  },
}
P.transport["item:large-soran-ruk-fragment"] = {
  hash = "36d915",
  fullHash = "36d915",
  text = "Large Soran'ruk Fragment. The Large Soran'ruk Fragment rests in Shadowfang Keep, far from the other shards. Its broken orb once held a disgraced demon of the Burning Legion. Disgraced demons of the Burning Legion may be condemned to imprisonment in enchanted orbs. Mages and warlocks aligned with the Legion receive these vessels and draw on the fel forces trapped within. Even when an orb is shattered, its bound fiend's lingering essence still radiates power. Each fragment draws ambitious practitioners of shadow magic. The orb of Soran'ruk was cracked into two halves long ago. Cultists elsewhere scattered one half into smaller pieces. A sorcerer in the cursed Shadowfang Keep claimed the larger half. The Shadowfang Darksouls carry the Large Soran'ruk Fragment, which holds the bound spirit until someone seeks to reforge the ancient vessel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_large-soran-ruk-fragment-e1b21f26a6ad800762e5/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["item:laughing-sister-s-hair"] = {
  hash = "df6ec5",
  fullHash = "df6ec5",
  text = "Laughing Sister's Hair. In Ashenvale, laughing sisters' hair draws weavers seeking its natural magic. Kil'hala at the Crossroads uses the gathered locks to make enchanted robes. Near Raynewood Retreat in Ashenvale, laughing sisters are dryads whose hair holds natural magic. Dryads protect the woods and are linked to Cenarius and the night elves. Horde craftsmen prize their hair as a potent crafting material. Kil'hala, a troll tailor at the Crossroads, spins the locks into enchanted robes for Deino's promising pupils of the arcane.",
  ["1"] = {
    {file = "Audio/Transport/full_item_laughing-sister-s-hair-c9b367aabc10724f924a/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["item:legacy-of-the-aspects"] = {
  hash = "21b767",
  fullHash = "21b767",
  text = "Legacy of the Aspects. Legacy of the Aspects is an ancient tome hidden deep within the Dor'Danil Barrow Den in southern Ashenvale. Retrieved during a Horde trial of the intellect, the volume contains essential lore concerning the Great Aspects that shaped ancient Azeroth. While earlier trials set forth by tauren elders test physical endurance and resolve, the pursuit of Legacy of the Aspects is designed to challenge the mind. Tasked by Braug Dimspirit at the entrance to the Talondeep Path in the Stonetalon Mountains, an aspirant must delve into the haunted barrow dens of Dor'Danil. Guarded by the restless spirits of fallen druids and the vicious creatures that slew them, the ancient text rests upon a stone pedestal. Claiming the volume is only the first step; the seeker must commit its contents to memory before relinquishing the book, as they are tested on its historical lessons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_legacy-of-the-aspects-57fc25b60cf136dbc076/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["item:letter-to-delgren"] = {
  hash = "c940cf",
  fullHash = "c940cf",
  text = "Letter to Delgren. Balthule Shadowstrike sends a warning from the Tower of Althalaxx in northern Darkshore. His letter to Delgren the Purifier describes the Dark Strand cult's demonic work and must reach Maestra's Post in Ashenvale. Balthule Shadowstrike watches the Dark Strand cult gather around the Tower of Althalaxx ruins. He cannot destroy the cult alone, so he writes to Delgren the Purifier, his tutor in the Holy Light, asking for aid. The cult's foul rites threaten more than Darkshore's coast. The letter must travel south through the region into western Ashenvale, where Delgren works with night elf Sentinels against demonic and undead threats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-delgren-d62cb6aa45a9d667d447/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["item:letter-to-jin-zil"] = {
  hash = "5f9ee6",
  fullHash = "5f9ee6",
  text = "Letter to Jin'Zil. At the Crossroads, Letter to Jin'Zil carries word of Serena Bloodfeather's defeat. Darsok Swiftdagger sends it to the Darkspear witch doctor in the Stonetalon Mountains, telling him the northern Barrens are free of the Bloodfeather threat. After the harpies at the Dry Hills are wiped out and Serena Bloodfeather is slain, Darsok Swiftdagger writes to an old comrade. The harpies of the Barrens first roosted in the peaks of the Stonetalon Mountains. Darsok sends news of the fallen matron to Jin'Zil, a witch doctor, and introduces a promising warrior to the wider frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-jin-zil-0fafe28a185aeff857c9/1-0000.mp3", duration = 31.3730612, start = 0},
  },
}
P.transport["item:letter-to-jorgen"] = {
  hash = "37c54e",
  fullHash = "37c54e",
  text = "Letter to Jorgen. A sealed letter calls on Jorgen in Stormwind City to help with a missing diplomat. A diplomat bound for Theramore failed to arrive for talks with Lady Jaina Proudmoore, and royal investigators moved quickly to keep the matter quiet. While official agents searched the capital, other channels stirred. The letter bypasses military bureaucracy and seeks out Jorgen, a gruff veteran who fishes beneath the great statues in the Valley of Heroes. It invokes old obligations and draws him into a covert inquiry amid rumors of a Defias conspiracy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_letter-to-jorgen-998566eefc44336776e5/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["item:lewis-note"] = {
  hash = "a8c6ec",
  fullHash = "a8c6ec",
  text = "Lewis' Note. At Sentinel Hill, Quartermaster Lewis sends an urgent supply requisition to a private armorer in Stormwind. A courier carries it by gryphon, asking for protective gear for the Westfall garrison. The People's Militia at Sentinel Hill gets little support from Stormwind's House of Nobles. Skirmishes with the Defias Brotherhood keep draining its meager stocks of gear. To keep the defenders outfitted, Quartermaster Lewis turns to private business instead of crown supplies. His requisition bypasses official military channels entirely. An Alliance courier must fly by gryphon to Old Town and present the order to Osric Strang, proprietor of Limited Immunity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lewis-note-c5ccc0bd24f03522e3be/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["item:lightning-gland"] = {
  hash = "3eb063",
  fullHash = "3eb063",
  text = "Lightning Gland. In the Barrens, Lightning Glands are taken from stormhides roaming the plains. Brewmaster Drohn in Ratchet needs them for trogg ale, a fiery brew Chen Stormstout taught him to make. Stormhides roam the Barrens savannas among other predators touched by the elements. Their flesh holds lightning glands, organs charged with latent electricity. These glands are poor fare on their own, but brewers prize them for the sting they bring to a brew. Brewmaster Drohn keeps Chen Stormstout’s brewing traditions alive in Ratchet. To make trogg ale, a potent brew, Drohn needs five lightning glands, a thunderhawk saliva gland, and a fresh kodo liver. The finished drink has a sharp kick that adventurers find invigorating and potent.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lightning-gland-714e132ea3f446f12928/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["item:logging-rope"] = {
  hash = "f3bece",
  fullHash = "f3bece",
  text = "Logging Rope. At the Warsong Lumber Camp, Logging Rope keeps the mills and machinery supplied. Furbolg tribes have stolen shipments across Ashenvale, leaving the Warsong to recover the line they need. Logging Rope shipments meant for the Warsong Lumber Camp have been stolen. The Foulweald and Thistlefur furbolgs intercepted the line before it reached the loggers. The tribes keep the ropes in their encampments across northern and central Ashenvale. Corruption has driven the furbolgs mad, and they fiercely defend their ancestral woods. Locke Okarr at Splintertree Post seeks to recover the stolen supplies before work at the Warsong Lumber Camp stops. The heavy rope lets the Horde secure timber, bind logs, and rig saw machinery. Furbolg resistance continues across the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_logging-rope-c92e93c9436ec91b09a5/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["item:lok-s-skull"] = {
  hash = "6741e6",
  fullHash = "6741e6",
  text = "Lok's Skull. In the southern Barrens, Lok's Skull marks the fall of a feared Razormane leader. Lok Orcbane led fierce quilboar raids against Horde supply routes, and the skull is his severed head. Lok Orcbane led aggressive Razormane assaults on Horde supply lines in the southern Barrens. He emerged from Razorfen Kraul with his lieutenants Nak and Kuz. After betraying Mangletooth and leaving him captive at Camp Taurajo, Lok became known to orcish defenders for ruthless raids they struggled to contain. Mangletooth directs Horde champions to Lok's camp, where claiming Lok's skull avenges the captive and strikes at the leadership driving the Razormane offensive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lok-s-skull-19c6379fe4fe7da893e0/1-0000.mp3", duration = 37.7730612, start = 0},
  },
}
P.transport["item:lonebrow-s-journal"] = {
  hash = "a8c9c9",
  fullHash = "a8c9c9",
  text = "Lonebrow's Journal. Lonebrow's Journal is a weathered diary found clutched in the skeletal remains of the dwarven explorer Henrig Lonebrow at the base of the Great Lift. Its pages detail the final grim journey of Lonebrow through the Barrens and point toward dangers lurking within Razorfen Kraul. Henrig Lonebrow met an unfortunate end near the base of the Great Lift connecting the Barrens to Thousand Needles. Lying abandoned on a rocky ledge, his skeletal remains still grip this weathered journal. The diary serves as a testament to his final travels and directs whoever discovers it to bring word to the night elf druid Falfindel Waywarder at Thalanaar, the border outpost leading into Feralas. Lonebrow's notes shed critical light on the quilboar menace brewing in the southern barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lonebrow-s-journal-9a866fb28b7faef501d1/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["item:lorgalis-manuscript"] = {
  hash = "da3822",
  fullHash = "da3822",
  text = "Lorgalis Manuscript. The Lorgalis Manuscript lies hidden beneath Ashenvale in the sunken ruins of Blackfathom Deeps. The ancient text concerns the Old Gods, and dark scholars covet its words about powers that sleep. The Lorgalis Manuscript lies at the bottom of Blackfathom Deeps, where long-dead elves once lived before their city fell. Lorgalis wrote of the Old Gods, who raged across Azeroth when the world was new and now lie chained and sleeping. The text praises Aku'mai, a servant of the Old Gods who dwells in the Deeps. Its lore is said to open mystical doorways and stir ancient beings sleeping deep beneath the world. The manuscript rests in a pitted iron chest among the flooded corridors, drawing the attention of cultists and shadow scholars alike.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lorgalis-manuscript-c0dbe0f3b73ab8d113a4/1-0000.mp3", duration = 43.52, start = 0},
  },
}
P.transport["item:lunar-fungus"] = {
  hash = "092db0",
  fullHash = "092db0",
  text = "Lunar Fungus. Lunar Fungus grows in Darkshore's caves, where druids gather it for healing. Mixed with Earthroot and water, it helps make a salve for sick deer. Lunar Fungus grows from Lunar Fungal Blooms in Darkshore's underground caverns. The Cenarion Circle values its amplifying effects. Mixed with soothing water and common Earthroot, it lends potency to a salve that counters debilitating afflictions. Damp caves where it grows are also frequented by territorial moonkin, so gathering it means navigating carefully. In Auberdine, Alanndarian Nightsong has young druids gather Lunar Fungus as part of their studies in nature's healing arts. They see how physical ingredients such as this fungus can counter poisons in local deer. By learning how herbal remedies work, initiates prepare to channel natural antidotes through shapeshifting and spiritual power.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lunar-fungus-2d6a1e482c17f124df1e/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["item:lurker-venom"] = {
  hash = "540bc6",
  fullHash = "540bc6",
  text = "Lurker Venom. Around Loch Modan, dwarven defenders need Lurker Venom to counter Dark Iron sabotage. The toxin comes from predatory spiders in the rocky hills and woods. Lurker Venom helps dwarves disarm Dark Iron explosives. Ashlan Stonesmirk, an explosives expert, named the spiders’ poison as an ingredient for the mixture Chief Engineer Hinderweir prepares. The solvent combines the venom with rare minerals and tears from the loch’s crocolisks, forming a reactive compound that can disarm complex explosives. Lurker spiders range from common wood lurkers to the matriarch Shanda the Spinner, and their bites threaten travelers and mountaineers across the hills and crags.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lurker-venom-b3c63638d3b422eda197/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["item:lydon-s-toxin"] = {
  hash = "54f23b",
  fullHash = "54f23b",
  text = "Lydon's Toxin. In Tarren Mill, Apothecary Lydon has made a toxin to disrupt the Venture Company's logging in the Stonetalon Mountains. Horde adventurers carry it to Apothecary Zamah in Thunder Bluff, who must devise a way to spread it. Apothecary Lydon made the toxin in the Hillsbrad Foothills to fight the Venture Company loggers despoiling the Stonetalon Mountains. He says the compound is lethal on contact and may spread from one target to another. Before it can be used against the goblins near Windshear Crag, the mixture must cross continents to Thunder Bluff. Apothecary Zamah, the Royal Apothecary Society's representative there, needs the raw toxin to devise a wide-dispersal device called the Toxic Fogger.",
  ["1"] = {
    {file = "Audio/Transport/full_item_lydon-s-toxin-21e3e6d761512f854013/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:macgrann-s-dried-meats"] = {
  hash = "c771e2",
  fullHash = "c771e2",
  text = "MacGrann's Dried Meats. Tundra MacGrann has a month's worth of salted meat set aside for winter in Dun Morogh. His provisions are locked in a thorium meat locker, but Old Icebeard has carried off the whole cache. Tundra MacGrann prepared for winter by hunting game and salting the meat. He stored weeks of provisions in a sturdy chest, then locked it in a thorium meat locker to keep scavenging bears and prowling predators away from his homestead. Even so, he never expected an intruder strong enough to carry off the whole chest instead of trying to pry it open. Old Icebeard raided MacGrann's camp while the dwarf was away tracking deer and dragged the heavy chest to his den in Chill Breeze Valley. The yeti cannot break through the solid thorium plating, but MacGrann's injured leg keeps him from mounting a swift rescue into the cavern. Without help retrieving the cache before winter sets in, the stranded hunter faces starvation in the mountain snows.",
  ["1"] = {
    {file = "Audio/Transport/full_item_macgrann-s-dried-meats-dcba9ecf141a81f5d895/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["item:mackreel-s-moonshine"] = {
  hash = "633975",
  fullHash = "633975",
  text = "MacKreel's Moonshine. On the broken Thandol Span, Foggy MacKreel brews moonshine strong enough to fell a sentry. Brewmeister Bilger in Southshore takes a batch to settle Foggy's debt. Foggy MacKreel brews his moonshine while stationed as a guard on the Thandol Span. The liquor has a fierce reputation, and even hardened dwarven sentries can be laid low after a night of drinking it. They wake with headaches like siege engines rolling overhead. Travelers value its warmth against the damp chill of Lordaeron and Khaz Modan. Foggy MacKreel owed an unsettled debt to Brewmeister Bilger, Southshore's tavern keeper and master brewer. He sent a batch of moonshine instead of coin to clear his tab. Bilger accepts the liquor in place of gold and adds MacKreel's potent brew to his stock for the chilly coastal days of the Hillsbrad Foothills.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mackreel-s-moonshine-e48e7523e389da795703/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["item:maggot-eye-s-paw"] = {
  hash = "44b304",
  fullHash = "44b304",
  text = "Maggot Eye's Paw. At Garren's Haunt, Maggot Eye's Paw proves the gnoll chieftain is dead. The paw is carried to Brill as proof of his execution for stealing corpses for the Scourge. Maggot Eye raided graves and pillaged the countryside near Garren's Haunt, supplying corpses to the Lich King's armies. The Forsaken posted a death sentence and bounty in Brill. To collect the bounty and close it, hunters must bring the gnoll's severed paw back to town. Executor Zygand accepts that proof in place of rumors of Maggot Eye's death.",
  ["1"] = {
    {file = "Audio/Transport/full_item_maggot-eye-s-paw-618fec86f7103fe5df45/1-0000.mp3", duration = 28.6563265, start = 0},
  },
}
P.transport["item:maggran-s-reserve-letter"] = {
  hash = "81920c",
  fullHash = "81920c",
  text = "Maggran's Reserve Letter. At Sun Rock Retreat, Maggran Earthbinder sends orders to relieve a guard at the Great Lift. The letter promises Grish Longrunner leave to visit his family. Maggran Earthbinder sends orders from Sun Rock Retreat to the Great Lift. Grish Longrunner, a Horde sentry at the post, is to be relieved by a replacement warrior. The Great Lift's wooden winches stand far to the south, where Grish has kept watch. With the new warrior taking his place, he can leave his post and return home to visit his family.",
  ["1"] = {
    {file = "Audio/Transport/full_item_maggran-s-reserve-letter-8019113a7a52c34dfb79/1-0000.mp3", duration = 28.3428571, start = 0},
  },
}
P.transport["item:mangy-claw"] = {
  hash = "17ccf3",
  fullHash = "17ccf3",
  text = "Mangy Claw. In Dun Morogh, Mangy Claw bears the mark of a deadly hunt. The great ice claw bear Mangeclaw killed a stranded dwarven pilot, and the severed claw proves the beast was slain. Pilot Hildelve’s steam tank broke down in Dun Morogh’s frozen hills, leaving him to search for ore on foot and face the mountain wilderness alone. His recovered journal tells how he fought off an ice claw bear named Mangeclaw, though the struggle left him savagely mauled. The bear returned later and killed the weakened pilot. In his final written entry, Hildelve pleaded for vengeance. Taking the Mangy Claw from the fallen bear fulfills that request.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mangy-claw-82546f5b7cff11707655/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["item:marshal-haggard-s-badge"] = {
  hash = "bd7329",
  fullHash = "bd7329",
  text = "Marshal Haggard's Badge. At his farm in Elwynn, Marshal Haggard has lost the badge he carried in Stormwind's service. Dead-tooth Jack stole it by trickery, and the Defias may use it to impersonate city officials. Marshal Haggard retired to a small farmstead in the hills of Elwynn Forest, but his old Stormwind Marshal's badge still carries official weight. One night, Dead-tooth Jack, a Defias rogue, wore a Stormwind tabard and posed as Marshal Dughan, Goldshire's garrison commander. He tricked Haggard into believing his former peers needed the insignia for official business. The aging marshal handed it over without suspicion. Jack fled into the woods before Haggard saw through the ruse. In Defias hands, the emblem of Stormwind authority could let outlaws pass checkpoints or confuse local patrols.",
  ["1"] = {
    {file = "Audio/Transport/full_item_marshal-haggard-s-badge-04996b638daa5cab68eb/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:mary-s-looking-glass"] = {
  hash = "621fa8",
  fullHash = "621fa8",
  text = "Mary's Looking Glass. In Duskwood, Mary’s discarded looking glass passes from a ghoul to a stargazer. Blind Mary once treasured the polished mirror. After her death and the loss of her eyes, her reflection became an agonizing reminder of what she had lost. She cast the looking glass away behind her barn, where Duskwood's gloom closed in. An Insane Ghoul found it among the ruined outskirts and carried it south to the crypts of Tranquil Gardens Cemetery. In Darkshire, the stargazer Viktori Prism'Antras dreams of seeing through Duskwood's eternal twilight to the clear heavens above. His telescope needs special optical lenses and reflective glass. Mary sends adventurers after the feral undead in the cemetery's ruined chapel to recover her looking glass. Viktori needs it as a reflector in his machine for viewing the stars.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mary-s-looking-glass-9bcb3e4648a8e49d35fa/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["item:mathystra-relic"] = {
  hash = "0aca17",
  fullHash = "0aca17",
  text = "Mathystra Relic. Among Mathystra’s overgrown ruins in northern Darkshore, ancient night elven relics still hold traces of magic. The Twilight's Hammer cult has taken an interest in them. Mathystra once stood on the Kalimdor coast as a city and bastion of elven civilization. Before the Great Sundering, it was a proud place. Now toppled columns and cracked stones lie half-swallowed by brush and sea mist, with restless spirits and lurking beasts among them. Relics from that age are scattered through the ruins. Ten thousand years of neglect have worn them, but traces of elven arcane craft remain, and they are dangerous in careless hands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mathystra-relic-62a30fedf25321b3b711/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["item:melenas-head"] = {
  hash = "2a0257",
  fullHash = "2a0257",
  text = "Melenas' Head. At Fel Rock, Melenas' Head marks the end of a lingering demonic threat on Teldrassil. Taken as a bounty from Lord Melenas, the satyr commander encamped there, it is proof of his death. Satyrs on Teldrassil’s new World Tree shame the night elves who guard Shadowglen and the surrounding reaches. Lord Melenas made his lair in Fel Rock’s twisted caverns, just north of the elven settlements, and rallied aggressive grell warriors to his banner. The kaldorei prize discretion when dealing with corruption so close to their heartlands. Melenas' Head is private proof that his schemes have ended before his influence could spread.",
  ["1"] = {
    {file = "Audio/Transport/full_item_melenas-head-a4cdc3a79122453001c3/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:menethil-statuette"] = {
  hash = "163305",
  fullHash = "163305",
  text = "Menethil Statuette. Off the Wetlands coast, the Menethil Statuette lies lost from a shipwreck. The rare silver likeness honors Lordaeron's fallen king. King Terenas Menethil II appears in his youth, a long-haired paladin lifting a hammer toward the heavens. He was humble and disliked personal monuments, so few statues or likenesses were made in his honor. The Scourge's fall of Lordaeron destroyed almost all of them. This surviving effigy is extraordinarily valuable to the Alliance. The Blind Princess carried the statuette toward the Alliance harbor of Menethil. Bluegill murlocs attacked the merchant vessel off the marshy coast, scattering its cargo. The statuette became trapped in a half-buried barrel on shore. With Dragonmaw orcs and other local threats nearby, defenders hurried to send the recovered icon south to Stormwind City. There, Highlord Bolvar Fordragon entrusted it to the Cathedral of Light.",
  ["1"] = {
    {file = "Audio/Transport/full_item_menethil-statuette-f84c213c7938f446e18b/1-0000.mp3", duration = 55.9281633, start = 0},
  },
}
P.transport["item:merrin-s-letter"] = {
  hash = "f487b2",
  fullHash = "f487b2",
  text = "Merrin's Letter. At the Whelgar's Excavation site, Merrin Rockweaver sends an urgent message from the Wetlands. Raptors have overrun the dig, but Merrin assures her loved ones that she survived. Merrin Rockweaver writes from the ruined dig at Whelgar's Excavation in the Wetlands. The dwarven expedition had been uncovering enormous prehistoric fossils and relics when they disturbed a nest of Mottled Raptors. The beasts swarmed the trenches, killed several workers, and cut off the surviving researchers. Amid the chaos, Merrin sends word to her husband Tarrel at Menethil Harbor. She, Prospector Whelgar, and Ormer Ironbraid survived behind a barricaded shelter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_merrin-s-letter-4c170ee51248d271a055/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["item:middle-of-gelkak-s-key"] = {
  hash = "58537c",
  fullHash = "58537c",
  text = "Middle of Gelkak's Key. Off Darkshore, Gelkak Gyromast’s key lies in three pieces after threshadons sank his ship. Greymist murlocs took the middle fragment from the shore. Gelkak Gyromast’s winding key broke when threshadons dragged his ship beneath the waves. The gnome pirate came ashore with his belongings shattered on the rocky shoals. The specialized key was made for his mechanical first mate, but the wreck split it into three pieces scattered along the strand. Coastal beasts carried off the top and bottom. Greymist murlocs prowling the Darkshore surf took the middle piece and kept it in their camps and among the wreckage they hold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_middle-of-gelkak-s-key-b414c4c3838684a9d63b/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:milly-s-harvest"] = {
  hash = "4ee5a5",
  fullHash = "4ee5a5",
  text = "Milly's Harvest. In the Northshire Vineyards, Milly's grapes lie abandoned after the Defias arrive. Crates and buckets of fruit remain at risk of theft or being crushed beneath the abbey guards' boots. Milly Osworth gathers grapes in the Northshire Vineyards, where the harvest matters to local vintners and the abbey community. When armed brigands in red masks push into the fields, Milly flees to the abbey grounds. Her fresh-picked grapes remain scattered between the rows. Stormwind guards watch the valley entrance, but too few soldiers leave Northshire vulnerable. The garrison promises to drive out the Defias, while Milly fears a drawn-out fight between guards and thieves will ruin her harvest. The crates may be trampled or carried off as provisions, costing Northshire one of its few peaceful harvests.",
  ["1"] = {
    {file = "Audio/Transport/full_item_milly-s-harvest-00a03b4632d1ed3e7a21/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["item:miners-gear"] = {
  hash = "736519",
  fullHash = "736519",
  text = "Miners' Gear. Miners' Gear lies stored in the Silver Stream Mine after its ore ran out. Kobolds have overrun the tunnels, and the Miners' League wants the tools recovered before local guards attack. The Silver Stream Mine in northern Loch Modan holds the Miners' League's stored tools. After the mine ran out of ore, the league turned its quiet tunnels into a depot for mining equipment. Kobolds soon overran the mine, took the goods, and made their nests among the crates. The league fears the dwarven gear could be wrecked in an assault by the Mountaineers or ruined by the scavengers. Adventurers are sent inside to bring the crates back to safety.",
  ["1"] = {
    {file = "Audio/Transport/full_item_miners-gear-d7342ea7a3e79fd713ba/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
P.transport["item:miners-union-card"] = {
  hash = "598b55",
  fullHash = "598b55",
  text = "Miners' Union Card. In Moonbrook, union cards mark the laborers lost beneath the earth. Workers once carried them through the mines, and now the cards remain with skeletal dead in the dark drifts. Before the Defias Brotherhood took control of Moonbrook, miners worked below ground for the guild, drawing valuable ore for the kingdom. A tunnel collapse crushed a major shaft and killed dozens beneath the rock. The dead rose as skeletal miners, excavators, and dynamiters. Union cards remain in their bony pockets, the last proof of who they were. In Stormwind, surviving colleagues seek the cards to learn the dead workers' identities and bring closure to their families.",
  ["1"] = {
    {file = "Audio/Transport/full_item_miners-union-card-9198740beeffd9650ddb/1-0000.mp3", duration = 38.164898, start = 0},
  },
}
P.transport["item:minshina-s-skull"] = {
  hash = "aefe64",
  fullHash = "aefe64",
  text = "Minshina's Skull. On the Echo Isles, Minshina's Skull holds the bound soul of Minshina, a Darkspear troll and brother of Master Gadrin. Zalazane trapped him there after driving the tribe from the isles, and uses the skull to fuel dark rituals. Minshina was captured and slain when Zalazane seized the Echo Isles and drove out the Darkspear. The traitorous witch doctor bound his victim's soul to Minshina's severed skull instead of letting him pass into death. The skull lies within a circle of power on the southernmost isle, tethering Minshina to Zalazane's magic. Tormented by dreams of his brother calling to him, Master Gadrin seeks brave travelers to enter the occupied islands, reclaim the skull, and break Zalazane's hold over Minshina's spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_minshina-s-skull-52a0a8a36624cf90c980/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["item:mirror-lake-water-sample"] = {
  hash = "50f2e0",
  fullHash = "50f2e0",
  text = "Mirror Lake Water Sample. At Mirror Lake in Elwynn Forest, a flask of water is gathered for Jennea Cannon in Stormwind. The mages will test it for signs of altered arcane currents in local water. Jennea Cannon sends promising apprentices to collect water from Mirror Lake. The lake lies just southwest of the Stormwind Gate, and they fill a specially prepared flask at the base of its waterfall. The Wizard's Sanctum in Stormwind is concerned that the world's mystic channels remain unsettled after catastrophic conflicts. Its mages will examine the sample for stray magical taint in the waterways used by people nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mirror-lake-water-sample-1b8d25a533c6a68117ae/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["item:mist-veil-s-lockbox"] = {
  hash = "732895",
  fullHash = "732895",
  text = "Mist Veil's Lockbox. Off Darkshore, Mist Veil's Lockbox lies in the sunken night elven vessel. It holds the captain's log and personal effects, lost when coastal murlocs ambushed and sank the ship. The night elven vessel Mist Veil sank while sailing toward Auberdine. Coastal murlocs ambushed it alongside its sister ship, the Silver Dawning, and overwhelmed both vessels. The captain perished in the attack. Their logbook and personal belongings remain sealed in the lockbox in the flooded hold, surrounded by murlocs. Surviving sailors reached Auberdine, but the loss of their vessel and commander still grieves them. Gorbold Steelhand seeks Mist Veil's Lockbox so the captain's final effects can be honored and laid to rest. Recovering it from the flooded wreck may bring some solace to the survivors on the mainland.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mist-veil-s-lockbox-61ab9baf56018b303c7d/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["item:mo-grosh-crystal"] = {
  hash = "43bbe9",
  fullHash = "43bbe9",
  text = "Mo'grosh Crystal. In northeastern Loch Modan, Mo'grosh ogres mine and hoard rare crystals with unusual alchemical properties. The crystals help dwarven engineers neutralize Dark Iron explosives. The Mo'grosh ogres mine these crystals in their stronghold in northeastern Loch Modan. Though the ogres favor brute strength over delicate metallurgy, their clan prizes the stones. Common enforcers, mystic shamans, and towering leaders carry them. The crystals are uncommon, so the ogres guard them closely within the Mo'grosh Stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mo-grosh-crystal-c92d00e089cfb02d91d7/1-0000.mp3", duration = 32.8097959, start = 0},
  },
}
P.transport["item:modr-fragment"] = {
  hash = "7dba8a",
  fullHash = "7dba8a",
  text = "Modr Fragment. At Whelgar Excavation Site, Modr Fragment lies among the relics and loose earth of a raptor-overrun dig. The ancient Titan script on it is one of four missing pieces of the Goaz Stone. Prospector Whelgar uncovered the Goaz Stone, a massive tablet marked with ancient Titan writing, at his Wetlands dig. Vicious raptors drove the Explorers' League from the site before they could finish their work. The translated inscription broke off at four gaps, hiding warnings of a divine plan and a doomed prophecy. Modr Fragment is one of the missing pieces, left among the relics and overturned soil when the diggers fled for their lives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_modr-fragment-dd4f81ba9b9f31e5c361/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["item:moldy-tome"] = {
  hash = "b0c096",
  fullHash = "b0c096",
  text = "Moldy Tome. A half of the Tome of the Cabal lies ruined on the Hillsbrad coast. Salvaged from a shipwreck, the Moldy Tome holds dark rituals sought by warlocks who study demonic summoning. The Tome of the Cabal was a rare work of dark arts held in Lordaeron. At some point, it was vandalized and torn in two. One half, now called the Moldy Tome, traveled by ship south toward Menethil Harbor and Ironforge. The vessel never arrived. It sank in the dangerous waters west of Southshore, and the surviving half washed ashore south of Azurelode Mine. Damp and surf ruined its pages, while murlocs scavenged along the Hillsbrad coast.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moldy-tome-ee41405861b24f15943a/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["item:moonpetal-lily"] = {
  hash = "970cfc",
  fullHash = "970cfc",
  text = "Moonpetal Lily. Moonpetal Lilies are large, luminous flora native to Teldrassil that flourish around freshwater pools. Renowned for their potent restorative qualities, their petals are prized as key ingredients in natural remedies and healing draughts. Moonpetal Lilies grow exclusively along the moist banks of freshwater pools and ponds, particularly favored along the northwestern side of Aldrassil in Shadowglen. Like much of the plant life flourishing atop the newly grown World Tree, they absorb the unique essence of Teldrassil's sheltered groves. Their broad petals are gentle and radiant, easily spotted hugging the tranquil water's edge where natural moisture allows them to thrive. Night elf healers and herbalists value the Moonpetal Lily for its extraordinary healing properties. When combined with other forest flora, such as Hyacinth Mushrooms, the lily acts as a powerful soothing and stabilizing agent. This restorative quality makes it an essential component when brewing antidotes to counteract lethal toxins, notably the virulent venom produced by the Webwood spiders lurking within Shadowthread Cave.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonpetal-lily-7c0b4d32ca8a81e45275/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["item:moonstalker-fang"] = {
  hash = "dacd51",
  fullHash = "dacd51",
  text = "Moonstalker Fang. Near Auberdine, travelers gather Moonstalker Fangs for Wizbang Cranktoggle's sampling devices. The teeth come from the moonstalkers of Darkshore. Moonstalker Fangs come from saber cats that hunt along Darkshore’s forest fringes. Their long teeth can shear flesh and bone. Wizbang Cranktoggle, an eccentric gnome tinkerer, uses them in a different way. North of Auberdine, near the bridge, Buzzbox 323 crushes the durable fangs to dust for his ecological surveys.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonstalker-fang-c4f9131958914cb5cba9/1-0000.mp3", duration = 30.0408163, start = 0},
  },
}
P.transport["item:moonwell-water-tube"] = {
  hash = "0385d3",
  fullHash = "0385d3",
  text = "Moonwell Water Tube. At Auberdine, water from the moonwell carries purifying nature magic. The vial is used to test a mysterious red crystal set among Darkshore’s eastern ridges. Water from Auberdine’s moonwell fills the tube. The sacred pool is tied to Elune and holds restorative, purifying magic. Even a small amount can be used against corruption or to test strange mystical forces.",
  ["1"] = {
    {file = "Audio/Transport/full_item_moonwell-water-tube-02196634751a17343c03/1-0000.mp3", duration = 21.6293878, start = 0},
  },
}
P.transport["item:mossy-tumor"] = {
  hash = "ae480a",
  fullHash = "ae480a",
  text = "Mossy Tumor. Around Wellspring Lake, mossy tumors mark Teldrassil's spreading corruption. Carved from the bark and flesh of corrupted timberlings, these poisonous growths show the malevolence taking hold in the young World Tree. Teldrassil's timberlings were made to nurture and tend the great tree's boughs, but many have grown hostile and diseased. Mossy tumors are signs of that sickness made flesh. Thick with toxins, they spread across the Mire Beasts, Tramplers, and Elder Timberlings around Wellspring Lake. Rellian Greenspyre and the keepers in Darnassus send travelers to cut away the tumors and burn them thoroughly, so their poison cannot take deeper root in the island's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mossy-tumor-36a7df0968fc8493f4d7/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:mountain-lion-blood"] = {
  hash = "a49bbe",
  fullHash = "a49bbe",
  text = "Mountain Lion Blood. Across Hillsbrad and Alterac, Mountain Lion Blood draws Apothecary Lydon’s interest. In Tarren Mill, Lydon seeks fresh blood to make the Royal Apothecary Society’s dreaded Elixir of Pain. Mountain lions prowl the highlands and foothills of Hillsbrad and Alterac. Hunters prize their pelts and claws, while the Forsaken of the Royal Apothecary Society seek the blood in their veins. Apothecary Lydon in Tarren Mill believes fresh mountain lion blood can form the base of a potent brew meant to bring misery to the living. Apothecary Lydon’s experiments in Tarren Mill support the Royal Apothecary Society’s work to perfect the Forsaken’s New Plague. Lydon gathers blood from vigorous wild beasts to refine a concoction called the Elixir of Pain, testing how local organic compounds can be turned against the enemies of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mountain-lion-blood-f96ce7269e145933cb5e/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["item:mudsnout-blossom"] = {
  hash = "c05386",
  fullHash = "c05386",
  text = "Mudsnout Blossom. Mudsnout Blossoms grow in Nethander Stead, south of Tarren Mill. Mudsnout gnolls guard the foul, toxic mushrooms, and Apothecary Lydon seeks them for his elixir research. South of Tarren Mill, Mudsnout Blossoms grow in Nethander Stead. Despite their name, they are large, foul-smelling mushrooms that flourish in soiled dirt among the local Mudsnout gnolls' camps. The gnolls defend the territory fiercely. The mushrooms' spores and flesh poison living things, causing agony and rapid bodily decay.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-blossom-5efee5321f6301065d59/1-0000.mp3", duration = 32.1828571, start = 0},
  },
}
P.transport["item:mudsnout-composite"] = {
  hash = "696f4d",
  fullHash = "696f4d",
  text = "Mudsnout Composite. At Tarren Mill, Mudsnout Composite is prepared for the Royal Apothecary Society's research into a new plague. Apothecary Lydon makes it from Mudsnout Blossoms gathered in the Hillsbrad Foothills and sends it to the Undercity. Apothecary Lydon makes Mudsnout Composite from Mudsnout Blossoms gathered in the Hillsbrad Foothills. The paste is noxious on its own, but Master Apothecary Faranell must bind it with a colloid of decay to bring out its deadlier qualities. Together, the ingredients form a key chemical component in the Dark Lady's Elixir of Agony.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-composite-772991af353624b3b518/1-0000.mp3", duration = 32.2612245, start = 0},
  },
}
P.transport["item:mudsnout-mixture"] = {
  hash = "0cb34e",
  fullHash = "0cb34e",
  text = "Mudsnout Mixture. In the Undercity, Master Apothecary Faranell prepares a base for a deadly Forsaken poison. Mudsnout Mixture begins with mushrooms sent north from Tarren Mill. Apothecary Lydon in Tarren Mill seeks to craft a virulent new biological weapon. He sends a composite made from Mudsnout Blossoms north to the Undercity. The toxic mushrooms grow at Nethander Stead, held by gnolls. Master Apothecary Faranell sees promise in the composite and adds his own colloid of decay. The resulting Mudsnout Mixture is volatile. It steadies the mushroom compound and prepares its virulent properties for further catalytic refinement in the foothills.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mudsnout-mixture-95fc91bd8f3061cf5422/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["item:murloc-head"] = {
  hash = "f744a8",
  fullHash = "f744a8",
  text = "Murloc Head. Along the Western Strand, Murloc Head is grim proof of a threat Southshore wants brought under control. Lieutenant Farren Orinelle collects the severed heads for Marshal Redpath, who requires evidence of the murlocs being culled. Southshore's fishermen and coastal travelers face an immediate threat from aggressive murlocs along the Western Strand. Alliance fighters often clear the beaches, but Marshal Marcus Redpath wants proof before he approves reports of the threat being reduced. Lieutenant Farren Orinelle hires fighters to bring him murloc heads. Farren finds the work repulsive, and the sight has spoiled his appetite for Southshore's seafood.",
  ["1"] = {
    {file = "Audio/Transport/full_item_murloc-head-adb718dc01691858191a/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["item:musquash-root"] = {
  hash = "0e0648",
  fullHash = "0e0648",
  text = "Musquash Root. Beneath the Stonewrought Dam, Musquash Root grows in the Wetlands. The rare root is hard to gather, and a hidden coven beneath Stormwind needs it for a brew. Musquash Root grows in the damp ground beneath the Stonewrought Dam's falls. The mist and secluded setting make it hard to gather. Few herbalists seek it, but practitioners of the darker arts prize its chemical and alchemical properties.",
  ["1"] = {
    {file = "Audio/Transport/full_item_musquash-root-edd7f6ec612a61423bc3/1-0000.mp3", duration = 25.1559184, start = 0},
  },
}
P.transport["item:mysterious-fossil"] = {
  hash = "04f865",
  fullHash = "04f865",
  text = "Mysterious Fossil. Along Darkshore's coast, Prospector Remtravel uncovers the Mysterious Fossil. The Explorers' League sends it across the sea for study. Prospector Remtravel uncovers an unusual fossil while working along Darkshore's wild coast. He arranges for dwarven scholars to receive it instead of leaving it in the wilderness. In Darnassus, Chief Archaeologist Greywhisker sees an extraordinary find among the stones of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_mysterious-fossil-45ab5e2d5e5a59d3330c/1-0000.mp3", duration = 25.5477551, start = 0},
  },
}
P.transport["item:nak-s-skull"] = {
  hash = "369533",
  fullHash = "369533",
  text = "Nak's Skull. In the southern Barrens, Nak leads Razormane warbands against the Horde. His skull proves his defeat and gives Mangletooth a means to avenge betrayal by his former kin. Nak, Kuz, and Lok Orcbane lead raids from Razorfen Kraul across the Barrens. Their warbands strike Horde settlements and roads, while defenders at the Crossroads do not know the three commanders are planning attacks beyond ordinary tribal skirmishing. At Camp Taurajo, the captive Razormane Mangletooth has been left to die in a cage by his own people. He now seeks revenge against those former brethren. Mangletooth demands proof that Nak and his companions are dead: their severed skulls, delivered by Horde adventurers. He means to use that proof to break the southern raiding parties.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nak-s-skull-ad2313666f566cd7e284/1-0000.mp3", duration = 44.7477551, start = 0},
  },
}
P.transport["item:nek-rosh-s-head"] = {
  hash = "88e537",
  fullHash = "88e537",
  text = "Nek'rosh's Head. In the Wetlands, Nek'rosh's Head proves the Dragonmaw chieftain has fallen. Captain Stoutfist receives it as proof that the threat to Menethil Harbor has been broken. The Dragonmaw clan gathers forces and siege weapons across the marshlands, threatening the Alliance port of Menethil Harbor. After the clan's catapults are burned, the port's defense depends on killing Chieftain Nek'rosh. His severed head gives Captain Stoutfist and the Ironforge authorities proof that the warlord's hold over the Wetlands is broken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nek-rosh-s-head-0bd4056ac9ae61e6488f/1-0000.mp3", duration = 29.2832653, start = 0},
  },
}
P.transport["item:neru-fragment"] = {
  hash = "52986c",
  fullHash = "52986c",
  text = "Neru Fragment. Unearthed from disturbed earth, the Neru Fragment carries part of the Goaz Stone's ancient Titan script. The relic was discovered at Whelgar's Excavation in the Wetlands, and its words tell of Azeroth's primeval history. Prospector Whelgar led the dwarven expedition that discovered the Goaz Stone. The relic broke into four pieces: Ados, Modr, Golm, and Neru. Raptors overran the dig, halting the work, and the Neru Fragment remained beneath loose soil among the aggressive beasts. Once recovered, it can join the other pieces and restore the tablet. Its surviving words speak of a divine plan and a doomed prophecy, giving dwarven scholars a record to decipher.",
  ["1"] = {
    {file = "Audio/Transport/full_item_neru-fragment-d492476929c6410efa7a/1-0000.mp3", duration = 41.3779592, start = 0},
  },
}
P.transport["item:nessa-s-collection"] = {
  hash = "79a4eb",
  fullHash = "79a4eb",
  text = "Nessa's Collection. At Rut'theran Village, fish bones and scales gathered from nearby waters are prepared for study by Laird in Auberdine. Nessa's Collection shows the great size of aquatic life around Teldrassil's roots. Nessa Shadowsong lives in Rut'theran Village at Teldrassil's base, where she gathered fish bones and scales to compare island sea life with that of mainland Kalimdor. Catches from the waters around the Great Tree grow to striking size. Nessa sent physical proof across the sea to Laird, a fish merchant along Auberdine's docks. The parcel travels through Vesprystus, Rut'theran's hippogryph master, and offers practical evidence of Teldrassil's growing vitality. In Darkshore, Laird finds that the specimens far outsize their mainland counterparts. The collection holds jawbones nearly twice the size of those from fish native to the Darkshore coast, and scales as large as a clenched fist. For coastal night elves, the package offers a clear look at how greatly the waters around Teldrassil differ from northern Kalimdor's somber shores.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nessa-s-collection-905a47418374b6c5da5f/1-0000.mp3", duration = 61.5183673, start = 0},
  },
}
P.transport["item:nether-gem"] = {
  hash = "284440",
  fullHash = "284440",
  text = "Nether Gem. Across Tirisfal Glades, the Nether Gem carries Gunther Arcanus’s image to Bethor Iceshard in the Undercity. Gunther entrusts it to an emissary after his lost spellbook is returned, opening a path to the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nether-gem-cbbfd21d6162382d4fe4/1-0000.mp3", duration = 12.4342857, start = 0},
  },
}
P.transport["item:ng-5"] = {
  hash = "33dd61",
  fullHash = "33dd61",
  text = "NG-5. In the Stonetalon Mountains, Gaxim Rustfizzle needs NG-5 for his explosive plans. The volatile chemical is Nitromirglyceronium, the ignition compound he needs to set off wagons loaded with dynamite as a distraction. Gaxim Rustfizzle, a gnome operative in the Stonetalon Mountains, needs NG-5 for his engineering plans. The compound is formally known as Nitromirglyceronium, a hazardous chemical solution that demands care—or reckless gnomish enthusiasm. Gaxim says it provides the reaction needed to detonate entire wagons loaded with dynamite, creating a massive explosion to distract his adversaries in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ng-5-a62c92bab083c63726b7/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["item:nida-s-necklace"] = {
  hash = "668962",
  fullHash = "668962",
  text = "Hilary's Necklace. In Lakeshire, Hilary searches for the necklace she lost in Lake Everstill. Her father gave it to her when she was young, and it slipped beneath the water while she and the other children fished by the docks. Hilary lost her necklace while fishing with her friend Shawn along the Lakeshire shore. Her father had given it to her, and she treasures the gift. Fierce beasts and aggressive murlocs live in the lake's depths, so local children stay on the docks. The necklace remains beneath the water, buried in the lakebed silt.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nida-s-necklace-c783aa696201591d9803/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["item:nightmare-shard"] = {
  hash = "e0a4c4",
  fullHash = "e0a4c4",
  text = "Nightmare Shard. In the Wailing Caverns, a glowing shard bears a taint Falla Sagewind cannot ignore. She binds its pure, disturbed essence of the Emerald Dream into the Nightmare Shard and sends it to senior druids for a warning kept from others. Deep in the Wailing Caverns, Falla Sagewind examines a mysterious glowing shard and finds its energy darker than she expected. It reflects an unnatural affliction in the Emerald Dream, like a waking nightmare. Falla binds this tainted essence into the Nightmare Shard and orders it carried without delay to elder leaders of the Cenarion Circle.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nightmare-shard-24167a8e4b3dae493c70/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["item:nightsaber-fang"] = {
  hash = "78fd6d",
  fullHash = "78fd6d",
  text = "Nightsaber Fang. In Teldrassil, hunters take fangs from the nightsabers prowling the forest. Woodland residents also seek these teeth as reagents. Nightsabers hunt beneath Teldrassil’s canopy, among the deadliest natural predators of northern Kalimdor. Night elves revere them for their agility, ferocity, and deep spiritual bond with Elune. A hunter who kills one can take its sharp fangs as proof of skill. Some figures in the forest seek those fangs for darker rites.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nightsaber-fang-5026e9f49d1ce5c11012/1-0000.mp3", duration = 29.0742857, start = 0},
  },
}
P.transport["item:nissa-s-remains"] = {
  hash = "7dc51f",
  fullHash = "7dc51f",
  text = "Nissa's Remains. Nissa's remains belong to a noblewoman of the once-wealthy Agamand dynasty in northern Tirisfal Glades. Slain and made mindless servants of the Scourge during the Third War, Nissa and her family are now hunted by former laborers seeking vengeance. Before the Third War, the Agamands were Tirisfal Glades' wealthiest and most influential dynasty. Their prosperous mills stood across the northern hills. When the Plague of Undeath spread through Lordaeron, the family patriarchs refused to flee. They fortified their estates and persuaded their retainers and laborers to stay and fight. Their pride cost them their lives. The Scourge slew the Agamands, then raised them as mindless thralls bound to the Lich King's will. In Brill, survivors who later broke free under Queen Sylvanas Windrunner still remember the Agamands' fatal pride. Coleman Farthing, once a laborer in their mills, resents his former masters for luring the workers into undeath. He charges adventurers with putting down the risen Agamands and retrieving their physical remains, including Nissa's. For Farthing and other Forsaken, destroying these relics offers a grim sense of closure and revenge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nissa-s-remains-460890b7e531c14aab31/1-0000.mp3", duration = 70.0865306, start = 0},
  },
}
P.transport["item:nitroglycerin"] = {
  hash = "45611d",
  fullHash = "45611d",
  text = "Nitroglycerin. At Bael Modan, Nitroglycerin helps the dwarves drive their excavation through tauren lands. Their soldiers and officers carry the volatile chemical, which can also be used against the fortress. Bael Modan's dwarves dig into the ancestral lands of the Stonespire tauren with heavy drillers and volatile chemicals. At the excavation site and its fortified keep, they keep nitroglycerin close to blast deep holes and break apart hills. Soldiers and officers, including Lord Cyrik Blackforge, carry vials of the fluid as the digging continues.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nitroglycerin-76dead01b6581c292ed9/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["item:nondescript-letter"] = {
  hash = "4c3617",
  fullHash = "4c3617",
  text = "Nondescript Letter. Calvin Montague sends a Nondescript Letter east from Deathknell to Innkeeper Renee in Brill. He gives it to newly awakened Forsaken as an excuse to leave the valley and reach the Gallows' End Tavern. Calvin Montague asks newly arisen Forsaken near Deathknell to carry an unmarked envelope east to Brill. He claims he is tired from fighting zombies and spiders, and says the letter is for an innkeeper named Renee. His promise of rich compensation sounds hollow, and the errand takes travelers out of the valley toward the Gallows' End Tavern.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nondescript-letter-874adb1e1c13ea08078f/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["item:nori-s-mug"] = {
  hash = "055ac0",
  fullHash = "055ac0",
  text = "Nori's Mug. In Dun Morogh, Nori Pridedrift sends his mug out with a warm drink. Travelers carry scalding mornbrew to Durnan Furcutter in Anvilmar, then bring the empty mug back to its owner. Nori Pridedrift lends his mug for a delivery through Dun Morogh's freezing passes. The mug carries hot mornbrew to Durnan Furcutter in Anvilmar, where the drink offers comfort against the bitter cold. Once Durnan has drained it, the mug makes the return trip to Nori. He reminds travelers that mugs do not grow on trees, and expects his sturdy drinking vessel back.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nori-s-mug-c5afb9ed9415677177ce/1-0000.mp3", duration = 32.2612245, start = 0},
  },
}
P.transport["item:notched-rib"] = {
  hash = "77598b",
  fullHash = "77598b",
  text = "Notched Rib. At Agamand Mills, Notched Ribs prove the Forsaken are breaking the Scourge's hold on Tirisfal. Across northern Tirisfal Glades, the Scourge gathers skeletons in ruined armor. Cracked Skull Soldiers and Rattlecage Soldiers attack any living being or creature with free will they meet. Blades leave their brittle bones pitted and scored. Deathguards demand proof that Forsaken scouts and volunteers are killing these mindless intruders. A battle-marked rib shows that another of the Lich King's thralls has been shattered. Northwest of Brill, the Agamand Mills hold a key position. If the Scourge settles among the ruined farmsteads and windmills, the undead gain a base from which to strike deep into Tirisfal. Deathguard Dillinger watches the northern roads and sends champions to break up the skeleton ranks before they can gather strength. The notched ribs brought back to Brill show that the Forsaken line holds as it wears down the Scourge vanguard bone by bone.",
  ["1"] = {
    {file = "Audio/Transport/full_item_notched-rib-24b0114c78a9e6b3f89b/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["item:nugget-slug"] = {
  hash = "1134be",
  fullHash = "1134be",
  text = "Nugget Slug. Nugget slugs are specialized 17.5-gauge mechanical fasteners used in industrial engineering. Stockpiled in tool buckets by the Venture Company at the Sludge Fen, they are coveted by tinkerers attempting to repair volatile machinery. Nugget slugs are heavy-duty metallic fasteners manufactured for demanding industrial assemblies. Specifically sized at 17.5 gauge, these components are an essential part of the heavy equipment deployed across Venture Company extraction sites. While useless as ordinary trade goods, they are indispensable to tinkerers dealing with customized goblin hardware.",
  ["1"] = {
    {file = "Audio/Transport/full_item_nugget-slug-d4eee09e9cc501ed8616/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["item:ogre-s-monocle"] = {
  hash = "cbfc4c",
  fullHash = "cbfc4c",
  text = "Ogre's Monocle. In southern Duskwood, Zzarc'Vul wears an immense monocle. Its lens has the exact dimensions Viktori Prism'Antras needs for a stargazing telescope in Darkshire. Zzarc'Vul, an ogre, wears a huge monocle tailored to his massive stature. When Viktori Prism'Antras of Darkshire began building a stargazing instrument from blueprints by the gnome engineer Cog, ordinary lenses proved too small. Zzarc'Vul's eyewear is the only polished glass in the region with the size and curve needed to focus light through the finished telescope. The Vul'Gol Ogre Mound lies in the shadow of southern Duskwood, where Zzarc'Vul lives among his brute brethren. The brute shows little wish to give up his distinctive accessory. To claim the lens, you must defeat him on his own ground, then carry the glass back to Darkshire so Viktori can turn his gaze to the night skies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ogre-s-monocle-c39bdc7a055162877039/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["item:okra"] = {
  hash = "e426bd",
  fullHash = "e426bd",
  text = "Okra. In Westfall, Okra grows in the plots at Saldean's Farm. Homesteaders prize the crop, and it thickens the stews that feed them. Saldean's Farm still yields vegetables while much of Westfall lies fallow under threat from Defias outlaws and rogue harvest golem attacks. Okra grows in the tilled plots around the farm. The crop persists through the harsh conditions, nourishing local homesteaders when trade and supplies from Stormwind run dry. Salma Saldean's famous Westfall Stew depends on okra. She combines sliced pods with whatever meat settlers can hunt across the dusty plains, including vulture flesh, goretusk snouts, and coastal murloc eyes. The pods break down in the heat, thickening thin broth into a filling, restorative meal. For settlers clinging to their homesteads, fresh okra turns sparse scavenging into a hot supper.",
  ["1"] = {
    {file = "Audio/Transport/full_item_okra-ee8e8b4bd4285a3d8bc9/1-0000.mp3", duration = 51.4612245, start = 0},
  },
}
P.transport["item:ordanus-head"] = {
  hash = "1757b3",
  fullHash = "1757b3",
  text = "Ordanus' Head. At Raynewood Retreat, Ordanus' Head is claimed as proof that Keeper Ordanus has fallen. Blood elf magi Braelyn Firehand seeks it in Ashenvale. Keeper Ordanus was an ancient keeper of the grove and one of Cenarius's elder sons. Braelyn Firehand climbed the heights of Stonetalon Mountains on her master's orders, seeking to end the druids' stifling of magic at the peak and take vengeance on Ordanus. Before she could strike, the keeper was spirited away to the heart of Ashenvale. Braelyn used arcane scrying to peer through the forest canopy and found his sanctuary in the boughs of Raynewood Retreat. She demanded his severed head as proof that the wild demigod's arrogance had been answered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ordanus-head-8c031a6873d3ffe9aa36/1-0000.mp3", duration = 40.96, start = 0},
  },
}
P.transport["item:orendil-s-cure"] = {
  hash = "82bc7b",
  fullHash = "82bc7b",
  text = "Orendil's Cure. In northern Ashenvale, Orendil Broadleaf brews a draught for a child in Astranaar. He uses rare Bathran's Hair to treat Relara Whitemoon's mysterious, deathly sickness. Relara Whitemoon, still young, fell deathly ill in Astranaar, and ordinary remedies failed. Her father, Pelturas Whitemoon, sought help from Orendil Broadleaf, a hermit and master of natural medicine who lives in northern Ashenvale. Orendil used bundles of rare Bathran's Hair gathered from the haunted ruins of Bathran's Haunt to brew a draught for Relara. When the vial arrives, it gives Pelturas hope. Yet the cure only slows the disease, so he must seek the further remedies Orendil suggested.",
  ["1"] = {
    {file = "Audio/Transport/full_item_orendil-s-cure-329588d497b6d007593f/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["item:oslow-s-toolbox"] = {
  hash = "5feed4",
  fullHash = "5feed4",
  text = "Oslow's Toolbox. Foreman Oslow needs tools for Lakeshire's defenses, but they lie beneath Lake Everstill. Sent from Goldshire, the chest went down when Blackrock orcs struck its boat with a catapult. Foreman Oslow needs construction tools to keep Lakeshire's defenses and buildings in repair. Blackrock orcs besiege the Redridge Mountains, and the bridge into town lies destroyed. The tools came from Goldshire, so the shipment crossed Lake Everstill in a rowboat. Blackrock forces struck the vessel with a catapult, sending the boat and Oslow's heavy chest into the depths among the murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_oslow-s-toolbox-b6a9d54baaf2d220ff53/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["item:osric-s-crate"] = {
  hash = "5f9544",
  fullHash = "5f9544",
  text = "Osric's Crate. At Sentinel Hill, Osric's Crate brings armor from Stormwind to the People's Militia. The defenders face the Defias Brotherhood and marauding gnolls without the Stormwind army. Westfall faces the Defias Brotherhood and marauding gnolls, while the Stormwind army remains absent. At Sentinel Hill, the People's Militia must make do without the crown's formal support. Osric's Crate holds freshly made armor from the capital, sent to Quartermaster Lewis to distribute among the volunteer fighters. Gryphons carry the crate from Dungar Longdrink's roost in Stormwind's Trade District to Thor at Sentinel Hill. The flight avoids the dangerous roads through Elwynn Forest and across the Westfall border, where bandits may ambush travelers. Gryphons help keep frontier garrisons supplied during wartime.",
  ["1"] = {
    {file = "Audio/Transport/full_item_osric-s-crate-3461044a5798a1fb27a3/1-0000.mp3", duration = 46.1061224, start = 0},
  },
}
P.transport["item:package-of-empty-ooze-containers"] = {
  hash = "0a1ac2",
  fullHash = "0a1ac2",
  text = "Package of Empty Ooze Containers. In Ironforge, Package of Empty Ooze Containers is ready for dangerous field sampling in Felwood. Laris Geardawdle supplies jars built to hold tainted and cursed ooze without dissolving. Laris Geardawdle sends a dozen empty jars with travelers bound for Felwood. Six are meant for cursed ooze and six for tainted ooze. Raw specimens are caustic, and ordinary luggage can be digested by them. Sturdy, sealed glass keeps the acidic residue contained on the journey across continents to Laris's workbench in Ironforge. Laris Geardawdle's interest in ooze reaches beyond eccentric hobby. He has noticed Forsaken researchers from the Royal Apothecary Society harvesting these strange organisms across Azeroth, and wonders what they know. He suspects slimes may be primordial secretions tied to the world's creation. Field agents use his jars to gather evidence, which he hopes will win him acclaim within the Explorers' League.",
  ["1"] = {
    {file = "Audio/Transport/full_item_package-of-empty-ooze-containers-f5d3bdcd86bbcffd1f43/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["item:painted-gnoll-armband"] = {
  hash = "36e8a7",
  fullHash = "36e8a7",
  text = "Painted Gnoll Armband. At Westbrook Garrison, Painted Gnoll Armbands prove that Riverpaw gnolls have been slain. The marked bands come from packs pressing against Elwynn Forest's western border. Riverpaw warriors and scavengers wear rough armbands painted with crude tribal patterns. The bands come from gnolls along Elwynn Forest's wilderness borders. For Stormwind's defenders, the packs pose a growing threat near Stone Cairn Lake and in the woods south of Westbrook Garrison. Stormwind's Army is stretched thin across the kingdom, leaving Westbrook Garrison hard pressed to secure the western border. Deputy Rainer offers a standing bounty for slaying Riverpaw outrunners and runts. Their painted armbands prove the kills, helping the deputies count the bounties and thin the packs near nearby farmlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_painted-gnoll-armband-c3096f8a5126372a5c6f/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["item:panther-cage-key"] = {
  hash = "6268e0",
  fullHash = "6268e0",
  text = "Panther Cage Key. The Panther Cage Key is a small metal key held by Wizlo Bearingshiner at Whitereach Post. It unlocks a reinforced cage holding an enraged, captive predator within the wreckage of an ambushed caravan in Thousand Needles. When a traveling caravan was attacked and ransacked by centaur raiders north of Whitereach Post, the goblin tinker Wizlo Bearingshiner barely escaped with his life. Amid the ruins of wagons and plundered cargo, the marauders left one thing entirely untouched: a sturdy cage housing a ferocious, rare panther. Around the predator's neck hung Wizlo's prized invention, a hypercapacitor gizmo. Unwilling to approach the snarling beast, the centaur gave the cage a wide berth, leaving Wizlo's key as the only way to open the door and retrieve the device.",
  ["1"] = {
    {file = "Audio/Transport/full_item_panther-cage-key-3bba72f4c7455e7013e0/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["item:parker-s-lunch"] = {
  hash = "f80a6e",
  fullHash = "f80a6e",
  text = "Parker's Lunch. Darcy packs Parker's Lunch in Lakeshire for Guard Parker's patrol. The meal offers a glimpse of the bonds and modest comforts among Redridge's defenders. Darcy, a waitress at the Lakeshire inn, packs a meal for Guard Parker. He patrols the exposed road south toward Duskwood while Redridge faces attacks from gnolls and Blackrock orcs. The garrison is stretched thin and cut off from Stormwind's aid, leaving guards to keep long, lonely watches. Darcy's small gesture keeps Parker fed and begins a bashful courtship between the two townspeople.",
  ["1"] = {
    {file = "Audio/Transport/full_item_parker-s-lunch-46d4e0db0fbbf156be3e/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["item:partially-filled-vessel"] = {
  hash = "dc2731",
  fullHash = "dc2731",
  text = "Partially Filled Vessel. Tenaron Stormgrip gives young night elf initiates the Partially Filled Vessel in Aldrassil. It carries blessed moonwell water from Shadowglen toward Dolanaar. Young kaldorei initiates gather blessed water from Shadowglen’s secluded moonwell. In Aldrassil, Tenaron Stormgrip pours a sample into the vessel for its journey across Teldrassil. More water from the tree’s moonwells must be gathered to tend to the island’s health. Carry the vessel south through the valley gates, then follow the cobblestone roads west to Dolanaar. The journey takes a young adventurer beyond Shadowglen’s protected nursery and into Teldrassil’s wider wilds. At Dolanaar’s central moonwell, Corithras Moonrage takes the vessel and directs the next part of the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_item_partially-filled-vessel-6c21712d5d483e53d117/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["item:pendant-of-shadow"] = {
  hash = "6be797",
  fullHash = "6be797",
  text = "Pendant of Shadow. At the Tower of Ilgalar, Morganth carries the Pendant of Shadow as he pursues the Scythe of Elune. Theocritus wants the talisman brought to the Tower of Azora as proof Morganth has been slain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pendant-of-shadow-a852169912c74a45145d/1-0000.mp3", duration = 9.95265306, start = 0},
  },
}
P.transport["item:pendant-of-the-sea-lion"] = {
  hash = "0e06c3",
  fullHash = "0e06c3",
  text = "Pendant of the Sea Lion. At the Shrine of Remulos, druids join the Pendant of the Sea Lion's two halves. The completed talisman marks an initiate's readiness to learn an aquatic form. A druid must master the water's dangers to claim the sea lion's aquatic aspect. The pendant has two halves, one embodying the agility to slip past aquatic predators, the other the endurance to withstand prolonged submersion. At the Shrine of Remulos in Moonglade, the pieces are joined into one. After the pendant is forged, an initiate brings it to an elder mentor. Turak Runetotem waits on the rises of Thunder Bluff, while Mathrengyl Bearwalker is in Darnassus. The talisman proves the initiate has completed trials under Dendrite Starblaze, allowing the elder to teach the secrets of taking an aquatic form.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pendant-of-the-sea-lion-fd04cda19b61546eb1d2/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["item:perenolde-tiara"] = {
  hash = "667edb",
  fullHash = "667edb",
  text = "Perenolde Tiara. In the ruins of Alterac, an emerald-studded heirloom of the Perenolde family has turned up again. Dwarven craftsmen of Ironforge made it, and collectors in Stormwind now seek it. The Perenolde family ruled Alterac before the kingdom fell during the Second War. Their treasures included a delicate tiara, made by master jewelers in Ironforge and set with brilliant emeralds. After King Aiden Perenolde’s treachery brought Alterac to ruin, the tiara vanished amid the devastation of the high crags. Grel'borg the Miser, an ogre mage, unearthed the tiara while searching Alterac’s ruins for abandoned wealth. Word of the surviving relic reached Count Remington Ridgewell, a wealthy noble in Stormwind who collects famous relics for his family museum. Now the count seeks to take the tiara from the ogre.",
  ["1"] = {
    {file = "Audio/Transport/full_item_perenolde-tiara-49dabacced623e2a5b73/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["item:phial-of-scrying"] = {
  hash = "b7ad2e",
  fullHash = "b7ad2e",
  text = "Phial of Scrying. In Darkshore, scouts use the Phial of Scrying to reach Onu from afar. The ancient of lore provides the enchanted vessel, which calls forth a bowl for scrying across corrupted woodlands. The Phial of Scrying carries mystical waters that form a temporary bowl on the ground. Scouts investigating deep within Darkshore use it for long-distance divination. From perilous places such as the Master's Glaive, they can speak directly with Onu instead of returning to his grove.",
  ["1"] = {
    {file = "Audio/Transport/full_item_phial-of-scrying-a9a97e093738815b6c3a/1-0000.mp3", duration = 26.357551, start = 0},
  },
}
P.transport["item:piece-of-krom-zar-s-banner"] = {
  hash = "eaef82",
  fullHash = "eaef82",
  text = "Piece of Krom'zar's Banner. At Regthar Deathgate's bunker west of the Crossroads, a torn banner marks the broken assault. Warlord Krom'zar led the Kolkar retaliatory force from Desolace. Warlord Krom'zar led a warband east from Desolace to strike back. Kolkar chieftains across the Barrens had fallen, and the furious centaurs attacked the defensive bunkers west of the Crossroads. A strip cut from Krom'zar's fallen standard gives Regthar Deathgate proof that the assault was crushed and the southern trade routes were preserved for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_piece-of-krom-zar-s-banner-1b1f159eacba0d1174a7/1-0000.mp3", duration = 30.0146939, start = 0},
  },
}
P.transport["item:plainstrider-beak"] = {
  hash = "d3f9d5",
  fullHash = "d3f9d5",
  text = "Plainstrider Beak. Across the Barrens, hunters bring Plainstrider Beaks back to the Crossroads. Huntmasters use them as proof that birds threatening local provisions have been culled. Plainstriders forage around the Crossroads and threaten its supplies. Greater, fleeting, and ornery plainstriders roam the surrounding savannah. Sergra Darkthorn asks arriving hunters to bring back their beaks as proof that the flocks have been culled away from supply lines and storehouses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-beak-89c790989c25b1d1bb16/1-0000.mp3", duration = 24.9208163, start = 0},
  },
}
P.transport["item:plainstrider-feather"] = {
  hash = "2e2c87",
  fullHash = "2e2c87",
  text = "Plainstrider Feather. On Red Cloud Mesa, young hunters gather Plainstrider Feather from the birds roaming Mulgore’s plains. Camp Narache uses them for clothing and tribal adornments, honoring the creatures that provide for the village. Young tauren on Red Cloud Mesa learn to track and hunt for what the tribe needs. Plainstriders roam the grassy plateau, providing food and useful feathers. Camp Narache makes garments and gear from their plumage. Young hunters bring feathers and fresh meat to Grull Hawkwind to meet the camp’s needs. The offering is their first test before Chief Hawkwind recognizes them and welcomes them in Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-feather-cdf28665463e991d7367/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["item:plainstrider-kidney"] = {
  hash = "c8ebc5",
  fullHash = "c8ebc5",
  text = "Plainstrider Kidney. Across the Barrens, hunters harvest Plainstrider Kidney for Kalimdor's unusual brewing traditions. The organ is unappetizing to most travelers, yet essential to an exotic brew. The vast, arid plains of the Barrens are home to tall, flightless plainstriders. Hunters often take their feathers and meat for tools and simple rations, while Brewmaster Drohn in Ratchet seeks their internal organs for another purpose. Drohn says plainstrider kidneys are needed to recreate Chen Stormstout's legendary potent ale. He claims the kidneys give the brew a unique kick, in a tradition passed down through an unconventional line of brewmasters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-kidney-c8f2ee2384f5a802e629/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:plainstrider-meat"] = {
  hash = "c96a9b",
  fullHash = "c96a9b",
  text = "Plainstrider Meat. Across Red Cloud Mesa, Plainstrider Meat helps feed Camp Narache. Young tauren hunt the birds for food and feathers, proving their skill and self-reliance. Camp Narache on Red Cloud Mesa depends on game from the surrounding grasslands. Plainstrider meat helps feed the village when food stocks run low. The birds also provide feathers for clothing and ceremonial adornments. Tauren life depends on the land, and survival means taking what is needed while respecting nature. Grull Hawkwind sends young hunters across Red Cloud Mesa to track the swift plainstriders. They gather meat and feathers to prove their tracking skill and self-reliance. Then they appear before Grull's father, Chief Hawkwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-meat-ae8e091dbfb9591f9fa0/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["item:plainstrider-scale"] = {
  hash = "99adb5",
  fullHash = "99adb5",
  text = "Plainstrider Scale. Across Mulgore, Plainstrider Scale is sought for a remedy Maur Raincaller prepares in Bloodhoof Village. The tough scale helps counter a spreading infection. Plainstriders roam Mulgore with tough scales covering their powerful legs. The scales protect them, though only some are firm enough to grind for folk remedies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-scale-f6d153a3c6bf5885df3d/1-0000.mp3", duration = 19.1477551, start = 0},
  },
}
P.transport["item:plainstrider-talon"] = {
  hash = "170589",
  fullHash = "170589",
  text = "Plainstrider Talon. Across Mulgore, tauren shamans gather Plainstrider Talon for cleansing totems. The sharp claws come from large, flightless plainstriders native to the region, and help cleanse corrupted water. Large, flightless plainstriders roam Mulgore’s open grasses, using powerful legs and sharp claws to forage through tough prairie earth and defend against predators. To the tauren of Bloodhoof Village, every part of a hunted beast carries spiritual resonance. When goblin ventures tainted sacred sources such as the Winterhoof Water Well, shaman Mull Thunderhorn sought plainstrider talons alongside prairie wolf paws. In tauren ritual crafting, reagents from native predators and foragers channel the land’s spiritual essence into totems that can purge unnatural poisons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_plainstrider-talon-6cbba0749f3617dd2065/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:podrig-s-order"] = {
  hash = "22f5ab",
  fullHash = "22f5ab",
  text = "Podrig's Order. At the Sepulcher, Podrig's Order calls for fresh weapons from the Undercity. Deathguard Podrig found the Sepulcher's stores mostly adequate after an inventory ordered by Executor Hadrec. Replacement weapons were running desperately low. His dispatch lists the blades and arms needed by the Deathguards holding the outpost in Silverpine Forest, a frontier threatened by the Scourge, feral beasts, and other dangers. The order goes to Gordon Wendham, a weapon dealer in the Undercity's Trade Quarter, because the damp crypts of Silverpine make forging weapons difficult. Couriers carry the document to bat master Karos Razok, using Forsaken flight paths to speed the shipment from the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_item_podrig-s-order-d084c3ee6819e5387df6/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["item:pork-belly-pie"] = {
  hash = "810bc7",
  fullHash = "810bc7",
  text = "Pork Belly Pie. In Elwynn Forest, Billy Maclure wants a pie from the Stonefield farm before he speaks about a missing necklace. Auntie Bernice Stonefield bakes it despite the feud between their families. The Stonefield and Maclure families have quarreled over land and pride for years in Elwynn Forest. Young Billy Maclure has a weakness for Auntie Bernice's pork belly pie. When a valuable Stonefield family necklace goes missing, Billy refuses to share what he knows until an adventurer brings him a warm slice. Bernice bakes the pie reluctantly, wishing the greedy boy would choke on it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pork-belly-pie-3a252cf38e0e85b6534d/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["item:powdered-azurite"] = {
  hash = "2c4cf5",
  fullHash = "2c4cf5",
  text = "Powdered Azurite. In Hillsbrad Foothills, Powdered Azurite is taken from the Azurelode Mine. Thun'grim Firegaze needs it to forge brutal armor for rising Horde warriors. Powdered Azurite comes from the mineral veins beneath Hillsbrad Foothills. Human workers dig the blue stone from Azurelode Mine, then grind and pack it for trade and metalworking. A skilled smith mixes the dust with dense metals to make armor more durable and resilient. Horde blacksmiths prize Powdered Azurite for its strength in metalworking, though it comes from human-held tunnels across the Great Sea. Thun'grim Firegaze, an aging orc armorer in the Barrens, asks for small amounts alongside refined iron and fiery reagents. Mixed into the smelt, the powder helps him hammer out the heavy plating of his Brutal Armor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_powdered-azurite-796c1f6856843c14c40f/1-0000.mp3", duration = 46.1061224, start = 0},
  },
}
P.transport["item:powers-of-the-void"] = {
  hash = "a608f4",
  fullHash = "a608f4",
  text = "Powers of the Void. A stolen tome draws Drusilla La Salle's attention in Northshire. Powers of the Void was kept in a restricted wing of Northshire Abbey's library until a novice took it while defecting to the Defias Brotherhood. Drusilla seeks its recovery for her own study of dark magic. Powers of the Void was kept behind guarded shelves in Northshire Abbey's library. The abbey archives hold holy scripture and clerical records, along with scholarly works on shadow and nether energies. The tome was presumably penned by the archmage Khadgar. Because its subject was dangerous, abbey authorities kept the book under guard and away from casual visitors. That barred Northshire's warlock mentor, Drusilla La Salle, from browsing it without drawing the priesthood's suspicion. A Northshire novice carried the tome away while abandoning his vows to join the Defias Brotherhood. As he fled into the neighboring vineyards, he took several valuable volumes from the abbey. Drusilla sends promising warlock initiates into the Defias bandit camp to recover the book from their tents. She wants the dark knowledge for her own study, and the effort tests whether an initiate has the nerve to bind otherworldly demons.",
  ["1"] = {
    {file = "Audio/Transport/full_item_powers-of-the-void-a512597eaf08be275d6a/1-0000.mp3", duration = 71.6016327, start = 0},
  },
}
P.transport["item:prairie-alpha-tooth"] = {
  hash = "3e1249",
  fullHash = "3e1249",
  text = "Prairie Alpha Tooth. Around Thunder Bluff, prairie wolf alphas roam Mulgore’s open plains. Mull Thunderhorn needs their teeth to cleanse the Wildmane Well. Mulgore’s wells sustain the tauren, and keeping them pure calls for rites of respect and sacrifice. Mull Thunderhorn of Bloodhoof Village needs teeth from the prairie wolf alphas that prowl beneath Thunder Bluff to cleanse the Wildmane Well. These fierce pack leaders embody the strength of the wild. Their teeth honor the balance between hunter, prey, and the spirits of the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-alpha-tooth-eef76720358cb1f160ef/1-0000.mp3", duration = 29.5444898, start = 0},
  },
}
P.transport["item:prairie-wolf-heart"] = {
  hash = "99b64e",
  fullHash = "99b64e",
  text = "Prairie Wolf Heart. Maur Raincaller in Bloodhoof Village needs a Prairie Wolf Heart for a remedy against venom. Maur Raincaller lives in Bloodhoof Village and is suffering from the venom of Mazzranache, the legendary plainstrider. The bite brings fever and threatens to spread poison through him. Maur seeks the heart of a prairie wolf, along with cougar bone and bird gizzard, for a traditional plains remedy meant to stop the infection before delirium proves fatal.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-wolf-heart-7bf1ba7b5f2a516c87c0/1-0000.mp3", duration = 25.4693878, start = 0},
  },
}
P.transport["item:prairie-wolf-paw"] = {
  hash = "858c60",
  fullHash = "858c60",
  text = "Prairie Wolf Paw. Across Mulgore, Prairie Wolf Paws are gathered from the wolves that hunt the plains. Mull Thunderhorn in Bloodhoof Village uses them with plainstrider talons to make a cleansing totem. Prairie wolves hunt in packs across Mulgore’s rolling grasses, alongside prairie stalkers and their pack alphas. They threaten young hunters and local livestock, and their place in the spiritual balance of the plains matters to tauren shamans. The shamans see the paws as more than trophies: they carry the land’s innate vitality. When goblin ventures tainted Mulgore’s sacred water reserves, shaman Mull Thunderhorn needed the land’s physical aid against the pollution. Joined with plainstrider talons, wolf paws provide the spiritual resonance for cleansing totems. With one made, the work of purifying the Winterhoof Water Well can begin.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prairie-wolf-paw-a92c3745444d7bec7abb/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["item:pridewing-venom-sac"] = {
  hash = "07b6f2",
  fullHash = "07b6f2",
  text = "Pridewing Venom Sac. Around Mirkfallon Lake, Pridewing Venom Sacs are sought by the night elves of Astranaar. Reports suggest Horde agents harvest the poison for covert attacks, and the Sentinels mean to deny them that supply. Pridewings hunt from the crags south of Ashenvale, especially around Mirkfallon Lake. These airborne predators are native to the Stonetalon Mountains, and their venom can be gathered from the glands in their bodies. Reports from Theramore suggest Horde assassins are taking that poison to coat blades for covert attacks on night elf settlements. In Astranaar, Sentinels send scouts to hunt the wyverns and collect their venom glands before Horde agents can claim them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pridewing-venom-sac-2337820e24d042aefe99/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["item:prismatic-punch-card"] = {
  hash = "728442",
  fullHash = "728442",
  text = "Prismatic Punch Card. In Gnomeregan, the Prismatic Punch Card carries the highest security clearance. Gnome refugees in Ironforge seek the records it unlocks. When the gnomes fled Gnomeregan, troggs and toxic irradiation drove them from their city. Vast stores of research and civic records remained in its depths. The gnomes guarded high-level systems with rising levels of clearance. To reach the Matrix Punchograph 3005-D in the lower Engineering Labs, a card must pass through a series of terminals. It starts white, then advances through yellow, blue, and red before the final terminal stamps it Prismatic. The card's encoded clearance is listed as awaiting the invention of an entirely new number.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prismatic-punch-card-5bb4caf752470683c71c/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["item:pristine-spider-silk"] = {
  hash = "afe875",
  fullHash = "afe875",
  text = "Pristine Spider Silk. Stormwind mages seek Pristine Spider Silk for robes woven to endure enchantments. The fine thread comes from venomous spiders in Duskwood. Stormwind mages need silk strong enough to bear enchantments and the wear of an adept. Tailors use common spider silk, but the strands gathered from carrion recluses and black widow hatchlings in Duskwood are more resilient. Mages from the Wizard's Sanctum send rising adepts into those woods to collect the silk. Master tailor Wynne Larson then weaves it into a robe for an adept.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pristine-spider-silk-83f8817ab6f729230297/1-0000.mp3", duration = 30.0146939, start = 0},
  },
}
P.transport["item:prowler-claws"] = {
  hash = "f53dec",
  fullHash = "f53dec",
  text = "Prowler Claws. Across the Barrens, Prowler Claws are carried back to Sergra Darkthorn at the Crossroads. They show that a hunter can track and defeat the prowlers stalking the plains. Savannah Prowlers hide in the Barrens’ tall grass, waiting to strike with patience and cunning. These large cats ambush creatures that enter their hunting grounds, unlike grazing plainstriders and zhevra. Taking their curved claws means facing predators that rely on stealth and defend their territory. For Horde warriors and scouts, the hunt tests whether they can track a stalker through its own ground and make it the prey. Sergra Darkthorn, the huntress at the Crossroads, asks initiates to bring back Prowler Claws before facing greater trials. The claws show that a hunter can follow tracks through the savannah grass and withstand a predator’s attack. Those who return with them have proved they can stay alert among the dangerous beasts of the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_prowler-claws-ff68eb081f72bbaf2969/1-0000.mp3", duration = 51.3828571, start = 0},
  },
}
P.transport["item:pure-hearts"] = {
  hash = "1f8647",
  fullHash = "1f8647",
  text = "Pure Hearts. In the Undercity, Pure Hearts draw a succubus from the Twisting Nether. Carendin Halgar gives these ritual reagents to Forsaken warlocks, who use them to manifest the demon and attempt to defeat and bind her. Carendin Halgar gives Pure Hearts to warlocks who summon a succubus in the Undercity's Magic Quarter. Set on the summoning circle, these untainted spiritual essences lure the demon across the Twisting Nether and into the mortal realm. Once she appears, the warlock must resist her enthralling mind-charms and strike her down. Defeating the succubus asserts mystical dominance and sends her back to the Twisting Nether. Carendin then teaches the warlock the spell to summon her at will.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pure-hearts-06b565270c59a6befb29/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["item:purified-kor-gem"] = {
  hash = "aaa1ae",
  fullHash = "aaa1ae",
  text = "Purified Kor Gem. At Jordan Stilwell’s forge outside Ironforge, a Purified Kor Gem is needed for a weapon of the Light. First, the corrupted stone must be cleansed by elven magic. A Corrupted Kor Gem is held by naga in Blackfathom Deeps beneath the coast of Ashenvale. A paladin takes it to Thundris Windweaver, a night elf in Auberdine. Thundris draws on arcane and natural arts to purge the stone’s aquatic and shadowy taint. The cleanse leaves a Purified Kor Gem, fit to channel holy power. Jordan Stilwell, a human weaponsmith outside Ironforge, needs the gem to forge a masterwork weapon. He has long held designs for an arm worthy of the Silver Hand, but lacked the rare materials to make it. The Purified Kor Gem, Whitestone Oak Lumber, and rare ore provide the spiritual core for channeling a paladin’s righteous wrath.",
  ["1"] = {
    {file = "Audio/Transport/full_item_purified-kor-gem-f1a45a71c104843b42f1/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["item:putrid-claw"] = {
  hash = "1a20cb",
  fullHash = "1a20cb",
  text = "Putrid Claw. Putrid Claws reach Deathguard Dillinger as proof that the Scourge near Brill is being held back. Mindless undead roam the woods west of town, especially by the old bridge. The mindless Scourge keeps crossing into Tirisfal Glades. Rotting dead and ravaged corpses wander the eastern borders, gathering along roads and near the old bridge west of Brill. Deathguards place bounties on these horrors to protect travelers and garrison supply lines. A severed putrid claw proves that one more shambling corpse has been put down for good.",
  ["1"] = {
    {file = "Audio/Transport/full_item_putrid-claw-83c8ab2b539cf5e78dfd/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["item:pyrewood-shackle"] = {
  hash = "f21241",
  fullHash = "f21241",
  text = "Pyrewood Shackle. At Pyrewood Village, enchanted shackles bind its beleaguered inhabitants to Archmage Arugal's strange magic. The bands are tied to the dark fate that grips the townsfolk when night falls.",
  ["1"] = {
    {file = "Audio/Transport/full_item_pyrewood-shackle-5aba0a666752a39ad17b/1-0000.mp3", duration = 10.997551, start = 0},
  },
}
P.transport["item:quinn-s-potion"] = {
  hash = "a3db82",
  fullHash = "a3db82",
  text = "Quinn's Potion. At the Sepulcher, Apothecary Renferrel brews Quinn's Potion to help an injured scout recover. Quinn Yorick needs it after a disastrous patrol in Silverpine Forest. Apothecary Renferrel brews a remedy for Deathstalker Quinn Yorick. Word reached the Royal Apothecary Society at the Sepulcher after Quinn was badly hurt and left unable to move near the Ivar Patch. Renferrel made the draught to help him recover. Though minor field casualties rarely draw Renferrel from his darker research for Lady Sylvanas, he supplied the remedy so the scout could regain enough strength to travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_quinn-s-potion-e1c62d76289332c7b457/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["item:ran-bloodtooth-s-skull"] = {
  hash = "156300",
  fullHash = "156300",
  text = "Ran Bloodtooth's Skull. In Ashenvale, Ran Bloodtooth's Skull bears proof that a corrupted furbolg chieftain has fallen. The night elves of Astranaar receive it as a sign that a fierce threat to their woodland realm has ended. The furbolgs of Ashenvale have fallen into murderous madness under demonic taint and wilderness corruption. Ran Bloodtooth led one of the fiercest tribes. His skull gives the night elf Sentinels proof that he has fallen and his hold over the local furbolgs is broken, bringing some respite to Astranaar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ran-bloodtooth-s-skull-7f9424dd59577ce0111c/1-0000.mp3", duration = 30.0930612, start = 0},
  },
}
P.transport["item:raptor-head"] = {
  hash = "28fd30",
  fullHash = "28fd30",
  text = "Raptor Head. Across the Barrens, Raptor Head trophies answer a bounty from Gazrog at the Crossroads. The guard payroll vanished from a watchtower, and a wild raptor was caught in the theft. A stolen chest of guard payroll has left the Crossroads watchtower without its silver. The defenders caught a wild raptor red-handed, to their disbelief. Gazrog has put a bounty on the cunning reptiles prowling the Barrens. Bring their severed heads to the outpost, and the predators will be culled before they can pilfer more Horde supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_raptor-head-87155dc9361ac09fc3af/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["item:rare-earth"] = {
  hash = "857390",
  fullHash = "857390",
  text = "Rare Earth. At Dolanaar, Rare Earth waits for delivery to Denalan's camp near Lake Al'Ameth. The mineral-rich soil came from Darnassus for his botanical experiments on Teldrassil. Rare Earth is late reaching Dolanaar from Darnassus. Denalan, an eccentric botanist on Lake Al'Ameth's eastern shore, requested the parcel to study plants in Teldrassil's young ecosystem. Herbalist Syral Bladeleaf now entrusts the soil to travelers heading south, hoping it reaches Denalan before its potency fades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rare-earth-3c257a09fd5d24438f67/1-0000.mp3", duration = 29.8579592, start = 0},
  },
}
P.transport["item:rattlecage-skull"] = {
  hash = "ae7b11",
  fullHash = "ae7b11",
  text = "Rattlecage Skull. In Deathknell, novice Forsaken warlocks gather skulls from mindless undead. Venya Marthand asks for them as a test of their will before teaching them the dark arts of summoning. In Deathknell, Venya Marthand guides newly raised Forsaken who have a gift for dark magic. She sends them to subdue Rattlecage Skeletons near the ruined smithy and bring back their severed skulls. The trial tests whether a fledgling warlock can bend creatures from beyond this world to their command. It also lays the groundwork for breaching the void and binding a first demonic servant.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rattlecage-skull-c16bf8341b90f2e4c923/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["item:raven-claw-talisman"] = {
  hash = "6e2aa4",
  fullHash = "6e2aa4",
  text = "Raven Claw Talisman. In Ban'ethil Barrow Den, the Raven Claw Talisman is kept among relics needed to awaken sleeping druids. The sacred night elf relic is one of four Relics of Wakening used to guide the Druids of the Talon safely back from the Emerald Dream. The Raven Claw Talisman rests in a designated chest inside Ban'ethil Barrow Den, where Teldrassil's Druids of the Talon entered deep meditative sleep. Their hibernation is a delicate spiritual threshold. Without the proper ceremonial focus, a druid whose link to the waking world is broken may remain stranded in the Emerald Dream. Athridas Bearmantle in Dolanaar needs this talisman, the Black Feather Quill, the Sapphire of Sky, and the Rune of Nesting to perform the awakening ritual and bring the sleepers back safely. Corrupted Gnarlpine furbolgs have overrun Ban'ethil Barrow Den, putting its sacred chests and sleeping druids in peril. Their desecration has cut the sanctuary off from outside aid, and the relics may be lost or destroyed. Athridas Bearmantle calls on Teldrassil's defenders to brave the den's winding earthen corridors and secure the Raven Claw Talisman before the displaced druids are lost to the Dream forever.",
  ["1"] = {
    {file = "Audio/Transport/full_item_raven-claw-talisman-eb89190b4864ed3bd62a/1-0000.mp3", duration = 70.635102, start = 0},
  },
}
P.transport["item:razorflank-s-medallion"] = {
  hash = "db7b91",
  fullHash = "db7b91",
  text = "Razorflank's Medallion. Charlga Razorflank's medallion lies deep within Razorfen Kraul, carried by the crone who rules the stronghold. Its return gives the night elf sentinels proof that she has fallen. Charlga Razorflank carries the medallion as the leader of the Razorfen quilboar. At Thalanaar, Falfindel Waywarder learns of fallen explorers such as Heralath and the dwarf Lonebrow, then sends Alliance adventurers against the quilboar leader. The medallion confirms Charlga's death to the night elf sentinels guarding Feralas's borders. They can know that the gathered forces within the Kraul have lost their leader.",
  ["1"] = {
    {file = "Audio/Transport/full_item_razorflank-s-medallion-9d5678c043e5d83c2b82/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["item:reagent-pouch-shaman"] = {
  hash = "26537a",
  fullHash = "26537a",
  text = "Reagent Pouch (shaman). Burning Blade cultists in Durotar carry reagents for a shaman's first fire sapta. Telf Joolam uses them with fire tar from Razormane quilboar to make the draught that lets a young shaman see the realm of fire. Burning Blade cultists carry reagents for a young shaman's first fire sapta. The hermit Telf Joolam uses the powders and oils in their pouches with fire tar from Razormane quilboar. Together, these components make a draught that grants sight into the realm of fire and attunes the shaman to the spirits of flame. Burning Blade cultists turn flame toward destruction and fel sorcery, yet the elements in their pouches still belong to heat and combustion. Shaman teach that elemental forces exist in tension: fire creates as well as destroys. A shaman can take the cultists' tools and use those elements to awaken true communion with the spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_reagent-pouch-shaman-0a00e2dac4e1e9159382/1-0000.mp3", duration = 51.1216327, start = 0},
  },
}
P.transport["item:reconstructed-tome"] = {
  hash = "3925d3",
  fullHash = "3925d3",
  text = "Reconstructed Tome. In warlocks’ hands, the Reconstructed Tome gathers the scattered teachings of the cabal. Its pages hold the rites for summoning and binding a felhunter from the Twisting Nether. Warlocks of the Alliance and Horde search for the torn leaves of the Tome of the Cabal. They piece the grimoire back together and consult occult scholars, who are eager to glimpse its rare teachings before the finished book is surrendered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_reconstructed-tome-a8ac59d7f4f856b5e6ae/1-0000.mp3", duration = 22.282449, start = 0},
  },
}
P.transport["item:recruitment-letter"] = {
  hash = "e9b099",
  fullHash = "e9b099",
  text = "Recruitment Letter. Takrin Pathseeker sends promising adventurers from Durotar west to serve in the Barrens. His letter directs able-bodied volunteers to the border outpost run by Kargal Battlescar. Takrin Pathseeker watches young warriors and scouts prove themselves around Razor Hill. He chooses those who seem strong enough for frontline service and gives them a letter for duty in the Barrens. Across the Southfury River bridge, recruits leave Durotar’s sheltered red dirt and join the Horde’s guard against quilboar, centaur, and Alliance scouts. Kargal Battlescar receives the recruits at the outpost just across the river. The grizzled veteran manages the post and evaluates each conscript before signing off on their enlistment. A signed recruit is soon sent farther west to the Crossroads, where the frontier outposts are stretched thin.",
  ["1"] = {
    {file = "Audio/Transport/full_item_recruitment-letter-5da9b00d34764e2bebbb/1-0000.mp3", duration = 48.0130612, start = 0},
  },
}
P.transport["item:red-burlap-bandana"] = {
  hash = "c88ea8",
  fullHash = "c88ea8",
  text = "Red Burlap Bandana. In Northshire Valley, Deputy Willem gathers red bandanas from slain Defias thieves near the abbey vineyards. The cloth marks low-ranking highwaymen and cutpurses of the Brotherhood. Red burlap masks mark the Defias Brotherhood's rank-and-file. Cheap, rough cloth dyed red hides a thief's features and signals allegiance to the growing rebellion. In Northshire, young recruits and common thugs carry these scarves into the eastern orchards. The local guards recognize the striking red fabric as proof of thieves slain nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-burlap-bandana-73f1a41a9b86129c7d26/1-0000.mp3", duration = 31.1379592, start = 0},
  },
}
P.transport["item:red-leather-bandana"] = {
  hash = "e7b2dd",
  fullHash = "e7b2dd",
  text = "Red Leather Bandana. In Westfall, Red Leather Bandanas mark those who defy Stormwind’s Crown. The Defias Brotherhood wears them as face coverings and a sign of their cause.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-leather-bandana-47931026c2ce38f63a2f/1-0000.mp3", duration = 9.40408163, start = 0},
  },
}
P.transport["item:red-linen-bandana"] = {
  hash = "30bcbc",
  fullHash = "30bcbc",
  text = "Red Linen Bandana. Across Elwynn Forest, Red Linen Bandana marks the Defias Brotherhood. Its cloth hides a wearer’s face and can be put to use by local settlers. Across Elwynn Forest, full Defias operatives wear woven red linen bandanas. In Northshire Valley, lower-ranking initiates and common thugs use coarse burlap masks instead. The crimson cloth hides a face and marks allegiance to Edwin VanCleef's rogue fraternity. It also signals their rebellion against Stormwind's crown. Sara Timberlain at the Eastvale Logging Camp asks travelers to gather bandanas from outlaw encampments. Though tied to bandits, the masks are made from respectable linen. After washing and needlework, settlers can turn the cloth into sturdy clothing and bandages for the forest's working folk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-linen-bandana-0307d5b9ab24b1764390/1-0000.mp3", duration = 46.4979592, start = 0},
  },
}
P.transport["item:red-wool-bandana"] = {
  hash = "9c73bc",
  fullHash = "9c73bc",
  text = "Red Wool Bandana. Inside the Stormwind Stockade, Red Wool Bandana scraps mark Defias brotherhood. Imprisoned cutthroats tear them from jailhouse wool blankets and wear them as emblems of defiance behind bars. In the Stormwind Stockade, Defias Brotherhood inmates hold fast to their identity. They secretly tear scraps from prison wool blankets and stitch them into red bandanas to wear as their colors. Guards treat the scarves as contraband, and their discovery can spark fatal mutinies. For the prisoners, each bandana declares that their brotherhood and rebellion endure, even in chains. Red Wool Bandanas became known for the death of Mac Raskol, a fourteen-year-old prison guard. He caught inmates shredding blankets to make the scarves and tried to discipline them. Defias convicts stabbed him in the back. His grieving grandmother, Nikova, now seeks adventurers to enter the rioting dungeon, cull the rioters, and bring back the crimson cloth as proof of vengeance.",
  ["1"] = {
    {file = "Audio/Transport/full_item_red-wool-bandana-b2a87bea2f053f7b40a3/1-0000.mp3", duration = 56.8946939, start = 0},
  },
}
P.transport["item:remaining-drops-of-purest-water"] = {
  hash = "dec62b",
  fullHash = "dec62b",
  text = "Remaining Drops of Purest Water. Across Kalimdor and Lordaeron, shaman gather what Brine needs for a draught. Its last drops wait for a perilous journey. Brine prepares a water draught in the Barrens from water gathered across Kalimdor and Lordaeron. Part of it gives shaman vision of distant elements. The remaining drops are kept for a harder purpose. Shaman carry them to the coast of Silverpine Forest, near the Sepulcher, where the Brazier of Everfount stands. There, the drops are burned with the bracers of a fallen, tainted elemental. The pure water cuts through the undead plague’s corruption, calling an untainted water spirit to commune with the shaman and complete their communion with the element.",
  ["1"] = {
    {file = "Audio/Transport/full_item_remaining-drops-of-purest-water-78260e9a41977bac9015/1-0000.mp3", duration = 38.164898, start = 0},
  },
}
P.transport["item:remedy-of-arugal"] = {
  hash = "ccc94c",
  fullHash = "ccc94c",
  text = "Remedy of Arugal. In Silverpine Forest, Dalar Dawnweaver seeks Arugal's spell to learn how his worgen magic works. Before taking Shadowfang Keep, Archmage Arugal sheltered at an abandoned wheat farm north of the river bridge in Silverpine Forest. He recorded his strange arts in spellbooks left among the farm tools and rotting floorboards. One scroll, the Remedy of Arugal, describes early methods and magical formulas from his experiments with the transmutations that cursed the local people. Dalar Dawnweaver, a Forsaken spellcaster at the Sepulcher, thinks little of Arugal's standing and considers his intellect fragile and transparent. Still, Dawnweaver needs to understand the worgen curse's workings. Recovering the Remedy gives Forsaken agents the arcane knowledge Dawnweaver seeks to counter Arugal's spreading menace and secure Silverpine for Lady Sylvanas.",
  ["1"] = {
    {file = "Audio/Transport/full_item_remedy-of-arugal-66a3f23bcc2f61adae30/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["item:rendered-spores"] = {
  hash = "4938fc",
  fullHash = "4938fc",
  text = "Rendered Spores. Across the Barrens, Rendered Spores are being rushed from Apothecary Helbrim to Thunder Bluff before they decay. Apothecary Zamah must stabilize the emulsion beneath the city. Apothecary Helbrim makes Rendered Spores from fungal spores gathered near the Barrens’ damp oases. He processes the strange spores into an active chemical emulsion, but it is unstable. After forty-five minutes, it breaks down and becomes useless for scientific study. Apothecary Helbrim cannot finish refining the emulsion at his remote outpost. It must reach his Forsaken colleague, Apothecary Zamah, beneath Spirit Rise in Thunder Bluff. In the Pools of Vision, Zamah has the equipment and reagents to reseal and finish processing the spores for the Royal Apothecary Society.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rendered-spores-8b63f5fa304a94e2d985/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:renferrel-s-findings"] = {
  hash = "87caa9",
  fullHash = "87caa9",
  text = "Renferrel's Findings. In Silverpine Forest, Renferrel's Findings carry research south to Tarren Mill. Apothecary Renferrel gathered the notes at the Sepulcher for Apothecary Lydon, who is helping brew the Forsaken's New Plague. At the Sepulcher, Apothecary Renferrel records his work on the New Plague. The Royal Apothecary Society labours under direct orders from Lady Sylvanas Windrunner, the Dark Lady. Researchers scattered across Lordaeron must work together to achieve a breakthrough. Renferrel sends his findings south to Tarren Mill, where fellow researchers can build on his results. The papers link Silverpine Forest to Hillsbrad Foothills and the Forsaken's alchemical network. Apothecary Lydon awaits Renferrel's notes in Tarren Mill, where he can compare them with his own work against the living and the Scourge. Reliable couriers must cross Hillsbrad's contested roads; without them, the Society's scattered research would quickly stall.",
  ["1"] = {
    {file = "Audio/Transport/full_item_renferrel-s-findings-4414991c9d82707ae7b9/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["item:report-on-the-defias-brotherhood"] = {
  hash = "4761b8",
  fullHash = "4761b8",
  text = "Report on the Defias Brotherhood. At Stormwind Keep, a report on the Defias Brotherhood carries the findings of a long investigation to the royal court. City Architect Baros Alexston entrusts it to the adventurer who uncovered the conspiracy. City Architect Baros Alexston prepared a report for Stormwind's leaders after a long investigation into unrest in Westfall and nearby lands. He entrusted the document to the adventurer who unraveled the conspiracy. The report is carried to Stormwind Keep, where it is meant to accompany a personal audience about the conspirators' schemes and the danger they pose to the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_report-on-the-defias-brotherhood-6ae1b24e6c4db7658993/1-0000.mp3", duration = 30.6677551, start = 0},
  },
}
P.transport["item:resonite-crystal"] = {
  hash = "84ca6f",
  fullHash = "84ca6f",
  text = "Resonite Crystal. In Boulderslide Cavern, kobolds are digging frantically for Resonite Crystal. Their work has drawn Mor'rogal's concern at Sun Rock Retreat.",
  ["1"] = {
    {file = "Audio/Transport/full_item_resonite-crystal-eec28b8179cc0d530891/1-0000.mp3", duration = 8.75102041, start = 0},
  },
}
P.transport["item:restabilization-cog"] = {
  hash = "77f42f",
  fullHash = "77f42f",
  text = "Restabilization Cog. Outside Gnomeregan's irradiated ruins, leper gnomes still carry Restabilization Cogs. In Kharanos, tinkerers need the intact parts to build the Recombobulator, a machine meant to reverse leper mutation. Radiation flooded Gnomeregan in a failed attempt to wipe out the invading troggs. Countless gnomes became sick, hostile leper gnomes, driven from their home as exiles. Even in madness, they carry intricate gnomish machinery and fittings that can be salvaged. Ozzie Togglevolt and Razzle Sprysprocket believe the terrible change can be undone. They need adventurers to recover parts from the afflicted outside Gnomeregan's gates and finish their prototype Recombobulation Device. Intact Restabilization Cogs will balance its inner combustion systems.",
  ["1"] = {
    {file = "Audio/Transport/full_item_restabilization-cog-b7f18b424b378c257a74/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["item:ring-of-zoram"] = {
  hash = "eb5720",
  fullHash = "eb5720",
  text = "Ring of Zoram. At Zoram, the ring of the city's rulers has surfaced again after millennia beneath the sea. The naga now hold it, and Talen seeks the key to an ancient statuette. Before the Well of Eternity collapsed, Zoram stood on Kalimdor's western coast as a jewel of the night elven empire. Its rulers wore the Ring of Zoram, whose inner band bears a strange code in the night elven language. The Great Sundering shattered the continent ten thousand years ago, and the ring sank with the city beneath the tides. It lies beneath the waters of what is now the Zoram Strand. For millennia, silt and ruins hid the ring. Then naga began scouring Ashenvale's coast, and Ruuzel, a naga leader who dwells on an islet off the northern strand, uncovered it among the sunken debris. The night elf scholar Talen seeks the ring for more than its age. It is the only key that can unlock relics salvaged from the depths, including ancient statuettes sealed on the sea floor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ring-of-zoram-1d11cb41d539c90f2007/1-0000.mp3", duration = 56.1632653, start = 0},
  },
}
P.transport["item:robo-mechanical-guts"] = {
  hash = "2d5aa6",
  fullHash = "2d5aa6",
  text = "Robo-Mechanical Guts. In Stormwind, Shoni gathers parts from the roaming machines of Gnomeregan. She needs them to repair tunneling vehicles meant to help reclaim the city in Dun Morogh. After High Tinker Gelbin Mekkatorque and the surviving gnomes fled Gnomeregan, thousands of automated mechanisms, clockwork sentries, and industrial robots remained inside. The machines still roam the radioactive city's corridors on their own. In Stormwind City, tinker Shoni is assembling gyrodrillmatic excavationators to break through Gnomeregan's defenses and reclaim the lost city. Without fresh materials, she sends adventurers into the contaminated halls to salvage working parts from the robots, including springs, wires, and gyro-components.",
  ["1"] = {
    {file = "Audio/Transport/full_item_robo-mechanical-guts-d7fb8031b6b2b3d10f6d/1-0000.mp3", duration = 42.1616327, start = 0},
  },
}
P.transport["item:rocket-car-parts"] = {
  hash = "bf7c74",
  fullHash = "bf7c74",
  text = "Rocket Car Parts. Rocket Car Parts are the scattered, twisted metal remains of high-speed collisions across the Shimmering Flats in Thousand Needles. Constantly generated by reckless gnome and goblin racers pushing experimental speeders past their limits, these salvaged scraps are harvested by opportunists looking to turn racetrack accidents into quick coin. The Mirage Raceway in the Shimmering Flats is the staging ground for an unending, combustible rivalry between goblin and gnome engineering. In their pursuit of unmatched land speed, racers regularly suffer catastrophic breakdowns, explosive misfires, and high-velocity crashes that scatter metal across the salt flats. These discarded remnants—ranging from bent cylinders and burnt gears to crushed sheet metal—do not stay abandoned for long. Scavengers and merchants, most notably the opportunistic dwarf Kravel Koalbeard, hire passing adventurers to comb the blinding white expanse and collect the debris. Because both racing teams are perpetually desperate for spare machinery to patch together their next prototype, scavenged wreckage can easily be resold directly back to the very teams that wrecked it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rocket-car-parts-71953aa69602e2dbabf0/1-0000.mp3", duration = 66.4032653, start = 0},
  },
}
P.transport["item:rod-of-channeling"] = {
  hash = "c4b0d7",
  fullHash = "c4b0d7",
  text = "Rod of Channeling. In the Wetlands, the Rod of Channeling is carried by Dragonmaw spellcasters. Warlocks seeking to summon a felhunter gather three for Strahad Farsan's acolytes to steady the ritual circle in Ratchet. Warlocks need more than willpower to bind a volatile felhunter. Strahad Farsan asks for three matched rods so his acolytes can channel magic together and steady the summoning circle while the warlock binds the beast. Dragonmaw darkcasters carry these rods for their own workings. Bonewarders and shadowwarders bear them at Angerfang Encampment and in the surrounding Wetlands ruins. Combat leaves the rods worn and nicked, but they still focus chaotic nether energy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rod-of-channeling-36318b2bb7522602eccc/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["item:rot-blossom"] = {
  hash = "6d8ae2",
  fullHash = "6d8ae2",
  text = "Rot Blossom. Rot Blossoms grow among Duskwood's desecrated graves, fed by blighted soil and undead remains. Their foul alchemical properties make them sought after. In Duskwood, Rot Blossoms grow in the defiled earth of graveyards such as the Tranquil Gardens Cemetery. Local rumors say the blooms can take root inside the cracked skulls of Skeletal Horrors and Skeletal Fiends stalking the barrows. For people in Darkshire, gathering them is grim and dangerous. Disturbing the soil means facing the unrested dead. Rot Blossoms provide an ingredient for local brews. Their dark essences are needed to make Zombie Juice, a foul draft tied to Duskwood's efforts to survive. Those sent to gather the flowers often aid the Night Watch as they cut down restless skeletons wandering the haunted graves.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rot-blossom-f78de1bcfa37ed5a7463/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["item:rot-hide-ichor"] = {
  hash = "39dbfc",
  fullHash = "39dbfc",
  text = "Rot Hide Ichor. On Fenris Isle, Rot Hide Ichor draws the Royal Apothecary Society’s attention. Apothecary Renferrel gathers it at the Sepulcher to learn what corrupted the gnolls and how to oppose them. On Fenris Isle, Rot Hide gnolls are no ordinary beasts. Their bodies are decomposed and twisted by an unnatural blight, and a noxious ichor flows through their veins to sustain their animated flesh. The Royal Apothecary Society suspects the fluid may reveal how the pack was corrupted and who commands them from within the ruined keep. At the Sepulcher, Apothecary Renferrel gathers vials of the ichor for study. The Forsaken hope to isolate the chemical and magical forces that fuel the gnolls, then find their weaknesses before sending troops across Lordamere Lake in a full assault.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rot-hide-ichor-916b48236545e5719491/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["item:rough-quartz"] = {
  hash = "dac35a",
  fullHash = "dac35a",
  text = "Rough Quartz. In Durotar, a Rough Quartz comes from a Minor Manifestation of Earth. A shaman brings the stone to an elder, who binds it into the first Earth Totem. Rough Quartz is a gift from a Minor Manifestation of Earth to a shaman who communes with the spirits in Durotar or Mulgore. To the untrained eye, it looks like an ordinary desert pebble. The stone represents endurance, patience, and unwavering strength. At the Valley of Trials, Canaga Earthcaller binds it into carved wood to make an Earth Totem. The quartz becomes the spiritual focus joining a young shaman to Azeroth's living soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rough-quartz-e8b910472a1280437b03/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["item:rumbleshot-s-ammo"] = {
  hash = "d80690",
  fullHash = "d80690",
  text = "Rumbleshot's Ammo. Near the Grizzled Den, Rumbleshot's Ammo lies abandoned in the snow. The crate was bound for gunsmith Hegnar Rumbleshot in Dun Morogh, but a frightened courier fled from hungry wendigos and left it behind. Hegnar Rumbleshot keeps a roadside arms shop on the mountain path from Coldridge Pass toward Anvilmar. Ironforge riflemen, mountaineers, and dwarven mortar teams drill in the snowy heights, and his supplies run low as quickly as powder burns. Loslor sent this shipment of shot from Kharanos, but it never reached the shelves. Its courier camped too close to the Grizzled Den's wendigos. When they attacked, the courier panicked and fled, leaving the heavy crate in the beasts' hunting grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rumbleshot-s-ammo-97b2364687f3774714e0/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["item:rune-inscribed-parchment"] = {
  hash = "ac0424",
  fullHash = "ac0424",
  text = "Rune-Inscribed Parchment. In the Valley of Trials, Gornek hands aspiring orc shamans a message from Shikrik. It calls them to become spiritual leaders and conduits for elemental spirits. New orc shamans begin training under veteran overseers in the Valley of Trials. While an initiate performs initial trials for Gornek, he hands them a rune-covered document sent by Shikrik, the local shamanic instructor. The message summons them to deeper communion with the elements. Among the orcs, shamans mediate between the living and their ancestors. The writ marks a move from brute strength toward disciplined reverence for ancestors.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-parchment-3ce16659cdd45ac791e9/1-0000.mp3", duration = 35.1346939, start = 0},
  },
}
P.transport["item:rune-inscribed-pendant"] = {
  hash = "29446a",
  fullHash = "29446a",
  text = "Rune-Inscribed Pendant. The Rune-Inscribed Pendant is a magical trinket recovered from Dalaran supply shipments destined for Ambermill. Prized by the Kirin Tor, these pendants serve as conduits for channeling potent arcane energies. Discovered among crates of cartographic supplies bound for the Dalaran enclave at Ambermill, this pendant bears intricate arcane inscriptions. High-ranking wizards of the Kirin Tor frequently employ such artifacts to focus and amplify their spellcasting. The presence of numerous channeled pendants moving into the region immediately draws the suspicion of the Forsaken at the Sepulcher, signaling an impending project of immense magical power.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-pendant-ecb724296b89bfb1c6cf/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:rune-inscribed-tablet"] = {
  hash = "ed59ea",
  fullHash = "ed59ea",
  text = "Rune-Inscribed Tablet. In the Valley of Trials, Gornek gives young Darkspear troll shamans a stone message. It sends promising mystics to Shikrik to begin formal communion with the elements. Gornek gives the rune-carved stone to initiates who prove their mettle in the Valley of Trials. The troll shaman Ishi-yo sent it to direct them to Shikrik, the shaman trainer. For Darkspear trolls, the tablet begins a shared path with the orcs, joining their old spiritual traditions with the shamanic heritage Warchief Thrall has renewed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-inscribed-tablet-bec16be2b465b5464a9f/1-0000.mp3", duration = 28.7346939, start = 0},
  },
}
P.transport["item:rune-of-nesting"] = {
  hash = "96d681",
  fullHash = "96d681",
  text = "Rune of Nesting. At Ban'ethil Barrow Den, the Rune of Nesting lies among four sacred relics. It helps Athridas Bearmantle prepare the ritual that safely awakens the Druids of the Talon from the Emerald Dream. The Rune of Nesting lies in the Chest of Nesting, deep in the winding chambers of Ban'ethil Barrow Den. Night elf druids hibernate in underground barrow dens to commune with nature through the Emerald Dream. To return safely, the Druids of the Talon need a precise awakening ritual guided by sacred relics. The rune is one of four: the Raven Claw Talisman, the Black Feather Quill, the Sapphire of Sky, and the Rune of Nesting. Together, the relics help call the sleeping druids back to the waking world. Corrupted Gnarlpine furbolgs have overrun Ban'ethil Barrow Den, putting its sleeping defenders in peril. Without the relics, the druids risk remaining trapped in the Emerald Dream while invaders desecrate their sanctuary. Recovering the Rune of Nesting and its companion artifacts allows Athridas Bearmantle in Dolanaar to prepare the ritual that can safely awaken them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_rune-of-nesting-09eb2192edfe8bfc6200/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["item:runes-of-summoning"] = {
  hash = "7f6c7a",
  fullHash = "7f6c7a",
  text = "Runes of Summoning. In the Undercity's Magic Quarter, Carendin Halgar gives warlocks runes for summoning a voidwalker. The ritual draws an unbound voidwalker into a circle, where an aspiring warlock can bend it to their will. Carendin Halgar gives the Runes of Summoning to warlocks ready to command a voidwalker. In the Magic Quarter of the Undercity, Forsaken practitioners study how to manipulate the Nether. A warlock casts the runes in the active summoning circle below Halgar's station. The ritual tears through the Void and draws forth a creature to be overpowered and bound into servitude.",
  ["1"] = {
    {file = "Audio/Transport/full_item_runes-of-summoning-93d523746b441fdeb5ac/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["item:sack-of-murloc-heads"] = {
  hash = "8470ce",
  fullHash = "8470ce",
  text = "Sack of Murloc Heads. Along the Hillsbrad beaches, a gruesome sack of Murloc Heads is gathered as proof of military action against local shore pests. Lieutenant Farren Orinelle hands the bundle to passing adventurers for delivery to Marshal Redpath in Southshore. Southshore faces constant attacks from Syndicate outlaws, Forsaken skirmishers, and wild murlocs along the coast. Local officers must show town leaders that coastal threats are being culled to secure funding and favor. Lieutenant Farren Orinelle collects severed heads as proof, but finds the cargo distasteful. His squeamishness leads him to hand the sack to travelers instead of bringing the grisly evidence to Marshal Redpath himself.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sack-of-murloc-heads-26367210128721a027b4/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["item:sack-of-supplies"] = {
  hash = "785500",
  fullHash = "785500",
  text = "Sack of Supplies. A caravan shipment bound for Rezlak lies scattered among the harpy roosts of Razorwind Canyon. Dustwind harpies intercepted the goods as they crossed Durotar. Rezlak needs steady supplies for his work outside Orgrimmar. The goblin engineer, contracted from Ratchet by Gazlowe, builds for the Horde. A caravan carrying a promised shipment passed near the canyon road south of Orgrimmar, where Dustwind harpies ambushed it. They dragged the cargo into their roosts in Razorwind Canyon, scattering sacks among dirt and scree beside their nesting sites.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sack-of-supplies-8d63e6780485cac48262/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:salty-scorpid-venom"] = {
  hash = "63b9a2",
  fullHash = "63b9a2",
  text = "Salty Scorpid Venom. Salty Scorpid Venom is a caustic fluid harvested from the scorpids stalking the Shimmering Flats in Thousand Needles. Packed with natural salts from the desert floor, it is prized by gnomish rocket racers attempting to engineer volatile, ultra-hot fuel. The scorpids crawling the arid expanse of the Shimmering Flats have adapted to an intensely mineral-rich environment. Over generations, the venom of beasts like the Scorpid Reavers and Scorpid Terrors has absorbed enormous quantities of local salt. Rather than brewing antidotes or standard poisons, gnomish tinkers like Fizzle Brassbolts prize this caustic compound as a prospective additive for high-combustion engine fuel. Out at the Mirage Raceway, the engineering competition between gnomes and goblins drives inventors to test increasingly dangerous materials in their rocket cars. Fizzle Brassbolts believes boiling down the salted venom, treating it with specialized catalysts, and mixing it into propellant tanks will deliver the blazing heat necessary to outrun goblin racers on the salt pans.",
  ["1"] = {
    {file = "Audio/Transport/full_item_salty-scorpid-venom-30e485f7958289ec3eb9/1-0000.mp3", duration = 59.115102, start = 0},
  },
}
P.transport["item:samophlange-item"] = {
  hash = "b6f883",
  fullHash = "b6f883",
  text = "Samophlange (item). In the Barrens, Samophlange is hidden inside an automated control console. Goblin mechanics cannot explain what the strange component does. Samophlange lies inside a control console in the Barrens, behind a maze of wiring and hollow tubes. It takes careful searching to free the component from its housing. It looks like a vital part of clockwork and steam machinery, but goblin tinkerers cannot make sense of its purpose. They mean to send it to the Tinkers' Union in Undermine, though the fragile piece may not survive rough handling.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samophlange-item-e8b7789710fd8f6f1c48/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["item:samophlange-manual"] = {
  hash = "b8cda3",
  fullHash = "b8cda3",
  text = "Samophlange Manual. In Orgrimmar, Rilli Greasygob seeks the scattered pages of the Samophlange Manual. The handbook holds instructions for repairing and operating the Venture Company's samophlange. Boss Copperplug guarded the Venture Company's knowledge of the samophlange. The ambitious overseer kept the manual's pages from most workers, giving scattered leaves only to his most loyal subordinates. When the device slipped from company hands, no one could repair it without gathering the torn documentation from Copperplug and his crew at the Boulder Lode Mine. Rilli Greasygob left the Venture Company and settled in Orgrimmar to learn how the samophlange was built. Copperplug had never favored him, so Rilli depends on enterprising travelers to retrieve the manual's cover and loose leaves. Reassembled, the handbook gives goblin tinkerers working alongside the Horde a rare look at Venture Company engineering.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samophlange-manual-478da53dab23d4c547ab/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["item:sample-ichor"] = {
  hash = "099c29",
  fullHash = "099c29",
  text = "Sample Ichor. In Silverpine Forest, Sample Ichor carries traces of necromancy and warlock sorcery. Apothecary Renferrel refined it from the fluid that sustains the Rot Hide gnolls. Apothecary Renferrel sent Sample Ichor to the Undercity for closer study. He recovered samples from the Rot Hide gnolls and their lingering remnants, then reduced the foul liquid to its base components. His analysis showed that the ichor was made through necromantic rites woven with warlock magic. Since its craft reaches beyond simple alchemy, Renferrel sent the sample to Bethor Iceshard for divination.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-ichor-bd4bd33acfd7a789fb3e/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["item:sample-of-zanzil-s-altered-mixture"] = {
  hash = "1d7356",
  fullHash = "1d7356",
  text = "Sample of Zanzil's Altered Mixture. A courier carries Sample of Zanzil's Altered Mixture across the sea to Tarren Mill. The brew came from the witch doctor Zanzil and leaves its carrier weakened. Serge Hinott may find a cure and uncover the poison's workings. An operative carries the mixture after infiltrating the Venture Company's tower near the Sludge Fen in the Barrens. The sample came from a cache in Gallywix's lockbox, and Zanzil's brew has left the agent afflicted. Shenthul sends the stricken operative across the Great Sea with the sample. At Tarren Mill in the Hillsbrad Foothills, apothecary Serge Hinott has the rare skill to isolate the toxin and learn its components.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-of-zanzil-s-altered-mixture-7a48ace03eb6f6d3e33c/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["item:sample-snapjaw-shell"] = {
  hash = "e957d5",
  fullHash = "e957d5",
  text = "Sample Snapjaw Shell. Across the Barrens, Sample Snapjaw Shells carry lingering vitality from freshwater oases. Tauren druids send them across the Great Sea to help heal Silverpine Forest. Snapjaws thrive in the lush, strange oases of the Barrens. Their durable shells keep a faint inner glow and pulse with energy long after separation from the creature. Tauren druids watching the land's swift changes see in these carapaces the resilient spark of Kalimdor's wilderness. Their vigor shows how life can flourish even in harsh, arid surroundings. Tauren naturalists send couriers across the sea with shells for Mura Runetotem at the Sepulcher. Stationed in Silverpine Forest's blighted expanses, Mura seeks ways to help the Forsaken heal the northlands. She studies the life-force preserved in the snapjaw's armor, hoping to find what can renew an ailing forest and bring growth back to dying soil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sample-snapjaw-shell-e2cf57fc804fee30c609/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:samuel-s-remains"] = {
  hash = "4bf30f",
  fullHash = "4bf30f",
  text = "Samuel's Remains. Near Deathknell, Samuel's Remains are gathered from a Scourge thrall and laid beside Marla. Samuel Fipps and his wife Marla lived peacefully in Tirisfal Glades before the plague of undeath swept across Lordaeron. Samuel succumbed to the contagion and became the Scourge's mindless servant. Marla escaped undeath, but Samuel struck her down. With her dying breath, she asked to be buried beside him once his cursed form was put to rest. Novice Elreth in Deathknell sends newly awoken Forsaken northeast of the settlement to find Samuel's wandering form, recover his bones, and bury them in the front row of the local cemetery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_samuel-s-remains-48ca48f08d5be11c91cc/1-0000.mp3", duration = 37.1983673, start = 0},
  },
}
P.transport["item:sapphire-of-aku-mai"] = {
  hash = "951cf7",
  fullHash = "951cf7",
  text = "Sapphire of Aku'Mai. Along Blackfathom Deeps, the naga are harvesting the glowing Sapphires of Aku'Mai. Water spirits cling to the crystals, and Je'neu Sancrea seeks help confiscating them before their arcane power can be exploited. Blackfathom Deeps holds Sapphires of Aku'Mai in its watery cavern entrances along Ashenvale's Zoram Strand. Water spirits cling to the crystalline formations, rich in elemental energy, making them potent aids in magical workings. When scouts reported the subterranean naga quarrying the gems from cavern walls, Je'neu Sancrea, a shaman, sought adventuring help to confiscate them. In naga hands, the stones could fuel devastating arcane rites.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sapphire-of-aku-mai-60b1c9d2e9ac17baa75b/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["item:sapphire-of-sky"] = {
  hash = "1b7c62",
  fullHash = "1b7c62",
  text = "Sapphire of Sky. In Ban'ethil Barrow Den, Sapphire of Sky helps call sleeping Druids of the Talon back from the Emerald Dream. It is one of four sacred Relics of Wakening kept by the night elves. Druids of the Talon sleep in hibernation within Ban'ethil Barrow Den, deep among Teldrassil's roots, while they commune with the wilds. Waking from that deep trance is perilous. Four sacred relics protect the passage: the Black Feather Quill, the Raven Claw Talisman, the Rune of Nesting, and the Sapphire of Sky. The gem completes the harmony needed to call the sleeping spirits back from the Emerald Dream. Without it, they risk being trapped there forever. Corrupted Gnarlpine furbolgs have overrun Ban'ethil Barrow Den, leaving the sacred relics in their repositories. The Sapphire of Sky is secured inside the Chest of the Sky, along the winding underground corridors. The druids still sleep as the furbolgs rampage around them. Athridas Bearmantle in Dolanaar needs the sapphire and its companion relics to wake the sleepers before they are lost forever.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sapphire-of-sky-6a8184abba82bff47707/1-0000.mp3", duration = 61.1787755, start = 0},
  },
}
P.transport["item:sara-balloo-s-plea"] = {
  hash = "a521fa",
  fullHash = "a521fa",
  text = "Sara Balloo's Plea. Sara Balloo asks a trusted Alliance champion to carry her handwritten letter to King Magni Bronzebeard. Grieving in Ironforge, she cannot face the monarch herself and trusts the champion to bring her appeal before him. Sara Balloo sends a humble appeal to Ironforge's throne. Grieving, she cannot bring herself to face the High Seat, so she seeks an adventurer loyal to the Alliance to carry her words. Her message asks King Magni Bronzebeard to look toward the private mourning and sacrifices of ordinary dwarven families who serve the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sara-balloo-s-plea-1849ff58803c736c6917/1-0000.mp3", duration = 29.5444898, start = 0},
  },
}
P.transport["item:sarilus-foulborne-s-head"] = {
  hash = "5d96eb",
  fullHash = "5d96eb",
  text = "Sarilus Foulborne's Head. Across the border from the Barrens, Sarilus Foulborne's Head reaches Ashenvale as proof of the sorcerer's death. The undead mage defiled Ashenvale's waters, and the Sentinels demanded his head.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarilus-foulborne-s-head-584a921d9e694d4cacd9/1-0000.mp3", duration = 11.6244898, start = 0},
  },
}
P.transport["item:sarkoth-s-mangled-claw"] = {
  hash = "e3c534",
  fullHash = "e3c534",
  text = "Sarkoth's Mangled Claw. Across the southern bluffs of the Valley of Trials, Sarkoth's Mangled Claw bears the mark of a wounded hunter. Hana'zua's crushing blow scarred the scorpid's pincer before its venomous sting struck him down. Hana'zua, a young Darkspear troll, met Sarkoth while hunting in the Valley of Trials. The massive scorpid's venomous stinger pierced his chest, leaving him bleeding beneath a nearby tree. Before the blow landed, Hana'zua crushed the beast's pincer. Its severed, battered claw proves Sarkoth has been slain. For the wounded hunter, that scar on the beast is proof his desperate strike left its mark, and a last hold on his warrior's honor as venom courses through his veins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarkoth-s-mangled-claw-83ad2bff7b201a528349/1-0000.mp3", duration = 40.7510204, start = 0},
  },
}
P.transport["item:sarltooth-s-talon"] = {
  hash = "f52d60",
  fullHash = "f52d60",
  text = "Sarltooth's Talon. Above Whelgar's Excavation Site, Sarltooth's Talon marks the end of the raptor's attack. Ormer Ironbraid wants the claw as proof that the beast has been slain. Ormer Ironbraid watched from the ridge as raptors overran Whelgar's Excavation Site and butchered the dwarven expedition. He could not stop the slaughter. One massive raptor, Sarltooth, seemed to Ormer the likely pack leader. Seeking vengeance for his fallen kin, Ormer demanded the beast's death and one of its talons as proof. The claw marks the end of Sarltooth's reign over the ancient dwarven ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sarltooth-s-talon-18fb336051b7f9b9157f/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["item:sathrah-s-sacrifice"] = {
  hash = "c36acf",
  fullHash = "c36acf",
  text = "Sathrah's Sacrifice. At the Temple of the Moon, Sathrah's Sacrifice offers Lady Sathrah's spirit a chance at peace. Her silvery spinnerets come from the mighty spider who dwells in Teldrassil. Lady Sathrah was a venerable creature of Teldrassil, until creeping madness and corruption spread through the great tree's boughs and took hold of her. The Sisterhood of Elune asks you to bring back her silvery spinnerets as a consecrated offering, not a trophy. At the fountain in the Temple of the Moon, the remains are bathed in holy water. The rite washes away the taint that poisoned Sathrah's mind and frees her troubled soul. Her spirit then appears peacefully within the sanctuary, with the promise of rebirth under Elune's grace.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sathrah-s-sacrifice-a2c38b47b21f76229ee2/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["item:satyr-horns"] = {
  hash = "42bcc1",
  fullHash = "42bcc1",
  text = "Satyr Horns. In Ashenvale, Satyr Horns draw dryads seeking vengeance and traders bound for Ratchet. The horns come from satyrs whose corruption has taken root in the ancient forest. Ashenvale’s satyrs bear horns that mark their demonic corruption. At the Shrine of Aessina, the dryad Illiyana gathers them in grief and vengeance for her lost sister Anilia. Pixel, a traveling goblin resting at Splintertree Post, seeks them for trade. Demand for satyr horns has risen in Ratchet, where hunters can sell these remnants of slain demons. Satyr Horns must be cut from the beasts themselves; ordinary suppliers do not sell them. Satyrs hold strongholds across Ashenvale, including the corrupted groves of Xavian, the hollows of Satyrnaar, and the ruins of Night Run. Clearing these enclaves drives back the lingering demonic taint and supplies grieving guardians and eager merchants with proof of the cull.",
  ["1"] = {
    {file = "Audio/Transport/full_item_satyr-horns-c0154b5389bfee7972b8/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["item:savannah-lion-tusk"] = {
  hash = "2f89c8",
  fullHash = "2f89c8",
  text = "Savannah Lion Tusk. In the Barrens, Savannah Lion Tusks go from hunting trophies to ingredients in Chen Stormstout's legendary potent ale. The great cats roaming the Barrens carry sharp, heavy tusks. Prowlers, huntresses, prides ruled by patriarchs, and beasts like Humar the Pridelord all bear them. Travelers often take the teeth as proof of a successful hunt. Brewmaster Drohn in Ratchet uses the tusks with plainstrider kidneys and thunder lizard horns to recreate Chen Stormstout's famous namesake brew, a potent ale with a legendary kick few mortal gullets can withstand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_savannah-lion-tusk-412e67d5ed0e31a0bbb3/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["item:scaber-stalk"] = {
  hash = "b5c9c8",
  fullHash = "b5c9c8",
  text = "Scaber Stalk. In Darkshore, Barithras Moonshade seeks Scaber Stalks from a hidden cavern behind Cliffspring Falls. Scaber Stalks grow in a subterranean cave behind Cliffspring Falls, among the northeastern mountains of Darkshore. The pale mushrooms thrive in the damp, secluded cave network, far from ordinary forest growth. Their remote, hazardous home makes them rare to gather, and Barithras Moonshade in Auberdine commissions scouts to brave its darkness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scaber-stalk-8766b3b3b04e54f4a2ae/1-0000.mp3", duration = 24.1110204, start = 0},
  },
}
P.transport["item:scale-of-old-murk-eye"] = {
  hash = "b468cd",
  fullHash = "b468cd",
  text = "Scale of Old Murk-Eye. On Westfall's coast, Old Murk-Eye terrorizes the shore. Captain Grayson, the ghost at Westfall Lighthouse, needs a scale from the murloc as proof of his death. Old Murk-Eye turned Westfall's coast into a killing ground. Captain Grayson, the ghost bound to Westfall Lighthouse, says the cunning murloc rallied weaker-minded murlocs to raid the shore. Murk-Eye drove away the keeper's family, leaving the beacon dark when Grayson's ship struck the rocks. When the family returned to relight the flame, Murk-Eye attacked again and slaughtered them. Grayson seeks a scale from the creature as proof that the shore is clear of its fiercest predator.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scale-of-old-murk-eye-bdbcb53667986b0580a7/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["item:scarlet-armband"] = {
  hash = "3bea25",
  fullHash = "3bea25",
  text = "Scarlet Armband. In Deathknell, Scarlet Armbands mark the zealots pressing into Forsaken territory. Executor Arren demands them as proof that the newly risen have struck back. Scarlet Armbands mark the Scarlet Crusade's followers, from Initiates to fresh converts. The Crusade's red insignia warns newly risen Forsaken in Deathknell that danger waits close by. Crusaders make no distinction between the Scourge's mindless servants and the free-willed subjects of the Dark Lady. To them, every walking corpse must burn. Executor Arren gathers the armbands to confirm that enemy scouts southeast of Deathknell have died and that new Forsaken can defend their fledgling nation.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-armband-67c7b56b5d995df51774/1-0000.mp3", duration = 39.2097959, start = 0},
  },
}
P.transport["item:scarlet-crusade-documents"] = {
  hash = "a07883",
  fullHash = "a07883",
  text = "Scarlet Crusade Documents. At the Crusade's camp near Deathknell, a messenger carries Scarlet Crusade Documents through Tirisfal. The intercepted orders name field commanders and direct their forces, giving the Forsaken military leadership intelligence on Scarlet positions across the Glades. Meven Korgal carried the documents from the Crusade's encampment southeast of Deathknell. By order of the Highlord, they direct the captains of the Crusade's Tirisfal Regional Command. Captain Perrine must further fortify the southwest tower and gather information on the undead in Brill. Captain Vachon must crush undead movement near the northern tower, while Captain Melrose watches the borders of the Plaguelands. The orders name Scarlet field officers, their posts, and their duties across Tirisfal Glades. Executor Arren sees that Deathknell's local forces cannot use the full breadth of this intelligence. The captured documents become a newly awakened Forsaken's passport out of Deathknell. Carry them northeast, past Cold Hearth Manor, to Brill, and deliver them to Executor Zygand outside Brill Town Hall. With the orders in hand, Forsaken military leaders plan swift strikes against Scarlet commanders entrenched across the Glades.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-crusade-documents-7ea5fa54b6d14cecd17d/1-0000.mp3", duration = 67.9967347, start = 0},
  },
}
P.transport["item:scarlet-insignia-ring"] = {
  hash = "b45fca",
  fullHash = "b45fca",
  text = "Scarlet Insignia Ring. In Tirisfal Glades, Scarlet Insignia Rings mark the Crusade's members. In Brill, the Forsaken collect them as proof that another zealot has fallen. Every Scarlet Crusade fighter in Tirisfal Glades carries an insignia ring, from new neophytes and zealous friars to captains Melrache and Perrine. The Crusade's fiery sigil marks each ring, identifying members within an order consumed by paranoia. To outsiders, the rings identify Lordaeron's most fanatical human remnant. Deathguard Burgess in Brill collects the rings under orders from Varimathras, Lady Sylvanas's dreadlord lieutenant. The Forsaken see the Scarlet Crusade as a pestilence across their newly claimed homeland. Recruits bring the rings back to Brill as proof of a Crusader's death and of their loyalty to the throne of the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scarlet-insignia-ring-6d6d2b7d0732da4a1af6/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:scavenged-goods"] = {
  hash = "a4bac9",
  fullHash = "a4bac9",
  text = "Scavenged Goods. Around Deathknell, Forsaken gather Scavenged Goods from equipment boxes. Newly risen undead rely on these discarded supplies to arm and clothe the recruits who follow. New Forsaken rise in Deathknell's graveyard with little more than rotting burial shrouds. Nearby settlements and kingdoms offer the undead no aid, so they must salvage what they need. Deathguard Saltain gathers discarded weapons, tools, and garments from supply crates across the village, then gives them to the next recruits to rise.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scavenged-goods-726d78f13e455fef2582/1-0000.mp3", duration = 29.8579592, start = 0},
  },
}
P.transport["item:scavenger-paw"] = {
  hash = "66adfb",
  fullHash = "66adfb",
  text = "Scavenger Paw. In Deathknell, Scavenger Paw comes from the young, ragged wolves roaming the hills. Newly awakened Forsaken gather the severed paws for local caretakers to stitch into crude protective gear. Deathknell's newly returned Forsaken have little to spare. The Scourge and the Scarlet Crusade press against Tirisfal, so every scrap of hide and bone goes to practical use. Novice Elreth assists Shadow Priest Sarvis and gathers paws from scavenger wolves, along with bat wings. She uses them to make serviceable garments and armor for Forsaken who have just risen from their graves, still disoriented by their return.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scavenger-paw-e35a32f925482cc13c63/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["item:scorched-spider-fang"] = {
  hash = "8ba42f",
  fullHash = "8ba42f",
  text = "Scorched Spider Fang. Across the Wetlands, Scorched Spider Fangs are taken from Cave Stalkers and Leech Stalkers. Furen Longbeard in Stormwind needs fifty to strengthen mail for Alliance warriors. In Stormwind, blacksmith Furen Longbeard uses unusual methods to strengthen mail. He calls for fifty scorched fangs from the giant spiders of the Wetlands. Their dense, venomous, toughened substance reinforces the mail links as he tempers them. Cave Stalkers and Leech Stalkers bear the fangs Furen needs. They live in the Wetlands' sunken valleys and burrows, where damp and rot surround their hardened, scorched mandibles. Gathering fifty means venturing into deep hollows and facing the spiders in their swarms.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scorched-spider-fang-13f11bb6c3fbcc76bc27/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["item:scroll-of-messaging"] = {
  hash = "0b8443",
  fullHash = "0b8443",
  text = "Scroll of Messaging. In Stonetalon, Gaxim Rustfizzle has a plan for the Scroll of Messaging. The gnome engineer means to use its sending spell to trigger remote explosives. Gaxim Rustfizzle plans to turn a message into a blast at the Venture Company's logging operation. He will combine the scroll's transmission incantation with volatile NG-5 charges. The explosion is meant to distract the guards, giving operatives time to slip past and steal engineering schematics and confidential correspondence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_scroll-of-messaging-eb71551b0c3334870818/1-0000.mp3", duration = 26.5926531, start = 0},
  },
}
P.transport["item:sea-creature-bones"] = {
  hash = "1e6853",
  fullHash = "1e6853",
  text = "Sea Creature Bones. On Darkshore, Sea Creature Bones come from massive marine carcasses washed ashore. Gwennyth Bly'Leggonde gathers skeletal samples for the Temple of the Moon in Darnassus, where the cause of the strandings is under investigation. Massive sea creatures have begun flinging themselves onto Darkshore’s shallows, where they perish. Among them are giant threshers far larger than those native to the local waters. Night elves see the sudden increase as an ominous portent. Gwennyth Bly'Leggonde, sent by the Temple of the Moon to Auberdine, gathers bones from the beached creatures. Hippogryphs carry the specimens to Darnassus for close examination. The immense carcasses attract local scavengers. Greymist murlocs gather around the dead and dying creatures, feeding on their remains and fiercely defending the feeding grounds. The murlocs are too weak to hunt beasts of this size, but investigators and adventurers must fight through their packs along Mist's Edge to recover bone fragments for study.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sea-creature-bones-293401354fbee1795f64/1-0000.mp3", duration = 56.8685714, start = 0},
  },
}
P.transport["item:sea-turtle-remains"] = {
  hash = "915de9",
  fullHash = "915de9",
  text = "Sea Turtle Remains. Along Darkshore, giant sea turtles lie dead on the coast and beneath the waves. Their remains go to researchers in Auberdine, who study the growing number of strandings. Giant sea creatures are washing ashore along Darkshore, while others lie beneath the water near sunken wrecks. In Auberdine, Gwennyth Bly'Leggonde oversees the collection of bone fragments and tissue from the bodies. The Temple of the Moon in Darnassus urgently requests these samples. Its scholars and priestesses fear the creatures may be fleeing an unnatural disturbance in the waters around Teldrassil. Recovering the remains is dangerous. Murloc tribes along the coast routinely gather around the huge carcasses, picking bones clean and nesting beside them. Scholars need fresh bone fragments and tissue before the scavengers destroy evidence that could explain the creatures' fatal migration.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sea-turtle-remains-2057ef1ada47389b7c30/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["item:sealed-description-of-thredd-s-visitor"] = {
  hash = "1c3250",
  fullHash = "1c3250",
  text = "Sealed Description of Thredd's Visitor. Warden Thelwater seals a report about a visitor to Bazil Thredd in the Stormwind Stockade. The confidential account helps track a covert operative moving through Stormwind's political and criminal spheres. Prisoner Bazil Thredd spent years in the Stockade without a visitor. Then a quiet man began coming once or twice each week, carrying valid identification papers under the name Maelik. Warden Thelwater took note of the unusual visits and wrote down the man's appearance. He sealed the description so no meddling eyes could read it before proper investigators acted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-description-of-thredd-s-visitor-b050152c7ee277b4c039/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["item:sealed-envelope"] = {
  hash = "7aab3c",
  fullHash = "7aab3c",
  text = "Sealed Envelope. Fizziks has sealed Venture Company secrets inside the Sealed Envelope for delivery to Sputtervalve in Ratchet. After the Venture Company cast goblin engineer Fizziks out of its logging operations in the Stonetalon Mountains, he smuggled out company secrets. The envelope holds internal manuals, operating procedures, and technical specifications. Among them are schematics for the Super Reaper 6000, a machine built for industrial clear-cutting. Fizziks sends the documents south to Sputtervalve, an engineer in the neutral goblin port of Ratchet. The Steamwheedle Cartel's business rivals have little personal love or trust for Fizziks, yet the designs have undeniable engineering value. They reveal Venture Company mechanical ingenuity and give independent engineers a chance to exploit its advanced logging technologies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-envelope-85309ffd35b3402ad9f5/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["item:sealed-note-to-elling"] = {
  hash = "2cd2ee",
  fullHash = "2cd2ee",
  text = "Sealed Note to Elling. Jorgen sends a sealed dispatch through Stormwind to Elling Trias, the proprietor of Trias' Cheese. The fisherman’s message draws Trias into a quiet inquiry about a vanished diplomat. Jorgen gives a strict charge for the sealed note in Stormwind: place it in Elling Trias's hands and keep silent. The stakes leave no room for careless talk. Trias runs a cheese shop in the Trade District, where Jorgen's message brings the inquiry into the diplomat's disappearance to his counter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-note-to-elling-14f0e954d65ada947d60/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["item:sealed-note-to-watcher-backus"] = {
  hash = "9659c1",
  fullHash = "9659c1",
  text = "Sealed Note to Watcher Backus. In Stormwind, Elling Trias sends a sealed note to Watcher Backus in Duskwood. He asks the Night Watch guard to report Defias activity near Darkshire. Elling Trias agrees to use his contacts to help search for the missing diplomat. He seals a note for Watcher Backus, a Night Watch guard stationed in Duskwood. Trias sends a traveler south through the forest to deliver it by hand. He hopes Backus will report any Defias seen near Darkshire.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sealed-note-to-watcher-backus-e40f1f87a360508aede7/1-0000.mp3", duration = 26.5926531, start = 0},
  },
}
P.transport["item:searing-collar"] = {
  hash = "b89366",
  fullHash = "b89366",
  text = "Searing Collar. At Skull Rock in Durotar, Burning Blade cultists wear Searing Collars in their rites. The heated torcs burn their flesh as the cultists attune themselves to demonic power. The Burning Blade gathers for dark rites in Skull Rock, just east of Orgrimmar. Cultists, neophytes, and thugs wear Searing Collars around their necks, enduring heat that brands and sears their skin. Margoz, a hermit, studies the cruel devices. He suspects the burning and the enchantments bound to the metal attune the wearers to demonic energies. What part do these collars play in the corruption spreading through orc society under the Horde’s nose?",
  ["1"] = {
    {file = "Audio/Transport/full_item_searing-collar-16d57b3b0fe8a220f81f/1-0000.mp3", duration = 38.5044898, start = 0},
  },
}
P.transport["item:searing-coral"] = {
  hash = "5eabe4",
  fullHash = "5eabe4",
  text = "Searing Coral. Along the Wetlands coast, Searing Coral is gathered from living iron coral beneath the sea. Tinkerers and smiths value the mineral-rich material for its unusual ability to endure heat and strengthen armor. Searing Coral grows in the cold sea south of Menethil Harbor. The living iron coral thrives in saltwater, yet yields mineral-rich material that withstands extreme heat. Harvesters pry the hardened growths loose through dangerous surf, with coastal predators nearby. Dwarven smiths do not traditionally work Searing Coral. In Ironforge, curious gnome craftsmen such as Klockmort Spannerspan use methods from veteran armorsmith Furen Longbeard. They smelt the coral and hammer it into metal alloys, making lightweight, durable armor for aspiring warriors.",
  ["1"] = {
    {file = "Audio/Transport/full_item_searing-coral-3e4c009cdf3e19973b51/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["item:secure-crate"] = {
  hash = "104267",
  fullHash = "104267",
  text = "Secure Crate. In the Barrens, a Secure Crate waits for a traveler to carry it to Ratchet. Potions and alchemical goods inside are bound for the Eastern Kingdoms. Couriers, caravans, and goblin ships carry trade between Kalimdor and the Eastern Kingdoms. When a Barrens caravan misses its departure, travelers take fragile cargo like this Secure Crate down to the coast. It holds potions, alchemical goods, and reagents for associates across the Great Sea. The crate is sealed against the Barrens trails and the sea spray on its voyage. The crate’s land journey ends at the Ratchet docks, where Wharfmaster Dizzywig oversees shipping. Ratchet is a neutral port for goods crossing the sea, including cargo bound for Blackwater Cove. Dizzywig works under the Steamwheedle Cartel’s ledger, recording parcels and freight before loading them onto the next departing vessel. Ratchet links the Old World with the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_secure-crate-c082f0cc172d13db3985/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["item:senir-s-report"] = {
  hash = "cdc8cc",
  fullHash = "cdc8cc",
  text = "Senir's Report. In the cold foothills of Dun Morogh, Senir Whitebeard sends word of the Frostmane trolls to Ironforge. His report carries findings gathered under King Magni Bronzebeard’s directive for Senator Barin Redstone. Senir Whitebeard’s report gathers mountaineer observations from scouting against Frostmane trolls in Dun Morogh’s crags. Stationed in the cold foothills, Senir includes his brother Grelin’s account of Coldridge Valley, where Grelin acted under King Magni Bronzebeard’s sanction. Senir sends the findings to Senator Barin Redstone in Ironforge’s High Seat and advises couriers to leave out how much outside help he needed to compile them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_senir-s-report-08da0f3c791fdc06930c/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["item:serena-s-head"] = {
  hash = "acc35b",
  fullHash = "acc35b",
  text = "Serena's Head. At the Dry Hills in the northern Barrens, Serena Bloodfeather's head is sought as proof of her death. Darsok Swiftdagger plans to display it on a Horde supply wagon as a warning against further harpy raids.",
  ["1"] = {
    {file = "Audio/Transport/full_item_serena-s-head-711edd766fece96410e1/1-0000.mp3", duration = 11.8595918, start = 0},
  },
}
P.transport["item:serpentbloom"] = {
  hash = "5cd3d2",
  fullHash = "5cd3d2",
  text = "Serpentbloom. Serpentbloom is a rare, subterranean herb found growing only in the dark depths of the Wailing Caverns. Its potent natural properties have drawn the keen interest of the Forsaken's Royal Apothecary Society. Serpentbloom grows exclusively within the damp, shadowy tunnels of the Wailing Caverns beneath the Barrens. Rooted in an ecosystem warped by unrestrained Emerald Dream energies, the plant thrives far from sunlight and often harbors venomous serpents nesting among its stems. Because the cave system is overrun with hostile beasts and corrupted druids, few who venture inside ever return with viable specimens. Operating from the Pools of Vision beneath Thunder Bluff, Apothecary Zamah collects Serpentbloom on behalf of the Royal Apothecary Society of Undercity. The Forsaken continuously seek out virulent, strange, and chemically potent vegetation across Kalimdor to fuel their research for the Dark Lady. Zamah believes that harvesting Serpentbloom in significant quantities could yield valuable breakthroughs for Forsaken alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_serpentbloom-2f08018057f637e01ca4/1-0000.mp3", duration = 59.2718367, start = 0},
  },
}
P.transport["item:sethir-s-journal"] = {
  hash = "3e95b6",
  fullHash = "3e95b6",
  text = "Sethir's Journal. On Teldrassil, Sethir's Journal was recovered through stealth. Its pages confirm that corruption from mainland Kalimdor has reached the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sethir-s-journal-b9eebe53c4af2d666609/1-0000.mp3", duration = 8.51591837, start = 0},
  },
}
P.transport["item:sevren-s-orders"] = {
  hash = "e6e28d",
  fullHash = "e6e28d",
  text = "Sevren's Orders. In Brill, Magistrate Sevren sends a proven Forsaken agent to the Undercity. The orders direct the agent to Bethor Iceshard in the Magic Quarter. Skilled Forsaken agents who prove themselves against the Scourge in Tirisfal Glades are summoned south as their people strengthen their hold on Lordaeron. Magistrate Sevren writes the orders as an introduction and credentials for Bethor Iceshard, one of the Dark Lady's foremost arcane practitioners in the Magic Quarter. Sevren knows only that the assignment concerns reaching out to an errant lich. The Undercity's high mages give the summons their full authority.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sevren-s-orders-74d8167f1f29f9d31ede/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
P.transport["item:shadowhide-pendant"] = {
  hash = "be2e8c",
  fullHash = "be2e8c",
  text = "Shadowhide Pendant. In Redridge, Shadowhide Pendant charms pass among gnolls working with Morganth. Lakeshire accepts ten as proof that its law has been enforced. Shadowhide Pendant charms pass among the Shadowhide warriors, brutes, and spellcasters. Deep in Redridge's hills, the clan has gathered under Lieutenant Fangore and fallen under the sway of Morganth, a rogue wielder of the Arcane. To Lakeshire's townspeople, the crude charms mark an organized threat harassing settlements for an enemy of the Crown. Stormwind law, upheld by Magistrate Solomon, sets death as the sentence for actively aiding a known criminal of the realm. Royal reinforcements are too few, so Bailiff Conacher at Lakeshire Town Hall relies on adventurers to keep the peace. Ten Shadowhide Pendants prove that gnolls obeying Morganth's orders have faced frontier justice.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shadowhide-pendant-fddbb4446e1882ef4354/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["item:shaman-voodoo-charm"] = {
  hash = "30a8be",
  fullHash = "30a8be",
  text = "Shaman Voodoo Charm. In Ban'ethil Barrow Den, Gnarlpine shamans wield the Shaman Voodoo Charm. Its vile magic can sever a sleeping druid's spirit from the body. The Gnarlpine tribe has fallen into madness and corruption on Teldrassil. Within Ban'ethil Barrow Den, its shamans wield magic beyond ordinary wilderness sorcery. Their voodoo charms let them tear a sleeping druid's consciousness from the mortal realm and trap it in the Emerald Dream. The furbolgs then animate the empty body. Night elf protectors become mindless guardians, killing anyone who enters the barrows.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shaman-voodoo-charm-1f8cdc3267277cbecefa/1-0000.mp3", duration = 32.7314286, start = 0},
  },
}
P.transport["item:shard-of-water"] = {
  hash = "7f8858",
  fullHash = "7f8858",
  text = "Shard of Water. Along the Barrens coast, Islen Waterseer receives the Shard of Water from a shaman who has faced corruption. Shamans must understand balance, life, and preservation to master water. In the Call of Water, they travel to corrupted springs, even crossing the sea to blighted Silverpine Forest. After purifying the tainted waters, a shaman receives the Shard of Water. Returning the crystal token to Islen Waterseer on the rocky Barrens shore proves the initiate's worth and provides the final key to forge a Water Totem.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shard-of-water-83c83427acae8d937360/1-0000.mp3", duration = 31.0595918, start = 0},
  },
}
P.transport["item:shaw-s-report"] = {
  hash = "55cc75",
  fullHash = "55cc75",
  text = "Shaw's Report. In Westfall, Shaw's Report carries confidential intelligence from SI:7 to Gryan Stoutmantle. Written by Master Mathias Shaw, it describes the Stonemasons Guild, Edwin VanCleef, and their grievance with the crown after Stormwind was rebuilt.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shaw-s-report-21981be6542073408a2c/1-0000.mp3", duration = 14.3412245, start = 0},
  },
}
P.transport["item:shimmering-frond"] = {
  hash = "f90dd9",
  fullHash = "f90dd9",
  text = "Shimmering Frond. In the Oracle Glade, a strange plant casts a twisting, shimmering aura. Its fronds come from a species native to the Swamp of Sorrows, far across the Great Sea. A radiant plant grows among the trees near the Oracle Glade. Its aura pulses, and its fronds shimmer in the woodland light. Denalan, who tends planters beside Lake Al'Ameth, recognizes the leaves as belonging to a species from the Swamp of Sorrows in the Eastern Kingdoms. How seeds from that distant marsh crossed the Great Sea and took root on Teldrassil remains a mystery. Denalan is growing specimens in his own soil to study them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shimmering-frond-4f86839877a4a5c541e1/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:shimmerweed"] = {
  hash = "e42404",
  fullHash = "e42404",
  text = "Shimmerweed. On Shimmer Ridge, Frostmane trolls gather shimmerweed for their rituals. Dwarven brewmaster Rejold Barleybrew wants to test its sharp flavor in his stout. The Frostmane trolls tend shimmerweed on the icy crags of Shimmer Ridge, high above Dun Morogh's lowlands. They harvest the plant and store it in woven baskets throughout their camps, where it fuels their sacred rituals. Few mountaineers beyond troll society pay the herb much mind, though inventive outsiders have taken an interest. In Brewnall Village, brewmaster Rejold Barleybrew suspects shimmerweed may be the missing piece in his attempt to brew the ultimate dwarven stout. He has detected the herb's pungent, unmistakable flavor and wants to see what it brings to his fermenting vats. Rejold hires travelers to slip into Frostmane camps, evade the hostile trolls, and bring back bushels.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shimmerweed-f590ead081d73d463edf/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["item:shindrell-s-note"] = {
  hash = "f4ff7c",
  fullHash = "f4ff7c",
  text = "Shindrell's Note. In Astranaar, Shindrell Swiftfire writes a missive about corruption near the town and along Ashenvale's coast. She sends the intelligence report east through the forest to Kayneth Stillwind. Sentinels and druids coordinate to watch Ashenvale's borders as unrest spreads through the forest. In Astranaar, Sentinel Shindrell Swiftfire writes of troubling disturbances along the western coast and among the central canopies. She addresses her report to Kayneth Stillwind, a druid at the shrine of Forest Song in the Nightsong Woods to the east. Couriers carry Shindrell's firsthand observations to aid Kayneth's investigation of corruption creeping through the sacred groves.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shindrell-s-note-a4f22af158ae7fcbb8c2/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["item:shipment-of-boots"] = {
  hash = "c19d2d",
  fullHash = "c19d2d",
  text = "Shipment of Boots. Off the Barrens coast, Shipment of Boots lies in a Southsea encampment south of Ratchet. Drizzlik sent the crate from Booty Bay for Gazlowe's trade network, but the pirates seized it before it reached port. Gazlowe arranged for Drizzlik, a clothing merchant in Booty Bay, to send boots to Ratchet. Southsea Freebooters patrolling the Merchant Coast ambushed the ship and carried the crates to their beach encampments south of the harbor. They scattered the stolen goods among their tents and shanties, and the shipment remains there, far from Ratchet's docks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipment-of-boots-d3b2a158b62318a9e463/1-0000.mp3", duration = 32.0783673, start = 0},
  },
}
P.transport["item:shipment-of-iron"] = {
  hash = "e77ecf",
  fullHash = "e77ecf",
  text = "Shipment of Iron. In Hillsbrad Fields, a crate of raw iron waits at the human smithy. The metal feeds local arms production, making the shipment a target for Forsaken forces seeking to cut the supply lines that arm the townsfolk. Across the Hillsbrad Foothills, human peasants have mounted stiff resistance against Tarren Mill. Much of their strength comes from the smithy at the southwestern edge of Hillsbrad Fields, where Blacksmith Verringtan and his apprentices work round the clock, making weapons and armor from heavy shipments of iron. Forsaken commanders ordered the forge put out, its smiths killed, and its stored metal seized for the Horde war effort, hoping to break the farmers’ resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipment-of-iron-2b994217cab5d32b269e/1-0000.mp3", duration = 36.9632653, start = 0},
  },
}
P.transport["item:shipping-schedule"] = {
  hash = "f267f5",
  fullHash = "f267f5",
  text = "Shipping Schedule. At Jerod's Landing, the Defias Brotherhood moves contraband along Elwynn's waterways. Its dockmaster guards a schedule that maps shipments between Redridge and Westfall, and SI:7 wants it. South of Goldshire, Jerod's Landing sits on the Elwynn bank of the Nazferiti River. The Defias Brotherhood seized the landing as a hub for river traffic. From there, they move contraband between Redridge and Westfall along waterways beyond the Stormwind Guard's notice. Their dockmaster keeps the Shipping Schedule close, recording these shipments. Master Mathias Shaw leads SI:7, Stormwind's intelligence agency, and ordered the schedule stolen. It can map Defias supply lines, while taking it tests new operatives. The theft must be made inside the dock house, from the dockmaster's pockets. If the operative is caught, SI:7 denies any connection, leaving no trail to its barracks in Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_shipping-schedule-b3c3476a8238c56781f5/1-0000.mp3", duration = 55.1444898, start = 0},
  },
}
P.transport["item:sida-s-bag"] = {
  hash = "196626",
  fullHash = "196626",
  text = "Sida's Bag. In the Wetlands, Sida's Bag lies swallowed in an ooze near Ironbeard's Tomb. Sida, a resident of Menethil Harbor, fled after throwing her satchel at one of the slimes during her weekly visit; the bag and its contents must be recovered from the acidic creatures. Sida visits Ironbeard's Tomb near Dun Modr each week. Dreadful, dripping oozes ambushed her there, and panic drove her to fling her satchel at one of them. The ooze absorbed the bag into its body. The distraction gave Sida time to escape alive and return to Menethil Harbor, while her possessions remained trapped inside an unknown slime. The oozes around Ironbeard's Tomb range from crimson to monstrous, and look much alike. Sida's Bag can be found by cutting down the marsh slimes until the swallowed satchel emerges intact. Acidic muck has soaked the durable sack, but its contents remain preserved. Sida reclaims her belongings, then discards the ruined, slime-coated exterior and offers the washed-out container to whoever braved the marsh on her behalf.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sida-s-bag-0505e2378e72a4518ac4/1-0000.mp3", duration = 60.2383673, start = 0},
  },
}
P.transport["item:signed-recruitment-letter"] = {
  hash = "396341",
  fullHash = "396341",
  text = "Signed Recruitment Letter. Kargal Battlescar sends the Signed Recruitment Letter west from the Far Watch Post. His mark directs new recruits to report for duty at the Crossroads. At the Far Watch Post, Kargal Battlescar prepares recruits for service in the Barrens. The post stands east of the Southfury River, where newcomers cross from Durotar. When a conscript proves ready to Kargal, he stamps and signs a letter of introduction. The orders send recruits west along the road to the Crossroads. There, Sergra Darkthorn coordinates supplies and the defense of the dry plains. Kargal's orders carry his personal contempt for the officer who awaits the recruit. He calls Sergra Darkthorn an abrasive shaman who talks in circles around soldiers. Kargal openly questions Warchief Thrall's high opinion of her. Even so, the dispatch must reach Sergra's hands before any further assignments at the Crossroads are granted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_signed-recruitment-letter-f0f867477c6ce5c922e2/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["item:silithid-egg-the-barrens"] = {
  hash = "844177",
  fullHash = "844177",
  text = "Silithid Egg (The Barrens). Across the Field of Giants, silithid eggs lie buried beneath the soil. Horde researchers gather them to learn about the swarm spreading through the southern Barrens. Silithid mounds rise from the Field of Giants as strange insect-like creatures churn the earth. Their eggs lie beneath the hardened soil, guarded by territorial silithid. The Horde knows little about these creatures, but scouts at the Crossroads have seen signs of coordination and intelligence beyond that of ordinary wild beasts. Unhatched eggs may help scholars in Orgrimmar learn about the silithid’s life cycle and nature. Silithid eggs must be dug from the mounds with an adapted digging claw. The creatures defend their underground nurseries fiercely, swarming anyone who threatens their unhatched young. Korran, a troll researcher, needs intact specimens for study before the swarm spreads farther across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silithid-egg-the-barrens-22b02916cc82a40e3392/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["item:silixiz-s-tower-key"] = {
  hash = "dfba90",
  fullHash = "dfba90",
  text = "Silixiz's Tower Key. Foreman Silixiz carries the key to the Venture Company tower near the Sludge Fen. Shattered Hand operatives must take it from his pocket as part of an undercover sabotage assignment. North of the Sludge Fen, the Venture Company keeps its tower under tight security. Grand Foreman Puzik Gallywix oversees the isolated lookout, while goblin mercenaries patrol the compound. Outside, Foreman Silixiz carries the tower key. A Shattered Hand operative from Orgrimmar must steal it and keep it. Force will not do: the operative must enter unseen and pick Silixiz's pocket, proving their stealth before climbing into the tower's toxic upper levels.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silixiz-s-tower-key-a3fad68168480bec238f/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["item:silver-dawning-s-lockbox"] = {
  hash = "feeab3",
  fullHash = "feeab3",
  text = "Silver Dawning's Lockbox. Off the Darkshore coast, Silver Dawning's Lockbox lies in the wreck of a ship lost to coastal murlocs. Inside are the fallen captain's personal effects and ship log. The Silver Dawning sailed across the sea toward Auberdine when coastal murlocs attacked. They drove the ship beneath the waves north of the harbor, and the captain died in the assault. The flooded hull still holds the captain's personal lockbox, with the ship's log and private belongings inside. Recovering them could bring a final measure of peace to the surviving crew ashore.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silver-dawning-s-lockbox-8c578143eee0b4d97937/1-0000.mp3", duration = 31.6865306, start = 0},
  },
}
P.transport["item:silvery-spinnerets"] = {
  hash = "429816",
  fullHash = "429816",
  text = "Silvery Spinnerets. Near Wellspring Lake, Silvery Spinnerets are harvested from Lady Sathrah in northern Teldrassil. Her silver webs once gathered healing evening dew for the Temple of the Moon. The Sisterhood of Elune seeks the spinnerets for a sacred rite honoring her soul. Lady Sathrah once spun shimmering webs by moonlight near Wellspring Lake. Her silver silk gathered evening mist into healing dew prized by the Sisterhood of Elune in Darnassus. But corruption reached her in Teldrassil, driving her into violent madness. Sathrah threatened her brood and the surrounding forest. Priestess A'moora asks travelers to end her suffering and recover her spinnerets, bringing mercy to a once-revered creature of the great boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_silvery-spinnerets-fc5503c133dfa81a40a7/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["item:simple-memorandum"] = {
  hash = "e8924e",
  fullHash = "e8924e",
  text = "Simple Memorandum. In Coldridge Valley, the Simple Memorandum sends novice gnome warriors to Anvilmar. It directs them to train with Thran Khorman for the war to take back Gnomeregan. The Simple Memorandum sends young gnome fighters to train in Anvilmar. As they face local wildlife and troggs in Coldridge Valley, they receive letters of introduction. This one directs its bearer to Thran Khorman, the warrior trainer there. Gnomes bring intellect and contraptions to battle, but taking back Gnomeregan calls for strength and martial discipline. The memorandum tells its bearer to leave early training behind and learn the art of war from Thran.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-memorandum-05cce001e477d271d388/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["item:simple-rune"] = {
  hash = "5d2b4a",
  fullHash = "5d2b4a",
  text = "Simple Rune. In Coldridge Valley, Thran Khorman calls young dwarven warriors to Anvilmar. The Simple Rune is an inscribed stone token that directs recruits to seek instruction from their warrior trainer. The Simple Rune marks the start of a recruit’s training. Thran Khorman gives the inscribed stone to promising young fighters who have begun clearing threats from Coldridge Valley. Its marks are a formal summons, not a magical charm. A recruit who reads it is expected to report to Thran inside Anvilmar, where the warrior trainer teaches basic combat and offers practical advice for surviving Dun Morogh’s hostile wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-rune-7305011a3409ebb8977e/1-0000.mp3", duration = 34.6644898, start = 0},
  },
}
P.transport["item:simple-sigil"] = {
  hash = "d06a9f",
  fullHash = "d06a9f",
  text = "Simple Sigil. In Shadowglen, a Simple Sigil calls novice night elf warriors to training with Alyissia. It marks their first step into Teldrassil’s defense. In Shadowglen, Conservator Ilthalaine guides young night elves as they seek their calling. A runner brings a Simple Sigil from the warrior trainer Alyissia, and Ilthalaine gives it to fledgling warriors. Its inscription tells each recruit to report for instruction. The token marks the start of their martial training as troubling times come to the World Tree. Alyissia uses the sigil to speak with recruits about the kaldorei’s pressing needs. Teldrassil’s recent growth, corruption spreading among forest beasts, and the rediscovery of distant lands such as Feralas have stretched night elven protectors thin. The sigil holds no power. It welcomes a recruit among the guardians charged with shielding their people from emerging threats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-sigil-b548c569124d535d6dc2/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["item:simple-tablet"] = {
  hash = "cba972",
  fullHash = "cba972",
  text = "Simple Tablet. At the Valley of Trials, Gornek gives new troll warriors a message to take to Frang. Gornek gives new troll warriors a message from Tar'sere, addressed to Frang, the warrior trainer near the Den. It introduces the recruit to combat training in Durotar and asks them to present themselves to Frang. The message calls on them to take up weapons for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_item_simple-tablet-ac26fb4112c029be079a/1-0000.mp3", duration = 20.7412245, start = 0},
  },
}
P.transport["item:singed-scale"] = {
  hash = "74b25f",
  fullHash = "74b25f",
  text = "Singed Scale. In Durotar, Singed Scale comes from the charred plates of electrified thunder lizards. Horde warriors bring the scales to prove their endurance and learn defensive combat. Horde veterans judge a warrior by the blows they can bear while shielding allies. In Thunder Ridge, a canyon in western Durotar, lightning hides and thunder lizards crackle with storm energy. Hunting these beasts means enduring relentless electrical shocks and crushing blows. Their blackened scales show that a fighter can withstand punishing assaults and hold firm under pressure. At the Far Watch Post, on the border between Durotar and the Barrens, the veteran warrior Uzzek asks initiates for five scales before teaching them. He believes they need physical toughness before they can learn stances and tactical defense. Bringing the scales proves they have the fortitude to join thick hide, heavy armor, and careful footwork into a firm defense against the Horde’s enemies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_singed-scale-8f9d9e3c09f364a05164/1-0000.mp3", duration = 52.7934694, start = 0},
  },
}
P.transport["item:skeleton-finger"] = {
  hash = "55b269",
  fullHash = "55b269",
  text = "Skeleton Finger. In Duskwood, Skeleton Finger is gathered from the restless dead. Madame Eva of Darkshire collects these remains with ghoul fangs and spider venom to make protective talismans. The dead rise throughout Duskwood, from skeletal raiders and warriors to necrotic mages and fiends. Most travelers leave their foul remains untouched, but fortune tellers and mystics prize their cold essence. Madame Eva, the seer of Darkshire, gathers the bony fingers to bind their lingering necrotic energies into the Totem of Infliction, a ward that strikes back at attackers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skeleton-finger-736858226a6303239d25/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["item:skin-of-sweet-rum"] = {
  hash = "c4041a",
  fullHash = "c4041a",
  text = "Skin of Sweet Rum. At the Lion's Pride Inn in Goldshire, Skin of Sweet Rum is bound for Lakeshire, where war has thinned the tavern's stores. Lakeshire's tavern supplies are running low as the Blackrock orc invasion cuts off the roads into the Redridge Mountains. Barkeep Daniels needs drink for the town guards and refugees, so he sends travelers to gather regional specialties. Among them is a waterskin of sweet rum from the Lion's Pride Inn in Goldshire.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skin-of-sweet-rum-baf8693dd68c69b450dc/1-0000.mp3", duration = 24.9208163, start = 0},
  },
}
P.transport["item:skittering-blood"] = {
  hash = "2e53be",
  fullHash = "2e53be",
  text = "Skittering Blood. Skittering Blood feeds the Royal Apothecary Society's work on a New Plague. The reagent comes from arachnids in the Skittering Dark of Silverpine Forest, where Forsaken alchemists seek a weapon against the Scourge and humanity. Skitterweb lurkers, strikers, and their broodmother Krethis the Shadowspinner yield a venomous blood. Apothecary Renferrel found that, refined with toxins from grizzled bear hearts, it forms the base of an exceptionally lethal elixir. Its contaminating agents make it useful in the Apothecarium's chemical experiments. In the Undercity, Master Apothecary Faranell directs the Royal Apothecary Society's search for a New Plague. The Forsaken face Scourge hordes and hostile human remnants, and turn to biological warfare to even the odds. Faranell studies the blood's toxic strength as he works toward a contagion that can destroy unlife and living flesh alike.",
  ["1"] = {
    {file = "Audio/Transport/full_item_skittering-blood-38f18cd258f3d7c8490c/1-0000.mp3", duration = 52.244898, start = 0},
  },
}
P.transport["item:sleepers-key"] = {
  hash = "1d3bfe",
  fullHash = "1d3bfe",
  text = "Sleepers' Key. At Stonetalon Peak, Sleepers' Key helps guard a sacred druidic vault. Night elf druids made it one of three enchanted keys for the Talon Den Hoard. The Talon Den rises on Stonetalon Peak as a redoubt and sanctum for the druids of Kalimdor. To guard sacred relics and potent treasures from unwanted attention, night elf keepers built a system of locks and hidden caches. Sleepers' Key is one of three keys that together form a protective ward. The key lies in a secluded cache deep in the den, opened with the Gatekeeper's Key hidden near the threshold. The Claw Key and the Barrow Key complete the set. Set all three into the Talon Den Hoard's stone locks, and the ward fades, revealing the ancient items within.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sleepers-key-53abde7c68897383a8b1/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["item:smoky-iron-ingot"] = {
  hash = "9eadff",
  fullHash = "9eadff",
  text = "Smoky Iron Ingot. At the Windshear dig sites, kobolds smelt Smoky Iron Ingots from ore they pull from the Stonetalon Mountains. Orcish armorers prize the bars as raw material for sturdy mail gear for Horde warriors. Kobolds smelt Smoky Iron Ingots in the Windshear Crag tunnels of the Stonetalon Mountains. They dig ore from the rocky slopes and heat it over crude, smoking fires. Residue and charcoal cling to the bars, but the metal remains dense and strong. Thun'grim Firegaze, a near-blind orc armorer, works from a rugged camp overlooking the Barrens. He asks for these ingots to make armor for proven Horde warriors. Alongside refined iron bars, powdered azurite, and volatile phlogiston, the smoky metal forms a resilient core for Brutal Hauberks.",
  ["1"] = {
    {file = "Audio/Transport/full_item_smoky-iron-ingot-17b0f6210c260c1683dd/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["item:smoldering-embers"] = {
  hash = "f324a7",
  fullHash = "f324a7",
  text = "Smoldering Embers. In the Charred Vale, Smoldering Embers remain after fire elementals are extinguished. Night elf Sentinels gather them as proof that the fires are being subdued. Venture Company logging and industry set the Charred Vale ablaze and stirred destructive forces from deep within the earth. Burning Ravagers, Burning Destroyers, and Rogue Flame Spirits then swept across the scorched basin. When an elemental is extinguished, its ash-covered core remains as a Smoldering Ember. These cinders show that the fires overrunning the vale are being brought under control.",
  ["1"] = {
    {file = "Audio/Transport/full_item_smoldering-embers-34402c5936d3414d59fb/1-0000.mp3", duration = 32.2612245, start = 0},
  },
}
P.transport["item:snellig-s-snuffbox"] = {
  hash = "07bb42",
  fullHash = "07bb42",
  text = "Snellig's Snuffbox. At the Lost Fleet, Snellig's Snuffbox remains with its undead owner among the wrecks. First Mate Fitzsimmons in Menethil Harbor wants it as proof his cursed crewmate has been put to rest. First Mate Snellig still clutches his snuffbox in a wreck off the northern Wetlands. When the Third Fleet of Kul Tiras ran aground there, its sailors and officers drowned beneath a mysterious power tied to a hidden treasure aboard the ships. Bound by that power, the drowned crew rose again as tortured spirits and skeletal undead. Snellig haunts the rotting hold of the wreck closest to the coastline. His snuffbox is a small, ordinary reminder of his mortal life at sea. First Mate Fitzsimmons, the disaster's sole living survivor, wants this possession returned as proof that at least one lost shipmate has found release from torment.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snellig-s-snuffbox-76c724b28047bdf4cc95/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["item:snufflenose-command-stick"] = {
  hash = "ddcecd",
  fullHash = "ddcecd",
  text = "Snufflenose Command Stick. In Ratchet, Mebok Mizzyrix sends trained gophers after blueleaf tubers in Razorfen Kraul. Mebok Mizzyrix has trained snufflenose gophers to find blueleaf tubers deep in Razorfen Kraul. The roots lie hidden beneath the thorny tunnels, where finding them is nearly impossible without help. Mebok, a merchant in Ratchet, avoids entering the quilboar dens himself. He gives adventurers the Snufflenose Command Stick to direct the gophers. From up to fifty paces away, the stick guides them to sniff out and uncover the roots.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snufflenose-command-stick-23cb0c04212794a389c5/1-0000.mp3", duration = 29.8579592, start = 0},
  },
}
P.transport["item:snufflenose-owner-s-manual"] = {
  hash = "55ddf0",
  fullHash = "55ddf0",
  text = "Snufflenose Owner's Manual. In Ratchet, Mebok Mizzyrix keeps Snufflenose Owner's Manual beside him. Marwig Rustbolt of Snuff Inc. wrote the booklet to explain how to send a trained Snufflenose Gopher after Blueleaf Tubers in Razorfen Kraul. Marwig Rustbolt, owner of Snuff Inc., wrote a guide to handling the company's trained snufflenose gophers. Their keen noses can detect Blueleaf Tubers buried underground from fifty paces away. The manual explains how to release a gopher from a ventilated crate and guide its rooting with a command stick. Prospectors direct it through Razorfen Kraul's thorns and quilboar tunnels to find the tubers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_snufflenose-owner-s-manual-ea3e39282888d791e5e1/1-0000.mp3", duration = 34.4032653, start = 0},
  },
}
P.transport["item:sodium-nitrate"] = {
  hash = "44c3a7",
  fullHash = "44c3a7",
  text = "Sodium Nitrate. At Bael Modan, Sodium Nitrate helps the dwarves blast through the southern Barrens’ stone. Gann Stonespire seeks the chemical for charges against the fortress. Dwarven excavators at Bael Modan use Sodium Nitrate to break through the southern Barrens’ rock. The Bael'dun expedition entered the Stonespire tribe’s ancestral lands with earthmovers and blasting reagents. Riflemen, soldiers, and officers carry the chemical inside the excavation works and nearby fortress.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sodium-nitrate-074cd7f0927feab2b8f6/1-0000.mp3", duration = 26.9061224, start = 0},
  },
}
P.transport["item:solomon-s-plea-to-darkshire"] = {
  hash = "c8814d",
  fullHash = "c8814d",
  text = "Solomon's Plea to Darkshire. Magistrate Solomon asks Darkshire for aid as Lakeshire faces mounting threats. His urgent letter to Lord Ello Ebonlocke requests the Night Watch to help defend Redridge. Lakeshire faces attacks from Blackrock orcs, gnolls, and murlocs, with few reinforcements arriving from Stormwind. Magistrate Solomon sends a formal plea to Mayor Ello Ebonlocke in Darkshire, asking him to send Night Watch militia north into Redridge. With central military support failing across southern Azeroth, human settlements must seek help from one another to survive.",
  ["1"] = {
    {file = "Audio/Transport/full_item_solomon-s-plea-to-darkshire-855c159b48996dc38f28/1-0000.mp3", duration = 32.8097959, start = 0},
  },
}
P.transport["item:solomon-s-plea-to-westfall"] = {
  hash = "cb6ed8",
  fullHash = "cb6ed8",
  text = "Solomon's Plea to Westfall. In Lakeshire, Magistrate Solomon sends an urgent appeal to Westfall for help against Blackrock orcs and gnolls. He asks Gryan Stoutmantle to send the People's Militia while Stormwind's royal army fails to answer. Blackrock orcs and hostile gnolls threaten Redridge, and Magistrate Solomon is isolated in Lakeshire. Stormwind's royal army has not arrived in force to defend the region's borders. With no time to wait for support from the capital, Solomon writes to seek help beyond the regular army. Word has reached him of a volunteer defense force forming in Elwynn to the west, so he appeals to the People's Militia. Solomon addresses his message to Gryan Stoutmantle, a veteran warrior organizing Westfall's frontier defense. He hopes Stoutmantle can spare fighters for Lakeshire until Stormwind sends regular reserves. An adventurer carries the document. With Stormwind's outlying territories poorly coordinated, local magistrates must arrange mutual aid on their own.",
  ["1"] = {
    {file = "Audio/Transport/full_item_solomon-s-plea-to-westfall-2c0a22184e528fbf234e/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["item:soran-ruk-fragment"] = {
  hash = "c03879",
  fullHash = "c03879",
  text = "Soran'ruk Fragment. In Blackfathom Deeps, cultists hold shards of Soran'ruk, a shattered prison orb. The pieces still carry fel energy from the demon once bound inside. Soran'ruk's prison orb was broken apart after the demon fell from favor with the Burning Legion. Demons who displease their masters may have their spirits sealed in orbs, then given to fel spellcasters as sources of power. The Twilight's Hammer cultists in the submerged ruins of Blackfathom Deeps possess smaller shards from one half of the orb. They draw on the lingering demonic essence for their own workings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_soran-ruk-fragment-c6ea6c57e2bc77874fe7/1-0000.mp3", duration = 35.7877551, start = 0},
  },
}
P.transport["item:southsea-treasure"] = {
  hash = "663433",
  fullHash = "663433",
  text = "Southsea Treasure. The Southsea Treasure is a valuable hoard kept deep within the hold of the Southsea Freebooter vessel, the Tide Razor. Sought by Wrenix the Wretched in Ratchet, retrieving it tests the lockpicking and infiltration skills of fledgling thieves. Anchored along the Merchant Coast south of Ratchet, the pirate vessel Tide Razor serves as a forward base and training ground for the Southsea Freebooters. Stashed deep in its lowest hold lies a coveted stash of plunder known as the Southsea Treasure. Wrenix the Wretched, a goblin scoundrel operating out of Ratchet, considers it the ultimate test for aspiring pickpockets. According to Wrenix, the last five operatives sent to filch the chest returned in pieces, owing to the alert pirates aboard and a surprisingly ferocious guardian guarding the hold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_southsea-treasure-02f4718b59c94b7047e3/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["item:spectral-comb"] = {
  hash = "beb91e",
  fullHash = "beb91e",
  text = "Spectral Comb. At a ruined farmstead south of Darkshire, the Spectral Comb gathers ghost hair from Blind Mary. Ghostly hair lies beyond the reach of ordinary combs, leaving mortal craftsmen few ways to gather such fibers. The Spectral Comb can pass through a spirit’s intangible tresses. Carried south of Darkshire to a ruined farmstead, it is offered to Blind Mary, a weeping ghost who wails alone. Grooming brings her solace, and she willingly uses the comb. The spectral fibers she leaves behind can be woven into Ghost Hair Thread.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spectral-comb-adf5164775dda2344536/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["item:spells-of-shadow"] = {
  hash = "c75f71",
  fullHash = "c75f71",
  text = "Spells of Shadow. Beneath Orgrimmar, Spells of Shadow rests in the hands of Searing Blade cultists. The Forsaken leadership in the Undercity wants the grimoire recovered. Searing Blade cultists keep Spells of Shadow among their guarded treasures in Ragefire Chasm. The splinter cult is tied to the Shadow Council, and its members wield dark rites granted by demon masters of the Burning Legion. The book holds shadow and fel sorcery. Cultists and warlocks keep it close as they plot beneath the Horde in Durotar. Word of the Searing Blade's demonic gifts reached the Undercity's royal quarters. Lady Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, decided the relics were wasted on cultists with lesser vision. Varimathras sends Horde adventurers into Ragefire Chasm to seize Spells of Shadow and its companion tome, Incantations from the Nether. Their power is meant to serve the Forsaken cause against the Scourge and the Lich King.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spells-of-shadow-178206955f38b014356a/1-0000.mp3", duration = 52.8195918, start = 0},
  },
}
P.transport["item:spotted-sunfish"] = {
  hash = "56db64",
  fullHash = "56db64",
  text = "Spotted Sunfish. At Lake Everstill, Spotted Sunfish draw fishers and hungry murlocs alike. The fish bring trade to Lakeshire, though murlocs make the shallows dangerous. Spotted Sunfish bring trade to the Lakeshire piers. Dockmaster Baren buys them from the lake's steady catch, supplying food and commerce to a town under strain. Aggressive murloc tribes prowl the shallows and disrupt fishing. They gather sunfish at their camps, where travelers can take the fish by force.",
  ["1"] = {
    {file = "Audio/Transport/full_item_spotted-sunfish-af71bbb1e7d557300b9c/1-0000.mp3", duration = 26.8277551, start = 0},
  },
}
P.transport["item:stalker-claws"] = {
  hash = "91c966",
  fullHash = "91c966",
  text = "Stalker Claws. Across Mulgore, Stalker Claws are taken from prairie stalkers for a cleansing rite. Tauren shamans bind them into totems used to purify tainted wells. Prairie stalkers hunt across Mulgore’s grassy steppes. Their stealth and lethal precision make them deadly predators, yet they keep an essential balance within the Earth Mother's design. Mull Thunderhorn needs their claws to help heal the blighted land. He seeks no harm to the beasts; the natural force of their hunt holds the spiritual strength needed to counter artificial corruption. Goblin drilling and mining across central Kalimdor have sent chemical poisons into the underground waters that feed ancestral tauren wells. The Thunderhorn Water Well has been tainted by vile muck. Tribal shamans bind Stalker Claws and Cougar Claws into a Thunderhorn Cleansing Totem, a spiritual conduit that scours the unnatural sludge from the earth's springs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stalker-claws-badd9d4c788ec9be9ab5/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["item:steelgrill-s-tools"] = {
  hash = "21b8c3",
  fullHash = "21b8c3",
  text = "Steelgrill's Tools. At Steelgrill's Depot, Beldin Steelgrill needs fresh tools to keep his workshop running. The master technician pushes siege engines and his own equipment hard, so shipments from nearby Kharanos keep arriving. Beldin Steelgrill is among Dun Morogh's finest siege engine technicians, but merchants know his rough touch. He works without pause on armored tanks and mechanical contraptions, and delicate tools break quickly in his hands. Arclight spanners snap and fang-ratchets wear out, so Beldin keeps ordering replacements from Kharanos to stock his repair benches. Beldin's tools help keep Ironforge's war machines in working order. At his depot northeast of Kharanos, he services combat vehicles for experienced drivers such as Pilot Stonegear. Fresh wrenches and ratchets keep the work moving on the siege engines assembled there, and the depot's repairs support local defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_steelgrill-s-tools-106c2f22757214a3e233/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["item:steelsnap-s-rib"] = {
  hash = "329a39",
  fullHash = "329a39",
  text = "Steelsnap's Rib. In Thousand Needles, Steelsnap's Rib marks the end of a feared hyena's reign. Melor Stonehoof in Thunder Bluff wants the bone brought to Hunter Rise as proof that Steelsnap has been slain. Tauren hunts often seek food, honor, or harmony with nature. Steelsnap is different. The alpha hyena roams the canyon floor south of Camp E'thok in Thousand Needles, terrorizing peaceful wildlife and rallying lesser predators to bloodshed. Hunt master Melor Stonehoof, on Hunter Rise, marks Steelsnap for death. He asks for the hyena's rib as proof the tyrant is slain and the canyon cleansed of its blight.",
  ["1"] = {
    {file = "Audio/Transport/full_item_steelsnap-s-rib-a48bb821195311e90691/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["item:stolen-silver"] = {
  hash = "7566d9",
  fullHash = "7566d9",
  text = "Stolen Silver. At the Crossroads, a strongbox of Horde silver has gone missing from the guard tower. Sunscale raptors carried the coins to their nests at the Raptor Grounds south of Ratchet. Sunscale raptors carried a strongbox of silver from the Crossroads guard tower. The coins were meant as pay for the garrison guards. The raptors dragged the lockbox to their communal nests at the Raptor Grounds, south of Ratchet. Gazrog and the other overseers cannot explain why the predators took it. The theft leaves them wondering whether the raptors prize shiny things or possess a cunning beyond that of ordinary wild beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stolen-silver-d12af18eaa39a3a251d9/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["item:stone-of-relu"] = {
  hash = "ecf000",
  fullHash = "ecf000",
  text = "Stone of Relu. In the Wetlands, the Stone of Relu is lost to a raptor after an ambush. Archaeologist Flagongut believes it can unlock secrets within ancient fossils. Explorers' League work uncovered the Stone of Relu. Archaeologist Flagongut believes it can decipher prehistoric fossils gathered from Kalimdor and the Eastern Kingdoms. He means to use it on his Wetlands specimens and on the fossil Prospector Remtravel unearthed in Darkshore. Archaeologist Flagongut was traveling along the Wetlands roads to meet Prospector Whelgar when mottled raptors ambushed him. In the scramble, the relic was lost and swallowed by one of the beasts. The League now seeks the marsh raptors so the ancient stone can be cut from their gullets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stone-of-relu-ce32f72efe27461843df/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["item:stonetalon-sap"] = {
  hash = "5c99b5",
  fullHash = "5c99b5",
  text = "Stonetalon Sap. Near Mirkfallon Lake and Stonetalon Peak, sap beasts carry the sap Jin'Zil seeks. The Darkspear witch doctor uses it in a brew for his caged night elf prisoners.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stonetalon-sap-a57e1e2e3a6f230cad5b/1-0000.mp3", duration = 10.5795918, start = 0},
  },
}
P.transport["item:stormpike-banner"] = {
  hash = "aa3e55",
  fullHash = "aa3e55",
  text = "Stormpike Banner. Alliance recruits enter Icewing Cavern to earn the Stormpike Banner. The trial lies southwest of Dun Baldar in Alterac Valley, where harpies guard the standard. Lieutenant Haggerdin sends new Alliance soldiers into Icewing Cavern southwest of Dun Baldar. Before they face the Frostwolf orcs, recruits must brave the harpies, seize the Stormpike Banner, and bring it back alive. Those who return earn the rank and insignia of an initiate in the Stormpike Guard.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormpike-banner-99893e09f8699e35d74b/1-0000.mp3", duration = 26.5142857, start = 0},
  },
}
P.transport["item:stormpike-s-request"] = {
  hash = "0540a3",
  fullHash = "0540a3",
  text = "Stormpike's Request. Mountaineer Stormpike sends a written commission from Loch Modan to Stormwind City. He asks Furen Longbeard to craft him a shield of exceptional dwarven quality. Mountaineer Stormpike needs a sturdy shield while stationed in Loch Modan. He trusts no ordinary smith with the work and asks Furen Longbeard, whose craft he greatly admires. Furen now lives among the humans in Stormwind's Dwarven District, having left Ironforge. Stormpike assumes a king's ransom drew him south, so traveling adventurers carry the commission across the kingdoms. Furen Longbeard receives Stormpike's letter in Stormwind's Dwarven District and agrees to make the shield. A proud and established member of the Stormpike clan, known across Khaz Modan for its martial grit and wealth, Furen welcomes word and business from his northern homeland. He sets to work on the mountaineer's order.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormpike-s-request-00c906d0c69e9059b762/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["item:stormwind-armor-marker"] = {
  hash = "f4bbee",
  fullHash = "f4bbee",
  text = "Stormwind Armor Marker. Stormwind Armor Marker lets those who aid the realm claim crafted gear from sanctioned artisans. Sara Timberlain accepts one at the Eastvale Logging Camp. Stormwind's commanders issue armor markers to those who serve the realm. Keeping law and order across Elwynn Forest stretches Stormwind's resources thin, so commanders sometimes use these official requisition slips instead of handing out standard gear at military outposts. A marker confirms the bearer's service and authorizes local craftsmen under contract to provide tailored armor. At the Eastvale Logging Camp, Sara Timberlain and other artisans work under commission from the Stormwind Army. The camp lies on Elwynn's eastern frontier, where they use local materials to make protective cloth and leather garments. Present a marker there to receive custom-fitted defense for guarding the surrounding woodlands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stormwind-armor-marker-4fefbdbb19f5f43a2b14/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["item:stoutmantle-s-response-to-solomon"] = {
  hash = "e10170",
  fullHash = "e10170",
  text = "Stoutmantle's Response to Solomon. Gryan Stoutmantle sends a hard answer from Sentinel Hill to Lakeshire. His dispatch tells Magistrate Solomon that the People's Militia cannot spare a single soldier for Redridge Mountains. Magistrate Solomon of Lakeshire asks Sentinel Hill for reinforcements as Blackrock orcs and gnolls press his town. Gryan Stoutmantle replies in writing with sorrow for Lakeshire's losses, but Westfall faces a war of its own. The People's Militia formed from desperation after the Crown withdrew its garrison. Farmers and volunteers now fight the Defias Brotherhood alone. Stoutmantle's forces are already bleeding and stretched thin, with no men to spare for another abandoned frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_item_stoutmantle-s-response-to-solomon-4b0f51be66982f51cc9d/1-0000.mp3", duration = 39.444898, start = 0},
  },
}
P.transport["item:strange-smelling-powder"] = {
  hash = "fa5ef7",
  fullHash = "fa5ef7",
  text = "Strange Smelling Powder. In Loch Modan, Strange Smelling Powder has raised alarm during an inquiry into sabotage. Chief Engineer Hinderweir suspects an explosive and seeks an expert's judgment. Strange Smelling Powder was found amid signs of sabotage against Loch Modan's infrastructure. Chief Engineer Hinderweir fears it may be an engineered explosive, unlike the usual powder used in mining. He cannot identify its mixture or origin, and will not tamper with it himself. Even a small spark could bring disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strange-smelling-powder-e7a58062515e15c7875c/1-0000.mp3", duration = 29.5444898, start = 0},
  },
}
P.transport["item:strangely-marked-box"] = {
  hash = "484012",
  fullHash = "484012",
  text = "Strangely Marked Box. Along Darkshore, a Strangely Marked Box is found among cargo on dead sea turtles. Its runes point to the naga and show that the turtles did not come ashore by chance. Dead sea turtles and other sea creatures wash up on Darkshore's beaches. Some carry broken harnesses and carriages strapped to their shells. Sealed boxes marked with foreign, winding runes lie among the wreckage. Greymist murlocs often shelter in the hollow ribs and broken wagons, feeding on the carcasses and guarding what remains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strangely-marked-box-74aae32d4600b233a8ea/1-0000.mp3", duration = 31.3730612, start = 0},
  },
}
P.transport["item:strigid-owl-feather"] = {
  hash = "d7a0e3",
  fullHash = "d7a0e3",
  text = "Strigid Owl Feather. Strigid Owl Feathers are gathered from the owls in Teldrassil's boughs. Zenn Foulhoof seeks them for his covert dealings.",
  ["1"] = {
    {file = "Audio/Transport/full_item_strigid-owl-feather-c2a0a8f1a8b6cc09aa87/1-0000.mp3", duration = 7.07918367, start = 0},
  },
}
P.transport["item:sturdy-dragonmaw-shinbone"] = {
  hash = "311876",
  fullHash = "311876",
  text = "Sturdy Dragonmaw Shinbone. At the Angerfang Encampment, renegade Dragonmaw orcs provide sturdy shinbones for armor. In the Undercity, Velora Nitely needs them to frame leg guards for warriors. Velora Nitely needs bones that can bear the strain of brutal leg guards. The renegade Dragonmaw orcs at the Angerfang Encampment in the central Wetlands have thick, sturdy frames, and their shinbones can brace the armor. Each bone must be tested by hand. Warriors discard any that snap under pressure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sturdy-dragonmaw-shinbone-429a7e9e1253b91c4740/1-0000.mp3", duration = 30.5893878, start = 0},
  },
}
P.transport["item:sully-balloo-s-letter"] = {
  hash = "768f23",
  fullHash = "768f23",
  text = "Sully Balloo's Letter. Sully Balloo's Letter carries a soldier's farewell from the waters beneath the Thandol Span. Addressed to his wife Sara in Ironforge, it bears the love that endured through his final days. Beneath the Thandol Span, where the Wetlands road crosses toward the Arathi Highlands, a dwarf's skeletal remains lie pinned under rushing water. In his grasp rests a fragile, waterlogged envelope. The letter inside begins, “My dear Sara...” Its parchment has suffered beneath the water, but the ink still holds the care with which the dwarven defender wrote in his final days or hours. He never returned to Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sully-balloo-s-letter-de29b3a2ed23210a605c/1-0000.mp3", duration = 37.4595918, start = 0},
  },
}
P.transport["item:sunscorched-shell"] = {
  hash = "315b27",
  fullHash = "315b27",
  text = "Sunscorched Shell. Beneath Highperch, wyvern eggs leave shells hardened by Thousand Needles' desert heat. Armorer Mathiel in Darnassus uses them to make lacquer for mail links. Highperch wyverns lay eggs on the mesa needles of southern Kalimdor. Beneath their roosts, discarded shell fragments bake in the desert sun and searing winds. Their brittle remains hold a natural resilience that draws the attention of skilled artisans. In Darnassus, armorer Mathiel studies methods pioneered by his colleague, the dwarf smith Furen Longbeard. Mathiel processes the shells into a fine lacquer for mail armor. Applied to the metal links, the coating strengthens them without burdening the wearer.",
  ["1"] = {
    {file = "Audio/Transport/full_item_sunscorched-shell-a524c2d936329cae9203/1-0000.mp3", duration = 40.0718367, start = 0},
  },
}
P.transport["item:super-reaper-6000-blueprints"] = {
  hash = "e8b252",
  fullHash = "e8b252",
  text = "Super Reaper 6000 Blueprints. In Windshear Crag, the Venture Company’s Super Reaper 6000 Blueprints are coveted by goblin rivals. They hold the technical schematics for an enormous mechanized woodcutter deployed in Stonetalon Mountains, designed under gnome engineer Gerenzo Wrenchwhistle’s supervision. Venture Company operators carry the Super Reaper 6000 Blueprints through Windshear Crag. The plans show how to build the massive mechanized lumber harvesters driving the company’s relentless clear-cutting. To the dismay of traditional goblin engineers, the Venture Company put Gerenzo, a gnome, in charge of designing the model. When goblin engineer Ziz Fizziks was ousted from the operation, Sputtervalve quickly hired him to steal the designs. Yet Gerenzo’s dense, eccentric gnomish notations are almost as hard to decipher as the plans are to take by force.",
  ["1"] = {
    {file = "Audio/Transport/full_item_super-reaper-6000-blueprints-e357f306177b203adbad/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["item:supplies-for-sven"] = {
  hash = "f857f7",
  fullHash = "f857f7",
  text = "Supplies for Sven. Darkshire sends provisions to Sven Yorgen's camp in northwestern Duskwood. The Carevin family keeps his small band supplied as they hold their watch against the shadows. Sven Yorgen and his few followers camp in the northwestern wilderness, far from Darkshire. Their numbers are too low, and their watch too demanding, to spare anyone for the journey into town. The Carevin family sends food, bandages, and other necessities to the isolated camp, helping the band hold its ground.",
  ["1"] = {
    {file = "Audio/Transport/full_item_supplies-for-sven-5d7bb1a480f7c44a2a20/1-0000.mp3", duration = 28.0293878, start = 0},
  },
}
P.transport["item:surena-s-choker"] = {
  hash = "871bef",
  fullHash = "871bef",
  text = "Surena's Choker. In Stormwind, Gakin the Darkbinder seeks the choker he gave his former apprentice, Surena Caledon. After Surena fled to join the Defias Brotherhood, Gakin sent aspiring acolytes to take it back by force. Gakin the Darkbinder works quietly beneath the Slaughtered Lamb in Stormwind, where he took Surena Caledon on as a promising student of the dark arts. Drawn to her youthful charm and magical aptitude, he gave her a valuable bloodstone choker to aid her studies. Surena abandoned her training and fled with Erlan Drudgemoor, a rogue aligned with the Defias Brotherhood. Gakin will not leave a potent artifact in a traitor’s hands. He sends initiates seeking mastery over the void to find Surena at the Brackwell Pumpkin Patch and reclaim the necklace by force. Their deed will show where true loyalty lies.",
  ["1"] = {
    {file = "Audio/Transport/full_item_surena-s-choker-e483f30d13dada8b8295/1-0000.mp3", duration = 48.3265306, start = 0},
  },
}
P.transport["item:swoop-gizzard"] = {
  hash = "52ec40",
  fullHash = "52ec40",
  text = "Swoop Gizzard. Across Mulgore, swoops soar as predatory birds, and their gizzards go into traditional remedies for deadly toxins. Swoops hunt across Mulgore’s plains and mesas, with keen eyes and a taste for scavenging. Tauren use their feathers and meat in daily life, while herbalists and healers prize their internal organs, especially the gizzard. Dense and muscular, it helps counter venomous bites and festering infections when combined with cougar bones and wolf hearts. In Bloodhoof Village, Maur Raincaller tends the wound Mazzranache left on his shoulder. The legendary plainstrider’s venom drives Maur into delirium as the poison creeps through him. To make a poultice that can expel the lethal venom, Maur needs a swoop gizzard, a prairie wolf heart, a flatland cougar femur, and a plainstrider scale.",
  ["1"] = {
    {file = "Audio/Transport/full_item_swoop-gizzard-6e7a7db465ead4b74252/1-0000.mp3", duration = 47.2816327, start = 0},
  },
}
P.transport["item:tablet-of-verga"] = {
  hash = "279a5a",
  fullHash = "279a5a",
  text = "Tablet of Verga. In Skull Rock, the Tablet of Verga lies in Burning Blade hands, its demonic runes sought by warlocks in Orgrimmar. The Tablet of Verga bears ritual runes for summoning creatures of the Nether and bending them to a master's will. The Burning Blade cult stole the stone and hid it in a chest inside Skull Rock, just east of Orgrimmar. Warlocks in the Cleft of Shadow seek it to study the markings and learn to summon a voidwalker. Recovering it also keeps the cult from gaining that same advantage.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tablet-of-verga-6eb11bb355823af00328/1-0000.mp3", duration = 28.1861224, start = 0},
  },
}
P.transport["item:tainted-heart"] = {
  hash = "6b6555",
  fullHash = "6b6555",
  text = "Tainted Heart. In Teldrassil, Denalan gives adventurers a heart still troubled by corruption. Though its outer foul moss is gone, lingering energies remain, and he seeks to cleanse them with rich soil. Teldrassil's natural balance is troubled by a malady that warps its plants and beasts. After foul moss is stripped from a blighted growth, Denalan gives adventurers the Tainted Heart within. Darkness still clings to its tissue. Denalan hopes specially prepared, nutrient-rich earth can counter the taint and restore what was corrupted.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-heart-f0006ace8d3b98a7f7b0/1-0000.mp3", duration = 31.9216327, start = 0},
  },
}
P.transport["item:tainted-keg"] = {
  hash = "0606eb",
  fullHash = "0606eb",
  text = "Tainted Keg. At Tarren Mill, Tainted Keg carries stolen dwarven stout laced with a lethal Forsaken brew made by Apothecary Lydon. Sent to imprisoned human farmers as refreshments, it tests poisons being developed by the Royal Apothecary Society. Dun Garok's dwarven riflemen lost a barrel of Shindigger Stout to thieves. Apothecary Lydon mixed the stout with his newly refined Elixir of Agony. The Forsaken chose an ordinary drink to carry the poison, hoping it would escape suspicion. A familiar ale became a swift death sentence.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-keg-17063cbc82b3ed465c21/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["item:tainted-letter"] = {
  hash = "bda238",
  fullHash = "bda238",
  text = "Tainted Letter. Drusilla La Salle sends the Tainted Letter to human warlock initiates near Northshire Abbey. It bears her seal and directs them to seek her tutelage discreetly. The Tainted Letter bears Drusilla La Salle’s insignia and reaches initiates returning from nearby kobold camps. While priests, paladins, and soldiers train openly across Northshire Abbey’s lawns, fel practitioners must keep their path quiet. The letter directs novice warlocks to find their mentor near the abbey grounds without drawing the notice of town guards or clerics. Drusilla La Salle meets her pupils on the fringes, where sentries are less likely to pry. Elwynn’s ordinary folk distrust warlocks, so the letter begins a lesson in discipline. Arcane and nether magic bring the risk of corruption. Those who commune with denizens of the Twisting Nether must temper ambition with patient self-control.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-letter-eab34d9e0ed384f91d41/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["item:tainted-memorandum"] = {
  hash = "2f6cb4",
  fullHash = "2f6cb4",
  text = "Tainted Memorandum. In Coldridge Valley, Alamar Grimm gives the Tainted Memorandum to novice gnome warlocks. His note urges them to leave old paths behind and seek power through the dark arts. At Anvilmar, fel practitioners are neither celebrated nor widely trusted. Alamar Grimm gives the Tainted Memorandum to young gnomes who study forbidden arts. He rejects the Holy Light and ordinary weapons, pointing to Gnomeregan’s fall as proof that old ways and tinkering failed their people. Grimm sees reliance on dwarven charity as a dead end. He urges gnomes to claim undeniable power and summon minions who will obey without question, if they are to secure their own future.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tainted-memorandum-37c1ebd783c28fe9b668/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["item:talisman-of-corruption"] = {
  hash = "38663e",
  fullHash = "38663e",
  text = "Talisman of Corruption. In Darkshore, Xabraxxis uses the Talisman of Corruption to turn the Blackwood furbolgs against their former allies. The satyr keeps it in his personal pouch, where its magic binds the tribe to fel madness. Auberdine's night elves have long sought the cause of the Blackwood furbolgs' turn against their former allies. Thundris Windweaver found that satyrs had brought about the tribe's fall. With talismans like this, demonic agents spread corrupting sorcery through the wilderness, tainting food and twisting peaceful forest spirits into frenzied beasts. The devices channel fel magic that grips the minds and wills of local tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_talisman-of-corruption-f06429104497a7f74c93/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["item:tallonkai-s-jewel"] = {
  hash = "c2e4e6",
  fullHash = "c2e4e6",
  text = "Tallonkai's Jewel. On Teldrassil, Tallonkai's Jewel is lost from its druidic talisman. Ferocitas the Dream Eater prizes the emerald, which is needed to mend the Emerald Dreamcatcher. Tallonkai Swiftroot received the Emerald Dreamcatcher from Gaerolas Talvethen, warden of the druids in the Ban'ethil Barrow Den. The talisman is a powerful focus that draws energy from the Emerald Dream. When it was damaged, someone pried its radiant central emerald free and carried it into eastern Teldrassil. Ferocitas the Dream Eater, a corrupted Gnarlpine leader, took the jewel and made it into a necklace. Its green light glimmered in the forest gloom, but its harmony with the Emerald Dream meant nothing to the furbolg. To Ferocitas, it was only a trophy until it could be recovered.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tallonkai-s-jewel-c3d85c190e2242ab5d21/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["item:taming-rod"] = {
  hash = "4ed613",
  fullHash = "4ed613",
  text = "Taming Rod. In Durotar, Taming Rods help novice hunters learn to command beasts. Trainers give them to students so they can practice before forming lasting bonds with animal companions. In Razor Hill, trainers such as Thotar give Taming Rods to aspiring orc and troll hunters. These enchanted tools help novices who cannot yet bind a wild creature permanently. A rod pacifies a regional predator, such as a dire mottled boar or an armored scorpid, so the hunter can practice giving commands and fighting beside an animal companion. The bond lasts only briefly, leaving the student free to learn without forming a lasting tie to the beast. Each Taming Rod's magic fades after a short while, and each is attuned to specific kinds of wild beasts. Novices face successive trials against different temperaments, from docile foragers to aggressive venomous hunters. When a student has shown they can command them, the rod goes back to the trainer. The trainer then teaches the student to tame, call, and dismiss lifelong companions without an artifact.",
  ["1"] = {
    {file = "Audio/Transport/full_item_taming-rod-7ce18cc25833d5c0cbe2/1-0000.mp3", duration = 63.9216327, start = 0},
  },
}
P.transport["item:tattered-manuscript"] = {
  hash = "a57c7b",
  fullHash = "a57c7b",
  text = "Tattered Manuscript. In Thousand Needles, the Tattered Manuscript lies hidden in Splithoof Hold. Its torn pages came from the Tome of the Cabal, and warlocks seek them to learn how to summon a felhunter. The Tome of the Cabal was once a unique, intact volume kept in the fallen kingdom of Lordaeron. An unknown defiler tore almost half its pages from the binding. The remaining spine and pages became known as the Moldy Tome. They were sent south toward Khaz Modan, then lost at sea. The torn leaves crossed the Great Sea to Kalimdor and came into the hands of the Galak centaur inside Splithoof Hold. The manuscript rests in a battered chest deep in the caverns of Splithoof Hold, where it endured the dry winds of Thousand Needles. Alliance warlocks work with Krom Stoutarm in Ironforge, while Horde practitioners aid Jorah Annison in the Undercity. Both groups brave the aggressive centaur to reunite the leaves with the Moldy Tome. Together, the books hold the dark rituals for summoning and binding a demonic felhunter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tattered-manuscript-1509a7cd354cb56ece15/1-0000.mp3", duration = 58.88, start = 0},
  },
}
P.transport["item:tazan-s-satchel"] = {
  hash = "73a03c",
  fullHash = "73a03c",
  text = "Tazan's Satchel. Near Ratchet, Tazan carries a locked satchel as he deals with pirates along the coast. The Shattered Hand wants the secret information inside. Tazan deals with pirates camped along the Barrens coast near Ratchet. Therzok, a guild master of the Shattered Hand beneath Orgrimmar in the Cleft of Shadow, takes notice. The guild seeks covert power beyond Warchief Thrall's cautious diplomacy, and marks Tazan for elimination to seize the intelligence in his satchel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tazan-s-satchel-6b59f2e4a76c511ac0e4/1-0000.mp3", duration = 26.5926531, start = 0},
  },
}
P.transport["item:tear-of-the-moons"] = {
  hash = "cfff51",
  fullHash = "cfff51",
  text = "Tear of the Moons. At Bael Modan in the southern Barrens, dwarven excavators have unearthed the Tear of the Moons. Its strange power draws Feegly into obsession, while General Twinbraid fears what the crystal can do. Dwarven excavators unearthed the Tear of the Moons during the first digging at Bael Modan. The crystal's strange radiance captivated the miners, especially Feegly. He claimed it gave him great strength, then grew unstable and turned against his comrades. General Twinbraid, commander of the expedition, feared the relic's influence and declared it cursed. He took the crystal and locked it in his personal strongbox at Bael'dun Keep. Then he cast Feegly out into the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tear-of-the-moons-a86bcbc930a73b363ed5/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["item:tear-of-tilloa"] = {
  hash = "06b5b0",
  fullHash = "06b5b0",
  text = "Tear of Tilloa. In Duskwood, the Tear of Tilloa grows on the Mistmantle estate near Darkshire. Its alchemical use draws interest from those seeking rare reagents. The Tear of Tilloa grows on the grounds of Stalvan Mistmantle’s estate outside Darkshire. Duskwood’s soil has turned hostile to wholesome vegetation, yet the small white flower persists among the shadowed plots. It grows rarely and in a secluded place, drawing those who seek uncommon reagents beyond lawful markets.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tear-of-tilloa-621d3b5c4eaae2ed2f3a/1-0000.mp3", duration = 28.5257143, start = 0},
  },
}
P.transport["item:techbot-s-memory-core"] = {
  hash = "d2cddd",
  fullHash = "d2cddd",
  text = "Techbot's Memory Core. In Gnomeregan, Techbot's Memory Core holds the data Tinkmaster Overspark needs to study its corrupted behavior. Before Gnomeregan fell, Techbot aided Tinkmaster Overspark and his fellow inventors with a wealth of devices and knowledge. During the city's fall, an errant electrical discharge jolted the automaton and inverted its positronic brain into a hostile negatronic state. Now Techbot wanders Gnomeregan's tainted halls, attacking anyone in sight. Overspark hopes the memory core will help him understand the malfunction and restore his creation to its senses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_techbot-s-memory-core-abbaeb9acde4d89c9244/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["item:telescopic-lens"] = {
  hash = "32d386",
  fullHash = "32d386",
  text = "Telescopic Lens. Gazlowe needs the Telescopic Lens to finish the observatory telescope above Ratchet’s harbor. Southsea pirates took it from a ship, and the lens remains in their camp south of town. Ratchet is known chiefly for ruthless commerce, but its overseer and chief engineer, Gazlowe, has greater mechanical ambitions. His observatory rises above the harbor to house a telescope for watching maritime traffic and the stars. The larger lens came safely overland from Durotar. The smaller, vital lens traveled by sea, where Southsea Freebooters prey on merchant lanes off the Barrens coast. The Southsea Freebooters took anything of value when they raided the transport ship, including the delicate optics. The pirates may have left the lens among the clutter of their beachside camp south of Ratchet because they could not appreciate its craft or did not know how to pawn it. Gazlowe needs the unblemished glass brought back so his observation deck can come into focus.",
  ["1"] = {
    {file = "Audio/Transport/full_item_telescopic-lens-a3264c29ef7cc3d5ff0c/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["item:teronis-journal"] = {
  hash = "df21fd",
  fullHash = "df21fd",
  text = "Teronis' Journal. Teronis' Journal follows a scout's search through Ashenvale for a gem tied to a rod he hoped could slow furbolg attacks. Teronis, a longtime friend of Raene Wolfrunner, aided the Sentinels and searched Ashenvale for a gem. He believed it belonged to a rod that could slow the furbolg attacks on his people. Near the shore, aggressive creatures brought his journey to an end. The journal was recovered from his personal effects in remarkably good condition. Its findings about a radiant gem that once formed part of the rod give Astranaar's defenders a trail to follow in his unfinished search.",
  ["1"] = {
    {file = "Audio/Transport/full_item_teronis-journal-e08809bc9d4a2e447eaa/1-0000.mp3", duration = 32.7314286, start = 0},
  },
}
P.transport["item:tharil-zun-s-head"] = {
  hash = "fc65ff",
  fullHash = "fc65ff",
  text = "Tharil'zun's Head. Tharil'zun's Head reaches Lakeshire as proof that the commander terrorizing the Redridge approaches is dead. He led the Blackrock Outrunners occupying Stonewatch. Blackrock orcs at Stonewatch Keep have pressed Lakeshire hard, raiding farms and ambushing travelers on the roads. Tharil'zun directed the Blackrock Outrunners at the head of these attacks. Lakeshire's garrison cannot risk acting on rumors or partial victories, so Marshal Marris demands proof that Tharil'zun is dead. His severed head shows that the Outrunners' coordinated ambushes from the keep have suffered a major blow.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tharil-zun-s-head-4c19f98c2180732db770/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:tharnariun-s-hope"] = {
  hash = "c66c5f",
  fullHash = "c66c5f",
  text = "Tharnariun's Hope. In Darkshore, Tharnariun Treetender seeks a way to study the sick thistle bears and find a cure. His trap calms them long enough to bring them to his camp. Tharnariun Treetender made a calming trap to study the sick thistle bears. Across Darkshore, a mysterious affliction has left the animals increasingly frenzied and violent. Tharnariun hopes to cure them rather than see them killed. Set on the ground, Tharnariun's Hope casts a soothing light. A rabid thistle bear that crosses it grows calm for a time and can follow a traveler back to Tharnariun's camp for treatment.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tharnariun-s-hope-1336370f3213ccaf52c0/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["item:the-book-of-ur"] = {
  hash = "c351df",
  fullHash = "c351df",
  text = "The Book of Ur. Ur's book now lies in Shadowfang Keep, where Archmage Arugal found it before Forsaken scholars in the Undercity took interest. The Dalaran mage wrote of strange beings from other planes. Ur was a Dalaran mage known for studying other planes and their creatures. Before the Scourge came, the Kirin Tor knew his work well. Ur was fascinated by magic beyond this world, yet he chose to write down his findings instead of breaking through the veil recklessly. Caution and restraint shaped his research. When the Scourge attacked Dalaran, neither his magic nor his care could save him.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-book-of-ur-63b1aba6008ea3393b0e/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["item:the-collector-s-schedule"] = {
  hash = "7b6a55",
  fullHash = "7b6a55",
  text = "The Collector's Schedule. Near the Brackwell Pumpkin Patch, The Collector's Schedule marks when illicit gold shipments move through Elwynn Forest. Gnolls carry the handwritten itinerary, and Marshal Dughan recognizes the name it records. The Collector's Schedule marks dates and times for gold shipments from Elwynn's mines. Stormwind has not officially worked the mines for months, driven off by banditry and creature incursions, yet ore still leaves in an orderly flow. The itinerary names the days and hours when a figure called The Collector receives each shipment. The trail points to a camp near the Brackwell Pumpkin Patch in eastern Elwynn Forest. When Marshal Dughan sees the schedule, he recognizes the Collector's name. Who pays for the stolen gold remains unknown.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-collector-s-schedule-83d91682c18e36f614ca/1-0000.mp3", duration = 40.96, start = 0},
  },
}
P.transport["item:the-embalmer-s-heart"] = {
  hash = "5da75f",
  fullHash = "5da75f",
  text = "The Embalmer's Heart. In Duskwood, Eliza's buried corpse holds a heart that still beats. The Embalmer placed his own heart in his dead wife through dark magic, and it became the anchor of his power. Darkshire's tales remember the Embalmer as a gentle alchemist. When his wife Eliza died, grief shattered his mind. He turned to foul sorcery, cut out his own heart, and placed it in her lifeless chest. The magic stirred her corpse to unlife, but the return twisted Eliza into a ravenous creature with an insatiable hunger for living human flesh. Horrified by what he had done, the alchemist buried her again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-embalmer-s-heart-1fe42e6f518db7e69ca4/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["item:the-general-s-response"] = {
  hash = "eec716",
  fullHash = "eec716",
  text = "The General's Response. General Marcus Jonathan sends word to Lakeshire while Redridge waits for aid. His dispatch acknowledges Magistrate Solomon's plea against the Blackrock orcs and gnolls, but offers no immediate reinforcements from Stormwind. Magistrate Solomon sends an urgent plea to Stormwind City for troops to defend Redridge from the gathering Blackrock orc clans and Gnoll warbands. General Marcus Jonathan replies that the plea has been forwarded to the throne, but no soldiers are being sent now. He orders the letter returned to Lakeshire. Solomon is left troubled by Stormwind's delay and suspicious that something is wrong with its leaders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-general-s-response-fdb700370d04af0c460c/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["item:the-lich-s-spellbook"] = {
  hash = "5dece3",
  fullHash = "5dece3",
  text = "The Lich's Spellbook. On Brightwater Lake's island, a spellbook draws Bethor Iceshard's attention. He hopes its pages will reveal the lich's skill and who he was in life. A free-willed lich guards an island in Brightwater Lake with skeletal minions. He distrusts the outside world and mistakes other undead for Scourge thralls, ordering his guardians to kill anyone who approaches. Bethor Iceshard seeks skilled necromancers for the Forsaken beneath Queen Sylvanas Windrunner. He sends an emissary into the island camp to take the lich's spellbook. Bethor hopes its pages will reveal the master's power and identity before death took Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-lich-s-spellbook-b3631413165ad3f6d0d2/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["item:the-state-of-lakeshire"] = {
  hash = "770ae3",
  fullHash = "770ae3",
  text = "The State of Lakeshire. In Lakeshire, Magistrate Solomon's report calls for help before the town falls. It urges General Marcus Jonathan in Stormwind to send royal army reinforcements against the crisis in Redridge. Magistrate Solomon writes of the attacks threatening Lakeshire. Blackrock orcs and gnolls press the town, whose defenders cannot hold the borders indefinitely. Couriers carry his dispatch west along the road to Elwynn Forest. Solomon asks the Stormwind Army to intervene and protect the kingdom's eastern reach. General Marcus Jonathan receives Solomon's report at Stormwind's gates. He respects the magistrate's standing and understands the danger, but cannot move the army on his own. Deployments need the crown's consent, so Lakeshire's plea must wait for a council with the young King and regent Bolvar Fordragon.",
  ["1"] = {
    {file = "Audio/Transport/full_item_the-state-of-lakeshire-7eaa2fe5acbe024a0ffe/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["item:theramore-medal"] = {
  hash = "5638ec",
  fullHash = "5638ec",
  text = "Theramore Medal. At Northwatch Hold, Theramore Medal marks service among the marines and officers defending the outpost along the Merchant Coast. The insignia bears Theramore’s mark and identifies the Alliance garrison. Marines, marksmen, commandos, and officers serving from Northwatch Hold carry stamped medals bearing Theramore’s mark. The soldiers are loyal to Lady Jaina Proudmoore’s realm. For the human troops on the cliffs above the Barrens, the medals show that their service is legitimate and their authority comes from Theramore. Others see the tokens as trophies from an overzealous foreign garrison, one that treats every vessel approaching the coast as a mortal threat. Northwatch Hold’s gun batteries menace ships along the Merchant Coast, often bombarding privateers and merchantmen alike. After losing ships to the guns, Ratchet privateer Captain Thalo'thas Brightsun seeks the medals. He wants proof that Northwatch’s trigger-happy ranks have paid in blood for sinking his ships, and that the soldiers responsible have been slain in retribution.",
  ["1"] = {
    {file = "Audio/Transport/full_item_theramore-medal-835db9a6e4abb600eaba/1-0000.mp3", duration = 61.5183673, start = 0},
  },
}
P.transport["item:thick-bear-fur"] = {
  hash = "fcf341",
  fullHash = "fcf341",
  text = "Thick Bear Fur. In Dun Morogh, Thick Bear Fur keeps travelers and soldiers warm against the mountain cold. The pelts come from bears roaming the snowfields and help make insulated clothing and bedding. Bears roam Dun Morogh's ridges through some of the harshest snowfields in the Eastern Kingdoms. Their thick coats protect them from blizzards, and locals and travelers put those pelts to use. Hunters gather them to line clothing, insulate drafty outposts, and pad cold sleeping rolls. Pilot Bellowfiz outfitted his siege tank, Jetsteam, at Steelgrill's Depot for a month in the field on a long mission for the Siege Brigade. Cold iron offered little comfort in the high snowbanks, so he hired local scouts to gather thick bear fur from the snowfields south of the Grizzled Den. The pelts would make warm bedding for his cabin quarters.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thick-bear-fur-03f48824ffb48e791e03/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["item:thistlenettle-s-badge"] = {
  hash = "d23b03",
  fullHash = "d23b03",
  text = "Thistlenettle's Badge. Foreman Thistlenettle's badge is all that remains after the collapse in the Deadmines. Before the Defias Brotherhood sealed Moonbrook and the tunnels beneath it, dwarven prospectors from Ironforge's Explorers' League worked the old gold mines of Westfall. Foreman Thistlenettle and his crew were deep underground when a tunnel collapsed and split them apart. His brother Wilder escaped to Stormwind City, but the foreman and several laborers were left trapped below.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thistlenettle-s-badge-110541ba805ace890de9/1-0000.mp3", duration = 25.6261224, start = 0},
  },
}
P.transport["item:thresher-eye"] = {
  hash = "f8db1a",
  fullHash = "f8db1a",
  text = "Thresher Eye. Along Darkshore, Wizbang Cranktoggle wants Thresher Eyes for his Buzzboxes. He uses them to repair Buzzbox 411 on the beach north of Auberdine. Darkshore Threshers hunt the surf and outer shallows off Darkshore. They threaten local fishermen and travelers, and their large eyes have caught the interest of Wizbang Cranktoggle. The gnome engineer is stationed nearby and fond of crawler wine. He needs the eyes to repair Buzzbox 411, a far-speaking communication machine on the beach north of Auberdine. Wizbang does not explain how the slimy eyes repair delicate machinery. They might serve as crude lenses, chemical agents, or biological gears. Whatever the method, three eyes placed in Buzzbox 411's maintenance hatch restore its communication link, and Wizbang sends supplies through static-choked transmissions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thresher-eye-2cd2ec0a0d48b3c4ea54/1-0000.mp3", duration = 51.2783673, start = 0},
  },
}
P.transport["item:thule-s-head"] = {
  hash = "8f954c",
  fullHash = "8f954c",
  text = "Thule's Head. At the Sepulcher, High Executor Hadrec demands proof that Thule Ravenclaw is dead. His severed head confirms the commander of the Scourge forces on Fenris Isle has fallen and helps the Forsaken hold Silverpine Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thule-s-head-dd701febdca384cc107b/1-0000.mp3", duration = 12.9828571, start = 0},
  },
}
P.transport["item:thunder-lizard-blood"] = {
  hash = "63a95a",
  fullHash = "63a95a",
  text = "Thunder Lizard Blood. In the southern Barrens, hunters bring back Thunder Lizard Blood as proof of survival. The blood comes from the great beasts that roam the plains. Thunder lizards go by the names Stormsnouts, Stormhides, and Thunderheads across the plains. Their heavy steps shake the earth, and their crushing weight can flatten unwary hunters. Bringing back their blood shows the skill to hunt them and the endurance to survive beneath their thundering feet.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunder-lizard-blood-3413987f9587acb94cbd/1-0000.mp3", duration = 23.8759184, start = 0},
  },
}
P.transport["item:thunder-lizard-horn"] = {
  hash = "1a0647",
  fullHash = "1a0647",
  text = "Thunder Lizard Horn. In the Barrens, Brewmaster Drohn seeks a Thunder Lizard Horn for Chen Stormstout's legendary brew. Thunder lizards roam the Barrens, their crested bodies crackling with lightning. Brewmaster Drohn in Ratchet values their horns as an ingredient for Stormstout ale. His mentor learned the recipe from the wandering pandaren Brewmaster Chen Stormstout and passed it down to Drohn. The horn gives the drink its potent kick.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunder-lizard-horn-e85df262d62e0539b90e/1-0000.mp3", duration = 23.9542857, start = 0},
  },
}
P.transport["item:thunderhawk-saliva-gland"] = {
  hash = "2ae149",
  fullHash = "2ae149",
  text = "Thunderhawk Saliva Gland. Across the Barrens, greater thunderhawks yield a gland prized by Brewmaster Drohn. He needs it to recreate Chen Stormstout's fiery Trogg Ale. Greater thunderhawks hunt across the Barrens' arid savannas. These winged serpents are known for harnessing storms, and the older, more dangerous ones produce a saliva gland charged with natural potency. Travelers keep clear of the deadly beasts, but brewmasters value the gland as a rare base for exotic drinks. Brewmaster Drohn settled outside Ratchet after Chen Stormstout traveled through Kalimdor. Drohn studies the wandering brewmaster's fermentation methods and needs a fresh thunderhawk saliva gland, stormhide lightning glands, and kodo liver to brew Trogg Ale. The fiery spirit has an unmistakable kick and is meant to fortify hardy adventurers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhawk-saliva-gland-fb77795d8c9c605610e6/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["item:thunderhawk-wings"] = {
  hash = "b4e89e",
  fullHash = "b4e89e",
  text = "Thunderhawk Wings. Across the central and southern Barrens, hunters claim Thunderhawk Wings from the wind serpents that soar overhead. At Camp Taurajo, Jorn Skyseer receives them as proof of a hunter’s strength, cunning, and endurance. Hunters stationed at Camp Taurajo prize a pair of intact Thunderhawk Wings. Wind serpents, whom local hunters call thunderhawks, are fierce winged reptiles that strike swiftly from above. Tracking them across the open plains and claiming their wings in combat tests a hunter’s skill. For an initiate, bringing back the wings proves readiness to follow the lifelong path of an accomplished hunter.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhawk-wings-7a4b07e1f3b45834556c/1-0000.mp3", duration = 35.84, start = 0},
  },
}
P.transport["item:thunderhorn-cleansing-totem"] = {
  hash = "03cc7a",
  fullHash = "03cc7a",
  text = "Thunderhorn Cleansing Totem. Mull Thunderhorn prepares the Thunderhorn Cleansing Totem in Bloodhoof Village. Ancestral magic in the totem is meant to purify the Thunderhorn Water Well. Mull Thunderhorn entrusts a prepared totem to travelers in Bloodhoof Village. They carry it north to the Thunderhorn clan's sacred spring, where foul agents have tainted the water. The ancestral wells dug by the tauren tribes nourish their herds and hunting grounds. Through ritual invocation, the totem calms the water's disturbed spirits and cleanses the site.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thunderhorn-cleansing-totem-7c6c035dedd377078a1f/1-0000.mp3", duration = 28.3428571, start = 0},
  },
}
P.transport["item:thurman-s-remains"] = {
  hash = "f2d94a",
  fullHash = "f2d94a",
  text = "Thurman's Remains. At Agamand Mills, Thurman's remains bear witness to the family's failed stand against the Scourge. The once-wealthy mill owner fell to the Plague and now wanders his ruined estate as an undead thrall. Before the Third War, the Agamands were Tirisfal Glades' wealthiest landowners, with extensive mills and dozens of local workers. When the Scourge swept across Lordaeron, Thurman Agamand and his kin fortified their estate instead of fleeing. Certain their wealth and strong mills could withstand the attack, they persuaded their loyal workers to take up arms beside them. The defense failed. The Agamands and their workers were slaughtered and made mindless servants of the Lich King. Coleman Farthing, a former worker who rose as Forsaken, now demands the destruction of his former masters. He seeks Thurman's remains as proof that the foolish patriarch paid for dooming his household.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thurman-s-remains-02a5391b613163fc7f47/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["item:thurman-s-sewing-kit"] = {
  hash = "e9e77a",
  fullHash = "e9e77a",
  text = "Thurman's Sewing Kit. At Larson Clothiers, Thurman's Sewing Kit is needed for his tailoring work. The tools belong to young apprentice Thurman Schneider, who left them behind at his family's canal home to avoid a long day of stitching. Thurman's Sewing Kit holds the everyday tools of an apprentice tailor: needles, shears, and thread. Young Thurman Schneider studies tailoring at Larson Clothiers, deep in Stormwind's Mage Quarter near the Mage Tower. His mother, Rema Schneider, knows he cannot do his work without the kit, so she asks passersby along the Canals to carry it to the shop. When Thurman gets the tools, his reaction shows he left them behind on purpose, hoping to trade a day of stitching garments for leisure.",
  ["1"] = {
    {file = "Audio/Transport/full_item_thurman-s-sewing-kit-ec01270778d77218ad55/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["item:timberling-seed"] = {
  hash = "683a24",
  fullHash = "683a24",
  text = "Timberling Seed. Across Teldrassil, Timberling Seeds are gathered from plant spirits that have grown hostile. Naturalists and druids study them to learn why the forest's plant life has turned aggressive. Timberlings are nature elementals of Teldrassil, and their temper reflects the World Tree's balance. Lately they have grown hostile and angry, troubling the night elves who tend the boughs. Herbalists such as Denalan at Lake Al'Ameth suspect trouble in the soil. They gather seeds from wild timberlings, hoping that purified, carefully tended soil might let docile offspring sprout.",
  ["1"] = {
    {file = "Audio/Transport/full_item_timberling-seed-eb1c225e5b6b50264955/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["item:timberling-sprout"] = {
  hash = "4e2796",
  fullHash = "4e2796",
  text = "Timberling Sprout. Along Lake Al'Ameth, Timberling Sprouts take root already touched by corruption. Night elf wardens pull them before they grow into aggressive timberlings. Timberlings are plant spirits bound to Teldrassil's natural vitality. Along Lake Al'Ameth, the night elves find seedlings that sprout tainted and aggressive instead of healthy and in harmony with the wild. The young sprouts seem beyond cleansing or natural healing, so the caretakers gather and destroy them. They hope to stop hostile timberlings from spreading across the fragile boughs of the newly planted World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_item_timberling-sprout-a31b2393b0ff115cf525/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["item:tirisfal-pumpkin"] = {
  hash = "474076",
  fullHash = "474076",
  text = "Tirisfal Pumpkin. At Solliden Farmstead, living humans still tend pumpkins in blighted Tirisfal. The Forsaken take them for the Royal Apothecary Society’s mixtures. West of Brill, crops still grow despite the corruption spreading across Lordaeron. At Solliden Farmstead, living human farmers work the soil and grow large orange pumpkins under the watch of the nearby Scarlet Crusade. The harvest feeds these farmers. To the Forsaken of Brill, the pumpkins are targets for sabotage and raw materials for Apothecary Johaan. Deathguard Simmer sends young Forsaken into the contested fields to steal pumpkins from under the farmers’ noses. The vegetables do not feed the dead; they go into the Royal Apothecary Society’s cauldrons. Apothecaries test how natural plants react to plagues and experimental mixtures, using Lordaeron’s remaining crops against the living.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tirisfal-pumpkin-db46ce687481e353ae7e/1-0000.mp3", duration = 51.1216327, start = 0},
  },
}
P.transport["item:token-of-thievery"] = {
  hash = "870a93",
  fullHash = "870a93",
  text = "Token of Thievery. In the Redridge Mountains, rogues face a test set by Lucius at Alther's Mill. A locked footlocker holds the Token of Thievery, proof of skill recovered during their training. In Lakeshire, Lucius tests promising rogues in the field. He hides the Token of Thievery in a locked footlocker among the ruins of Alther's Mill, where Blackrock orcs threaten the area. Recovering it tests whether an initiate can pick a lock under mortal danger. Success earns a Certificate of Thievery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_token-of-thievery-c3aff6be71b72463a46a/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["item:tome-of-the-cabal-quest-item"] = {
  hash = "99d2ad",
  fullHash = "99d2ad",
  text = "Tome of the Cabal (quest item). Warlocks in Ratchet receive the Tome of the Cabal from Strahad Farsan after gathering dangerous components. Its pages hold the incantations for drawing a felhunter across the Twisting Nether and binding it. A felhunter is a vicious beast from the chaotic Twisting Nether, feared for devouring mana. Subduing one marks a passage for seasoned warlocks. The Tome of the Cabal holds the rites for opening a path to such a demon. Strahad Farsan, an experienced conjurer in Ratchet, gives the tome to an aspirant only after they gather the rare and dangerous components its magic requires. Strahad Farsan establishes the primary summoning circle in his sanctum, while his acolytes use rods of channeling to form a greater protective boundary. The warlock recites the tome's exact incantations and drags the felhunter into our world. The demon must be battled at once and subdued, binding it to the warlock's will.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tome-of-the-cabal-quest-item-38d8cb69e3bb3cae3221/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["item:top-of-gelkak-s-key"] = {
  hash = "875381",
  fullHash = "875381",
  text = "Top of Gelkak's Key. A giant foreststrider carries the Top of Gelkak's Key into the woods near Darkshore. It is one of three broken pieces of a mechanical key belonging to the shipwrecked gnome Gelkak Gyromast. Threshadons attacked Gelkak Gyromast's ship off Darkshore and sent it beneath the waves. The gnome washed ashore with the winding key for his mechanical first mate. The impact against the coastal rocks broke it into three pieces. Before the dizzy pirate could gather his wits, beasts scavenged the wreckage. A giant foreststrider carried the ornate upper piece into the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_top-of-gelkak-s-key-845c1aeb28f4208feb46/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["item:torch-of-the-dormant-flame"] = {
  hash = "663326",
  fullHash = "663326",
  text = "Torch of the Dormant Flame. At the Shrine of the Dormant Flame, a shaman prepares to kindle the Torch of the Dormant Flame. The unlit torch waits for a fire spirit's ember, earned on a mountaintop in Durotar. A shaman seeking fire's favor carries the unlit Torch of the Dormant Flame up the peaks above Durotar. Fire sapta lets the shaman see a Minor Manifestation of Fire on the mountaintop and challenge it. When the spirit falls, its glowing ember goes into the weathered brazier at the Shrine of the Dormant Flame. The shaman touches the torch's head to the white-hot blaze, and the wood awakens as a burning emblem of elemental mastery.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torch-of-the-dormant-flame-272986928220476e3fb7/1-0000.mp3", duration = 36.7281633, start = 0},
  },
}
P.transport["item:torn-fin-eye"] = {
  hash = "d8c180",
  fullHash = "d8c180",
  text = "Torn Fin Eye. Along Hillsbrad's coast, Torn Fin Eyes draw the Royal Apothecary Society's attention. The Forsaken seek them for alchemical work on new plagues. The Royal Apothecary Society puts rare biological components to use in its work on the Forsaken's New Plague. Torn Fin Eyes come from murlocs along the Western Strand of Hillsbrad Foothills. Their organic properties help activate volatile alchemical compounds. Mixed with Daggerspine naga scales, restorative troll elixirs, and gnoll-derived sludge, the eyes help stabilize and trigger toxic mixtures meant to spread death through enemy lands.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torn-fin-eye-4ea2a0a5a00a44f1e472/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["item:torn-murloc-fin"] = {
  hash = "d39244",
  fullHash = "d39244",
  text = "Torn Murloc Fin. In eastern Elwynn, Torn Murloc Fins show the Stormwind Army's bounty is being answered. Taken from foragers and lurkers along the riverbanks, they show that local waterways are being systematically cleared. Murlocs have grown numerous along eastern Elwynn's streams and lakes, and the Stormwind Army offers a bounty to reduce their numbers. Guard Thomas, who watches the bridge over the eastern river, collects the severed fins as proof of kills. Stormwind's soldiers are stretched thin by unrest at home and threats nearby, so local authorities depend on travelers to bring proof that murloc camps have been cleared.",
  ["1"] = {
    {file = "Audio/Transport/full_item_torn-murloc-fin-f423c3809a09198a320b/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["item:totem-of-hawkwind"] = {
  hash = "f4586a",
  fullHash = "f4586a",
  text = "Totem of Hawkwind. At Camp Narache, young tauren receive the Totem of Hawkwind before departing for Bloodhoof Village. They present it to Baine Bloodhoof as proof that they have completed their first trials and are ready to continue the Rites of the Earthmother. Chief Hawkwind carves the Totem of Hawkwind atop Red Cloud Mesa for youth coming of age. The token introduces its bearer and proves their passage. Tauren rarely use formal writ; meaningful symbols and familiar tribal craft carry a leader's intent. After a youth completes the first trials at Camp Narache, Hawkwind sends them onward with the totem, along the road into the wider lands of Mulgore. Its distinct carvings identify the bearer to Baine Bloodhoof and show they have the spirit and strength for the next trials, on the way to seeking the blessing of Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_item_totem-of-hawkwind-baa33965b8b9500289ea/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["item:tough-wolf-meat"] = {
  hash = "87b2e1",
  fullHash = "87b2e1",
  text = "Tough Wolf Meat. Northshire and Coldridge wolves prowl their valleys, leaving raw Tough Wolf Meat for hungry locals. Coarse and stringy, it feeds people in Elwynn Forest and supplies dwarven outfitters in Dun Morogh. Wolves prowl near Northshire Valley and Dun Morogh, threatening nearby settlements and providing a hard-won source of food. Their meat is coarse, stringy, and chewy, but resource-strapped frontiersmen prize it. Outside Northshire Abbey, Eagan Peltskinner hates the vicious beasts yet cooks their meat into steaks. He trades basic supplies and gear to those willing to cull the packs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tough-wolf-meat-1f82146135e73e7f1e98/1-0000.mp3", duration = 37.1983673, start = 0},
  },
}
P.transport["item:tourmaline-phial"] = {
  hash = "f1ed54",
  fullHash = "f1ed54",
  text = "Tourmaline Phial. At the Pools of Arlithrien, the Tourmaline Phial gathers blessed moonwell water for Teldrassil's rituals. Corithras Moonrage gives the Tourmaline Phial to travelers for rituals that tend the World Tree. Druids in Dolanaar use gemstone vials to collect pure moonwell water across Teldrassil. This phial is meant for the moonwell beside the Pools of Arlithrien, southeast of the road to Darnassus, where hostile Gnarlpine furbolgs are growing more troublesome.",
  ["1"] = {
    {file = "Audio/Transport/full_item_tourmaline-phial-23ebac0df9c346caecb4/1-0000.mp3", duration = 25.1559184, start = 0},
  },
}
P.transport["item:toxic-fogger"] = {
  hash = "4a6c98",
  fullHash = "4a6c98",
  text = "Toxic Fogger. In Stonetalon, the Toxic Fogger is bound for the Venture Company's air routes. The Forsaken Royal Apothecary Society filled the device with lethal poison to contaminate the company's flights. Apothecary Zamah sends the Toxic Fogger against the Venture Company's mining work. Apothecary Lydon brewed its toxin in Tarren Mill, and Zamah dispatched it from Thunder Bluff. She suspects the goblins use courier flying machines to carry messages and light cargo between Stonetalon and their headquarters. Her plan is to release the poison where those machines land and refuel. The Forsaken aim to strike the company's supply route instead of fighting its mercenary crews in drawn-out skirmishes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_toxic-fogger-bd54dfe6fea25631f8a3/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["item:treshala-s-pendant"] = {
  hash = "66ecd9",
  fullHash = "66ecd9",
  text = "Treshala's Pendant. In Razorfen Kraul, a pendant carries the bond between Treshala and Heralath Fallowbrook. Heralath brought it from their home in Darnassus into southern Kalimdor, where the quilboar tore it from him as he lay dying. Heralath Fallowbrook carried the pendant close when he left Teldrassil on perilous journeys. The necklace reminded him of home and of his beloved wife, Treshala, and the devotion they shared.",
  ["1"] = {
    {file = "Audio/Transport/full_item_treshala-s-pendant-2632e3f6894415b45835/1-0000.mp3", duration = 24.5028571, start = 0},
  },
}
P.transport["item:trogg-stone-tooth"] = {
  hash = "949773",
  fullHash = "949773",
  text = "Trogg Stone Tooth. In Loch Modan, Trogg Stone Tooth comes from the Stonesplinter troggs in the hills. Rugged and mineralized, each tooth gives dwarven defenders proof that the troggs are being hunted along the southern frontier. Captain Rugelfuss calls for volunteers to hunt the Stonesplinter troggs near Loch Modan's southern gate. With the Ironforge Reserve committed to the Alliance Front, local dwarven garrisons are stretched thin across Khaz Modan. Rugelfuss cannot spare the soldiers at the southern gate guard tower for patrols in the nearby hills. His standing call asks volunteers to hunt the lurking troggs and bring back Trogg Stone Teeth as crude, undeniable proof of each beast slain.",
  ["1"] = {
    {file = "Audio/Transport/full_item_trogg-stone-tooth-683bc0d5ab793128c4cc/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["item:troll-charm"] = {
  hash = "dbb096",
  fullHash = "dbb096",
  text = "Troll Charm. In Ashenvale, Troll Charms have been taken from fallen Darkspear travelers. The Thistlefur furbolgs seized the sacred amulets after ambushing the party on its way to Zoram'gar Outpost. Darkspear trolls carry spiritual charms as marks of dignity. Scout Mitsuwa says a troll without one is as diminished as an orc without battle scars. A party of Darkspear kin traveled through Ashenvale's canopy toward Zoram'gar Outpost when corrupted Thistlefur furbolgs ambushed and slaughtered them. Their spirits were commended to the afterlife, while the furbolgs took the charms as trophies and stashed them in chests deep within Thistlefur Hold.",
  ["1"] = {
    {file = "Audio/Transport/full_item_troll-charm-c4feb1a2245f79af555f/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["item:trophy-swoop-quill"] = {
  hash = "bbba2e",
  fullHash = "bbba2e",
  text = "Trophy Swoop Quill. Across Mulgore, swoops circle above the plains, and their quills mark a hunter’s skill. Tauren bring these feathers to Harken Windtotem in Bloodhoof Village. Swoops ride high above Mulgore’s grasslands, where they are hard to track. Young tauren hunters and travelers in Bloodhoof Village seek a trophy quill to prove their cleverness and resolve. Bringing one to elders such as Harken Windtotem honors the hunter’s clan and shows the sharp senses needed to thrive on the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_trophy-swoop-quill-fc34f9cab4d01d0b8e7b/1-0000.mp3", duration = 28.0293878, start = 0},
  },
}
P.transport["item:twilight-pendant"] = {
  hash = "b49eac",
  fullHash = "b49eac",
  text = "Twilight Pendant. In Blackfathom Deeps, Twilight Pendants mark the cultists who serve the Twilight's Hammer. The Argent Dawn seeks them as proof of the cult's work along Ashenvale's coast. Beneath the drowned ruins of Blackfathom Deeps, the Twilight's Hammer gathers with the naga to honor the chaotic Old Gods. Shadowmages, aquamancers, reavers, and loreseekers all wear Twilight Pendants as signs of devotion to their shadowy patrons. The cult keeps to the ruins of the former night elf temple, so these pendants offer outsiders one of the few ways to learn how many cultists gather there and hinder their plans. Argent Guard Manados in Darnassus seeks Twilight Pendants as evidence that the growing darkness is being driven back. Blackfathom Deeps once held a pristine moonwell, and its desecration by void-worshipers threatens Kalimdor. Gathering the pendants shows that the Twilight's Hammer foothold in Ashenvale is being dismantled before its patrons can unleash greater terror.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twilight-pendant-c7f1355a03b393c20b8b/1-0000.mp3", duration = 55.3534694, start = 0},
  },
}
P.transport["item:twilight-whisker"] = {
  hash = "b40ac0",
  fullHash = "b40ac0",
  text = "Twilight Whisker. In Malaka'jin, Witch Doctor Jin'Zil gathers Twilight Whisker for his brew. Twilight runners carry the whiskers in the northern heights of the Stonetalon Mountains. Twilight runners prowl the high crags near Stonetalon Peak. Hunters prize their pelts, while Witch Doctor Jin'Zil of Malaka'jin wants their stiff whiskers for a darker purpose. He seeks vengeance on night elves captured after defending these woodlands. To mock and poison his captives, Jin'Zil gathers resinous sap, countless eyes, fey dragon scales, and Twilight Whisker for a lethal draught he calls forest magic.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twilight-whisker-8164b7e1a150f6d40cbc/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["item:twitching-antenna"] = {
  hash = "3bd2b2",
  fullHash = "3bd2b2",
  text = "Twitching Antenna. In the southern Barrens, silithid antennae still twitch after they are cut free. Ruga Ragetotem at Camp Taurajo seeks them as proof of a young warrior’s speed and skill in combat before the nerves go still. Silithid Grubs, Swarmers, Harvesters, and Creepers carry antennae that twitch after they are cut from the head. The spasms fade soon after the insects are slain. A young warrior must hunt silithid in the southern wastes and hurry back across the scrublands while the antennae still twitch. Bringing them back in time tests both speed and skill, making the hunt a rite of passage for Horde warriors. The silithid antennae also point to a threat that troubles Camp Taurajo’s hunters. Silithid are not native to the Barrens, and their new burrowing mounds at the Field of Giants unsettle the camp. Ruga Ragetotem wants the specimens to study the danger and prepare Horde warriors for the alien menace moving into the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_item_twitching-antenna-e440613bb5faed82e279/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["item:ukor-s-burden"] = {
  hash = "252e36",
  fullHash = "252e36",
  text = "Ukor's Burden. At the Valley of Trials, Ukor's food is turned away, and he needs help bringing it back to Razor Hill. Ukor, an orc peon, rarely acts on his own, but he carried provisions from the inn in Razor Hill to help young recruits in the Valley of Trials. The journey led him through Durotar's red dust and dangerous wildlife. The overseers and instructors refused the food, believing hardship and hunger make true warriors. Now Ukor waits outside the canyon's mouth, afraid of the beasts along the trail back. He has entrusted the sack to passing travelers, asking them to return it to Innkeeper Grosk.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ukor-s-burden-4c74c33bbef9df764e55/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["item:uncloven-satyr-hoof"] = {
  hash = "a09186",
  fullHash = "a09186",
  text = "Uncloven Satyr Hoof. In Ashenvale, satyrs gorge themselves on the ancient forest’s magic. Their swollen hooves hold the power they steal, and Ula'elek uses it to forge armor in Sen'jin Village. Satyrs haunt the corrupted groves of northeastern Ashenvale, feeding on the ancient forest’s magical purity. The more they consume, the more corruption distorts their demonic bodies. Their hooves swell and lose their natural cleft, becoming dense stores of absorbed energy. Skilled shamans and leatherworkers can harvest that volatile power. At Sen'jin Village on Durotar’s coast, the troll armorer Ula'elek turns demonic corruption into strength for Horde champions. He takes hooves from satyrs that have fed on the forest and draws out their trapped magic. Then he channels that stolen power into brutal gauntlets, armor for young warriors facing the rigors of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_uncloven-satyr-hoof-7412ca22c6545da80ff8/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["item:underbelly-whelp-scale"] = {
  hash = "61a08e",
  fullHash = "61a08e",
  text = "Underbelly Whelp Scale. South of Lake Everstill, Underbelly Whelp Scale trades hands among Redridge craftsmen. Black dragon whelps provide the pliable scales, and local artisans value them when coin is scarce. Black dragons bear tough scales, but facing a full-grown one is deadly for ordinary folk. South of Lake Everstill, black dragon whelps nest among the crags. Their back plates can be brittle or coarse, while the softer scales beneath their bellies bend more readily and still offer protection. Those qualities make Underbelly Whelp Scale valuable in local trade. Craftsmen prize it, and creditors can accept it in place of coin. In Lakeshire, craftsmen sometimes barter when coin runs short or trade routes are strained. Verner Osgood, the local blacksmith, owes a heavy debt to Argus, a blacksmith in Goldshire. The debt began with a shipment of shoes brought in from Goldshire. Argus favors rare trade goods, so Verner depends on travelers to gather underbelly whelp scales. They can help settle what he owes and keep his workshop in good standing.",
  ["1"] = {
    {file = "Audio/Transport/full_item_underbelly-whelp-scale-3f06a9f5d469ed9bb7f0/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["item:unidentified-ore"] = {
  hash = "e44c30",
  fullHash = "e44c30",
  text = "Unidentified Ore. At Windshear Crag, Unidentified Ore draws the Venture Company's attention. Piznik recovered a sample and passed it to Ziz Fizziks for study in Undermine. The Venture Company's clear-cutting and strip mining at Windshear Crag exposed unusual mineral strata in the Stonetalon Mountains. The site's new boss, Gerenzo Wrenchwhistle, ordered large amounts of strange gold-green ore mined. Demoted goblin worker Piznik remained loyal to his fired former boss, Ziz Fizziks, and secured a sample while plotting his exit from the outfit. He handed it to a traveler bound for the crag's western ridge. Ziz planned to send most of the ore to Undermine for study and keep a small cut for personal profit.",
  ["1"] = {
    {file = "Audio/Transport/full_item_unidentified-ore-c5dd7397a3cb5d56b39a/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["item:unrefined-ore-sample"] = {
  hash = "5ad5bb",
  fullHash = "5ad5bb",
  text = "Unrefined Ore Sample. In Thousand Needles, an unusual ore draws the Horde's attention. Tatternack Steelforge seeks a sample to judge whether the raw mineral can strengthen the weapons of Warchief Thrall's armies. South of the Barrens, Gravelsnout kobolds dig through the stone beneath the canyon walls of Thousand Needles. Travelers returning north found a curious mineral among slain vermin, unlike the usual veins of Kalimdor. They refused to surrender their prize to the Horde. The kobolds who dig and survey the depths carry raw chunks of the ore from their excavations. At Camp Taurajo, weaponsmith Tatternack Steelforge works under orders from Warchief Thrall to improve the Horde's arms. Travelers who kept knowledge of the deposit angered him; he saw their refusal as an insult to the Horde's war effort. With a raw sample, Tatternack plans to test the mineral's strength and temper, then smelt it and forge a prototype blade for Orgrimmar's approval.",
  ["1"] = {
    {file = "Audio/Transport/full_item_unrefined-ore-sample-9bba43762f01f90cf827/1-0000.mp3", duration = 57.0514286, start = 0},
  },
}
P.transport["item:ur-s-treatise-on-shadow-magic"] = {
  hash = "4fd4ef",
  fullHash = "4fd4ef",
  text = "Ur's Treatise on Shadow Magic. Stormwind's mages once guarded Ur's Treatise on Shadow Magic, but Morganth stole the perilous tome and hid it in the Tower of Ilgalar. Ur of Dalaran wrote a treatise on shadow magic and its subtle, corruptive nature. The mages of the Wizard's Sanctum in Stormwind feared that such arts could bring doom and ruin to the unwary, so they sealed the volume against readers. After Morganth surrendered to dark arts and Stormwind's magical circle exiled him, he took the tome east into the Redridge Mountains, to his stronghold at the Tower of Ilgalar.",
  ["1"] = {
    {file = "Audio/Transport/full_item_ur-s-treatise-on-shadow-magic-a5f71ebf358a648e7c22/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["item:urgent-message"] = {
  hash = "e6c915",
  fullHash = "e6c915",
  text = "Urgent Message. The Urgent Message is a sealed dispatch penned by Brave Moonhorn warning Freewind Post of escalating centaur violence across Thousand Needles. Carried by travelers descending into the canyon, the letter alerts the tauren garrison that their supply lines and scouting parties are under immediate threat. Penned by Brave Moonhorn near the great lift that descends from the Barrens into Thousand Needles, the Urgent Message represents the first line of defense for travelers crossing the border. Moonhorn monitors the jagged canyons below, where aggressive centaur tribes have renewed their relentless raids against Horde travel. Addressed to Cliffwatcher Longhorn atop Freewind Post, the missive sounds the alarm about emboldened attackers striking dangerously close to crucial roadways, urging the local garrison to brace for sustained conflict and guard against secondary threats like the unpredictable Grimtotem clan.",
  ["1"] = {
    {file = "Audio/Transport/full_item_urgent-message-8e096e2ae96002658c71/1-0000.mp3", duration = 49.92, start = 0},
  },
}
P.transport["item:valdred-s-hands"] = {
  hash = "b25610",
  fullHash = "b25610",
  text = "Valdred's Hands. In southern Silverpine Forest, Valdred Moray's severed hands become proof of Raleigh Andrean's vengeance for his wife's murder. Raleigh seeks them in the Undercity as a grim trophy. The plague consumed Lordaeron and ended the friendship between Valdred Moray and Raleigh Andrean. Valdred had murdered Raleigh's wife, Deliah. Raleigh died and rose as one of the Forsaken, claiming he could no longer truly grieve. Yet he still wanted vengeance. When Valdred fled south past the Greymane Wall toward Gilneas, Raleigh sent an emissary after his former friend. He demanded Valdred's severed hands as proof that the deed was done.",
  ["1"] = {
    {file = "Audio/Transport/full_item_valdred-s-hands-1bdada127aac09f0d57b/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["item:velinde-s-journal"] = {
  hash = "37fab5",
  fullHash = "37fab5",
  text = "Velinde's Journal. Velinde Starsong's personal journal records her duties and the mystery of her departure from Darnassus. The Night Elf priestess's journal is stored in the Sentinel bunkhouse. When Night Elf priestess Velinde Starsong left Darnassus, her belongings were locked in a footlocker at the Sentinels' bunkhouse in the Tradesmen's Terrace. Among them was her personal journal, a record of her responsibilities and duties. The Sentinels respected Velinde and believed she had left to attend to private matters. Her journal's contents suggest her unexplained absence is more troubling than they first believed.",
  ["1"] = {
    {file = "Audio/Transport/full_item_velinde-s-journal-58cfdda572f77202f94b/1-0000.mp3", duration = 35.6832653, start = 0},
  },
}
P.transport["item:velinde-s-key"] = {
  hash = "c8b910",
  fullHash = "c8b910",
  text = "Velinde's Key. In Darnassus, Velinde's Key guards the writings of a vanished priestess. Thyn'tel Bladeweaver entrusts it to those who bring proof of their interest in Velinde Starsong's fate. Thyn'tel Bladeweaver keeps Velinde's Key in Darnassus. The simple key secures Priestess Velinde Starsong's personal belongings in a footlocker in the Sentinel bunkhouse above the Tradesmen's Terrace. Velinde left night elf lands without warning, and her possessions were set aside. Bladeweaver gives the key only to those who bring genuine evidence of their interest in learning her fate, such as revelations found in the Tome of Mel'Thandris.",
  ["1"] = {
    {file = "Audio/Transport/full_item_velinde-s-key-72c8e965c6727d70a3ff/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["item:venomtail-antidote"] = {
  hash = "42ec3d",
  fullHash = "42ec3d",
  text = "Venomtail Antidote. In Durotar, Venomtail Antidote is urgently needed to save a scout from scorpid poison. Kor'ghan brews the remedy in Orgrimmar for Rhinag, who lies stricken near Durotar's northwestern border. Durotar's venomtail scorpids can kill a warrior within an hour of a deep sting. Rhinag, a troll scout, was envenomed near the northwestern border, far from aid. His only chance is a remedy from Kor'ghan, an apothecary in Orgrimmar's Cleft of Shadow. Finding Kor'ghan means making your way beneath Orgrimmar. He knows desert toxins and harsh remedies, and prepares a vial to purge the venom before it turns fatal. The draught stops the poison and spares Rhinag a humiliating death in the wilderness. Kor'ghan still demands further trials and hunts from the scout to atone for his carelessness.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venomtail-antidote-36c347b7507032a3d1bd/1-0000.mp3", duration = 47.4644898, start = 0},
  },
}
P.transport["item:venomtail-poison-sac"] = {
  hash = "42b370",
  fullHash = "42b370",
  text = "Venomtail Poison Sac. In Durotar, a scorpion’s venom can bring a hunter near death, while its poison sac holds what alchemists need to make a cure. Scorpids roam Durotar’s red rocks, including Venomtail Scorpids, Corrupted Scorpids, and the Death Flayer. Their tail sacs hold a fast-acting venom that can overwhelm even seasoned warriors if left untreated. The same sacs contain the primary compounds alchemists need to make an antidote. When a scorpion stung the hunter Rhinag outside Orgrimmar, local alchemists needed four fresh poison sacs to make a remedy and neutralize the venom in his veins.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venomtail-poison-sac-c16afaea77bdf347158a/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["item:venture-co-documents"] = {
  hash = "ce3aef",
  fullHash = "ce3aef",
  text = "Venture Co. Documents. In eastern Mulgore, Venture Co. Documents confirm illegal strip-mining in tauren lands. The papers were recovered from a crate amid a ruined caravan and detail the company's operations. Venture Co. Documents were found atop mined ore in a ransacked wagon. The ledgers show the goblin-led cartel has quietly established drilling and mining outposts in Mulgore's eastern foothills. Across Kalimdor, the Venture Company is known for ruthless deforestation and uncontrolled excavation. Morin Cloudstalker and the tauren Outrunners use the seized records to judge the threat to their sacred ancestral plains and rally hunters to drive out the trespassers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-documents-9d5d065402448652d797/1-0000.mp3", duration = 38.5567347, start = 0},
  },
}
P.transport["item:venture-co-engineering-plans"] = {
  hash = "594760",
  fullHash = "594760",
  text = "Venture Co. Engineering Plans. At Windshear Crag, the Venture Co. Engineering Plans reveal how the logging machinery is built. Alliance operatives recover the schematics from the goblin mill. Inside the lumber mill south of Cragpool Lake, the Venture Co. Engineering Plans show the construction, strengths, and flaws of the timber-harvesting machines. The Venture Company uses those machines to strip the forests of Stonetalon, while smoke hangs over Windshear Crag.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-engineering-plans-764f43bd59f9739d6d86/1-0000.mp3", duration = 25.4693878, start = 0},
  },
}
P.transport["item:venture-co-letters"] = {
  hash = "f4c358",
  fullHash = "f4c358",
  text = "Venture Co. Letters. At Windshear Mine, Venture Co. Letters carry word of the cartel's work in Stonetalon Mountains. Recovered amid explosive distractions, they give the night elf Sentinels intelligence on goblin operations. Venture Company machines cut timber and strip-mine the ancient woodland around Windshear Crag. Alliance operatives set off covert sabotage to distract the workers and enter Windshear Mine. The letters they recover hold private messages and logistical records of the company's local work. Sentinel leaders can learn how the defilers arrange their workforce and supply lines from those records.",
  ["1"] = {
    {file = "Audio/Transport/full_item_venture-co-letters-87bdd652e97fcd2f827a/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["item:verdant-note"] = {
  hash = "006d66",
  fullHash = "006d66",
  text = "Verdant Note. In Camp Narache, Verdant Note calls young tauren druids to begin their training. Sent for Gart Mistrunner, it guides them toward the rites of the Earthmother. Young tauren with a gift for nature receive Verdant Note soon after their trials begin in the Red Cloud Mesa. A messenger carries Gart Mistrunner's brief summons to Camp Narache, where the initiate must report to the mentor. Restless spirits and shifting elements trouble Mulgore, and the elders need new druids trained quickly. Gart Mistrunner teaches initiates to commune with nature. He warns that night elves share a bond with the wild but keep their distance from tauren, guarded by ancient pride. Tauren druidism centers on reverence for the Earthmother. Initiates learn to hear the land's restless ancestral voices and serve as her living instruments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verdant-note-544963316b43bbf67078/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["item:verdant-sigil"] = {
  hash = "83912b",
  fullHash = "83912b",
  text = "Verdant Sigil. In Shadowglen, Conservator Ilthalaine gives young night elf druids the Verdant Sigil as a summons to begin training. Young night elves in Shadowglen who feel the call of the wild receive the Verdant Sigil from Conservator Ilthalaine. A messenger brings it from Mardant Strongoak, the druid trainer, and it directs novices to climb into Aldrassil's boughs. The token invites them to leave basic chores behind and begin serious study of communion with nature spirits and the mysteries of the Emerald Dream. Presenting the Verdant Sigil to Mardant Strongoak begins a young druid's lifelong craft. Novices are not yet ready to walk the sleeping trance of the Emerald Dream, but the token marks the start of their mentorship. Under Mardant's instruction, they learn to read the wilderness's whispers and practice early shapeshifting and healing arts in service of Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verdant-sigil-026d68103026be9ad694/1-0000.mp3", duration = 48.4571429, start = 0},
  },
}
P.transport["item:verna-s-westfall-stew-recipe"] = {
  hash = "ad83d3",
  fullHash = "ad83d3",
  text = "Verna's Westfall Stew Recipe. Verna's Westfall Stew Recipe travels to Salma Saldean as the Furlbrows prepare to leave their farm. Her handwritten formula carries a familiar comfort for those who remain. Verna and Farmer Furlbrow have homesteaded in Westfall for years, but the Defias Brotherhood and rogue harvest golems now run rampant across the countryside. They wait for their wagon to be repaired so they can escape toward Stormwind. While they wait, Verna writes down her beloved formula for Westfall Stew. She entrusts the recipe to travelers bound for her neighboring friend, Salma Saldean, so the familiar comfort of the stew can endure for those left behind.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verna-s-westfall-stew-recipe-c4ae847ebb09af875338/1-0000.mp3", duration = 38.5044898, start = 0},
  },
}
P.transport["item:verner-s-note"] = {
  hash = "926576",
  fullHash = "926576",
  text = "Verner's Note. In Redridge, Verner Osgood sends a written requisition west to Smith Argus in Goldshire. It describes Lakeshire’s iron shortage and asks the Elwynn smith for horseshoes. Lakeshire’s defense has consumed nearly all of Verner Osgood’s iron. The town’s blacksmith has used his reserves to arm and armor the Stormwind Guard, who are stretched thin against invading gnolls and local perils. Meanwhile, Lakeshire’s stables have fallen into neglect, without even basic horseshoes for their mounts. Verner asks Smith Argus in Goldshire to send prepared shoes from Elwynn, so the town can shoe its horses.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verner-s-note-52702c9ccbcdb5c9a093/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["item:verog-s-head"] = {
  hash = "3686e3",
  fullHash = "3686e3",
  text = "Verog's Head. Regthar Deathgate seeks Verog's Head as proof of the Kolkar leader's death. The chieftain commands forces around the Stagnant Oasis, and his defeat is meant to weaken the tribes threatening the Barrens. The Kolkar centaur threaten Horde travelers and supply routes across the northern Barrens. Verog the Dervish roams the arid scrubland, leaving his command tent at the Stagnant Oasis vulnerable. Horde operatives attack his forces around the pavilion until an alarm sounds. Verog rushes back to defend his camp, where he is slain and decapitated. Regthar Deathgate receives his head as proof that another dangerous Kolkar chieftain has fallen. Barak Kodobane's head is already on display beside it.",
  ["1"] = {
    {file = "Audio/Transport/full_item_verog-s-head-b6fe0b0937118f0f148b/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["item:vial-of-innocent-blood"] = {
  hash = "2903b7",
  fullHash = "2903b7",
  text = "Vial of Innocent Blood. Syndicate shadow mages gather Vial of Innocent Blood in the ruins of Durnholde Keep. The Royal Apothecary Society in Tarren Mill seeks it as a catalyst for experimental toxins. Syndicate shadow mages gather innocent blood in the ruins of Durnholde Keep. The Syndicate's fallen human nobles practice dark arts within the crumbled walls. Apothecary Lydon in Tarren Mill wants untainted blood for an experimental pacifying agent. He means to use it against the Venture Company in Stonetalon Mountains, and sees the Syndicate's stores as a convenient source.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-innocent-blood-c2919f1903e138866e4a/1-0000.mp3", duration = 31.764898, start = 0},
  },
}
P.transport["item:vial-of-phlogiston"] = {
  hash = "94e851",
  fullHash = "94e851",
  text = "Vial of Phlogiston. A Vial of Phlogiston is an alchemical substance used by master armorers to temper extraordinarily resilient mail. Guarded within the quilboar stronghold of Razorfen Kraul, it is coveted by both Alliance and Horde smiths forging specialized battle armor for promising warriors. Phlogiston is an intensely volatile, fire-bearing substance prized in esoteric metallurgy. Both the dwarven smith Furen Longbeard in Stormwind and the near-blind orc armorer Thun'grim Firegaze in the Barrens consider it an indispensable component for hardening warrior armor beyond ordinary physical limits. Without this alchemical agent, the specialized forging techniques required for Fire Hardened Mail or the Horde's Brutal Armor cannot be completed. Obtaining a Vial of Phlogiston requires venturing into the tangled thickets of Razorfen Kraul, located at the southern tip of the Barrens. The phlogiston is held deep within the bristling redoubt by the geomancer Roogug. Whether recovered for Furen in Stormwind or carried across the dust to Thun'grim's anvil, the substance demands a perilous descent into hostile quilboar territory.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-phlogiston-77e1e0a5143ebaabd974/1-0000.mp3", duration = 66.1420408, start = 0},
  },
}
P.transport["item:vial-of-purest-water"] = {
  hash = "e03e60",
  fullHash = "e03e60",
  text = "Vial of Purest Water. In the southern Barrens, Brine blesses a vial of pure water for a shaman initiate. Its contents help Islen Waterseer prepare a water sapta for seeing elemental spirits. Brine guides the initiate through trials of patience and cleansing before sealing the water in the vial. The water holds an uncorrupted elemental purity. Carry it across the Barrens to Islen Waterseer, who keeps watch on a solitary shore. She needs it to brew a water sapta. Without such pure water, a shaman cannot commune with spiritual guardians in places far from the sunbaked flats.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-purest-water-421e5f4a0a75cedd3bf5/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["item:vial-of-spider-venom"] = {
  hash = "064746",
  fullHash = "064746",
  text = "Vial of Spider Venom. In Duskwood, spiders carry venom that Madame Eva needs for a protective ward. She gathers it with undead remains to make a Totem of Infliction. Duskwood's thickets shelter venomous spiders, from pygmy venom webs and green recluses to black widows and Naraxis. Their fangs carry poison potent enough to paralyze travelers and decay flesh. Those who kill the spiders can draw the fluid into intact vials. In Darkshire, fortune teller Madame Eva sees ominous portents for travelers setting out into the dark world. She needs five vials of spider venom, ghoul fangs, and skeleton fingers to craft a ward of retribution. Her craft turns the venom’s biting nature against attackers, making the Totem of Infliction return harm to anyone who strikes its bearer.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vial-of-spider-venom-e56a78022b05686e2a9b/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["item:vicious-night-web-spider-venom"] = {
  hash = "4b1e15",
  fullHash = "4b1e15",
  text = "Vicious Night Web Spider Venom. In eastern Tirisfal, Vicious Night Web Spider Venom carries an old contagion. The Royal Apothecary Society prizes it for holding historical disease strains, and uses it in work on the Forsaken's New Plague. Apothecary Johaan in Brill studies old texts about a plague that killed thousands. The contagion behind that outbreak endured for centuries inside the venom of local Night Web spiders. Apothecaries hunt the vicious breed in Venomweb Vale, south of the Scarlet Monastery, and draw out the preserved contagion for their alchemical experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vicious-night-web-spider-venom-cba42efbbd0f5e230749/1-0000.mp3", duration = 31.2163265, start = 0},
  },
}
P.transport["item:vile-familiar-head"] = {
  hash = "5cb478",
  fullHash = "5cb478",
  text = "Vile Familiar Head. Near the Burning Blade Coven, Vile Familiar Heads mark a grim test for young Horde warlocks. Under Ruzan's guidance, they gather the gruesome trophies as proof of readiness to bind their first demonic minions. The test demands discipline and respect for the lethality of the beings they mean to summon. In the sun-baked canyon of the Valley of Trials, Ruzan asks novices seeking to learn summoning to bring him six Vile Familiar Heads. Vile familiars are fiery imps with dangerous elemental cunning, found outside the Burning Blade Coven. Novices must face and defeat them, proving they can subdue demonic life rather than be overcome by it. Warlocks are barely tolerated within Thrall's Horde, so their training calls for care. A novice slain by a conjured creature only deepens the dishonor and suspicion cast upon practitioners of the dark arts.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vile-familiar-head-8be0fa59c820edeacc9c/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["item:vile-fin-scale"] = {
  hash = "f2ff19",
  fullHash = "f2ff19",
  text = "Vile Fin Scale. Vile Fin Scale comes from murloc tribes prowling Tirisfal’s northern coasts and waterways. In Brill, the Royal Apothecary Society studies these samples as it works on a plague meant to strike the living and the Scourge. The Royal Apothecary Society seeks a blight that can spread through the living and the Scourge. Simple toxins are easy to brew, but an infectious disease needs properties that help it pass from one population to another. In Brill, Apothecary Johaan studies Vile Fin scales for their natural resilience and mucous coatings. He hopes these traits can help stabilize his experimental contagions and carry them onward. The Vile Fin tribe inhabits Tirisfal Glades’ northern shores and western shallows, where its members threaten travelers and press into Forsaken territory. Gathering their scales helps keep the feral murloc populations in check and supplies Johaan’s laboratory with fresh organic material for tests in biological warfare.",
  ["1"] = {
    {file = "Audio/Transport/full_item_vile-fin-scale-e8258b5a7f85a834a0c6/1-0000.mp3", duration = 57.2604082, start = 0},
  },
}
P.transport["item:voodoo-charm"] = {
  hash = "d301d1",
  fullHash = "d301d1",
  text = "Voodoo Charm. In Teldrassil’s barrows, the Voodoo Charm can break the Gnarlpine enchantment holding Oben Rageclaw’s body.",
  ["1"] = {
    {file = "Audio/Transport/full_item_voodoo-charm-278b33821e5aa8cfccc7/1-0000.mp3", duration = 6.76571429, start = 0},
  },
}
P.transport["item:wailing-essence"] = {
  hash = "140853",
  fullHash = "140853",
  text = "Wailing Essence. Wailing Essence is a strange, concentrated substance found within the ectoplasms roaming deep inside the Wailing Caverns. Suspected of fueling the bizarre mutations spreading through the flora and fauna of the Barrens, it has drawn the attention of opportunistic alchemists eager to bottle its potent properties. The subterranean caverns beneath the central Barrens have grown thick with unnatural energy, warping beasts and giving rise to gelatinous ectoplasms. These oozing creatures concentrate a viscous substance known as Wailing Essence. While local druids observe these waters with growing dread, goblin entrepreneurs see only raw commercial opportunity. In the port town of Ratchet, an eccentric alchemist named Mebok Mizzyrix believes this essence is the missing active ingredient for a line of lucrative 'smart drinks' meant to enhance consumer intellect, utterly unconcerned with the nightmarish corruption it might actually harbor.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wailing-essence-288b9dcd0d8abfdbd31b/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["item:warsong-axe-shipment"] = {
  hash = "1d44eb",
  fullHash = "1d44eb",
  text = "Warsong Axe Shipment. At Booty Bay, the Warsong Axe Shipment waits for its voyage to Ashenvale. The newly forged axes are bound for the Warsong Outriders and the work at their lumber camp. Axes for the Warsong Lumber Camp wait in Booty Bay. The camp’s woodcutters need a steady supply of durable tools, and not every tool can be forged on the front lines. Orders cross the Great Sea to this neutral goblin port, where the crate is stored near Wharfmaster Lozgil. The sharpened axes are meant for Splintertree Post, where they can be sent onward to the camp. Keeping distant frontier camps supplied takes a long journey across the sea.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-axe-shipment-13810aa35c70eb5399fd/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["item:warsong-oil"] = {
  hash = "adafb5",
  fullHash = "adafb5",
  text = "Warsong Oil. At the Warsong Lumber Camp, Warsong Oil keeps the logging machinery running. A satyr ambush has carried a shipment into corrupted forest enclaves. Warsong Oil keeps the Warsong Clan's logging machinery running in Ashenvale. Goblin-engineered shredders and massive sawmills need a steady supply of the lubricant. Without it, timber cutting could halt, slowing the lumber needed to build Orgrimmar and fortify Horde settlements across Durotar and the Barrens. Satyrs ambushed a shipment of Warsong Oil before it could reach Splintertree Post and the logging camps. They carried the containers into corrupted enclaves, including Night Run, Satyrnaar, and Xavian, where they use the flammable lubricant in their rituals.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-oil-37b2c211b1cd886d8582/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["item:warsong-outrider-update"] = {
  hash = "ac31f5",
  fullHash = "ac31f5",
  text = "Warsong Outrider Update. Along Ashenvale’s eastern border, a Warsong Outrider prepares a dispatch for the Horde. Stationed there, the outrider records frontline intelligence for couriers serving the Horde to carry, helping secure the crossing toward Azshara and strengthen the orcish foothold against night elf resistance. Beyond Splintertree Post, the eastern road runs toward the ancient ruins of Azshara through Ashenvale’s volatile borderlands. Mounted orcish vanguards patrol this frontier and record tactical sightings, patrol movements, and resource evaluations. They send their field notes to Kadrak at the northern watchtower, which guards the Barrens border. The reports give Horde commanders a clear view of enemy troop concentrations and territorial threats beneath the forest canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-outrider-update-617b8cad58fb82eda162/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["item:warsong-runner-update"] = {
  hash = "c15a04",
  fullHash = "c15a04",
  text = "Warsong Runner Update. At Zoram'gar Outpost, Warsong Runner Update carries reports from western Ashenvale to Kadrak. The Warsong runner at Zoram'gar Outpost watches the coast and nearby threats in western Ashenvale. The dispatch records observations gathered by scouts at the outpost and reports on local activity. It travels to Kadrak's watchtower on the Barrens border, helping Horde leaders strengthen their position and plan their movements into the elves' ancestral woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-runner-update-a6799e0b14bf675c4241/1-0000.mp3", duration = 25.9395918, start = 0},
  },
}
P.transport["item:warsong-saw-blades"] = {
  hash = "164da8",
  fullHash = "164da8",
  text = "Warsong Saw Blades. Warsong Saw Blades keep the Horde's lumber machinery cutting in Ashenvale. The Warsong Clan relies on goblin-made machines for its logging, and these blades supply its clear-cutting work. In Ashenvale, the Warsong Clan's logging depends on heavy machinery supplied and maintained by goblin engineers. Axes alone cannot meet the Horde's demand for Kalimdor lumber, so steam engines and circular saws cut through raw timber. Ashenvale's ancient hardwood quickly dulls and breaks ordinary blades. Replacement saw blades must keep arriving for the mills at the Warsong Lumber Camp to keep running. Getting mechanical parts through disputed territory brings constant trouble. Hostile furbolgs and satyrs often intercept other logging supplies, while goblin contacts such as Pixel at Splintertree Post handle the saw blade shipments. Lumber master Locke Okarr gathers the blades with rope, oil, and axes to keep the camp operating despite sabotage from Ashenvale's defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-saw-blades-b2c7e130bd8aac09019a/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["item:warsong-scout-update"] = {
  hash = "8062bb",
  fullHash = "8062bb",
  text = "Warsong Scout Update. At Splintertree Post, a Warsong scout records what the Horde needs to know about Ashenvale. Warsong scouts watch the woods as the Horde seeks timber and supply routes through Ashenvale. From Splintertree Post, a fortified encampment, they track night elf sentinels and movements across the territory. Their observations reach Kadrak at the Barrens-Ashenvale border among routine orders. He uses them to judge troop readiness and coordinate supplies and travel through the contested woods.",
  ["1"] = {
    {file = "Audio/Transport/full_item_warsong-scout-update-cbc2cf944cf44b64a792/1-0000.mp3", duration = 29.1526531, start = 0},
  },
}
P.transport["item:water-of-the-seers"] = {
  hash = "121cdd",
  fullHash = "121cdd",
  text = "Water of the Seers. In Bloodhoof Village, young tauren drink the sacred Water of the Seers before their tribal trials. The draught opens the mind to the spirit world and summons a Plains Vision to guide them. Young tauren drink the Water of the Seers before the tribal fire in Bloodhoof Village. Tribal mystics prepare the draught for the ancient Rite of Vision. It opens the drinker’s spiritual sight, and the Plains Vision appears from the embers to guide the way to Seer Wiserunner.",
  ["1"] = {
    {file = "Audio/Transport/full_item_water-of-the-seers-89ae6b3e1eb7fd5603fc/1-0000.mp3", duration = 26.0440816, start = 0},
  },
}
P.transport["item:water-pitcher"] = {
  hash = "585988",
  fullHash = "585988",
  text = "Water Pitcher. At Red Cloud Mesa, Water Pitcher carries fresh spring water from the local well to Camp Narache. Greatmother Hawkwind asks young tauren to bring it back as a lesson in humility, service, and respect for tribal elders. Water Pitcher rests beside the well southeast of Camp Narache. Greatmother Hawkwind asks a novice to fill it and carry it to Chief Hawkwind. The chore tests their character and teaches young braves that no duty is beneath a tribal protector. Caring for the everyday needs of their kin matters as much as wielding a weapon on the hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_item_water-pitcher-7dd8a62160650d4597c9/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["item:webwood-egg"] = {
  hash = "86191a",
  fullHash = "86191a",
  text = "Webwood Egg. In Shadowthread Cave, Webwood Eggs lie in brooding nests in Shadowglen. Naturalists seek viable eggs to study the young spiders in secure laboratory conditions. Researchers cannot safely tame or subdue a fully grown, venomous Webwood spider alone. Scholars like Gilshalan Windwalker instead collect unhatched eggs from clutches hidden in Shadowthread Cave. An egg can be carried safely, and the spiderlings contained when they hatch, giving naturalists live subjects to study without facing adult spiders’ deadly fangs. Teldrassil’s native wildlife has grown unnaturally aggressive and corrupted, alarming scholars across the boughs. Eggs and gathered venoms secured at Aldrassil are bound for Darnassus. Researchers hope that raising and examining the spiders in controlled settings will reveal more about the dark affliction spreading through the World Tree’s boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-egg-c71afc280af7ef20108d/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["item:webwood-ichor"] = {
  hash = "7ccf80",
  fullHash = "7ccf80",
  text = "Webwood Ichor. In Shadowglen, Webwood spiders carry venom that has left Iverron gravely ill. Dirania Silvershine needs their ichor, hyacinth mushrooms, and moonpetal lilies to brew an antidote. Webwood spiders in Shadowglen carry venom that has left Iverron gravely ill. Dirania Silvershine asks for their ichor, hyacinth mushrooms, and moonpetal lilies to prepare an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-ichor-a9d5f3e79d86b41cd02c/1-0000.mp3", duration = 22.0212245, start = 0},
  },
}
P.transport["item:webwood-spider-silk"] = {
  hash = "b19790",
  fullHash = "b19790",
  text = "Webwood Spider Silk. Webwood Spider Silk is gathered from Webwood Lurkers in the woods of Teldrassil. Crafters use spider silk in many ways, but these swatches draw the interest of suspicious figures among the World Tree’s boughs. Webwood Lurkers around Dolanaar spin a fine, strong thread that is dangerous to gather. Zenn Foulhoof, a satyr along the forest road, asks young adventurers to collect the silk with nightsaber fangs and strigid owl feathers. He says these rare reagents are needed for his forest business, and newcomers gather them without asking about his corrupt nature or true motives.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-spider-silk-03070579fcac64e36135/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["item:webwood-venom-sac"] = {
  hash = "57be61",
  fullHash = "57be61",
  text = "Webwood Venom Sac. In Shadowglen, Webwood Venom Sacs draw the attention of naturalists studying Teldrassil's growth. The sacs come from overgrown spiders, and their venom may show how the new World Tree has changed local wildlife. Webwood spiders live around and within Shadowthread Cave, and they are cousins to a much smaller breed found elsewhere. Their sudden growth and predatory aggression worry night elf researchers. Naturalists such as Gilshalan Windwalker study the venom in their sacs, examining its strength and composition. They hope to learn how Teldrassil's rapid, unblessed growth is changing the creatures that live on its boughs.",
  ["1"] = {
    {file = "Audio/Transport/full_item_webwood-venom-sac-37a35033c900dc2714f7/1-0000.mp3", duration = 37.355102, start = 0},
  },
}
P.transport["item:well-stone"] = {
  hash = "f327a7",
  fullHash = "f327a7",
  text = "Well Stone. Across Mulgore, Well Stones rest beside the water wells. Their earth and water magic helps prepare the Water of the Seers for tauren rites of passage. Well Stones rest in the soft earth beside Mulgore’s wells, where they absorb the spiritual resonance of the plains and the waters beneath them. Shaman and seers such as Zarlman Two-Moons know these stones as vessels of vital magic, not ordinary river pebbles. Combined with grounded Ambercorn beneath the plains’ mighty trees, their mineral properties temper the brew that awakens visionary trances in young tauren during the sacred Rite of Vision.",
  ["1"] = {
    {file = "Audio/Transport/full_item_well-stone-5d13dfa731ff2046e757/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["item:wendigo-mane"] = {
  hash = "71be67",
  fullHash = "71be67",
  text = "Wendigo Mane. Across Dun Morogh, wendigo manes are gathered from the beasts roaming its frozen crags. Their thick coats offer warmth against the mountain cold, and Pilot Stonegear has a use for them. Dun Morogh’s wendigos roam the snowdrifts, and their coarse fur shields against bitter drafts. Pilot Stonegear, stationed outside Kharanos, sends adventurers to Grizzled Den for their heavy manes. He plans to weave them into an insulating floor rug for the interior deck of his prized dwarven siege engine, Trollplow.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wendigo-mane-1f511936961453683616/1-0000.mp3", duration = 30.5632653, start = 0},
  },
}
P.transport["item:whitestone-oak-lumber"] = {
  hash = "e8bf3c",
  fullHash = "e8bf3c",
  text = "Whitestone Oak Lumber. Beneath Moonbrook, Whitestone Oak Lumber is shaped for the Defias fleet. Its strength also draws the attention of Alliance smiths seeking a haft for a sacred weapon.",
  ["1"] = {
    {file = "Audio/Transport/full_item_whitestone-oak-lumber-93138b6904da0641bf1a/1-0000.mp3", duration = 10.3444898, start = 0},
  },
}
P.transport["item:wildmane-cleansing-totem"] = {
  hash = "4b56d7",
  fullHash = "4b56d7",
  text = "Wildmane Cleansing Totem. At Mulgore’s Wildmane Water Well, one last cleansing remains. Mull Thunderhorn prepares a totem for the northern well after the Winterhoof and Thunderhorn wells are cleansed. The Wildmane Water Well still needs cleansing. Goblin ventures have poisoned the land and fouled Mulgore’s scarce water, so the tauren turn to sacred ritual against the blight. After the Winterhoof and Thunderhorn wells are cleansed, Mull Thunderhorn crafts a final totem for the well north of Thunder Bluff. Infused with natural spirits, it purifies the fetid water so life can nourish the plains again.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wildmane-cleansing-totem-bb1354a5ba43d4af0591/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["item:wiley-s-note"] = {
  hash = "66140b",
  fullHash = "66140b",
  text = "Wiley's Note. Wiley's Note is a confidential missive penned by the Lakeshire rogue Wiley the Black, paid as a debt to Gryan Stoutmantle. Its contents reveal alarming alliances formed by the Defias Brotherhood and draw Stormwind's intelligence service into the investigation. Penned in Redridge by the shady rogue Wiley the Black, this scribbled dispatch is handed over to settle an old favor owed to Gryan Stoutmantle. Within, Wiley exposes what he knows about the Defias Brotherhood's clandestine ambitions. His intelligence reveals that the brotherhood is not operating alone: they have brokered alliances with regional gnolls, kobolds, and goblin operatives to further their operations across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wiley-s-note-f2d17c37d7cbc1914992/1-0000.mp3", duration = 39.7061224, start = 0},
  },
}
P.transport["item:william-s-shipment"] = {
  hash = "e3afa9",
  fullHash = "e3afa9",
  text = "William's Shipment. In Goldshire, William Pestle packs candles from Elwynn's kobolds for his brother Morgan in Stormwind. William Pestle keeps trade moving between Goldshire and the capital. He gathers materials in Elwynn Forest, while his brother Morgan runs Pestle's Apothecary in Stormwind's Trade District. William cannot leave his duties to travel north, so he depends on couriers to carry the parcel of wax and candles into the city. Kobold candles from Elwynn's mines fill the shipment. William gathers the large candles for their wax and packs them for Morgan at Pestle's Apothecary. The wax joins the stock used in the capital's alchemical trade.",
  ["1"] = {
    {file = "Audio/Transport/full_item_william-s-shipment-7c8a0acbca999fc680f8/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["item:wine-ticket"] = {
  hash = "b0f48e",
  fullHash = "b0f48e",
  text = "Wine Ticket. In Stormwind, Renato Gallina hands out Wine Tickets to bring customers to his family's shop. Present one to Suzetta Gallina for a complimentary bottle of Pinot Noir. Renato Gallina promotes the Gallina Winery with printed tickets near Stormwind's Trade District. The winery is a boutique vintage shop along the nearby canals. Each ticket promises a complimentary sample of Pinot Noir, drawing curious passersby and newly arrived adventurers toward the family business in hopes they become loyal customers.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wine-ticket-7578e23859dbe005fcb2/1-0000.mp3", duration = 29.0481633, start = 0},
  },
}
P.transport["item:winterhoof-cleansing-totem"] = {
  hash = "6ea7a1",
  fullHash = "6ea7a1",
  text = "Winterhoof Cleansing Totem. At Winterhoof Water Well, Venture Company poisons the water beneath Mulgore's plains. Mull Thunderhorn crafts a totem to cleanse it. Mull Thunderhorn crafts the Winterhoof Cleansing Totem in Bloodhoof Village. Venture Company goblins have tainted Mulgore's underground water with their operations. Mull imbues the carved wood with protective magic meant to wash away the foreign poisons. Carried past hostile goblin guards to Winterhoof Water Well, the totem channels a focused ritual that disperses the contamination. Pure drinking water returns for the plains' wandering herds and native tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_item_winterhoof-cleansing-totem-6c8dc5f300b47b363547/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["item:witchwing-talon"] = {
  hash = "5aa3b1",
  fullHash = "5aa3b1",
  text = "Witchwing Talon. In the northwestern Barrens, Witchwing Talons mark dead harpy raiders. Horde scouts at the Crossroads seek them as proof while they work to secure vital caravan routes. Witchwing harpies raid Horde supply caravans from their roosts northwest of the Crossroads. Scout Darsok Swiftdagger coordinates strikes against the flock's hierarchy. Darsok requires physical proof of each dead scavenger, and the talons provide it. With proof that raiders have fallen, the scouts can weaken the flock's ranks before striking higher in its command.",
  ["1"] = {
    {file = "Audio/Transport/full_item_witchwing-talon-5c2c63294b9d918e718e/1-0000.mp3", duration = 31.1379592, start = 0},
  },
}
P.transport["item:wolf-heart-sample"] = {
  hash = "151169",
  fullHash = "151169",
  text = "Wolf Heart Sample. Wolf Heart Sample is bound for the Crossroads, carrying diseased wolf tissue from Lordaeron to Kalimdor. The Royal Apothecary Society seeks to learn what northern toxins do to the Barrens’ native beasts. Wolf Heart Sample began with plagued wolves in Lordaeron’s ruins. Apothecary Renferrel gathered the hearts, and they were packed for the journey across the Great Sea. The Forsaken’s Royal Apothecary Society seeks greater knowledge of venom, blights, and biological reagents. A courier carries the parcel to the Crossroads in the Barrens, linking Undercity’s experiments in the scarred Eastern Kingdoms with Kalimdor’s frontier outposts. At the Crossroads, Apothecary Helbrim receives Wolf Heart Sample. Helbrim studies how toxins from Lordaeron’s Scourge-ravaged lands affect the native wildlife of Kalimdor. The toxicity preserved in the wolf hearts may reveal properties that can improve Forsaken poisons and elixirs far from home.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wolf-heart-sample-70e28bfad772af09c769/1-0000.mp3", duration = 56.0587755, start = 0},
  },
}
P.transport["item:wolf-heart-samples"] = {
  hash = "0cee62",
  fullHash = "0cee62",
  text = "Wolf Heart Samples. In Silverpine Forest, wolf hearts hold a poison their living hosts endure. Apothecary Renferrel sends samples to the Royal Apothecary Society, whose members study them. Apothecary Renferrel found a deadly compound in certain wolf hearts while examining carcasses in Silverpine Forest. The poison saturates the tissue at a level that should kill the wolves, yet they live. Renferrel set tissue samples aside for delivery to Undercity. The Forsaken study organisms that withstand toxins as they seek to master biological warfare and prepare new reagents. Couriers carry the samples beneath the ruins of Lordaeron to Apothecary Zinge at the Royal Apothecary Society's headquarters in the Apothecarium. Zinge and her colleagues prize new toxins. They dissect and test the tainted tissue to isolate its virulent compounds and learn how the beasts survive them, hoping to use that knowledge in their alchemical work.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wolf-heart-samples-18fb639394076dbd5956/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["item:wood-pulp"] = {
  hash = "b66664",
  fullHash = "b66664",
  text = "Wood Pulp. At Bael Modan, Wood Pulp helps the dwarves prepare their blasting charges. The dwarven personnel stationed in the southern Barrens carry it as an absorbent base for stabilizing liquid explosives. At Bael Modan, Ironforge dwarves use earth-moving equipment and chemical explosives to tear into ancestral tauren hunting grounds. Liquid nitroglycerin is unstable on its own, so dwarven engineers soak it into porous wood pulp with sodium nitrate to make stable charges for excavation and combat. Riflemen, soldiers, and officers carry bundles for sapping and field munitions.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wood-pulp-afd475a25bb82f7dbf8c/1-0000.mp3", duration = 35.9967347, start = 0},
  },
}
P.transport["item:wooden-key"] = {
  hash = "e4d890",
  fullHash = "e4d890",
  text = "Wooden Key. In northern Ashenvale, the Wooden Key rests in the hands of maddened ancients near Felwood’s border. It opens a concealed chest with a remnant of Dartol's Rod. Crazed and Withered Ancients carry the Wooden Key along the shaded trails north of Raynewood Retreat. Shael'dryn once knew the local treants, but now says corruption has twisted their nature. One carries the key to a chest holding a piece of Dartol's Rod.",
  ["1"] = {
    {file = "Audio/Transport/full_item_wooden-key-b9d25f682a3e759fc4c6/1-0000.mp3", duration = 23.562449, start = 0},
  },
}
P.transport["item:worn-parchment"] = {
  hash = "46f596",
  fullHash = "46f596",
  text = "Worn Parchment. At the Tower of Althalaxx in northern Darkshore, Worn Parchment scraps offer clues to the cultists gathered there. North along Darkshore’s mist-shrouded coast, dark spellcasters and their followers have seized the ruined Tower of Althalaxx. Dark Strand Fanatics patrol the grounds outside and carry scraps of worn parchment among their belongings. One scrap holds only scattered writing and strange symbols. Gathered together, the fragments reveal a previously unknown organization called the Cult of the Dark Strand.",
  ["1"] = {
    {file = "Audio/Transport/full_item_worn-parchment-ba558a1cb2032f86dec0/1-0000.mp3", duration = 29.9363265, start = 0},
  },
}
P.transport["item:worn-stone-token"] = {
  hash = "6514a3",
  fullHash = "6514a3",
  text = "Worn Stone Token. Across the Alterac Mountains, Worn Stone Token enchantments have faded, though Dalaran crafted them to command elementals. The tokens remain with Dalaran personnel, from mages to laborers. Dalaran’s magi command elementals with talismans that bend beings from other realms to their will. Worn Stone Tokens are depleted versions of these implements. Theurgists and summoners carry them, as do Dalaran laborers and guards stationed around the ruins and internment camps of Alterac. Their presence shows how deeply elemental binding reaches into Dalaran’s daily work. At Tarren Mill, the Forsaken watch the nearby wizards. Magus Voidglare seeks Worn Stone Tokens to study Dalaran’s methods of enslaving elementals. Keeper Bel'varil directs agents to gather worn, inert tokens first. These let the Magus examine basic enchanting techniques safely before attempting more potent, volatile conduits.",
  ["1"] = {
    {file = "Audio/Transport/full_item_worn-stone-token-0b80048b53b01a18fcca/1-0000.mp3", duration = 53.524898, start = 0},
  },
}
P.transport["item:woven-wand"] = {
  hash = "a5f25c",
  fullHash = "a5f25c",
  text = "Woven Wand. In the Undercity, the Woven Wand has returned to Bethor Iceshard. Three Dalaran apprentices made it as a pledge of brotherhood, before betrayal and the fall of Lordaeron scattered them.",
  ["1"] = {
    {file = "Audio/Transport/full_item_woven-wand-e0a57d3460f927a75e53/1-0000.mp3", duration = 11.1542857, start = 0},
  },
}
P.transport["item:xavian-water-sample"] = {
  hash = "36246b",
  fullHash = "36246b",
  text = "Xavian Water Sample. At Xavian, ancient waters hold arcane power sought by Horde mages in Orgrimmar. They seek it to unravel the latent magic preserved in Ashenvale's oldest sacred sites. Xavian was a fabled ancient elven city, and its old knowledge remains known among the learned. Even in ruin, its waters are said to hold great magical power. Deino, an arcane instructor in Orgrimmar, sends rising mages deep into Ashenvale to draw fresh water from the pool beneath Xavian's tallest waterfall. They must cross dangerous ground, for corrupt satyrs now guard the ruins fiercely and oppose spellcasters who meddle there.",
  ["1"] = {
    {file = "Audio/Transport/full_item_xavian-water-sample-f5bb9cb3b7b9a54abdd4/1-0000.mp3", duration = 36.1795918, start = 0},
  },
}
P.transport["item:young-crocolisk-skin"] = {
  hash = "c6b8f8",
  fullHash = "c6b8f8",
  text = "Young Crocolisk Skin. In the Wetlands, young crocolisks provide hides for trade from Menethil Harbor. Their softer skins are cured by local tanner James Halloran and shipped to distant ports. Menethil Harbor sends marsh goods to distant ports from the western coast of Khaz Modan. The town’s resident tanner, James Halloran, cures hides among its most lucrative exports. Full-grown crocolisks have thick, tough scales, while their young provide softer leather that is easier to work. The delicate skins are in high demand, so Halloran depends on local hunters and passing travelers to search the boggy marshes just outside town and keep his curing racks stocked.",
  ["1"] = {
    {file = "Audio/Transport/full_item_young-crocolisk-skin-9c853eebb5bace5f1c29/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["item:yowler-s-paw"] = {
  hash = "47773a",
  fullHash = "47773a",
  text = "Yowler's Paw. In Lakeshire, Yowler's Paw is brought to Verner Osgood as proof the feared gnoll leader is dead. Yowler leads the packs menacing the hills above Lakeshire. Yowler leads the Redridge gnolls that terrorize the heights around Lake Everstill, their howls reaching Lakeshire. He is feared above all, a ruthless alpha driving the packs' expansion. Verner Osgood asks brave adventurers to bring him Yowler's paw, the customary proof of a bounty across human territories. Taking the paw marks the death of an unusually cunning predator and a blow against the chain of command among his disorganized followers. Yowler's Paw points to the danger facing Lakeshire. The Stormwind Army is consumed by the Blackrock orc threat entrenched around Stonewatch Keep, leaving civil authorities and townspeople to hire passing mercenaries for defense. Without regular royal garrisons, settlers such as Verner Osgood rely on proof that threats have been dealt with to keep local roads marginally safe for trade and travel.",
  ["1"] = {
    {file = "Audio/Transport/full_item_yowler-s-paw-9c0983eeed4cdcf3c941/1-0000.mp3", duration = 59.4285714, start = 0},
  },
}
P.transport["item:zalazane-s-head"] = {
  hash = "823470",
  fullHash = "823470",
  text = "Zalazane's Head. Master Gadrin awaits proof that Zalazane has fallen. The Darkspear seek relief from the witch doctor who drove them from the Echo Isles. Master Gadrin asks for proof that Zalazane is dead. The witch doctor betrayed the Darkspear and seized control of their island home with mind-enslaving hexes. His magic drove Vol'jin's people to the shores of Durotar. From the Echo Isles, Zalazane still sends hexed thralls across the water to seize more victims. Sen'jin Village needs proof that his rule has ended. Returning Zalazane's severed head confirms his defeat and gives the displaced tribe a measure of peace, with hope of reclaiming their stolen islands one day.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zalazane-s-head-9746f431c37a7aa993ec/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["item:zamah-s-note"] = {
  hash = "8b2783",
  fullHash = "8b2783",
  text = "Zamah's Note. Zamah's Note carries an urgent plea from Thunder Bluff to Tarren Mill. Zamah asks Apothecary Lydon for an alchemical way to drive the Venture Company from Stonetalon without direct bloodshed. The Venture Company has dug deep into the Stonetalon Mountains, felling trees and tearing up sacred land. Zamah wants a way to force the goblins out without slaughter. She turns to the Forsaken Royal Apothecary Society for help. Her note tells her colleague, Apothecary Lydon, about the danger in Stonetalon. Lydon is in Tarren Mill, far away in the Hillsbrad Foothills of Lordaeron. The sealed note must cross continents to reach Lydon. Travelers from Kalimdor take a zeppelin to the Undercity, then travel south through Silverpine Forest into Hillsbrad. Lydon is intrigued by Zamah's specific request. Word has reached him from across the ocean, and he prepares an alchemical answer to the goblin problem.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zamah-s-note-344598269ed54319ec0c/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["item:zargh-s-meats"] = {
  hash = "85f987",
  fullHash = "85f987",
  text = "Zargh's Meats. At the Crossroads, Zargh prepares fresh meat for Gryshka in Orgrimmar. The parcel gives young Horde travelers a reason to learn the wind rider route. Zargh, an orc butcher and hunter at the Crossroads in the Barrens, prepares fresh cuts for Gryshka, the innkeeper in Orgrimmar's Valley of Strength. The heat across the savannas can spoil fresh game quickly, so the parcel goes with couriers bound for the Crossroads roost. Wind Rider Master Devrak arranges a wyvern flight to Orgrimmar's Skytower, sparing travelers the long overland journey through Durotar. Zargh's delivery carries a personal sentiment along with its provisions. When Gryshka receives the meat, she recognizes Zargh's knack for winning a lady's favor with quality game. She is eager to prepare the cuts for the inn's patrons and guests. For newly arrived orc and troll travelers, the delivery offers an introduction to long-distance flight between Kalimdor's Horde settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zargh-s-meats-5b365f232e070e095d5b/1-0000.mp3", duration = 56.1632653, start = 0},
  },
}
P.transport["item:zhevra-hooves"] = {
  hash = "7cef1c",
  fullHash = "7cef1c",
  text = "Zhevra Hooves. Across the Barrens, zhevras graze in the open savannah. Their hooves prove a hunter can face swift, powerful prey. Zhevras graze across the Barrens, but their compact, muscular legs can strike hard. Sergra Darkthorn, the orc shaman in charge of the Crossroads, sends aspiring Horde scouts to gather hooves from zhevra runners. The hunt sharpens a fledgling hunter's instincts and resilience. A panicked runner can kick even a sturdy tauren flat. Intact hooves show a hunter can handle swift, kicking quarry before taking on Kalimdor's deadliest predators.",
  ["1"] = {
    {file = "Audio/Transport/full_item_zhevra-hooves-7ea9719c7c9bdfe88c5f/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
